-- =============================================================================
-- INDEXES
-- =============================================================================
CREATE INDEX IF NOT EXISTS idx_sessions_expires ON app.sessions USING btree (expires_at);
CREATE INDEX IF NOT EXISTS idx_sessions_identity ON app.sessions USING btree (identity_id);
CREATE INDEX IF NOT EXISTS idx_audit_date ON public.attendance_audit_log USING btree (created_at);
CREATE INDEX IF NOT EXISTS idx_audit_employee ON public.attendance_audit_log USING btree (employee_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_event ON public.attendance_audit_log USING btree (event_type);
CREATE INDEX IF NOT EXISTS idx_audit_session ON public.attendance_audit_log USING btree (session_id);
CREATE INDEX IF NOT EXISTS idx_auction_activity_auction_id ON public.auction_activity USING btree (auction_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_auction_awards_auction_id ON public.auction_awards USING btree (auction_id);
CREATE INDEX IF NOT EXISTS idx_auction_awards_status ON public.auction_awards USING btree (status);
CREATE INDEX IF NOT EXISTS idx_auction_bids_auction_id ON public.auction_bids USING btree (auction_id);
CREATE INDEX IF NOT EXISTS idx_auction_bids_placed_at ON public.auction_bids USING btree (auction_id, placed_at DESC);
CREATE INDEX IF NOT EXISTS idx_auction_bids_winning ON public.auction_bids USING btree (auction_id) WHERE (is_winning = true);
CREATE INDEX IF NOT EXISTS idx_auction_items_auction_id ON public.auction_items USING btree (auction_id);
CREATE INDEX IF NOT EXISTS idx_auction_items_product_id ON public.auction_items USING btree (product_id);
