-- =============================================================================
-- FUNCTIONS
-- =============================================================================
CREATE OR REPLACE FUNCTION app.current_identity_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
 SELECT NULLIF(current_setting('app.identity_id', true), '')::uuid; 
$function$;

CREATE OR REPLACE FUNCTION app.current_employee_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
 SELECT e.id FROM public.employees e WHERE e.identity_id = app.current_identity_id() LIMIT 1; 
$function$;

CREATE OR REPLACE FUNCTION app.current_customer_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
 SELECT c.id FROM public.customers c WHERE c.identity_id = app.current_identity_id() LIMIT 1; 
$function$;

CREATE OR REPLACE FUNCTION app.get_subtree_ids(p_manager_id uuid DEFAULT app.current_employee_id())
 RETURNS uuid[]
 LANGUAGE sql
 STABLE
AS $function$
 WITH RECURSIVE subtree AS (
      SELECT id FROM public.employees WHERE id = p_manager_id
      UNION ALL
      SELECT e.id FROM public.employees e JOIN subtree s ON e.manager_id = s.id
    ) SELECT array_agg(id) FROM subtree; 
$function$;

CREATE OR REPLACE FUNCTION app.has_capability(p_code text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS (
      SELECT 1 FROM public.employee_roles er
      JOIN public.role_capabilities rc ON rc.role_id = er.role_id
      JOIN public.capabilities cap ON cap.id = rc.capability_id AND cap.code = p_code
      WHERE er.employee_id = app.current_employee_id()
      UNION
      SELECT 1 FROM public.employee_capabilities ec
      JOIN public.capabilities cap ON cap.id = ec.capability_id AND cap.code = p_code
      WHERE ec.employee_id = app.current_employee_id() AND ec.grant_type = 'grant'
      EXCEPT
      SELECT 1 FROM public.employee_capabilities ec
      JOIN public.capabilities cap ON cap.id = ec.capability_id AND cap.code = p_code
      WHERE ec.employee_id = app.current_employee_id() AND ec.grant_type = 'deny'
    ); 
$function$;

CREATE OR REPLACE FUNCTION app.can_view_employee_data(p_employee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT p_employee_id = ANY(app.get_subtree_ids(app.current_employee_id())); 
$function$;

CREATE OR REPLACE FUNCTION app.get_visibility_ids()
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE
AS $function$

  DECLARE v_emp_id uuid := app.current_employee_id();
  BEGIN
    IF public.is_upper_management(v_emp_id) THEN
      RETURN app.get_subtree_ids(NULL);
    END IF;
    RETURN app.get_subtree_ids();
  END;
  
$function$;

CREATE OR REPLACE FUNCTION app.has_role(p_role_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS (
      SELECT 1 FROM public.employee_roles er
      JOIN public.roles r ON r.id = er.role_id AND r.name = p_role_name
      WHERE er.employee_id = app.current_employee_id()
    ); 
$function$;

CREATE OR REPLACE FUNCTION app.requires_auth()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT NULLIF(current_setting('app.identity_id', true), '') IS NOT NULL; 
$function$;

CREATE OR REPLACE FUNCTION public.is_order_in_statistics(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$

  SELECT p_status NOT IN ('draft', 'submitted', 'reviewing', 'returned_for_revision', 'cancelled')

$function$;

CREATE OR REPLACE FUNCTION public.get_visible_employee_ids(p_token text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid := p_token::uuid;
  v_session app.sessions;
  v_result uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN '{}'::uuid[]; END IF;
  IF v_session.identity_type = 'customer' THEN RETURN '{}'::uuid[]; END IF;

  IF public.is_upper_management(v_session.employee_id) THEN
    SELECT array_agg(id) INTO v_result FROM employees;
    RETURN COALESCE(v_result, '{}'::uuid[]);
  END IF;

  WITH RECURSIVE subtree AS (
    SELECT id FROM employees WHERE id = v_session.employee_id
    UNION ALL
    SELECT e.id FROM employees e JOIN subtree s ON e.manager_id = s.id
  )
  SELECT array_agg(id) INTO v_result FROM subtree;

  RETURN COALESCE(v_result, '{}'::uuid[]);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_visible_employee_ids(p_token uuid)
 RETURNS uuid[]
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 SELECT public.get_visible_employee_ids(p_token::text); 
$function$;

CREATE OR REPLACE FUNCTION public.validate_session(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_session app.sessions;
  v_employee RECORD;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN
    RETURN json_build_object('error', 'INVALID_SESSION');
  END IF;
  SELECT e.id, e.full_name INTO v_employee
  FROM public.employees e WHERE e.id = v_session.employee_id;
  RETURN json_build_object(
    'valid', true,
    'session', json_build_object('token', v_session.token, 'employee_id', v_session.employee_id,
      'identity_id', v_session.identity_id, 'identity_type', v_session.identity_type),
    'employee', json_build_object('id', v_employee.id, 'full_name', v_employee.full_name)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.login(p_phone text, p_password text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_identity RECORD;
  v_employee RECORD;
  v_token uuid;
BEGIN
  SELECT id, password_hash INTO v_identity
  FROM public.identities
  WHERE phone = p_phone AND is_active = true;
  IF v_identity IS NULL THEN
    RETURN json_build_object('error', 'INVALID_CREDENTIALS');
  END IF;
  IF v_identity.password_hash != crypt(p_password, v_identity.password_hash) THEN
    RETURN json_build_object('error', 'INVALID_CREDENTIALS');
  END IF;
  SELECT id INTO v_employee FROM public.employees WHERE identity_id = v_identity.id AND is_active = true;
  v_token := gen_random_uuid();
  INSERT INTO app.sessions (token, identity_id, employee_id, identity_type, expires_at)
  VALUES (v_token, v_identity.id, v_employee.id, 'employee', now() + interval '24 hours');
  RETURN json_build_object('token', v_token, 'employee_id', v_employee.id, 'identity_id', v_identity.id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.logout(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  DELETE FROM app.sessions WHERE token = p_token;
  RETURN json_build_object('success', true);
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_upper_management(p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_employee_id UUID;
BEGIN
  IF p_employee_id IS NOT NULL THEN
    v_employee_id := p_employee_id;
  ELSE
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM employee_roles er
    JOIN roles r ON r.id = er.role_id
    WHERE er.employee_id = v_employee_id
    AND r.name = 'الإدارة العليا'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.session_is_upper_management()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

  SELECT public.is_upper_management();

$function$;

CREATE OR REPLACE FUNCTION public.check_capability(p_token text, p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid;
  v_session app.sessions;
  v_cap_id uuid;
  v_role_ids uuid[];
BEGIN
  -- Cast text to uuid
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN false; END IF;

  -- Upper management bypass
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN true;
  END IF;

  SELECT id INTO v_cap_id FROM capabilities WHERE code = p_code;
  IF v_cap_id IS NULL THEN RETURN false; END IF;

  IF EXISTS (
    SELECT 1 FROM employee_capabilities
    WHERE employee_id = v_session.employee_id AND capability_id = v_cap_id AND grant_type = 'grant'
  ) THEN RETURN true; END IF;

  IF EXISTS (
    SELECT 1 FROM employee_capabilities
    WHERE employee_id = v_session.employee_id AND capability_id = v_cap_id AND grant_type = 'deny'
  ) THEN RETURN false; END IF;

  SELECT array_agg(role_id) INTO v_role_ids FROM employee_roles WHERE employee_id = v_session.employee_id;
  IF v_role_ids IS NULL THEN RETURN false; END IF;

  RETURN EXISTS (
    SELECT 1 FROM role_capabilities WHERE role_id = ANY(v_role_ids) AND capability_id = v_cap_id
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.check_capability(p_uu_id uuid, p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

BEGIN
  RETURN public.check_capability(p_uu_id::text, p_code);
END;

$function$;

CREATE OR REPLACE FUNCTION public._calc_base_unit_price(p_carton_price numeric, p_carton_quantity integer, p_unit_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$

BEGIN
  IF p_carton_price IS NULL OR p_carton_price <= 0 OR p_carton_quantity IS NULL OR p_carton_quantity <= 0 THEN
    RETURN NULL;
  END IF;
  IF p_unit_type = 'piece' THEN
    RETURN ROUND((p_carton_price / p_carton_quantity)::numeric, 2);
  ELSIF p_unit_type = 'dozen' THEN
    RETURN ROUND((p_carton_price / p_carton_quantity * 12)::numeric, 2);
  ELSIF p_unit_type = 'carton' THEN
    RETURN ROUND(p_carton_price::numeric, 2);
  ELSE
    RETURN NULL;
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public._get_auction_participant_status(p_auction_id uuid, p_session app.sessions)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$

DECLARE
  v_participant public.auction_participants;
  v_company_name varchar(255);
BEGIN
  IF p_session.customer_id IS NOT NULL THEN
    SELECT ap.* INTO v_participant FROM public.auction_participants ap
    WHERE ap.auction_id = p_auction_id AND ap.participant_type = 'customer' AND ap.participant_id = p_session.customer_id;
    SELECT company_name INTO v_company_name FROM public.customers WHERE id = p_session.customer_id;
  ELSIF p_session.employee_id IS NOT NULL THEN
    SELECT ap.* INTO v_participant FROM public.auction_participants ap
    WHERE ap.auction_id = p_auction_id AND ap.participant_type = 'employee' AND ap.participant_id = p_session.employee_id;
    SELECT full_name INTO v_company_name FROM public.employees WHERE id = p_session.employee_id;
  ELSE
    RETURN jsonb_build_object('status', 'visitor');
  END IF;

  IF v_participant.id IS NULL THEN
    RETURN jsonb_build_object(
      'status', 'registered',
      'can_request', true,
      'company_name', v_company_name
    );
  END IF;

  RETURN jsonb_build_object(
    'status', v_participant.status,
    'participant_id', v_participant.id,
    'deposit_paid', v_participant.deposit_paid,
    'company_name', v_company_name
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public._get_effective_tier_discount(p_tier_id uuid, p_product_id uuid, p_company_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$

DECLARE
  v_product_exception numeric;
  v_company_exception numeric;
  v_tier_default numeric;
BEGIN
  -- Priority 1: Product exception (applies_to_all_tiers or specific tier)
  SELECT discount_percent INTO v_product_exception
  FROM tier_product_exceptions
  WHERE product_id = p_product_id
    AND (tier_id = p_tier_id OR (tier_id IS NULL AND applies_to_all_tiers = true))
  ORDER BY applies_to_all_tiers DESC NULLS LAST
  LIMIT 1;

  IF v_product_exception IS NOT NULL THEN
    RETURN v_product_exception;
  END IF;

  -- Priority 2: Company exception
  SELECT discount_percent INTO v_company_exception
  FROM tier_company_exceptions
  WHERE tier_id = p_tier_id AND company_id = p_company_id;

  IF v_company_exception IS NOT NULL THEN
    RETURN v_company_exception;
  END IF;

  -- Priority 3: Tier default
  SELECT discount_percent INTO v_tier_default
  FROM tiers WHERE id = p_tier_id;

  RETURN COALESCE(v_tier_default, 0);
END;

$function$;

CREATE OR REPLACE FUNCTION public._return_qty_to_pieces(p_quantity integer, p_unit_type text, p_carton_quantity integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$

BEGIN
    IF p_unit_type = 'piece' THEN
        RETURN p_quantity;
    ELSIF p_unit_type = 'dozen' THEN
        RETURN p_quantity * 12;
    ELSIF p_unit_type = 'carton' THEN
        RETURN p_quantity * COALESCE(p_carton_quantity, 0);
    ELSE
        RETURN 0;
    END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.auto_cleanup_tracking_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_retention_days int;
    v_auto_cleanup boolean;
    v_cutoff_90d timestamptz;
    v_cutoff_60d timestamptz;
    v_cutoff_30d timestamptz;
    v_deleted_points int := 0;
    v_deleted_gps int := 0;
    v_deleted_logs int := 0;
    v_system_employee_id uuid;
BEGIN
    SELECT retention_days, auto_cleanup_enabled INTO v_retention_days, v_auto_cleanup
    FROM public.workday_settings LIMIT 1;

    IF NOT v_auto_cleanup THEN
        RETURN jsonb_build_object('skipped', true, 'reason', 'auto_cleanup_disabled');
    END IF;

    v_cutoff_90d := CURRENT_DATE - 90;
    v_cutoff_60d := CURRENT_DATE - 60;
    v_cutoff_30d := CURRENT_DATE - 30;

    -- Only delete tracking_points > 90 days
    DELETE FROM public.tracking_points WHERE recorded_at < v_cutoff_90d;
    GET DIAGNOSTICS v_deleted_points = ROW_COUNT;

    -- Delete gps_test_points > 60 days
    DELETE FROM public.gps_test_points WHERE captured_at < v_cutoff_60d;
    GET DIAGNOSTICS v_deleted_gps = ROW_COUNT;

    -- Delete cleanup logs > 30 days
    DELETE FROM public.tracking_cleanup_log WHERE created_at < v_cutoff_30d;
    GET DIAGNOSTICS v_deleted_logs = ROW_COUNT;

    -- NEVER delete: orders, order_items, customers, visits, collections,
    --               workday_sessions, workday_breaks (company assets)

    SELECT id INTO v_system_employee_id FROM public.employees ORDER BY created_at LIMIT 1;

    INSERT INTO public.tracking_cleanup_log
        (action_type, deleted_sessions, deleted_points, cutoff_date, executed_by, reason)
    VALUES ('auto_cleanup', 0, v_deleted_points, v_cutoff_90d, v_system_employee_id,
            jsonb_build_object('deleted_gps_test_points', v_deleted_gps,
                               'deleted_cleanup_logs', v_deleted_logs)::text);

    UPDATE public.workday_settings SET last_cleanup_at = now()
    WHERE id = (SELECT id FROM public.workday_settings LIMIT 1);

    RETURN jsonb_build_object(
        'deleted_tracking_points', v_deleted_points,
        'deleted_gps_test_points', v_deleted_gps,
        'deleted_cleanup_logs', v_deleted_logs,
        'cutoff_90d', v_cutoff_90d,
        'cutoff_60d', v_cutoff_60d,
        'cutoff_30d', v_cutoff_30d
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.auto_close_stale_sessions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_closed int := 0;
    v_warned int := 0;
    v_ws record;
    v_inactive_seconds numeric;
    v_warning_seconds numeric;
    v_last_activity timestamptz;
    v_is_midnight boolean;
BEGIN
    v_is_midnight := EXTRACT(HOUR FROM now()) = 0 AND EXTRACT(MINUTE FROM now()) <= 5;

    FOR v_ws IN
        SELECT * FROM public.workday_sessions
        WHERE status IN ('active', 'inactive_warning')
    LOOP
        SELECT COALESCE(
            v_ws.last_seen_at,
            (SELECT MAX(recorded_at) FROM public.tracking_points WHERE session_id = v_ws.id),
            v_ws.start_time
        ) INTO v_last_activity;

        v_inactive_seconds := EXTRACT(EPOCH FROM (now() - v_last_activity));

        -- Midnight rollover
        IF v_is_midnight AND v_ws.date < CURRENT_DATE THEN
            UPDATE public.workday_sessions
            SET end_time = COALESCE(v_ws.last_seen_at, now()),
                status = 'completed',
                close_reason = 'day_rollover',
                attendance_status = 'auto_closed',
                updated_at = now()
            WHERE id = v_ws.id;
            v_closed := v_closed + 1;

        -- In warning, 5min+ passed ? auto-close
        ELSIF v_ws.status = 'inactive_warning' THEN
            v_warning_seconds := EXTRACT(EPOCH FROM (now() - v_ws.warning_sent_at));
            IF v_warning_seconds >= 300 THEN
                UPDATE public.workday_sessions
                SET end_time = COALESCE(v_ws.last_seen_at, now()),
                    status = 'completed',
                    close_reason = 'no_activity_timeout',
                    attendance_status = 'auto_closed',
                    updated_at = now()
                WHERE id = v_ws.id;
                v_closed := v_closed + 1;
            END IF;

        -- Active, 2h+ inactive ? send warning
        ELSIF v_ws.status = 'active' AND v_inactive_seconds >= 7200 THEN
            UPDATE public.workday_sessions
            SET status = 'inactive_warning', warning_sent_at = now(), updated_at = now()
            WHERE id = v_ws.id;
            v_warned := v_warned + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('closed', v_closed, 'warned', v_warned);
END;

$function$;

CREATE OR REPLACE FUNCTION public.backfill_session_distances(p_min_distance_threshold numeric DEFAULT 20, p_max_accuracy numeric DEFAULT 50, p_max_speed numeric DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session record;
    v_distance integer;
    v_updated int := 0;
    v_with_points int := 0;
    v_no_points int := 0;
    v_null_before int := 0;
    v_zero_before int := 0;
BEGIN
    SELECT COUNT(*) INTO v_null_before
    FROM public.workday_sessions
    WHERE total_distance_meters IS NULL;

    SELECT COUNT(*) INTO v_zero_before
    FROM public.workday_sessions
    WHERE total_distance_meters = 0;

    FOR v_session IN
        SELECT id
        FROM public.workday_sessions
        WHERE total_distance_meters IS NULL OR total_distance_meters = 0
        ORDER BY date ASC
    LOOP
        SELECT COUNT(*) INTO v_no_points
        FROM public.tracking_points
        WHERE session_id = v_session.id
        LIMIT 1;

        v_distance := public.calculate_session_distance(
            v_session.id,
            p_min_distance_threshold,
            p_max_accuracy,
            p_max_speed
        );

        UPDATE public.workday_sessions
        SET total_distance_meters = v_distance,
            updated_at = now()
        WHERE id = v_session.id;

        v_updated := v_updated + 1;
        IF v_no_points > 0 THEN
            v_with_points := v_with_points + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'total_processed', v_updated,
        'with_tracking_points', v_with_points,
        'no_tracking_points', (v_updated - v_with_points),
        'null_before', v_null_before,
        'zero_before', v_zero_before,
        'thresholds', jsonb_build_object(
            'min_distance', p_min_distance_threshold,
            'max_accuracy', p_max_accuracy,
            'max_speed', p_max_speed
        )
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.backfill_session_distances_v2(p_min_distance_threshold numeric DEFAULT 0, p_max_accuracy numeric DEFAULT 100, p_max_speed numeric DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session record;
    v_distance integer;
    v_updated int := 0;
    v_with_points int := 0;
    v_no_points int := 0;
    v_total_before int := 0;
BEGIN
    SELECT COUNT(*) INTO v_total_before
    FROM public.workday_sessions
    WHERE total_distance_meters IS NOT NULL;

    FOR v_session IN
        SELECT id
        FROM public.workday_sessions
        WHERE total_distance_meters IS NOT NULL
           OR total_distance_meters = 0
        ORDER BY date ASC
    LOOP
        SELECT COUNT(*) INTO v_no_points
        FROM public.tracking_points
        WHERE session_id = v_session.id;

        v_distance := public.calculate_session_distance(
            v_session.id,
            p_min_distance_threshold,
            p_max_accuracy,
            p_max_speed
        );

        UPDATE public.workday_sessions
        SET total_distance_meters = v_distance,
            updated_at = now()
        WHERE id = v_session.id;

        v_updated := v_updated + 1;
        IF v_no_points > 0 THEN
            v_with_points := v_with_points + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'total_processed', v_updated,
        'with_tracking_points', v_with_points,
        'no_tracking_points', (v_updated - v_with_points),
        'sessions_with_data_before', v_total_before,
        'thresholds', jsonb_build_object(
            'min_distance', p_min_distance_threshold,
            'max_accuracy', p_max_accuracy,
            'max_speed', p_max_speed
        )
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.batch_upsert_work_policies(p_token uuid, p_policies jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_session app.sessions;
    v_admin_id uuid;
    v_policy jsonb;
    v_updated int := 0;
    v_errors jsonb := '[]'::jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_admin_id := v_session.employee_id;

    FOR v_policy IN SELECT * FROM jsonb_array_elements(p_policies)
    LOOP
        BEGIN
            INSERT INTO public.employee_work_policies (
                employee_id, work_location, schedule_type, tracking_required,
                attendance_enabled, required_daily_hours, shift_start_time, shift_end_time,
                late_threshold_minutes, early_departure_threshold_minutes,
                updated_by
            ) VALUES (
                (v_policy->>'employee_id')::uuid,
                COALESCE(v_policy->>'work_location', 'field'),
                COALESCE(v_policy->>'schedule_type', 'flexible'),
                COALESCE((v_policy->>'tracking_required')::boolean, true),
                COALESCE((v_policy->>'attendance_enabled')::boolean, true),
                (v_policy->>'required_daily_hours')::decimal,
                (v_policy->>'shift_start_time')::time,
                (v_policy->>'shift_end_time')::time,
                (v_policy->>'late_threshold_minutes')::integer,
                (v_policy->>'early_departure_threshold_minutes')::integer,
                v_admin_id
            )
            ON CONFLICT (employee_id) DO UPDATE SET
                work_location = COALESCE((v_policy->>'work_location'), employee_work_policies.work_location),
                schedule_type = COALESCE((v_policy->>'schedule_type'), employee_work_policies.schedule_type),
                tracking_required = COALESCE((v_policy->>'tracking_required')::boolean, employee_work_policies.tracking_required),
                attendance_enabled = COALESCE((v_policy->>'attendance_enabled')::boolean, employee_work_policies.attendance_enabled),
                required_daily_hours = COALESCE((v_policy->>'required_daily_hours')::decimal, employee_work_policies.required_daily_hours),
                shift_start_time = COALESCE((v_policy->>'shift_start_time')::time, employee_work_policies.shift_start_time),
                shift_end_time = COALESCE((v_policy->>'shift_end_time')::time, employee_work_policies.shift_end_time),
                late_threshold_minutes = COALESCE((v_policy->>'late_threshold_minutes')::integer, employee_work_policies.late_threshold_minutes),
                early_departure_threshold_minutes = COALESCE((v_policy->>'early_departure_threshold_minutes')::integer, employee_work_policies.early_departure_threshold_minutes),
                updated_by = v_admin_id,
                updated_at = now();
            v_updated := v_updated + 1;
        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object(
                'employee_id', v_policy->>'employee_id',
                'error', SQLERRM
            );
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'updated', v_updated,
        'errors', v_errors
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_net_work_hours(p_session_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_start_time timestamptz;
  v_end_time timestamptz;
  v_schedule_type text;
  v_duration_min numeric;
  v_break_min numeric;
  v_net_min numeric;
BEGIN
  SELECT ws.start_time, ws.end_time, ewp.schedule_type
  INTO v_start_time, v_end_time, v_schedule_type
  FROM workday_sessions ws
  LEFT JOIN employee_work_policies ewp ON ewp.employee_id = ws.employee_id
  WHERE ws.id = p_session_id;

  IF v_start_time IS NULL THEN
    RETURN 0;
  END IF;

  v_end_time := COALESCE(v_end_time, now());
  v_duration_min := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) / 60;

  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(wb.break_end, now()) - wb.break_start)) / 60), 0)
  INTO v_break_min
  FROM workday_breaks wb
  WHERE wb.session_id = p_session_id;

  -- Canonical rule: only subtract breaks for fixed_shift (office employees)
  IF v_schedule_type = 'fixed_shift' THEN
    v_net_min := v_duration_min - v_break_min;
  ELSE
    v_net_min := v_duration_min;
  END IF;

  RETURN GREATEST(v_net_min, 0);
END;

$function$;

CREATE OR REPLACE FUNCTION public.calculate_session_distance(p_session_id uuid, p_min_distance_threshold numeric DEFAULT 20, p_max_accuracy numeric DEFAULT 50, p_max_speed numeric DEFAULT 5)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_total_distance numeric := 0;
    v_anchor_lat numeric;
    v_anchor_lng numeric;
    v_anchor_time timestamptz;
    v_anchor_set boolean := false;
    v_pt record;
    v_dist numeric;
    v_time_diff_sec numeric;
    v_speed numeric;
    v_i int := 0;
    v_valid_count int := 0;
    v_consecutive_speed_skips int := 0;
    v_use_relaxed_accuracy boolean := false;
    v_effective_max_accuracy numeric;
BEGIN
    LOOP
        v_total_distance := 0;
        v_anchor_set := false;
        v_consecutive_speed_skips := 0;
        v_i := 0;

        IF v_use_relaxed_accuracy THEN
            v_effective_max_accuracy := GREATEST(p_max_accuracy, 500);
        ELSE
            v_effective_max_accuracy := p_max_accuracy;
        END IF;

        FOR v_pt IN
            SELECT tp.latitude, tp.longitude, tp.recorded_at, tp.accuracy_meters
            FROM public.tracking_points tp
            WHERE tp.session_id = p_session_id
            ORDER BY tp.recorded_at
        LOOP
            v_i := v_i + 1;

            -- 1. GPS coordinate validation — skip garbage points
            IF v_pt.latitude < -90 OR v_pt.latitude > 90
               OR v_pt.longitude < -180 OR v_pt.longitude > 180
               OR (ABS(v_pt.latitude) < 0.01 AND ABS(v_pt.longitude) < 0.01) THEN
                CONTINUE;
            END IF;

            v_valid_count := v_valid_count + 1;

            IF NOT v_anchor_set THEN
                IF v_pt.accuracy_meters IS NULL OR v_pt.accuracy_meters <= v_effective_max_accuracy THEN
                    v_anchor_lat := v_pt.latitude;
                    v_anchor_lng := v_pt.longitude;
                    v_anchor_time := v_pt.recorded_at;
                    v_anchor_set := true;
                END IF;
            ELSE
                -- Accuracy filter
                IF v_pt.accuracy_meters IS NOT NULL AND v_pt.accuracy_meters > v_effective_max_accuracy THEN
                    CONTINUE;
                END IF;

                -- Haversine distance from anchor
                v_dist := 6371000 * 2 * asin(sqrt(
                    power(sin(radians(v_pt.latitude - v_anchor_lat) / 2), 2) +
                    cos(radians(v_anchor_lat)) * cos(radians(v_pt.latitude)) *
                    power(sin(radians(v_pt.longitude - v_anchor_lng) / 2), 2)
                ));

                -- Min distance filter (GPS drift)
                IF v_dist < p_min_distance_threshold THEN
                    v_consecutive_speed_skips := 0;
                    CONTINUE;
                END IF;

                -- Speed filter
                v_time_diff_sec := EXTRACT(EPOCH FROM (v_pt.recorded_at - v_anchor_time));
                IF v_time_diff_sec > 0 THEN
                    v_speed := v_dist / v_time_diff_sec;
                    IF v_speed > p_max_speed THEN
                        v_consecutive_speed_skips := v_consecutive_speed_skips + 1;
                        -- Reset anchor if too many consecutive speed outliers
                        IF v_consecutive_speed_skips >= 5 THEN
                            v_anchor_lat := v_pt.latitude;
                            v_anchor_lng := v_pt.longitude;
                            v_anchor_time := v_pt.recorded_at;
                            v_consecutive_speed_skips := 0;
                        END IF;
                        CONTINUE;
                    END IF;
                END IF;

                -- Passed all filters
                v_total_distance := v_total_distance + v_dist;
                v_consecutive_speed_skips := 0;
                v_anchor_lat := v_pt.latitude;
                v_anchor_lng := v_pt.longitude;
                v_anchor_time := v_pt.recorded_at;
            END IF;
        END LOOP;

        -- Exit if: result is non-zero, already tried relaxed, or too few valid points
        IF v_total_distance > 0 OR v_use_relaxed_accuracy OR v_valid_count < 2 THEN
            EXIT;
        END IF;

        v_use_relaxed_accuracy := true;
    END LOOP;

    RETURN v_total_distance::int;
END;

$function$;

CREATE OR REPLACE FUNCTION public.check_capability(p_token text, p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid;
  v_session app.sessions;
  v_cap_id uuid;
  v_role_ids uuid[];
BEGIN
  -- Cast text to uuid
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN false;
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN false; END IF;

  -- Upper management bypass
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN true;
  END IF;

  SELECT id INTO v_cap_id FROM capabilities WHERE code = p_code;
  IF v_cap_id IS NULL THEN RETURN false; END IF;

  IF EXISTS (
    SELECT 1 FROM employee_capabilities
    WHERE employee_id = v_session.employee_id AND capability_id = v_cap_id AND grant_type = 'grant'
  ) THEN RETURN true; END IF;

  IF EXISTS (
    SELECT 1 FROM employee_capabilities
    WHERE employee_id = v_session.employee_id AND capability_id = v_cap_id AND grant_type = 'deny'
  ) THEN RETURN false; END IF;

  SELECT array_agg(role_id) INTO v_role_ids FROM employee_roles WHERE employee_id = v_session.employee_id;
  IF v_role_ids IS NULL THEN RETURN false; END IF;

  RETURN EXISTS (
    SELECT 1 FROM role_capabilities WHERE role_id = ANY(v_role_ids) AND capability_id = v_cap_id
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.check_capability(p_uu_id uuid, p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

BEGIN
  RETURN public.check_capability(p_uu_id::text, p_code);
END;

$function$;

CREATE OR REPLACE FUNCTION public.check_session_timeout(p_token uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_ws record;
    v_inactive_seconds numeric;
    v_warning_seconds numeric;
    v_last_activity timestamptz;
    v_has_recent_activity boolean;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    SELECT * INTO v_ws FROM public.workday_sessions
    WHERE id = p_session_id AND employee_id = v_employee_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'SESSION_NOT_FOUND'); END IF;

    -- Skip completed sessions
    IF v_ws.status = 'completed' THEN
        RETURN jsonb_build_object('action', 'completed');
    END IF;

    -- ============================================================
    -- Case 1: Midnight rollover (00:00-00:05) - close stale sessions
    -- ============================================================
    IF v_ws.status IN ('active', 'inactive_warning') AND v_ws.date < CURRENT_DATE
       AND EXTRACT(HOUR FROM now()) = 0 AND EXTRACT(MINUTE FROM now()) <= 5 THEN
        PERFORM public.end_workday(p_token, p_session_id,
            p_latitude => v_ws.end_latitude,
            p_longitude => v_ws.end_longitude,
            p_close_reason => 'day_rollover'
        );
        RETURN jsonb_build_object(
            'action', 'auto_closed',
            'reason', 'day_rollover',
            'message', '?? ????? ??? ????? ???????? ??????? ????? ???? ????? ????.'
        );
    END IF;

    -- ============================================================
    -- Determine last activity time
    -- Source of truth: last_seen_at (heartbeat) OR last tracking point
    -- ============================================================
    SELECT COALESCE(
        v_ws.last_seen_at,
        (SELECT MAX(recorded_at) FROM public.tracking_points WHERE session_id = p_session_id),
        v_ws.start_time
    ) INTO v_last_activity;

    v_inactive_seconds := EXTRACT(EPOCH FROM (now() - v_last_activity));

    -- Also check for business activity (visits, orders, collections, new customers)
    SELECT EXISTS (
        SELECT 1 FROM public.tracking_points
        WHERE session_id = p_session_id AND recorded_at > now() - interval '2 hours'
        UNION
        SELECT 1 FROM public.visits v
        WHERE v.employee_id = v_employee_id AND v.check_in_at > now() - interval '2 hours'
        UNION
        SELECT 1 FROM public.orders o
        WHERE o.owner_id = v_employee_id AND o.created_at > now() - interval '2 hours'
        UNION
        SELECT 1 FROM public.collections c
        WHERE c.owner_id = v_employee_id AND c.created_at > now() - interval '2 hours'
        UNION
        SELECT 1 FROM public.customers cu
        WHERE cu.owner_id = v_employee_id AND cu.created_at > now() - interval '2 hours'
    ) INTO v_has_recent_activity;

    -- If there's recent business activity but last_seen_at is old, update it
    IF v_has_recent_activity AND v_inactive_seconds > 120 THEN
        PERFORM public.touch_session_activity(p_session_id);
        IF v_ws.status = 'inactive_warning' THEN
            RETURN jsonb_build_object(
                'action', 'warning_cleared',
                'message', '?? ????? ???? ????. ?? ????? ????? ??????.'
            );
        END IF;
        v_inactive_seconds := 0;
    END IF;

    -- ============================================================
    -- Case 2: In inactive_warning - check grace period
    -- ============================================================
    IF v_ws.status = 'inactive_warning' THEN
        v_warning_seconds := EXTRACT(EPOCH FROM (now() - v_ws.warning_sent_at));

        -- Activity during warning ? clear it
        IF v_inactive_seconds < 120 THEN
            UPDATE public.workday_sessions
            SET status = 'active', warning_cleared_at = now(), updated_at = now()
            WHERE id = p_session_id;

            RETURN jsonb_build_object(
                'action', 'warning_cleared',
                'message', '?? ????? ???? ????. ?? ????? ????? ??????.'
            );
        END IF;

        -- 5 min grace passed ? auto-close
        IF v_warning_seconds >= 300 THEN
            PERFORM public.end_workday(p_token, p_session_id,
                p_latitude => v_ws.end_latitude,
                p_longitude => v_ws.end_longitude,
                p_close_reason => 'no_activity_timeout'
            );
            RETURN jsonb_build_object(
                'action', 'auto_closed',
                'reason', 'no_activity_timeout',
                'message', '?? ????? ??? ????? ???????? ???? ???? ?? ???? ??? ???? ?? ??????.'
            );
        END IF;

        -- Still in warning grace period
        RETURN jsonb_build_object(
            'action', 'warning_active',
            'inactive_minutes', (v_inactive_seconds / 60)::int,
            'warning_remaining_seconds', (300 - v_warning_seconds)::int,
            'message', '?? ??? ??? ?? ???? ??? ' || (v_inactive_seconds / 60)::int || ' ?????. ???? ????? ??? ????? ???????? ???? ' || (300 - v_warning_seconds)::int || ' ????? ??? ?? ??? ????? ?? ???? ????.'
        );
    END IF;

    -- ============================================================
    -- Case 3: Active but 2h+ inactivity ? issue warning
    -- ============================================================
    IF v_ws.status = 'active' AND v_inactive_seconds >= 7200 THEN  -- 2 hours
        UPDATE public.workday_sessions
        SET status = 'inactive_warning', warning_sent_at = now(), updated_at = now()
        WHERE id = p_session_id;

        RETURN jsonb_build_object(
            'action', 'warning_issued',
            'inactive_minutes', (v_inactive_seconds / 60)::int,
            'message', '?? ??? ??? ?? ???? ??? ??????. ???? ????? ??? ????? ???????? ???? 5 ????? ??? ?? ??? ????? ?? ???? ????.'
        );
    END IF;

    -- ============================================================
    -- Case 4: Active and within timeout - no action
    -- ============================================================
    RETURN jsonb_build_object(
        'action', 'ok',
        'inactive_minutes', (v_inactive_seconds / 60)::int
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.classify_employee_work_policies()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_field_count int := 0;
    v_office_count int := 0;
    v_unclassified_count int := 0;
    v_all_field_ids uuid[];
    v_all_office_ids uuid[];
BEGIN
    WITH field_employees AS (
        SELECT DISTINCT e.id AS employee_id
        FROM public.employees e
        WHERE e.is_active = true
        AND (
            EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id AND v.check_in_at >= now() - interval '30 days')
            OR
            EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_type = 'employee' AND o.owner_id = e.id AND o.created_at >= now() - interval '30 days')
        )
    )
    INSERT INTO public.employee_work_policies (
        employee_id, work_location, schedule_type, tracking_required,
        required_daily_hours, updated_by
    )
    SELECT employee_id, 'field', 'flexible', true, 8, NULL
    FROM field_employees
    ON CONFLICT (employee_id) DO UPDATE SET
        work_location = 'field',
        schedule_type = 'flexible',
        tracking_required = true,
        required_daily_hours = 8,
        updated_at = now();
    GET DIAGNOSTICS v_field_count = ROW_COUNT;

    WITH active_employees AS (
        SELECT e.id FROM public.employees e WHERE e.is_active = true
    ),
    field_ids AS (
        SELECT e.id FROM public.employees e
        WHERE e.is_active = true
        AND (
            EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id AND v.check_in_at >= now() - interval '30 days')
            OR
            EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_type = 'employee' AND o.owner_id = e.id AND o.created_at >= now() - interval '30 days')
        )
    ),
    office_employees AS (
        SELECT e.id AS employee_id
        FROM active_employees e
        WHERE e.id NOT IN (SELECT id FROM field_ids)
        AND (
            EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id)
            OR
            EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_type = 'employee' AND o.owner_id = e.id)
        )
    )
    INSERT INTO public.employee_work_policies (
        employee_id, work_location, schedule_type, tracking_required,
        required_daily_hours, updated_by
    )
    SELECT employee_id, 'office', 'fixed_shift', false, 8, NULL
    FROM office_employees
    ON CONFLICT (employee_id) DO UPDATE SET
        work_location = 'office',
        schedule_type = 'fixed_shift',
        tracking_required = false,
        required_daily_hours = 8,
        updated_at = now();
    GET DIAGNOSTICS v_office_count = ROW_COUNT;

    WITH active_employees AS (
        SELECT e.id FROM public.employees e WHERE e.is_active = true
    ),
    field_ids AS (
        SELECT e.id FROM public.employees e
        WHERE e.is_active = true
        AND (
            EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id AND v.check_in_at >= now() - interval '30 days')
            OR
            EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_type = 'employee' AND o.owner_id = e.id AND o.created_at >= now() - interval '30 days')
        )
    ),
    office_ids AS (
        SELECT e.id FROM active_employees e
        WHERE e.id NOT IN (SELECT id FROM field_ids)
        AND (
            EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id)
            OR
            EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_type = 'employee' AND o.owner_id = e.id)
        )
    ),
    unclassified_employees AS (
        SELECT e.id AS employee_id
        FROM active_employees e
        WHERE e.id NOT IN (SELECT id FROM field_ids)
        AND e.id NOT IN (SELECT id FROM office_ids)
    )
    SELECT COUNT(*) INTO v_unclassified_count FROM unclassified_employees;

    RETURN jsonb_build_object(
        'success', true,
        'field_employees', v_field_count,
        'office_employees', v_office_count,
        'needs_review', v_unclassified_count
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.cleanup_tracking_data(p_token uuid, p_mode character varying, p_employee_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_deleted_sessions int := 0; v_deleted_points int := 0;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    IF p_mode = 'all' THEN
        DELETE FROM public.tracking_points; GET DIAGNOSTICS v_deleted_points = ROW_COUNT;
        DELETE FROM public.workday_sessions WHERE status != 'active'; GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;
    ELSIF p_mode = 'employee' AND p_employee_id IS NOT NULL THEN
        DELETE FROM public.tracking_points WHERE employee_id = p_employee_id; GET DIAGNOSTICS v_deleted_points = ROW_COUNT;
        DELETE FROM public.workday_sessions WHERE employee_id = p_employee_id AND status != 'active'; GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;
    ELSIF p_mode = 'range' AND p_from IS NOT NULL AND p_to IS NOT NULL THEN
        DELETE FROM public.tracking_points WHERE recorded_at::date >= p_from AND recorded_at::date <= p_to; GET DIAGNOSTICS v_deleted_points = ROW_COUNT;
        DELETE FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND status != 'active'; GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;
    ELSIF p_mode = 'day' AND p_from IS NOT NULL THEN
        DELETE FROM public.tracking_points WHERE recorded_at::date = p_from; GET DIAGNOSTICS v_deleted_points = ROW_COUNT;
        DELETE FROM public.workday_sessions WHERE date = p_from AND status != 'active'; GET DIAGNOSTICS v_deleted_sessions = ROW_COUNT;
    END IF;
    INSERT INTO public.tracking_cleanup_log (action_type, deleted_sessions, deleted_points, cutoff_date, employee_id, reason, executed_by)
    VALUES ('manual_cleanup', v_deleted_sessions, v_deleted_points, CASE WHEN p_mode IN ('range', 'day') THEN p_from::timestamptz ELSE now() END, p_employee_id, 'Manual cleanup by management', v_session.employee_id);
    RETURN jsonb_build_object('deleted_sessions', v_deleted_sessions, 'deleted_points', v_deleted_points);
END;

$function$;

CREATE OR REPLACE FUNCTION public.deactivate_employee_weight_override(p_token uuid, p_override_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_override public.employee_weight_overrides;
    v_has_view_all boolean;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.check_capability(p_token, 'targets.manage') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT * INTO v_override FROM public.employee_weight_overrides WHERE id = p_override_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

    v_has_view_all := public.check_capability(p_token, 'targets.view_all');
    IF NOT v_has_view_all THEN
        IF v_override.employee_id != ALL(app.get_subtree_ids(v_session.employee_id)) THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'لا يمكن تعديل أوزان موظف خارج نطاقك');
        END IF;
    END IF;

    UPDATE public.employee_weight_overrides
    SET is_active = false, updated_at = now()
    WHERE id = p_override_id;

    RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.delete_module(p_token uuid, p_module_key character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_status varchar;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only');
  END IF;
  SELECT status INTO v_status FROM public.system_modules WHERE module_key = p_module_key;
  IF v_status IS NULL THEN RETURN jsonb_build_object('error', 'MODULE_NOT_FOUND'); END IF;
  IF v_status != 'deprecated' THEN RETURN jsonb_build_object('error', 'CANNOT_DELETE', 'detail', 'Only deprecated modules can be deleted.'); END IF;
  DELETE FROM public.system_modules WHERE module_key = p_module_key;
  RETURN jsonb_build_object('success', true, 'module_key', p_module_key);
END;

$function$;

CREATE OR REPLACE FUNCTION public.detect_long_stops(p_token uuid, p_session_id uuid, p_threshold_minutes integer DEFAULT 15)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    WITH ordered_points AS (
        SELECT
            recorded_at, latitude, longitude,
            LAG(recorded_at) OVER (ORDER BY recorded_at) AS prev_time,
            LAG(latitude) OVER (ORDER BY recorded_at) AS prev_lat,
            LAG(longitude) OVER (ORDER BY recorded_at) AS prev_lng,
            EXTRACT(EPOCH FROM (recorded_at - LAG(recorded_at) OVER (ORDER BY recorded_at))) / 60 AS gap_minutes
        FROM public.tracking_points
        WHERE session_id = p_session_id
        ORDER BY recorded_at
    ),
    stops AS (
        SELECT
            prev_time AS stop_start,
            recorded_at AS stop_end,
            gap_minutes,
            prev_lat AS latitude,
            prev_lng AS longitude
        FROM ordered_points
        WHERE gap_minutes >= p_threshold_minutes
    )
    SELECT jsonb_build_object(
        'stops', COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.stop_start) FROM stops s), '[]'::jsonb),
        'total_stops', (SELECT COUNT(*) FROM stops)
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.end_break(p_token uuid, p_session_id uuid, p_break_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_break record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    IF public.is_employee_executive(v_employee_id) THEN
        RETURN jsonb_build_object('error', 'EXECUTIVE_NOT_AUTHORIZED');
    END IF;

    SELECT * INTO v_break FROM public.workday_breaks
    WHERE id = p_break_id AND session_id = p_session_id AND employee_id = v_employee_id AND break_end IS NULL;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'BREAK_NOT_FOUND'); END IF;

    UPDATE public.workday_breaks
    SET break_end = now(),
        duration_seconds = EXTRACT(EPOCH FROM (now() - break_start))::integer
    WHERE id = p_break_id;

    RETURN jsonb_build_object('break_id', p_break_id, 'break_end', now(), 'duration_seconds',
        EXTRACT(EPOCH FROM (now() - v_break.break_start))::integer);
END;

$function$;

CREATE OR REPLACE FUNCTION public.end_workday(p_token uuid, p_session_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_device_status jsonb DEFAULT NULL::jsonb, p_close_reason text DEFAULT 'manual_close'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_workday record;
    v_open_breaks int := 0;
    v_break_id uuid;
    v_start_time time;
    v_end_time time;
    v_late_thresh int;
    v_early_thresh int;
    v_attendance_status text := 'unknown';
    v_late_min int := 0;
    v_early_min int := 0;
    v_distance integer;
    v_schedule_type text;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    SELECT * INTO v_workday FROM public.workday_sessions
    WHERE id = p_session_id AND employee_id = v_employee_id AND status IN ('active', 'inactive_warning');
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'SESSION_NOT_FOUND'); END IF;

    -- Read schedule_type from the employee's work policy (snapshot via work_policy_id)
    SELECT ewp.schedule_type INTO v_schedule_type
    FROM public.employee_work_policies ewp
    WHERE ewp.id = v_workday.work_policy_id;
    -- Default to 'flexible' if no policy found (should not happen for new sessions)
    IF v_schedule_type IS NULL THEN v_schedule_type := 'flexible'; END IF;

    -- GPS optional for auto-close; required for manual close
    IF p_close_reason = 'manual_close' AND (p_latitude IS NULL OR p_longitude IS NULL) THEN
        RETURN jsonb_build_object('error', 'GPS_REQUIRED');
    END IF;

    -- Auto-close open breaks
    FOR v_break_id IN SELECT id FROM public.workday_breaks
        WHERE session_id = p_session_id AND break_end IS NULL
    LOOP
        UPDATE public.workday_breaks SET
            break_end = now(),
            duration_seconds = EXTRACT(EPOCH FROM (now() - break_start))::int,
            auto_closed = true
        WHERE id = v_break_id;
        v_open_breaks := v_open_breaks + 1;
    END LOOP;

    -- Calculate attendance status based on schedule_type
    IF p_close_reason = 'manual_close' THEN
        IF v_schedule_type = 'fixed_shift' THEN
            -- Fixed-shift: use global workday_settings for late/early calculation
            SELECT official_start_time, official_end_time, late_threshold_minutes, early_departure_threshold_minutes
            INTO v_start_time, v_end_time, v_late_thresh, v_early_thresh
            FROM public.workday_settings LIMIT 1;

            IF v_workday.start_time::time > v_start_time + COALESCE(v_late_thresh, 0) * interval '1 minute' THEN
                v_attendance_status := 'late';
                v_late_min := EXTRACT(EPOCH FROM (v_workday.start_time::time - v_start_time)) / 60;
            END IF;

            IF v_attendance_status = 'unknown' AND now()::time < v_end_time - COALESCE(v_early_thresh, 0) * interval '1 minute' THEN
                v_attendance_status := 'early_departure';
                v_early_min := EXTRACT(EPOCH FROM (v_end_time - now()::time)) / 60;
            END IF;

            IF v_attendance_status = 'unknown' THEN
                v_attendance_status := 'ontime';
            END IF;
        ELSE
            -- Flexible or hourly: always ontime, no late/early calculation
            v_attendance_status := 'ontime';
        END IF;
    ELSIF p_close_reason IN ('no_activity_timeout', 'day_rollover') THEN
        v_attendance_status := 'auto_closed';
    END IF;

    -- Calculate and persist distance
    v_distance := public.calculate_session_distance(p_session_id);

    UPDATE public.workday_sessions SET
        end_time = CASE WHEN p_close_reason = 'manual_close' THEN now()
                        ELSE COALESCE(last_seen_at, now()) END,
        end_latitude = COALESCE(p_latitude, v_workday.start_latitude),
        end_longitude = COALESCE(p_longitude, v_workday.start_longitude),
        end_device_status = p_device_status,
        status = 'completed',
        attendance_status = v_attendance_status,
        late_minutes = v_late_min,
        early_departure_minutes = v_early_min,
        close_reason = p_close_reason,
        total_distance_meters = v_distance,
        updated_at = now()
    WHERE id = p_session_id;

    IF p_latitude IS NOT NULL THEN
        INSERT INTO public.tracking_points (session_id, employee_id, latitude, longitude, recorded_at, point_type)
        VALUES (p_session_id, v_employee_id, p_latitude, p_longitude, now(), 'end');
    END IF;

    RETURN jsonb_build_object(
        'ok', true, 'end_time', now(),
        'close_reason', p_close_reason,
        'open_breaks_closed', v_open_breaks,
        'attendance_status', v_attendance_status,
        'total_distance_meters', v_distance,
        'schedule_type', v_schedule_type
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.enrich_location(p_token uuid, p_location_id uuid, p_governorate_id uuid DEFAULT NULL::uuid, p_city_id uuid DEFAULT NULL::uuid, p_road text DEFAULT NULL::text, p_formatted_address text DEFAULT NULL::text, p_geocoding_provider text DEFAULT 'nominatim'::text, p_enrichment_version integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.employee_id IS NULL AND v_session.customer_id IS NULL THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN');
  END IF;
  UPDATE unified_locations
  SET
    governorate_id      = COALESCE(p_governorate_id, governorate_id),
    city_id             = COALESCE(p_city_id, city_id),
    road                = COALESCE(p_road, road),
    formatted_address   = COALESCE(p_formatted_address, formatted_address),
    enriched_at         = now(),
    enrichment_status   = 'completed',
    geocoding_provider  = p_geocoding_provider,
    enrichment_version  = p_enrichment_version
  WHERE id = p_location_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;
  RETURN jsonb_build_object('success', true, 'id', p_location_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.ensure_baseline(p_token uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 DECLARE v_emp_id uuid; v_baseline timestamptz; BEGIN SELECT e.id INTO v_emp_id FROM app.sessions s JOIN public.employees e ON e.identity_id = s.identity_id WHERE s.token = p_token AND s.expires_at > now() LIMIT 1; IF NOT FOUND THEN RETURN now(); END IF; INSERT INTO public.employee_baselines (employee_id, baseline_at) VALUES (v_emp_id, now()) ON CONFLICT (employee_id) DO NOTHING; SELECT baseline_at INTO v_baseline FROM public.employee_baselines WHERE employee_id = v_emp_id; RETURN v_baseline; END; 
$function$;

CREATE OR REPLACE FUNCTION public.ensure_system_customer_owner()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

     DECLARE
       v_employee_id uuid;
       v_identity_id uuid;
     BEGIN
       SELECT id INTO v_employee_id FROM employees WHERE code = 'SYS-OWNER' LIMIT 1;
       IF v_employee_id IS NOT NULL THEN RETURN v_employee_id; END IF;
       v_identity_id := gen_random_uuid();
       v_employee_id := gen_random_uuid();
       INSERT INTO identities (id, phone, password_hash, identity_type, is_active)
       VALUES (v_identity_id, '0000000000', extensions.crypt('000000', extensions.gen_salt('bf')), 'employee', true);
       INSERT INTO employees (id, identity_id, code, full_name, is_active)
       VALUES (v_employee_id, v_identity_id, 'SYS-OWNER', 'الأهرام', true);
       RETURN v_employee_id;
     END;
     
$function$;

CREATE OR REPLACE FUNCTION public.fn_create_notification_bulk(p_recipients uuid[], p_type character varying, p_title character varying, p_message text, p_entity_type character varying DEFAULT NULL::character varying, p_entity_id uuid DEFAULT NULL::uuid, p_target_path text DEFAULT NULL::text, p_event_key_prefix text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_rec uuid;
  v_key text;
BEGIN
  FOREACH v_rec IN ARRAY p_recipients LOOP
    v_key := CASE WHEN p_event_key_prefix IS NOT NULL THEN p_event_key_prefix || ':' || v_rec::text ELSE NULL END;
    PERFORM public.fn_create_notification(v_rec, p_type, p_title, p_message, p_entity_type, p_entity_id, p_target_path, v_key);
  END LOOP;
END;

$function$;

CREATE OR REPLACE FUNCTION public.fn_enrich_customer_location(p_customer_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_accuracy_meters numeric DEFAULT NULL::numeric, p_formatted_address text DEFAULT NULL::text, p_accuracy_level location_accuracy_level DEFAULT 'GPS'::location_accuracy_level)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_cur_location_id   uuid;
  v_cur_lat           numeric;
  v_cur_lng           numeric;
  v_cur_fmt_addr      text;

  v_addr_id           uuid;
  v_ex_city           varchar(100);
  v_ex_gov            varchar(100);
  v_ex_city_id        uuid;
  v_ex_gov_id         uuid;
  v_ex_lat            numeric;
  v_ex_lng            numeric;

  v_new_location_id   uuid;
  v_fmt               text;

  v_city_id           uuid;
  v_city_name         varchar(200);
  v_gov_id_from_city  uuid;
  v_gov_id            uuid;
  v_gov_name          varchar(200);
  v_ref_lat           numeric;
  v_ref_lng           numeric;
BEGIN
  -- ── Read current customer state ──
  SELECT location_id INTO v_cur_location_id
  FROM customers WHERE id = p_customer_id;

  SELECT city, governorate, city_id, governorate_id, id, latitude, longitude
  INTO v_ex_city, v_ex_gov, v_ex_city_id, v_ex_gov_id, v_addr_id, v_ex_lat, v_ex_lng
  FROM customer_addresses
  WHERE customer_id = p_customer_id AND is_default = true;

  -- ========================================================================
  -- GPS ENRICHMENT (customers.location_id → unified_locations)
  -- ========================================================================
  IF p_latitude IS NOT NULL AND p_longitude IS NOT NULL THEN
    IF v_cur_location_id IS NULL THEN
      v_new_location_id := gen_random_uuid();
      INSERT INTO unified_locations (id, latitude, longitude, accuracy_meters, formatted_address, captured_at)
      VALUES (v_new_location_id, p_latitude, p_longitude, p_accuracy_meters, p_formatted_address, now());
      UPDATE customers SET location_id = v_new_location_id, updated_at = now()
      WHERE id = p_customer_id;
    ELSE
      SELECT latitude, longitude, formatted_address
      INTO v_cur_lat, v_cur_lng, v_cur_fmt_addr
      FROM unified_locations WHERE id = v_cur_location_id;

      UPDATE unified_locations
      SET
        latitude         = COALESCE(NULLIF(latitude, 0), p_latitude),
        longitude        = COALESCE(NULLIF(longitude, 0), p_longitude),
        accuracy_meters  = CASE WHEN accuracy_meters IS NULL THEN p_accuracy_meters ELSE accuracy_meters END,
        formatted_address = COALESCE(formatted_address, p_formatted_address)
      WHERE id = v_cur_location_id;
    END IF;
  END IF;

  -- ── Resolve the formatted_address for city/gov matching ──
  v_fmt := p_formatted_address;
  IF v_fmt IS NULL THEN
    SELECT formatted_address INTO v_fmt
    FROM unified_locations
    WHERE id = COALESCE(v_cur_location_id, v_new_location_id);
  END IF;

  -- ========================================================================
  -- CITY / GOVERNORATE + COORDINATES ENRICHMENT (customer_addresses)
  -- ========================================================================
  IF (v_ex_city IS NULL OR v_ex_city = '' OR v_ex_gov IS NULL OR v_ex_gov = ''
      OR v_ex_lat IS NULL OR v_ex_lng IS NULL)
    AND (v_fmt IS NOT NULL AND v_fmt != ''
         OR p_latitude IS NOT NULL AND p_longitude IS NOT NULL)
  THEN
    -- ── Attempt 1: word-boundary match on city → infer governorate ──
    SELECT rc.id, rc.name_ar, rc.governorate_id
    INTO v_city_id, v_city_name, v_gov_id_from_city
    FROM reference_cities rc
    WHERE v_fmt ~* ('\m' || rc.name_ar || '\M')
    ORDER BY rc.display_order
    LIMIT 1;

    IF v_city_id IS NOT NULL THEN
      SELECT rg.id, rg.name_ar INTO v_gov_id, v_gov_name
      FROM reference_governorates rg WHERE rg.id = v_gov_id_from_city;
    END IF;

    -- ── Attempt 2: word-boundary match on governorate ──
    IF v_gov_id IS NULL THEN
      SELECT rg.id, rg.name_ar INTO v_gov_id, v_gov_name
      FROM reference_governorates rg
      WHERE v_fmt ~* ('\m' || rg.name_ar || '\M')
      ORDER BY rg.display_order
      LIMIT 1;
    END IF;

    -- ── Attempt 3: ILIKE fallback on city ──
    IF v_city_id IS NULL THEN
      SELECT rc.id, rc.name_ar INTO v_city_id, v_city_name
      FROM reference_cities rc
      WHERE (v_gov_id IS NULL OR rc.governorate_id = v_gov_id)
        AND v_fmt ILIKE '%' || rc.name_ar || '%'
      ORDER BY rc.display_order
      LIMIT 1;

      IF v_city_id IS NOT NULL AND v_gov_id IS NULL THEN
        SELECT rg.id, rg.name_ar INTO v_gov_id, v_gov_name
        FROM reference_governorates rg
        WHERE rg.id = (SELECT governorate_id FROM reference_cities WHERE id = v_city_id);
      END IF;
    END IF;

    -- ── Attempt 4: ILIKE fallback on governorate ──
    IF v_gov_id IS NULL THEN
      SELECT rg.id, rg.name_ar INTO v_gov_id, v_gov_name
      FROM reference_governorates rg
      WHERE v_fmt ILIKE '%' || rg.name_ar || '%'
      ORDER BY rg.display_order
      LIMIT 1;
    END IF;

    -- ── Resolve reference coordinates from matched city or governorate ──
    v_ref_lat := COALESCE(
      (SELECT rc.latitude FROM reference_cities rc WHERE rc.id = v_city_id),
      (SELECT rg.latitude FROM reference_governorates rg WHERE rg.id = v_gov_id)
    );
    v_ref_lng := COALESCE(
      (SELECT rc.longitude FROM reference_cities rc WHERE rc.id = v_city_id),
      (SELECT rg.longitude FROM reference_governorates rg WHERE rg.id = v_gov_id)
    );

    -- ── UPSERT default address with latitude/longitude ──
    INSERT INTO customer_addresses (
      customer_id, address_line1,
      city, governorate, city_id, governorate_id,
      latitude, longitude,
      address_source, location_accuracy, address_updated_at,
      is_default
    ) VALUES (
      p_customer_id,
      COALESCE(NULLIF(v_fmt, ''), ''),
      COALESCE(NULLIF(v_city_name, ''), v_ex_city, ''),
      COALESCE(NULLIF(v_gov_name, ''), v_ex_gov, ''),
      COALESCE(v_city_id, v_ex_city_id),
      COALESCE(v_gov_id, v_ex_gov_id),
      COALESCE(v_ex_lat, p_latitude, v_ref_lat),
      COALESCE(v_ex_lng, p_longitude, v_ref_lng),
      CASE WHEN p_latitude IS NOT NULL THEN 'gps'::address_source_type ELSE 'mixed'::address_source_type END,
      p_accuracy_level, now(),
      true
    )
    ON CONFLICT (customer_id) WHERE is_default = true
    DO UPDATE SET
      city             = COALESCE(NULLIF(customer_addresses.city, ''), EXCLUDED.city),
      governorate      = COALESCE(NULLIF(customer_addresses.governorate, ''), EXCLUDED.governorate),
      city_id          = COALESCE(customer_addresses.city_id, EXCLUDED.city_id),
      governorate_id   = COALESCE(customer_addresses.governorate_id, EXCLUDED.governorate_id),
      latitude         = COALESCE(customer_addresses.latitude, EXCLUDED.latitude, v_ref_lat),
      longitude        = COALESCE(customer_addresses.longitude, EXCLUDED.longitude, v_ref_lng),
      address_source   = CASE WHEN customer_addresses.address_source IS NULL THEN EXCLUDED.address_source ELSE customer_addresses.address_source END,
      location_accuracy = CASE WHEN customer_addresses.location_accuracy IS NULL THEN EXCLUDED.location_accuracy ELSE customer_addresses.location_accuracy END,
      address_updated_at = now(),
      street_address   = COALESCE(customer_addresses.street_address,
                           CASE WHEN EXCLUDED.address_line1 IS NOT NULL AND EXCLUDED.address_line1 != ''
                           THEN LEFT(EXCLUDED.address_line1, 255) END);
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.geocode_customer_address(p_token uuid, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_addr_id uuid;
  v_gov_id uuid;
  v_city_id uuid;
  v_gov_lat numeric;
  v_gov_lng numeric;
  v_city_lat numeric;
  v_city_lng numeric;
  v_existing_lat numeric;
  v_existing_lng numeric;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Find the customer's default address
  SELECT id, governorate_id, city_id, latitude, longitude
  INTO v_addr_id, v_gov_id, v_city_id, v_existing_lat, v_existing_lng
  FROM customer_addresses
  WHERE customer_id = p_customer_id AND is_default = true
  LIMIT 1;

  -- If no default address, nothing to geocode
  IF v_addr_id IS NULL THEN
    RETURN jsonb_build_object('status', 'no_address');
  END IF;

  -- If already has coordinates, skip
  IF v_existing_lat IS NOT NULL AND v_existing_lng IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'already_geocoded', 'latitude', v_existing_lat, 'longitude', v_existing_lng);
  END IF;

  -- Priority: city center > governorate center
  SELECT latitude, longitude INTO v_city_lat, v_city_lng
  FROM reference_cities WHERE id = v_city_id;

  SELECT latitude, longitude INTO v_gov_lat, v_gov_lng
  FROM reference_governorates WHERE id = v_gov_id;

  IF v_city_lat IS NOT NULL AND v_city_lng IS NOT NULL THEN
    UPDATE customer_addresses
    SET latitude = v_city_lat, longitude = v_city_lng,
        location_accuracy = 'GEOCODED'::location_accuracy_level,
        address_updated_at = now()
    WHERE id = v_addr_id;
    RETURN jsonb_build_object('status', 'geocoded', 'latitude', v_city_lat, 'longitude', v_city_lng);
  END IF;

  IF v_gov_lat IS NOT NULL AND v_gov_lng IS NOT NULL THEN
    UPDATE customer_addresses
    SET latitude = v_gov_lat, longitude = v_gov_lng,
        location_accuracy = 'GOVERNORATE_CENTER'::location_accuracy_level,
        address_updated_at = now()
    WHERE id = v_addr_id;
    RETURN jsonb_build_object('status', 'geocoded_gov', 'latitude', v_gov_lat, 'longitude', v_gov_lng);
  END IF;

  RETURN jsonb_build_object('status', 'no_coordinates');
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_alerts(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 DECLARE v_session app.sessions; v_subtree_ids uuid[]; v_settings record; v_interval_seconds int; v_start_time time; v_end_time time; v_active_alerts jsonb; v_resolved_alerts jsonb; BEGIN SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now(); IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF; IF NOT public.check_capability(p_token, 'attendance.view_alerts') THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;  IF public.check_capability(p_token, 'attendance.view_all') THEN v_subtree_ids := NULL; ELSE v_subtree_ids := app.get_subtree_ids(v_session.employee_id); END IF;  SELECT official_start_time, official_end_time, location_interval_seconds INTO v_start_time, v_end_time, v_interval_seconds FROM public.workday_settings LIMIT 1; v_interval_seconds := COALESCE(v_interval_seconds, 300);  WITH active_sessions AS ( SELECT wds.id, wds.employee_id, wds.start_time, e.full_name AS employee_name FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id WHERE wds.date = CURRENT_DATE AND wds.status = 'active' AND (v_subtree_ids IS NULL OR wds.employee_id = ANY(v_subtree_ids)) ), all_employees AS ( SELECT e.id, e.full_name FROM public.employees e WHERE e.is_active = true AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids)) ), not_started AS ( SELECT 'not_started' AS alert_type, ae.id AS employee_id, ae.full_name AS employee_name, 'لم يبدأ يوم العمل' AS title, 'الساعة الآن ' || to_char(now()::time, 'HH:MI') || ' — وقت البدء الرسمي ' || to_char(v_start_time, 'HH:MI') AS description, now() AS detected_at FROM all_employees ae WHERE NOT EXISTS (SELECT 1 FROM public.workday_sessions wds WHERE wds.employee_id = ae.id AND wds.date = CURRENT_DATE) AND CURRENT_TIME > v_start_time + interval '30 minutes' ), open_yesterday AS ( SELECT 'open_yesterday' AS alert_type, wds.employee_id, e.full_name AS employee_name, 'يوم عمل مفتوح من اليوم السابق' AS title, 'بدأ يوم ' || wds.date || ' الساعة ' || to_char(wds.start_time, 'HH:MI') AS description, now() AS detected_at FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id WHERE wds.date < CURRENT_DATE AND wds.status = 'active' ), long_break AS ( SELECT 'long_break' AS alert_type, wb.employee_id, e.full_name AS employee_name, 'استراحة طويلة' AS title, 'في استراحة منذ ' || round(EXTRACT(EPOCH FROM (now() - wb.break_start)) / 60) || ' دقيقة' AS description, wb.break_start AS detected_at FROM public.workday_breaks wb JOIN public.employees e ON e.id = wb.employee_id WHERE wb.break_end IS NULL AND EXTRACT(EPOCH FROM (now() - wb.break_start)) > 3600 ), no_updates AS ( SELECT 'no_updates' AS alert_type, as2.employee_id, as2.employee_name, 'انقطاع متابعة' AS title, 'آخر تحديث منذ أكثر من ' || (v_interval_seconds * 5 / 60) || ' دقيقة' AS description, COALESCE(tp.recorded_at, now()) AS detected_at FROM active_sessions as2 LEFT JOIN LATERAL ( SELECT recorded_at FROM public.tracking_points WHERE employee_id = as2.employee_id AND recorded_at >= CURRENT_DATE ORDER BY recorded_at DESC LIMIT 1 ) tp ON true WHERE tp.recorded_at IS NULL OR tp.recorded_at < now() - ((v_interval_seconds * 5) || ' seconds')::interval ), zero_visits AS ( SELECT 'zero_visits' AS alert_type, as2.employee_id, as2.employee_name, 'لا توجد زيارات اليوم' AS title, 'بدأ اليوم ' || to_char(as2.start_time, 'HH:MI') || ' — 0 زيارات حتى الآن' AS description, now() AS detected_at FROM active_sessions as2 WHERE NOT EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = as2.employee_id AND v.check_in_at::date = CURRENT_DATE) ), zero_orders AS ( SELECT 'zero_orders' AS alert_type, as2.employee_id, as2.employee_name, 'لا توجد طلبات اليوم' AS title, 'بدأ اليوم ' || to_char(as2.start_time, 'HH:MI') || ' — 0 طلبات بعد 4 ساعات من العمل' AS description, now() AS detected_at FROM active_sessions as2 WHERE as2.start_time < now() - interval '4 hours' AND NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.owner_id = as2.employee_id AND o.created_at::date = CURRENT_DATE) ) SELECT jsonb_build_object( 'active_alerts', COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.detected_at DESC) FROM ( SELECT * FROM not_started UNION ALL SELECT * FROM open_yesterday UNION ALL SELECT * FROM long_break UNION ALL SELECT * FROM no_updates UNION ALL SELECT * FROM zero_visits UNION ALL SELECT * FROM zero_orders ) t), '[]'::jsonb), 'resolved_alerts', '[]'::jsonb ) INTO v_active_alerts;  RETURN jsonb_build_object('active_alerts', COALESCE(v_active_alerts->'active_alerts', '[]'::jsonb), 'resolved_alerts', '[]'::jsonb); END; 
$function$;

CREATE OR REPLACE FUNCTION public.get_all_capabilities(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object('id', id, 'code', code, 'name', name, 'description', description, 'group', "group")
    ORDER BY "group", name
  ) INTO v_result FROM capabilities;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_attendance_analysis(p_token uuid, p_from date, p_to date, p_employee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    SELECT jsonb_build_object(
        'summary', jsonb_build_object(
            'total_work_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND status = 'completed' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'ontime_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'ontime' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'late_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'late' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'total_late_minutes', (SELECT COALESCE(SUM(late_minutes), 0) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'late' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'early_departure_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'early_departure' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'total_early_departure_minutes', (SELECT COALESCE(SUM(early_departure_minutes), 0) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'early_departure' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
            'absent_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'absent' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids)))),
        'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', sub.employee_id, 'name', sub.employee_name,
            'work_days', sub.work_days, 'ontime_days', sub.ontime_days, 'late_days', sub.late_days,
            'late_minutes', sub.late_minutes, 'early_departure_days', sub.early_departure_days,
            'early_departure_minutes', sub.early_departure_minutes, 'absent_days', sub.absent_days,
            'compliance_rate', CASE WHEN sub.work_days > 0 THEN ROUND((sub.ontime_days::numeric / sub.work_days) * 100, 1) ELSE 0 END
        ) ORDER BY sub.compliance_rate DESC)), '[]'::jsonb)
    ) INTO v_result
    FROM (SELECT wds.employee_id, e.full_name AS employee_name, COUNT(*) AS work_days,
        COUNT(*) FILTER (WHERE wds.attendance_status = 'ontime') AS ontime_days,
        COUNT(*) FILTER (WHERE wds.attendance_status = 'late') AS late_days,
        COALESCE(SUM(wds.late_minutes) FILTER (WHERE wds.attendance_status = 'late'), 0) AS late_minutes,
        COUNT(*) FILTER (WHERE wds.attendance_status = 'early_departure') AS early_departure_days,
        COALESCE(SUM(wds.early_departure_minutes) FILTER (WHERE wds.attendance_status = 'early_departure'), 0) AS early_departure_minutes,
        COUNT(*) FILTER (WHERE wds.attendance_status IN ('absent', 'unknown')) AS absent_days
        FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id
        WHERE wds.date >= p_from AND wds.date <= p_to AND wds.status = 'completed'
        AND (p_employee_ids IS NULL OR wds.employee_id = ANY(p_employee_ids))
        GROUP BY wds.employee_id, e.full_name) sub;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_attendance_health(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    SELECT jsonb_build_object(
        'today', jsonb_build_object(
            'active_sessions', (SELECT COUNT(*) FROM public.workday_sessions WHERE status = 'active' AND date = CURRENT_DATE),
            'completed_sessions', (SELECT COUNT(*) FROM public.workday_sessions WHERE status = 'completed' AND date = CURRENT_DATE),
            'auto_closed_sessions', (SELECT COUNT(*) FROM public.workday_sessions WHERE status = 'completed' AND attendance_status = 'auto_closed' AND date = CURRENT_DATE),
            'warning_events', (SELECT COUNT(*) FROM public.attendance_audit_log WHERE event_type IN ('warning_sent','warning_cleared') AND created_at >= CURRENT_DATE),
            'recovery_events', (SELECT COUNT(*) FROM public.session_recovery_log WHERE recovered_at >= CURRENT_DATE)
        ),
        'month', jsonb_build_object(
            'auto_closed_count', (SELECT COUNT(*) FROM public.workday_sessions WHERE status = 'completed' AND attendance_status = 'auto_closed' AND updated_at >= date_trunc('month', CURRENT_DATE)),
            'recovery_count', (SELECT COUNT(*) FROM public.session_recovery_log WHERE recovered_at >= date_trunc('month', CURRENT_DATE)),
            'avg_work_hours', (SELECT COALESCE(ROUND(AVG(EXTRACT(EPOCH FROM (end_time - start_time)) / 3600), 1), 0) FROM public.workday_sessions WHERE status = 'completed' AND end_time IS NOT NULL AND start_time IS NOT NULL AND date >= date_trunc('month', CURRENT_DATE)),
            'total_sessions', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= date_trunc('month', CURRENT_DATE)),
            'completed_sessions', (SELECT COUNT(*) FROM public.workday_sessions WHERE status = 'completed' AND date >= date_trunc('month', CURRENT_DATE))
        ),
        'employees_with_issues', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'employee_code', e.code,
                'employee_name', e.full_name,
                'session_id', wds.id,
                'date', wds.date,
                'status', wds.status,
                'issue', CASE WHEN wds.status = 'active' AND wds.date < CURRENT_DATE THEN 'stale_session'
                              WHEN wds.status = 'active' AND wds.date = CURRENT_DATE THEN 'currently_active'
                              ELSE 'unknown' END
            )), '[]'::jsonb)
            FROM public.workday_sessions wds
            JOIN public.employees e ON e.id = wds.employee_id
            WHERE (wds.status = 'active' AND wds.date < CURRENT_DATE)
               OR (wds.status = 'active' AND wds.date = CURRENT_DATE)
        )
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_auto_closed_sessions_month(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    SELECT jsonb_build_object(
        'total_count', COUNT(*),
        'by_reason', (
            SELECT jsonb_object_agg(ws.close_reason, cnt)
            FROM (
                SELECT ws.close_reason, COUNT(*) AS cnt
                FROM public.workday_sessions ws
                WHERE ws.status = 'completed'
                  AND ws.close_reason IN ('no_activity_timeout', 'day_rollover')
                  AND ws.updated_at >= date_trunc('month', CURRENT_DATE)
                  AND ws.updated_at < date_trunc('month', CURRENT_DATE) + interval '1 month'
                GROUP BY ws.close_reason
            ) ws
        ),
        'details', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'employee_name', e.full_name,
                    'employee_code', e.code,
                    'close_reason', ws.close_reason,
                    'last_seen_at', ws.last_seen_at,
                    'auto_closed_at', ws.updated_at,
                    'date', ws.date
                )
                ORDER BY ws.updated_at DESC
            )
            FROM public.workday_sessions ws
            JOIN public.employees e ON e.id = ws.employee_id
            WHERE ws.status = 'completed'
              AND ws.close_reason IN ('no_activity_timeout', 'day_rollover')
              AND ws.updated_at >= date_trunc('month', CURRENT_DATE)
              AND ws.updated_at < date_trunc('month', CURRENT_DATE) + interval '1 month'
        )
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_auto_closed_sessions_today(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'employee_name', e.full_name,
            'employee_code', e.code,
            'close_reason', ws.close_reason,
            'last_seen_at', ws.last_seen_at,
            'auto_closed_at', ws.updated_at,
            'start_time', ws.start_time,
            'date', ws.date
        )
        ORDER BY ws.updated_at DESC
    ) INTO v_result
    FROM public.workday_sessions ws
    JOIN public.employees e ON e.id = ws.employee_id
    WHERE ws.status = 'completed'
      AND ws.close_reason IN ('no_activity_timeout', 'day_rollover')
      AND ws.updated_at >= CURRENT_DATE
      AND ws.updated_at < CURRENT_DATE + interval '1 day';

    RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_collection_followup_queue(p_token uuid)
 RETURNS TABLE(id uuid, customer_name character varying, amount numeric, method character varying, status character varying, collected_at timestamp with time zone, created_at timestamp with time zone, owner_name character varying, days_since_creation bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT c.id, cu.company_name, c.amount, c.method, c.status, c.collected_at, c.created_at, NULL::varchar, EXTRACT(DAY FROM now() - c.created_at)::bigint FROM public.collections c JOIN public.customers cu ON cu.id = c.customer_id WHERE c.customer_id = v_session.customer_id ORDER BY c.created_at DESC;
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY SELECT c.id, cu.company_name, c.amount, c.method, c.status, c.collected_at, c.created_at, e.code, EXTRACT(DAY FROM now() - c.created_at)::bigint FROM public.collections c JOIN public.customers cu ON cu.id = c.customer_id LEFT JOIN public.employees e ON e.id = cu.owner_id WHERE cu.owner_id = ANY(v_visible) ORDER BY c.created_at DESC;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_collection_report(p_token uuid, p_grouping character varying DEFAULT 'day'::character varying, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF p_grouping = 'month' THEN
    WITH t AS (
      SELECT TO_CHAR(collected_at, 'YYYY-MM') as period,
             COUNT(id) as count,
             COALESCE(SUM(amount), 0) as total_amount
      FROM collections
      WHERE status = 'approved'
        AND (p_date_from IS NULL OR collected_at >= p_date_from)
        AND (p_date_to IS NULL OR collected_at <= p_date_to)
      GROUP BY TO_CHAR(collected_at, 'YYYY-MM')
    )
    SELECT jsonb_agg(
      jsonb_build_object('period', period, 'count', count, 'total_amount', total_amount)
      ORDER BY period
    ) INTO v_result FROM t;
  ELSIF p_grouping = 'week' THEN
    WITH t AS (
      SELECT TO_CHAR(collected_at, 'IYYY-"W"IW') as period,
             COUNT(id) as count,
             COALESCE(SUM(amount), 0) as total_amount
      FROM collections
      WHERE status = 'approved'
        AND (p_date_from IS NULL OR collected_at >= p_date_from)
        AND (p_date_to IS NULL OR collected_at <= p_date_to)
      GROUP BY TO_CHAR(collected_at, 'IYYY-"W"IW')
    )
    SELECT jsonb_agg(
      jsonb_build_object('period', period, 'count', count, 'total_amount', total_amount)
      ORDER BY period
    ) INTO v_result FROM t;
  ELSE
    WITH t AS (
      SELECT collected_at::date::text as period,
             COUNT(id) as count,
             COALESCE(SUM(amount), 0) as total_amount
      FROM collections
      WHERE status = 'approved'
        AND (p_date_from IS NULL OR collected_at >= p_date_from)
        AND (p_date_to IS NULL OR collected_at <= p_date_to)
      GROUP BY collected_at::date
    )
    SELECT jsonb_agg(
      jsonb_build_object('period', period, 'count', count, 'total_amount', total_amount)
      ORDER BY period
    ) INTO v_result FROM t;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_command_center(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_modules jsonb; v_decisions jsonb; v_requests jsonb; v_summary jsonb;
  v_production_ready int; v_total_modules int; v_healthy int; v_degraded int; v_down int; v_broken int;
  v_total_decisions int; v_verified_decisions int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only');
  END IF;
  SELECT COALESCE(jsonb_agg(m ORDER BY CASE WHEN m.status = 'broken' THEN 0 WHEN m.health_status = 'down' THEN 1 WHEN m.health_status = 'degraded' THEN 2 ELSE 3 END, m.readiness_score DESC), '[]'::jsonb) FROM (
    SELECT id, module_key, display_name, description, icon, status, implementation_level, validated_at, broken_since, deprecated_at, owner_approved, routes, core_rpcs, core_tables, services, page_dirs, pipeline_steps, pipeline_health_pct, last_health_check, health_status, readiness_score, business_priority, kb_file, decisions_total, decisions_verified, decisions_pct, depends_on, created_at, updated_at FROM public.system_modules
  ) m INTO v_modules;
  SELECT COALESCE(jsonb_agg(d ORDER BY d.module_key, d.created_at), '[]'::jsonb) FROM (
    SELECT id, module_key, decision_text, rationale, category, source_file, source_line, verifiable, verification_method, verified, verified_at, failure_reason, decided_at, tags, created_at FROM public.owner_decisions
  ) d INTO v_decisions;
  SELECT COALESCE(jsonb_agg(r ORDER BY CASE WHEN r.priority = 'critical' THEN 0 WHEN r.priority = 'high' THEN 1 WHEN r.priority = 'medium' THEN 2 WHEN r.priority = 'low' THEN 3 ELSE 4 END, r.approved_at DESC), '[]'::jsonb) FROM (
    SELECT id, title, description, status, priority, module_key, source_file, source_line, approved_at, depends_on, notes, tags, created_at, updated_at FROM public.owner_requests
  ) r INTO v_requests;
  SELECT COUNT(*) INTO v_total_modules FROM public.system_modules;
  SELECT COUNT(*) INTO v_healthy FROM public.system_modules WHERE health_status = 'healthy';
  SELECT COUNT(*) INTO v_degraded FROM public.system_modules WHERE health_status = 'degraded';
  SELECT COUNT(*) INTO v_down FROM public.system_modules WHERE health_status = 'down';
  SELECT COUNT(*) INTO v_broken FROM public.system_modules WHERE status = 'broken';
  SELECT COUNT(*) INTO v_production_ready FROM public.system_modules WHERE readiness_score >= 90 AND owner_approved = true AND pipeline_health_pct = 100 AND health_status = 'healthy';
  SELECT COUNT(*) INTO v_total_decisions FROM public.owner_decisions WHERE verifiable = true;
  SELECT COUNT(*) INTO v_verified_decisions FROM public.owner_decisions WHERE verifiable = true AND verified = true;
  v_summary := jsonb_build_object('total_modules', v_total_modules, 'healthy', v_healthy, 'degraded', v_degraded, 'down', v_down, 'broken', v_broken, 'production_ready', v_production_ready, 'total_verifiable_decisions', v_total_decisions, 'verified_decisions', v_verified_decisions, 'decisions_pct', CASE WHEN v_total_decisions > 0 THEN (v_verified_decisions * 100 / v_total_decisions) ELSE 0 END);
  RETURN jsonb_build_object('modules', v_modules, 'decisions', v_decisions, 'requests', v_requests, 'summary', v_summary);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_command_center_v2(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_modules jsonb; v_decisions jsonb; v_requests jsonb; v_summary jsonb;
  v_required_actions jsonb; v_module_counts jsonb;
  v_production_ready int; v_total_modules int; v_healthy int; v_degraded int; v_down int; v_broken int;
  v_total_decisions int; v_verified_decisions int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only');
  END IF;
  SELECT COALESCE(jsonb_agg(m ORDER BY CASE WHEN m.status = 'broken' THEN 0 WHEN m.health_status = 'down' THEN 1 WHEN m.health_status = 'degraded' THEN 2 ELSE 3 END, m.readiness_score DESC), '[]'::jsonb) FROM (
    SELECT id, module_key, display_name, description, icon, status, implementation_level, validated_at, broken_since, deprecated_at, owner_approved, routes, core_rpcs, core_tables, services, page_dirs, pipeline_steps, pipeline_health_pct, last_health_check, health_status, readiness_score, business_priority, kb_file, decisions_total, decisions_verified, decisions_pct, depends_on, created_at, updated_at FROM public.system_modules
  ) m INTO v_modules;
  SELECT COALESCE(jsonb_agg(d ORDER BY d.module_key, d.created_at), '[]'::jsonb) FROM (
    SELECT id, module_key, decision_text, rationale, category, source_file, source_line, verifiable, verification_method, verified, verified_at, failure_reason, decided_at, tags, created_at FROM public.owner_decisions
  ) d INTO v_decisions;
  SELECT COALESCE(jsonb_agg(r ORDER BY CASE WHEN r.priority = 'critical' THEN 0 WHEN r.priority = 'high' THEN 1 WHEN r.priority = 'medium' THEN 2 WHEN r.priority = 'low' THEN 3 ELSE 4 END, r.approved_at DESC), '[]'::jsonb) FROM (
    SELECT id, title, description, status, priority, module_key, source_file, source_line, approved_at, depends_on, notes, tags, created_at, updated_at FROM public.owner_requests
  ) r INTO v_requests;
  v_required_actions := jsonb_build_array(
    jsonb_build_object('label', 'طلبات تنتظر الاعتماد', 'count', (SELECT COUNT(*) FROM public.orders WHERE status IN ('submitted', 'reviewing')), 'link', '/orders/approval-queue'),
    jsonb_build_object('label', 'عملاء تجاوزوا الحد الائتماني', 'count', (SELECT COUNT(*) FROM public.customer_credit_accounts WHERE outstanding_credit + reserved_credit > credit_limit AND credit_status = 'active'), 'link', '/credit'),
    jsonb_build_object('label', 'مرتجعات تنتظر القرار', 'count', (SELECT COUNT(*) FROM public.returns WHERE status IN ('pending', 'inspecting')), 'link', '/returns'),
    jsonb_build_object('label', 'زيارات لم يتم إنهاؤها', 'count', (SELECT COUNT(*) FROM public.visits WHERE status = 'active' AND check_out_at IS NULL), 'link', '/visits'),
    jsonb_build_object('label', 'مندوبين بلا زيارات اليوم', 'count', (SELECT COUNT(*) FROM public.employees e WHERE is_active = true AND NOT EXISTS (SELECT 1 FROM public.visits v WHERE v.employee_id = e.id AND v.created_at >= CURRENT_DATE)), 'link', '/supervisor')
  );
  v_module_counts := jsonb_build_object(
    'orders_new', (SELECT COUNT(*) FROM public.orders WHERE created_at >= CURRENT_DATE),
    'customers_active', (SELECT COUNT(*) FROM public.customers WHERE is_active = true),
    'visits_active', (SELECT COUNT(*) FROM public.visits WHERE status = 'active'),
    'credit_due', (SELECT COUNT(*) FROM public.credit_invoices WHERE status = 'overdue'),
    'employees_active', (SELECT COUNT(*) FROM public.employees WHERE is_active = true)
  );
  SELECT COUNT(*) INTO v_total_modules FROM public.system_modules;
  SELECT COUNT(*) INTO v_healthy FROM public.system_modules WHERE health_status = 'healthy';
  SELECT COUNT(*) INTO v_degraded FROM public.system_modules WHERE health_status = 'degraded';
  SELECT COUNT(*) INTO v_down FROM public.system_modules WHERE health_status = 'down';
  SELECT COUNT(*) INTO v_broken FROM public.system_modules WHERE status = 'broken';
  SELECT COUNT(*) INTO v_production_ready FROM public.system_modules WHERE readiness_score >= 90 AND owner_approved = true AND pipeline_health_pct = 100 AND health_status = 'healthy';
  SELECT COUNT(*) INTO v_total_decisions FROM public.owner_decisions WHERE verifiable = true;
  SELECT COUNT(*) INTO v_verified_decisions FROM public.owner_decisions WHERE verifiable = true AND verified = true;
  v_summary := jsonb_build_object('total_modules', v_total_modules, 'healthy', v_healthy, 'degraded', v_degraded, 'down', v_down, 'broken', v_broken, 'production_ready', v_production_ready, 'total_verifiable_decisions', v_total_decisions, 'verified_decisions', v_verified_decisions, 'decisions_pct', CASE WHEN v_total_decisions > 0 THEN (v_verified_decisions * 100 / v_total_decisions) ELSE 0 END);
  RETURN jsonb_build_object('modules', v_modules, 'decisions', v_decisions, 'requests', v_requests, 'summary', v_summary, 'required_actions', v_required_actions, 'module_counts', v_module_counts);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_company_analytics(p_token uuid, p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_total_products integer;
  v_active_products integer;
  v_total_orders integer;
  v_total_revenue decimal;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT COUNT(*) INTO v_total_products FROM products WHERE company_id = p_company_id;
  SELECT COUNT(*) INTO v_active_products FROM products WHERE company_id = p_company_id AND is_active = true;

  SELECT COUNT(*), COALESCE(SUM(oi.total_price), 0)
  INTO v_total_orders, v_total_revenue
  FROM order_items oi
  JOIN products p ON p.id = oi.product_id
  WHERE p.company_id = p_company_id;

  RETURN jsonb_build_object(
    'total_products', v_total_products,
    'active_products', v_active_products,
    'total_order_items', v_total_orders,
    'total_revenue', v_total_revenue
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_company_products(p_token uuid, p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', p.id,
      'product_name', p.product_name,
      'legacy_code', p.legacy_code,
      'is_active', p.is_active,
      'carton_price', p.carton_price,
      'carton_quantity', p.carton_quantity,
      'piece_price', p.piece_price,
      'dozen_price', p.dozen_price,
      'created_at', p.created_at
    ) ORDER BY p.product_name
  ) INTO v_result
  FROM products p
  WHERE p.company_id = p_company_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_company_profile(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_row public.company_profile;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_row FROM public.company_profile WHERE id = 1;
  IF v_row.id IS NULL THEN RETURN json_build_object('error', 'NOT_FOUND'); END IF;

  RETURN json_build_object(
    'success', true,
    'data', json_build_object(
      'company_name', v_row.company_name,
      'company_banner_url', v_row.company_banner_url,
      'facebook_url', v_row.facebook_url,
      'sales_phone_1', v_row.sales_phone_1,
      'sales_phone_2', v_row.sales_phone_2,
      'sales_whatsapp_1', v_row.sales_whatsapp_1,
      'sales_whatsapp_2', v_row.sales_whatsapp_2,
      'technical_support_phone', v_row.technical_support_phone,
      'is_active', v_row.is_active,
      'updated_at', v_row.updated_at
    )
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_completed_workdays_history(p_token uuid, p_from date, p_to date, p_search text DEFAULT NULL::text, p_sort_by text DEFAULT 'total_net_minutes'::text, p_sort_order text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_per_page integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_total_employees int := 0;
    v_offset int;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.check_capability(p_token, 'attendance.view_history') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    v_offset := (p_page - 1) * p_per_page;

    WITH
    visible_employees AS (
        SELECT e.id, e.full_name, e.code, e.identity_id, rpl.name AS role_name
        FROM public.employees e
        LEFT JOIN LATERAL (
            SELECT r.name FROM public.employee_roles er
            JOIN public.roles r ON r.id = er.role_id
            WHERE er.employee_id = e.id
            LIMIT 1
        ) rpl ON true
        WHERE e.is_active = true
        AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        AND (
            p_search IS NULL
            OR e.full_name ILIKE '%' || p_search || '%'
            OR e.code ILIKE '%' || p_search || '%'
        )
    ),
    total_count AS (
        SELECT COUNT(*)::int AS cnt FROM visible_employees
    ),
    -- CANONICAL F5: schedule-aware net minutes
    session_kpis AS (
        SELECT
            wds.employee_id,
            wds.date,
            wds.start_time,
            wds.end_time,
            wds.status,
            wds.attendance_status,
            wds.late_minutes,
            wds.early_departure_minutes,
            wds.total_distance_meters,
            COALESCE(vd.completed_visit_count, 0) AS visit_count,
            GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60) AS duration_minutes,
            COALESCE(wb.break_minutes, 0) AS break_minutes,
            COALESCE(wb.break_count, 0) AS break_count,
            ewp.schedule_type,
            COALESCE(od.order_count, 0) AS order_count,
            COALESCE(od.sales_value, 0) AS sales_value,
            COALESCE(cd.canonical_collection_count, 0) AS collection_count,
            COALESCE(cd.canonical_collected_amount, 0) AS collection_amount,
            COALESCE(nd.new_customer_count, 0) AS new_customer_count,
            COALESCE(tp.tracking_points_count, 0) AS tracking_points_count
        FROM public.workday_sessions wds
        JOIN visible_employees ve ON ve.id = wds.employee_id
        LEFT JOIN public.employee_work_policies ewp ON ewp.employee_id = wds.employee_id
        LEFT JOIN (
            SELECT wb2.session_id,
                COUNT(*)::int AS break_count,
                COALESCE(SUM(COALESCE(wb2.duration_seconds, 0)), 0) / 60.0 AS break_minutes
            FROM public.workday_breaks wb2
            GROUP BY wb2.session_id
        ) wb ON wb.session_id = wds.id
        -- CANONICAL: Visits = public.visits WHERE status='completed'
        LEFT JOIN (
            SELECT v.employee_id,
                v.check_out_at::date AS d,
                COUNT(*)::int AS completed_visit_count
            FROM public.visits v
            WHERE v.status = 'completed'
            GROUP BY v.employee_id, v.check_out_at::date
        ) vd ON vd.employee_id = wds.employee_id AND vd.d = wds.date
        -- CANONICAL F1/F2: orders by created_by (identity_id), submitted_at, exclude draft/cancelled
        LEFT JOIN (
            SELECT o.created_by,
                o.submitted_at::date AS d,
                COUNT(*)::int AS order_count,
                COALESCE(SUM(o.total_amount), 0) AS sales_value
            FROM public.orders o
            WHERE public.is_order_in_statistics(o.status)
            GROUP BY o.created_by, o.submitted_at::date
        ) od ON od.created_by = ve.identity_id AND od.d = wds.date
        -- CANONICAL: Collections = public.collections WHERE status='collected'
        LEFT JOIN (
            SELECT c.created_by,
                c.collected_at::date AS d,
                COUNT(*)::int AS canonical_collection_count,
                COALESCE(SUM(c.amount), 0) AS canonical_collected_amount
            FROM public.collections c
            WHERE c.status = 'collected'
            GROUP BY c.created_by, c.collected_at::date
        ) cd ON cd.created_by = ve.identity_id AND cd.d = wds.date
        LEFT JOIN (
            SELECT c2.owner_id, c2.created_at::date AS d,
                COUNT(*)::int AS new_customer_count
            FROM public.customers c2
            GROUP BY c2.owner_id, c2.created_at::date
        ) nd ON nd.owner_id = wds.employee_id AND nd.d = wds.date
        LEFT JOIN (
            SELECT tp.session_id,
                COUNT(*)::int AS tracking_points_count
            FROM public.tracking_points tp
            GROUP BY tp.session_id
        ) tp ON tp.session_id = wds.id
        WHERE wds.date >= p_from AND wds.date <= p_to
          AND wds.status = 'completed'
    ),
    -- Deduplicate business KPIs by day: multiple sessions per day inflate visit/order/etc counts
    -- Pick one session per day (latest start_time) for business metrics
    deduped_session_kpis AS (
        SELECT *, ROW_NUMBER() OVER (
            PARTITION BY employee_id, date ORDER BY start_time DESC
        ) AS rn
        FROM session_kpis
    ),
    emp_aggregates AS (
        SELECT
            dsk.employee_id,
            COUNT(*) FILTER (WHERE dsk.rn = 1)::int AS total_days,
            -- CANONICAL F5: schedule-aware net minutes (sum across ALL sessions)
            COALESCE(SUM(
                GREATEST(COALESCE(dsk.duration_minutes, 0) -
                    CASE WHEN COALESCE(dsk.schedule_type, 'flexible') = 'fixed_shift'
                        THEN COALESCE(dsk.break_minutes, 0)
                        ELSE 0
                    END, 0)
            )::int, 0) AS total_net_minutes,
            COALESCE(AVG(
                GREATEST(COALESCE(dsk.duration_minutes, 0) -
                    CASE WHEN COALESCE(dsk.schedule_type, 'flexible') = 'fixed_shift'
                        THEN COALESCE(dsk.break_minutes, 0)
                        ELSE 0
                    END, 0)
            )::int, 0) AS avg_net_minutes,
            -- Business KPIs: SUM only one session per day (rn=1) to avoid inflation
            COALESCE(SUM(dsk.order_count) FILTER (WHERE dsk.rn = 1)::int, 0) AS total_orders,
            COALESCE(SUM(dsk.sales_value) FILTER (WHERE dsk.rn = 1)::numeric, 0) AS total_sales_value,
            COALESCE(SUM(dsk.collection_count) FILTER (WHERE dsk.rn = 1)::int, 0) AS total_collection_count,
            COALESCE(SUM(dsk.collection_amount) FILTER (WHERE dsk.rn = 1)::numeric, 0) AS total_collection_amount,
            COALESCE(SUM(dsk.new_customer_count) FILTER (WHERE dsk.rn = 1)::int, 0) AS total_new_customers,
            COALESCE(SUM(dsk.visit_count) FILTER (WHERE dsk.rn = 1)::int, 0) AS total_visits,
            -- Per-session metrics: sum across ALL sessions
            COALESCE(SUM(dsk.total_distance_meters)::int, 0) AS total_distance_meters,
            COALESCE(SUM(dsk.tracking_points_count)::int, 0) AS total_tracking_points,
            COUNT(*) FILTER (WHERE dsk.attendance_status = 'late')::int AS late_count,
            COUNT(*) FILTER (WHERE dsk.attendance_status = 'ontime')::int AS ontime_count,
            COUNT(*) FILTER (WHERE dsk.attendance_status = 'early_departure')::int AS early_departure_count
        FROM deduped_session_kpis dsk
        GROUP BY dsk.employee_id
    ),
    target_months AS (
        SELECT generate_series(
            date_trunc('month', p_from)::date,
            date_trunc('month', p_to)::date,
            '1 month'::interval
        )::date AS month_start
    ),
    month_ranges AS (
        SELECT
            tm.month_start,
            (tm.month_start + INTERVAL '1 month' - INTERVAL '1 day')::date AS month_end,
            EXTRACT(DAY FROM (tm.month_start + INTERVAL '1 month' - INTERVAL '1 day'))::int AS days_in_month,
            GREATEST(0, (LEAST(p_to, (tm.month_start + INTERVAL '1 month' - INTERVAL '1 day')::date) - GREATEST(p_from, tm.month_start) + 1))::int AS overlap_days
        FROM target_months tm
    ),
    prorated_targets AS (
        SELECT
            emt.employee_id,
            COALESCE(SUM(
                CASE WHEN mr.overlap_days > 0 AND emt.sales_target > 0
                    THEN (emt.sales_target::numeric / mr.days_in_month) * mr.overlap_days
                    ELSE 0 END
            ), 0) AS sales_target,
            COALESCE(SUM(
                CASE WHEN mr.overlap_days > 0 AND emt.visits_target > 0
                    THEN (emt.visits_target::numeric / mr.days_in_month) * mr.overlap_days
                    ELSE 0 END
            ), 0) AS visits_target,
            COALESCE(SUM(
                CASE WHEN mr.overlap_days > 0 AND emt.orders_target > 0
                    THEN (emt.orders_target::numeric / mr.days_in_month) * mr.overlap_days
                    ELSE 0 END
            ), 0) AS orders_target,
            COALESCE(SUM(
                CASE WHEN mr.overlap_days > 0 AND emt.collections_target > 0
                    THEN (emt.collections_target::numeric / mr.days_in_month) * mr.overlap_days
                    ELSE 0 END
            ), 0) AS collections_target,
            COALESCE(SUM(
                CASE WHEN mr.overlap_days > 0 AND emt.new_customers_target > 0
                    THEN (emt.new_customers_target::numeric / mr.days_in_month) * mr.overlap_days
                    ELSE 0 END
            ), 0) AS new_customers_target
        FROM public.employee_monthly_targets emt
        CROSS JOIN month_ranges mr
        WHERE emt.target_month = EXTRACT(MONTH FROM mr.month_start)::int
          AND emt.target_year = EXTRACT(YEAR FROM mr.month_start)::int
        GROUP BY emt.employee_id
    ),
    paginated_employees AS (
        SELECT
            ve.id,
            ve.full_name,
            ve.code,
            ve.role_name,
            ea.total_days,
            ea.total_net_minutes,
            ea.avg_net_minutes,
            ea.total_orders,
            ea.total_sales_value,
            ea.total_collection_count,
            ea.total_collection_amount,
            ea.total_new_customers,
            ea.total_visits,
            ea.total_distance_meters,
            ea.total_tracking_points,
            ea.late_count,
            ea.ontime_count,
            ea.early_departure_count,
            CASE WHEN pt.sales_target > 0 THEN ROUND(pt.sales_target::numeric, 2) ELSE NULL END AS sales_target,
            CASE WHEN pt.visits_target > 0 THEN ROUND(pt.visits_target::numeric, 2) ELSE NULL END AS visits_target,
            CASE WHEN pt.orders_target > 0 THEN ROUND(pt.orders_target::numeric, 2) ELSE NULL END AS orders_target,
            CASE WHEN pt.collections_target > 0 THEN ROUND(pt.collections_target::numeric, 2) ELSE NULL END AS collections_target,
            CASE WHEN pt.new_customers_target > 0 THEN ROUND(pt.new_customers_target::numeric, 2) ELSE NULL END AS new_customers_target,
            CASE WHEN COALESCE(pt.sales_target, 0) > 0 THEN ROUND((ea.total_sales_value / pt.sales_target * 100)::numeric, 1) ELSE NULL END AS sales_achievement_pct,
            CASE WHEN COALESCE(pt.visits_target, 0) > 0 THEN ROUND((ea.total_visits::numeric / pt.visits_target * 100)::numeric, 1) ELSE NULL END AS visits_achievement_pct,
            CASE WHEN COALESCE(pt.orders_target, 0) > 0 THEN ROUND((ea.total_orders::numeric / pt.orders_target * 100)::numeric, 1) ELSE NULL END AS orders_achievement_pct,
            CASE WHEN COALESCE(pt.collections_target, 0) > 0 THEN ROUND((ea.total_collection_amount / pt.collections_target * 100)::numeric, 1) ELSE NULL END AS collections_achievement_pct,
            CASE WHEN COALESCE(pt.new_customers_target, 0) > 0 THEN ROUND((ea.total_new_customers::numeric / pt.new_customers_target * 100)::numeric, 1) ELSE NULL END AS new_customers_achievement_pct,
            ROW_NUMBER() OVER (
                ORDER BY
                    CASE WHEN p_sort_by = 'total_net_minutes' AND p_sort_order = 'desc' THEN ea.total_net_minutes END DESC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_net_minutes' AND p_sort_order = 'asc' THEN ea.total_net_minutes END ASC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_sales_value' AND p_sort_order = 'desc' THEN ea.total_sales_value END DESC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_sales_value' AND p_sort_order = 'asc' THEN ea.total_sales_value END ASC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_orders' AND p_sort_order = 'desc' THEN ea.total_orders END DESC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_orders' AND p_sort_order = 'asc' THEN ea.total_orders END ASC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_visits' AND p_sort_order = 'desc' THEN ea.total_visits END DESC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_visits' AND p_sort_order = 'asc' THEN ea.total_visits END ASC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_collection_amount' AND p_sort_order = 'desc' THEN ea.total_collection_amount END DESC NULLS LAST,
                    CASE WHEN p_sort_by = 'total_collection_amount' AND p_sort_order = 'asc' THEN ea.total_collection_amount END ASC NULLS LAST,
                    ea.total_net_minutes DESC NULLS LAST
            ) AS sort_rank
        FROM visible_employees ve
        JOIN emp_aggregates ea ON ea.employee_id = ve.id
        LEFT JOIN prorated_targets pt ON pt.employee_id = ve.id
    ),
    total_emps AS (
        SELECT COUNT(*)::int AS cnt FROM paginated_employees
    ),
    paginated_employee_ids AS (
        SELECT pe.id, pe.full_name, pe.code, pe.role_name,
            pe.total_days, pe.total_net_minutes, pe.avg_net_minutes,
            pe.total_orders, pe.total_sales_value,
            pe.total_collection_count, pe.total_collection_amount,
            pe.total_new_customers, pe.total_visits,
            pe.total_distance_meters, pe.total_tracking_points,
            pe.late_count, pe.ontime_count, pe.early_departure_count,
            pe.sales_target, pe.visits_target, pe.orders_target,
            pe.collections_target, pe.new_customers_target,
            pe.sales_achievement_pct, pe.visits_achievement_pct,
            pe.orders_achievement_pct, pe.collections_achievement_pct,
            pe.new_customers_achievement_pct,
            pe.sort_rank
        FROM paginated_employees pe
        ORDER BY pe.sort_rank
        LIMIT p_per_page OFFSET v_offset
    ),
    paginated_sessions AS (
        SELECT
            sk.employee_id,
            sk.date, sk.start_time, sk.end_time,
            GREATEST(COALESCE(sk.duration_minutes, 0) -
                CASE WHEN COALESCE(sk.schedule_type, 'flexible') = 'fixed_shift'
                    THEN COALESCE(sk.break_minutes, 0)
                    ELSE 0
                END, 0)::int AS net_minutes,
            sk.break_minutes::int,
            sk.break_count,
            sk.visit_count,
            sk.order_count,
            sk.sales_value,
            sk.collection_count,
            sk.collection_amount,
            sk.new_customer_count,
            sk.attendance_status,
            sk.late_minutes,
            sk.early_departure_minutes,
            COALESCE(sk.total_distance_meters, 0)::int AS distance_meters,
            sk.tracking_points_count
        FROM session_kpis sk
        WHERE sk.employee_id = ANY(SELECT pei.id FROM paginated_employee_ids pei)
    ),
    grand_totals AS (
        SELECT
            COUNT(*) FILTER (WHERE rn = 1)::int AS total_days,
            COALESCE(SUM(GREATEST(COALESCE(duration_minutes, 0) -
                CASE WHEN COALESCE(schedule_type, 'flexible') = 'fixed_shift'
                    THEN COALESCE(break_minutes, 0)
                    ELSE 0
                END, 0))::int, 0) AS total_net_minutes,
            COALESCE(SUM(order_count) FILTER (WHERE rn = 1)::int, 0) AS total_orders,
            COALESCE(SUM(sales_value) FILTER (WHERE rn = 1)::numeric, 0) AS total_sales,
            COALESCE(SUM(collection_count) FILTER (WHERE rn = 1)::int, 0) AS total_collections,
            COALESCE(SUM(collection_amount) FILTER (WHERE rn = 1)::numeric, 0) AS total_collection_amount,
            COALESCE(SUM(new_customer_count) FILTER (WHERE rn = 1)::int, 0) AS total_new_customers,
            COALESCE(SUM(visit_count) FILTER (WHERE rn = 1)::int, 0) AS total_visits
        FROM deduped_session_kpis
    )
    SELECT jsonb_build_object(
        'employees', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object(
                'employee_id', pei.id,
                'employee_name', pei.full_name,
                'employee_code', pei.code,
                'role_name', pei.role_name,
                'summary', jsonb_build_object(
                    'total_days', pei.total_days,
                    'total_net_minutes', pei.total_net_minutes,
                    'avg_net_minutes', pei.avg_net_minutes,
                    'total_orders', pei.total_orders,
                    'total_sales_value', pei.total_sales_value,
                    'total_collection_count', pei.total_collection_count,
                    'total_collection_amount', pei.total_collection_amount,
                    'total_new_customers', pei.total_new_customers,
                    'total_visits', pei.total_visits,
                    'total_distance_meters', pei.total_distance_meters,
                    'total_tracking_points', pei.total_tracking_points,
                    'late_count', pei.late_count,
                    'ontime_count', pei.ontime_count,
                    'early_departure_count', pei.early_departure_count
                ),
                'targets', jsonb_build_object(
                    'sales_target', pei.sales_target,
                    'visits_target', pei.visits_target,
                    'orders_target', pei.orders_target,
                    'collections_target', pei.collections_target,
                    'new_customers_target', pei.new_customers_target
                ),
                'achievement', jsonb_build_object(
                    'sales_achievement_pct', pei.sales_achievement_pct,
                    'visits_achievement_pct', pei.visits_achievement_pct,
                    'orders_achievement_pct', pei.orders_achievement_pct,
                    'collections_achievement_pct', pei.collections_achievement_pct,
                    'new_customers_achievement_pct', pei.new_customers_achievement_pct
                ),
                'sessions', COALESCE(
                    (SELECT jsonb_agg(jsonb_build_object(
                        'date', ps.date,
                        'start_time', ps.start_time,
                        'end_time', ps.end_time,
                        'net_minutes', ps.net_minutes,
                        'break_minutes', ps.break_minutes,
                        'break_count', ps.break_count,
                        'visit_count', ps.visit_count,
                        'order_count', ps.order_count,
                        'sales_value', ps.sales_value,
                        'collection_count', ps.collection_count,
                        'collection_amount', ps.collection_amount,
                        'new_customer_count', ps.new_customer_count,
                        'attendance_status', ps.attendance_status,
                        'late_minutes', ps.late_minutes,
                        'early_departure_minutes', ps.early_departure_minutes,
                        'distance_meters', ps.distance_meters,
                        'tracking_points_count', ps.tracking_points_count
                    ) ORDER BY ps.date DESC)
                    FROM paginated_sessions ps
                    WHERE ps.employee_id = pei.id
                ), '[]'::jsonb)
            ) ORDER BY pei.sort_rank)
            FROM paginated_employee_ids pei
        ), '[]'::jsonb),
        'totals', (SELECT row_to_json(gt.*)::jsonb FROM grand_totals gt),
        'pagination', jsonb_build_object(
            'page', p_page,
            'per_page', p_per_page,
            'total', (SELECT cnt FROM total_count),
            'total_pages', GREATEST(1, CEIL((SELECT cnt::numeric FROM total_count) / p_per_page)::int)
        )
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_coverage_map(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_interval_seconds int;
    v_subtree_ids uuid[];
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    SELECT location_interval_seconds INTO v_interval_seconds FROM public.workday_settings LIMIT 1;
    v_interval_seconds := COALESCE(v_interval_seconds, 300);

    WITH today_orders AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            COUNT(*)::int AS order_count,
            COALESCE(SUM(o.total_amount), 0) AS sales_value
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    today_visits AS (
        SELECT v.employee_id, COUNT(*)::int AS visit_count
        FROM public.visits v WHERE v.check_in_at::date = CURRENT_DATE GROUP BY v.employee_id
    ),
    today_customers_count AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS new_customer_count
        FROM public.customers c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    -- ============================================================
    -- ACTIVE EMPLOYEES — ALL active employees, not just those with
    -- a session today. LEFT JOIN to sessions so we still get
    -- session info (start_time, status) when available.
    -- ============================================================
    active_employees AS (
        SELECT
            e.id AS employee_id,
            e.full_name AS employee_name,
            e.code AS employee_code,
            COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = e.id LIMIT 1), '') AS role_name,
            wds.id AS session_id,
            wds.start_time,
            wds.last_seen_at,
            wds.status AS session_status
        FROM public.employees e
        LEFT JOIN public.workday_sessions wds ON wds.employee_id = e.id AND wds.date = CURRENT_DATE
        WHERE e.is_active = true
          AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
    ),
    session_activity AS (
        SELECT ae.employee_id, ae.last_seen_at AS activity_at, 'heartbeat'::text AS activity_type
        FROM active_employees ae WHERE ae.session_id IS NOT NULL AND ae.last_seen_at IS NOT NULL
    ),
    tracking_activity AS (
        SELECT DISTINCT ON (tp.employee_id)
            tp.employee_id, tp.recorded_at AS activity_at, 'gps'::text AS activity_type
        FROM public.tracking_points tp
        WHERE tp.recorded_at >= CURRENT_DATE - INTERVAL '30 days'
        ORDER BY tp.employee_id, tp.recorded_at DESC
    ),
    visit_activity AS (
        SELECT v.employee_id, MAX(v.check_in_at) AS activity_at, 'visit'::text AS activity_type
        FROM public.visits v WHERE v.check_in_at >= CURRENT_DATE - INTERVAL '30 days'
        GROUP BY v.employee_id
    ),
    order_activity AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            MAX(o.created_at) AS activity_at, 'order'::text AS activity_type
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    collection_activity AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            MAX(c.created_at) AS activity_at, 'collection'::text AS activity_type
        FROM public.collections c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    combined_activity AS (
        SELECT employee_id, activity_at, activity_type FROM session_activity
        UNION ALL SELECT employee_id, activity_at, activity_type FROM tracking_activity
        UNION ALL SELECT employee_id, activity_at, activity_type FROM visit_activity
        UNION ALL SELECT employee_id, activity_at, activity_type FROM order_activity
        UNION ALL SELECT employee_id, activity_at, activity_type FROM collection_activity
    ),
    last_activity AS (
        SELECT DISTINCT ON (employee_id)
            employee_id, activity_at AS last_activity_at, activity_type AS last_activity_type
        FROM combined_activity ORDER BY employee_id, activity_at DESC NULLS LAST
    ),
    -- ============================================================
    -- REPRESENTATIVE LOCATION — 4 sources, 30-day lookback
    -- Priority (by newest timestamp):
    --   1. tracking_runtime (GPS pings)
    --   2. visit_checkin (visit check-in GPS)
    --   3. visit_checkout (visit check-out GPS)
    --   4. break_gps (break start GPS)
    -- ============================================================
    representative_location AS (
        SELECT DISTINCT ON (rl.employee_id)
            rl.employee_id, rl.latitude, rl.longitude, rl.accuracy_meters,
            rl.location_at, rl.source
        FROM (
            SELECT tp.employee_id, tp.latitude, tp.longitude, tp.accuracy_meters,
                   tp.recorded_at AS location_at, 'tracking_runtime'::text AS source
            FROM public.tracking_points tp
            WHERE tp.recorded_at >= CURRENT_DATE - INTERVAL '30 days'
              AND tp.latitude IS NOT NULL AND tp.longitude IS NOT NULL
            UNION ALL
            SELECT v.employee_id, v.check_in_latitude, v.check_in_longitude, NULL::numeric,
                   v.check_in_at, 'visit_checkin'::text
            FROM public.visits v
            WHERE v.check_in_at >= CURRENT_DATE - INTERVAL '30 days'
              AND v.check_in_latitude IS NOT NULL AND v.check_in_longitude IS NOT NULL
            UNION ALL
            SELECT v.employee_id, v.check_out_latitude, v.check_out_longitude, NULL::numeric,
                   v.check_out_at, 'visit_checkout'::text
            FROM public.visits v
            WHERE v.check_out_at >= CURRENT_DATE - INTERVAL '30 days'
              AND v.check_out_latitude IS NOT NULL AND v.check_out_longitude IS NOT NULL
            UNION ALL
            SELECT wb.employee_id, wb.latitude, wb.longitude, NULL::numeric,
                   wb.break_start, 'break_gps'::text
            FROM public.workday_breaks wb
            WHERE wb.break_start >= CURRENT_DATE - INTERVAL '30 days'
              AND wb.latitude IS NOT NULL AND wb.longitude IS NOT NULL
        ) rl
        ORDER BY rl.employee_id, rl.location_at DESC
    ),
    active_breaks AS (
        SELECT wb.session_id, wb.employee_id FROM public.workday_breaks wb
        JOIN active_employees ae ON ae.session_id = wb.session_id
        WHERE wb.break_end IS NULL
    ),
    -- ============================================================
    -- CUSTOMER LOCATIONS — 3-tier priority (unchanged)
    -- ============================================================
    customer_locations AS (
        SELECT
            c.id, c.code,
            COALESCE(c.company_name, c.responsible_name, '') AS customer_name,
            c.responsible_name, c.owner_id,
            COALESCE(cc.phone, '') AS phone,
            COALESCE(gov.name_ar, ca_legacy.governorate, '') AS governorate,
            COALESCE(ct.name_ar, ca_legacy.city, '') AS city,
            caddr.street_address,
            caddr.landmark,
            caddr.governorate_id,
            caddr.city_id,
            COALESCE(ul.formatted_address, '') AS formatted_address,
            COALESCE(ul.latitude, v.latest_lat, caddr.latitude) AS latitude,
            COALESCE(ul.longitude, v.latest_lng, caddr.longitude) AS longitude,
            CASE
                WHEN ul.latitude IS NOT NULL THEN 'customer_location'
                WHEN v.latest_lat IS NOT NULL THEN 'visit_gps'
                WHEN caddr.latitude IS NOT NULL THEN 'address_geocoded'
                ELSE 'unknown'
            END AS location_source,
            CASE
                WHEN ul.latitude IS NOT NULL THEN 'CUSTOMER_LOCATION'
                WHEN v.latest_lat IS NOT NULL THEN 'VISIT_GPS'
                WHEN caddr.latitude IS NOT NULL AND caddr.location_accuracy IS NOT NULL THEN caddr.location_accuracy::text
                WHEN caddr.latitude IS NOT NULL THEN 'GEOCODED'
                ELSE 'UNKNOWN'
            END AS location_accuracy,
            e.code AS owner_code, e.full_name AS owner_name,
            c.created_at,
            (SELECT COUNT(*)::int FROM public.orders o WHERE o.customer_id = c.id) AS total_orders,
            (SELECT COALESCE(SUM(o.total_amount), 0) FROM public.orders o WHERE o.customer_id = c.id) AS total_sales,
            (SELECT MAX(o.created_at) FROM public.orders o WHERE o.customer_id = c.id) AS last_order_at,
            (SELECT MAX(v.check_in_at) FROM public.visits v WHERE v.customer_id = c.id) AS last_visit_at
        FROM public.customers c
        LEFT JOIN public.unified_locations ul ON ul.id = c.location_id
        LEFT JOIN LATERAL fn_customer_default_address(c.id) caddr ON true
        LEFT JOIN LATERAL (
            SELECT check_out_latitude AS latest_lat, check_out_longitude AS latest_lng
            FROM public.visits
            WHERE customer_id = c.id
              AND status = 'completed'
              AND check_out_latitude IS NOT NULL
              AND check_out_longitude IS NOT NULL
            ORDER BY check_out_at DESC
            LIMIT 1
        ) v ON true
        LEFT JOIN reference_governorates gov ON gov.id = caddr.governorate_id
        LEFT JOIN reference_cities ct ON ct.id = caddr.city_id
        LEFT JOIN LATERAL (
            SELECT governorate, city FROM public.customer_addresses
            WHERE customer_id = c.id AND is_default = true LIMIT 1
        ) ca_legacy ON true
        LEFT JOIN LATERAL (
            SELECT phone FROM public.customer_contacts
            WHERE customer_id = c.id AND is_primary = true LIMIT 1
        ) cc ON true
        LEFT JOIN public.employees e ON e.id = c.owner_id
        WHERE c.is_active = true
          AND (v_subtree_ids IS NULL OR c.owner_id = ANY(v_subtree_ids) OR c.owner_id IS NULL)
    ),
    -- ============================================================
    -- EMPLOYEE REGION — resolves governorate AND city from
    -- current location by matching nearest reference_city
    -- ============================================================
    employee_region AS (
        SELECT DISTINCT ON (rl.employee_id)
            rl.employee_id,
            COALESCE(g.name_ar, '') AS governorate,
            COALESCE(rc.name_ar, '') AS city
        FROM representative_location rl
        JOIN active_employees ae ON ae.employee_id = rl.employee_id
        CROSS JOIN public.reference_cities rc
        LEFT JOIN public.reference_governorates g ON g.id = rc.governorate_id
        WHERE rl.latitude IS NOT NULL AND rl.longitude IS NOT NULL
        ORDER BY rl.employee_id,
            (rl.latitude - rc.latitude)^2 + (rl.longitude - rc.longitude)^2
    ),
    -- ============================================================
    -- GOVERNORATE STATS — aggregates customers + employees together
    -- ============================================================
    governorate_stats AS (
        SELECT
            governorate,
            COUNT(*) FILTER (WHERE type = 'customer')::int AS customer_count,
            COUNT(*) FILTER (WHERE type = 'employee')::int AS employee_count
        FROM (
            SELECT governorate, 'customer' AS type
            FROM customer_locations
            WHERE COALESCE(governorate, '') != ''
            UNION ALL
            SELECT er.governorate, 'employee' AS type
            FROM employee_region er
            WHERE COALESCE(er.governorate, '') != ''
        ) combined
        GROUP BY governorate
        ORDER BY governorate
    ),
    visited_customers_today AS (
        SELECT COUNT(DISTINCT v.customer_id)::int AS cnt FROM public.visits v
        WHERE v.check_in_at::date = CURRENT_DATE
    )
    SELECT jsonb_build_object(
        'summary', jsonb_build_object(
            'total_customers', (SELECT COUNT(*) FROM customer_locations),
            'active_employees', (SELECT COUNT(*) FROM active_employees),
            'covered_governorates', (SELECT COUNT(DISTINCT governorate) FROM (
                SELECT governorate FROM customer_locations WHERE COALESCE(governorate, '') != ''
                UNION
                SELECT er2.governorate FROM employee_region er2 WHERE COALESCE(er2.governorate, '') != ''
            ) gov_union),
            'visited_customers_today', COALESCE((SELECT cnt FROM visited_customers_today), 0),
            'today_orders', COALESCE((SELECT SUM(order_count) FROM today_orders), 0),
            'today_sales', COALESCE((SELECT SUM(sales_value) FROM today_orders), 0)
        ),
        'customers', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'id', cl.id, 'code', cl.code, 'name', cl.customer_name,
            'responsible_name', cl.responsible_name, 'phone', cl.phone,
            'governorate', cl.governorate, 'city', cl.city,
            'governorate_id', cl.governorate_id, 'city_id', cl.city_id,
            'street_address', cl.street_address, 'landmark', cl.landmark,
            'formatted_address', cl.formatted_address,
            'location_source', cl.location_source,
            'location_accuracy', cl.location_accuracy,
            'latitude', cl.latitude, 'longitude', cl.longitude,
            'owner_code', cl.owner_code, 'owner_name', cl.owner_name,
            'created_at', cl.created_at,
            'total_orders', cl.total_orders, 'total_sales', cl.total_sales,
            'last_order_at', cl.last_order_at, 'last_visit_at', cl.last_visit_at
        )) FROM customer_locations cl), '[]'::jsonb),
        'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', ae.employee_id,
            'name', ae.employee_name,
            'code', ae.employee_code,
            'role_name', ae.role_name,
            'status', CASE WHEN ae.session_id IS NULL THEN 'offline'
                           WHEN ab.employee_id IS NOT NULL THEN 'on_break'
                           WHEN EXISTS (SELECT 1 FROM public.visits v2 WHERE v2.employee_id = ae.employee_id AND v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL) THEN 'on_visit'
                           ELSE 'working' END,
            'connection_status', CASE WHEN ae.session_id IS NULL THEN 'offline'
                                      WHEN la.last_activity_at IS NULL THEN 'no_data'
                 WHEN la.last_activity_at > now() - (v_interval_seconds || ' seconds')::interval THEN 'connected'
                 WHEN la.last_activity_at > now() - ((v_interval_seconds * 5) || ' seconds')::interval THEN 'delayed'
                 ELSE 'lost' END,
            'latitude', rl.latitude, 'longitude', rl.longitude,
            'accuracy_meters', rl.accuracy_meters,
            'location_source', rl.source,
            'governorate', COALESCE(er.governorate, ''),
            'city', COALESCE(er.city, ''),
            'last_seen_at', CASE
                WHEN ae.session_id IS NOT NULL AND la.last_activity_at IS NOT NULL AND rl.location_at IS NOT NULL
                    THEN GREATEST(la.last_activity_at, rl.location_at)
                WHEN la.last_activity_at IS NOT NULL THEN la.last_activity_at
                WHEN rl.location_at IS NOT NULL THEN rl.location_at
                ELSE NULL END,
            'last_activity_at', la.last_activity_at,
            'last_activity_type', la.last_activity_type,
            'last_location_at', rl.location_at,
            'duration_minutes', CASE WHEN ae.start_time IS NOT NULL THEN EXTRACT(EPOCH FROM (now() - ae.start_time)) / 60 ELSE 0 END,
            'order_count', COALESCE(to2.order_count, 0),
            'sales_value', COALESCE(to2.sales_value, 0),
            'visit_count', COALESCE(tv.visit_count, 0),
            'new_customer_count', COALESCE(tc.new_customer_count, 0)
        )) FROM active_employees ae
        LEFT JOIN active_breaks ab ON ab.session_id = ae.session_id
        LEFT JOIN last_activity la ON la.employee_id = ae.employee_id
        LEFT JOIN representative_location rl ON rl.employee_id = ae.employee_id
        LEFT JOIN employee_region er ON er.employee_id = ae.employee_id
        LEFT JOIN today_orders to2 ON to2.employee_id = ae.employee_id
        LEFT JOIN today_visits tv ON tv.employee_id = ae.employee_id
        LEFT JOIN today_customers_count tc ON tc.employee_id = ae.employee_id), '[]'::jsonb),
        'governorate_stats', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'governorate', gs.governorate,
            'customer_count', gs.customer_count,
            'employee_count', gs.employee_count
        ) ORDER BY gs.governorate) FROM governorate_stats gs), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_credit_dashboard_stats(p_token uuid)
 RETURNS TABLE(new_apps bigint, under_review bigint, docs_pending bigint, approved bigint, rejected bigint, suspended bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT COUNT(*) FILTER(WHERE a.status = 'submitted'), COUNT(*) FILTER(WHERE a.status = 'under_review'), COUNT(*) FILTER(WHERE a.status IN ('submitted','under_review') AND a.doc_confirmed_by IS NULL), COUNT(*) FILTER(WHERE a.status = 'approved'), COUNT(*) FILTER(WHERE a.status = 'rejected'), COUNT(*) FILTER(WHERE a.status = 'suspended') FROM public.credit_applications a WHERE a.customer_id = v_session.customer_id;
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY SELECT COUNT(*) FILTER(WHERE a.status = 'submitted'), COUNT(*) FILTER(WHERE a.status = 'under_review'), COUNT(*) FILTER(WHERE a.status IN ('submitted','under_review') AND a.doc_confirmed_by IS NULL), COUNT(*) FILTER(WHERE a.status = 'approved'), COUNT(*) FILTER(WHERE a.status = 'rejected'), COUNT(*) FILTER(WHERE a.status = 'suspended') FROM public.credit_applications a;
  ELSE
    RETURN QUERY SELECT COUNT(*) FILTER(WHERE a.status = 'submitted'), COUNT(*) FILTER(WHERE a.status = 'under_review'), COUNT(*) FILTER(WHERE a.status IN ('submitted','under_review') AND a.doc_confirmed_by IS NULL), COUNT(*) FILTER(WHERE a.status = 'approved'), COUNT(*) FILTER(WHERE a.status = 'rejected'), COUNT(*) FILTER(WHERE a.status = 'suspended') FROM public.credit_applications a JOIN public.customers c ON c.id = a.customer_id WHERE c.owner_id = ANY(v_visible);
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_analytics_list(p_token uuid)
 RETURNS TABLE(customer_id uuid, code character varying, company_name character varying, is_active boolean, total_purchases numeric, order_count bigint, avg_order_value numeric, last_order_date timestamp with time zone, days_since_last_order integer, inactive_risk boolean, lost_customer_risk boolean, expected_next_order_date timestamp with time zone, potential_revenue_score numeric, ranking bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_identity_type text; v_identity_id uuid; v_employee_id uuid; v_visible uuid[];
BEGIN
  SELECT s.identity_type, s.identity_id, s.employee_id INTO v_identity_type, v_identity_id, v_employee_id FROM app.sessions s WHERE s.token = p_token AND s.expires_at > now(); IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY WITH visible_customers AS (
    SELECT c.id, c.code, c.company_name, c.is_active FROM public.customers c
    WHERE (v_identity_type = 'customer' AND c.identity_id = v_identity_id) OR (c.owner_id = ANY(v_visible))
  ), order_stats AS (
    SELECT o.customer_id, COALESCE(SUM(o.total_amount), 0) AS total_purchases, COUNT(*)::bigint AS order_count, MAX(o.submitted_at) AS last_order_date, MIN(o.submitted_at) AS first_order_date FROM public.orders o WHERE o.status IN ('submitted','approved') GROUP BY o.customer_id
  ), intervals AS (
    SELECT subq.customer_id, AVG(subq.days)::numeric AS avg_interval FROM (
      SELECT o2.customer_id, EXTRACT(DAY FROM (o2.submitted_at - LAG(o2.submitted_at) OVER (PARTITION BY o2.customer_id ORDER BY o2.submitted_at)))::numeric AS days FROM public.orders o2
      WHERE o2.status IN ('submitted','approved') AND o2.submitted_at IS NOT NULL
    ) subq WHERE subq.days IS NOT NULL AND subq.days > 0 GROUP BY subq.customer_id
  )
  SELECT vc.id, vc.code, vc.company_name, vc.is_active,
    COALESCE(os.total_purchases, 0), COALESCE(os.order_count, 0),
    CASE WHEN os.order_count > 0 THEN os.total_purchases / os.order_count ELSE 0 END,
    os.last_order_date,
    CASE WHEN os.last_order_date IS NOT NULL THEN EXTRACT(DAY FROM now() - os.last_order_date)::int ELSE NULL END,
    CASE WHEN os.last_order_date IS NOT NULL AND EXTRACT(DAY FROM now() - os.last_order_date) > 30 AND EXTRACT(DAY FROM now() - os.last_order_date) < 90 THEN true ELSE false END,
    CASE WHEN os.last_order_date IS NOT NULL AND EXTRACT(DAY FROM now() - os.last_order_date) >= 90 THEN true ELSE false END,
    CASE WHEN os.last_order_date IS NOT NULL AND COALESCE(i.avg_interval, 0) > 0 THEN os.last_order_date + (i.avg_interval || ' days')::interval ELSE NULL END,
    CASE WHEN os.last_order_date IS NOT NULL AND COALESCE(i.avg_interval, 0) > 0 THEN COALESCE(os.total_purchases, 0) * GREATEST(0, EXTRACT(DAY FROM now() - os.last_order_date) / i.avg_interval) ELSE COALESCE(os.total_purchases, 0) * 0.5 END,
    ROW_NUMBER() OVER (ORDER BY COALESCE(os.total_purchases, 0) DESC)
  FROM visible_customers vc
  LEFT JOIN order_stats os ON os.customer_id = vc.id
  LEFT JOIN intervals i ON i.customer_id = vc.id
  ORDER BY ranking;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_behavior_insights(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_total_orders int;
    v_total_value numeric;
    v_first_order_date timestamptz;
    v_last_order_date timestamptz;
    v_insights jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    -- Base metrics
    SELECT
        COUNT(*)::int,
        COALESCE(SUM(total_amount), 0),
        MIN(created_at),
        MAX(created_at)
    INTO v_total_orders, v_total_value, v_first_order_date, v_last_order_date
    FROM orders
    WHERE customer_id = p_customer_id
      AND public.is_order_in_statistics(status)
      AND created_at::date >= p_from
      AND created_at::date <= p_to;

    WITH order_dates AS (
        SELECT created_at::date AS order_date
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
        ORDER BY created_at
    ),
    gaps AS (
        SELECT order_date - LAG(order_date) OVER (ORDER BY order_date) AS gap_days
        FROM order_dates
    ),
    day_of_week AS (
        SELECT
            EXTRACT(DOW FROM created_at)::int AS dow,
            COUNT(*)::int AS cnt
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
        GROUP BY EXTRACT(DOW FROM created_at)
    ),
    half_split AS (
        SELECT
            COUNT(*) FILTER (WHERE created_at::date <= (p_from::date + ((p_to - p_from) / 2)::int)) AS first_half,
            COUNT(*) FILTER (WHERE created_at::date > (p_from::date + ((p_to - p_from) / 2)::int)) AS second_half
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
    )
    SELECT jsonb_build_object(
        'total_orders', COALESCE(v_total_orders, 0),
        'total_value', COALESCE(v_total_value, 0),
        'repeat_customer', COALESCE(v_total_orders, 0) > 1,
        'purchase_frequency', CASE
            WHEN COALESCE(v_total_orders, 0) > 1 AND v_first_order_date IS NOT NULL AND v_last_order_date IS NOT NULL
            THEN GREATEST(0, ROUND(
                (EXTRACT(EPOCH FROM (v_last_order_date - v_first_order_date)) / 86400) /
                NULLIF((v_total_orders - 1)::numeric, 0)
            , 1))
            ELSE 0
        END,
        'avg_days_between_orders', (SELECT ROUND(AVG(gap_days)::numeric, 1) FROM gaps WHERE gap_days IS NOT NULL),
        'most_active_day', (SELECT CASE
            WHEN dow = 0 THEN 'الأحد' WHEN dow = 1 THEN 'الإثنين'
            WHEN dow = 2 THEN 'الثلاثاء' WHEN dow = 3 THEN 'الأربعاء'
            WHEN dow = 4 THEN 'الخميس' WHEN dow = 5 THEN 'الجمعة'
            WHEN dow = 6 THEN 'السبت' ELSE 'غير متوفر'
        END FROM day_of_week ORDER BY cnt DESC LIMIT 1),
        'most_active_day_orders', (SELECT COALESCE(cnt, 0) FROM day_of_week ORDER BY cnt DESC LIMIT 1),
        'growth_trend', CASE
            WHEN COALESCE(v_total_orders, 0) >= 3 THEN (
                SELECT CASE
                    WHEN first_half < second_half THEN 'زيادة'
                    WHEN first_half > second_half THEN 'انخفاض'
                    ELSE 'ثبات'
                END FROM half_split
            ) ELSE 'غير كافٍ'
        END,
        'retention_score', CASE
            WHEN COALESCE(v_total_orders, 0) = 0 THEN 0
            WHEN v_total_orders = 1 THEN 1
            WHEN v_total_orders <= 3 THEN 2
            WHEN v_total_orders <= 6 THEN 3
            WHEN v_total_orders <= 12 THEN 4
            ELSE 5
        END,
        'months_active', CASE
            WHEN v_first_order_date IS NOT NULL THEN
                GREATEST(1, (SELECT ROUND(EXTRACT(DAY FROM (COALESCE(v_last_order_date, v_first_order_date) - v_first_order_date)) / 30.44)::int))
            ELSE 0
        END,
        'last_order_date', v_last_order_date,
        'first_order_date', v_first_order_date
    ) INTO v_insights;

    RETURN jsonb_build_object(
        'insights', COALESCE(v_insights, jsonb_build_object(
            'total_orders', 0, 'total_value', 0, 'repeat_customer', false,
            'purchase_frequency', 0, 'growth_trend', 'غير كافٍ', 'retention_score', 0
        ))
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_brands(p_token uuid, p_customer_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_identity_type text; v_identity_id uuid; v_employee_id uuid; v_visible uuid[]; v_cust public.customers; v_total numeric; v_brands json;
BEGIN
  SELECT s.identity_type, s.identity_id, s.employee_id INTO v_identity_type, v_identity_id, v_employee_id FROM app.sessions s WHERE s.token = p_token AND s.expires_at > now(); IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_cust FROM public.customers WHERE id = p_customer_id; IF NOT FOUND THEN RETURN NULL; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_identity_type = 'customer' THEN IF v_cust.identity_id != v_identity_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  ELSIF v_cust.owner_id IS NOT NULL AND NOT (v_cust.owner_id = ANY(v_visible)) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT COALESCE(SUM(oi.total_price), 0) INTO v_total FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved');
  SELECT json_agg(subq ORDER BY subq.total_spent DESC) INTO v_brands FROM (
    SELECT c.id AS company_id, c.company_name, SUM(oi.total_price) AS total_spent,
      CASE WHEN v_total > 0 THEN ROUND(SUM(oi.total_price) / v_total * 100, 1) ELSE 0 END AS share_pct,
      ROUND(((COALESCE(SUM(oi.total_price) FILTER (WHERE o.submitted_at >= CURRENT_DATE - INTERVAL '90 days'), 0) - COALESCE(SUM(oi.total_price) FILTER (WHERE o.submitted_at >= CURRENT_DATE - INTERVAL '180 days' AND o.submitted_at < CURRENT_DATE - INTERVAL '90 days'), 0)) / NULLIF(COALESCE(SUM(oi.total_price) FILTER (WHERE o.submitted_at >= CURRENT_DATE - INTERVAL '180 days' AND o.submitted_at < CURRENT_DATE - INTERVAL '90 days'), 0), 0)) * 100, 1) AS trend_pct
    FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id JOIN public.products p ON p.id = oi.product_id JOIN public.companies c ON c.id = p.company_id
    WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved')
    GROUP BY c.id, c.company_name ORDER BY total_spent DESC LIMIT 10
  ) subq;
  RETURN json_build_object('total_spent', v_total, 'brands', COALESCE(v_brands, '[]'::json));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_card(p_token uuid, p_customer_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_identity_type text; v_identity_id uuid; v_employee_id uuid; v_visible uuid[];
  v_cust public.customers; v_total_purchases numeric; v_order_count int; v_avg_value numeric;
  v_last_order timestamptz; v_last_visit timestamptz; v_cash_amt numeric; v_total_coll numeric;
  v_visit_count int; v_reorder_interval numeric; v_first_order timestamptz;
  v_growth numeric; v_prior_total numeric; v_expected_next timestamptz; v_potential_revenue numeric;
  v_balance numeric; v_total_ordered numeric;
BEGIN
  SELECT s.identity_type, s.identity_id, s.employee_id INTO v_identity_type, v_identity_id, v_employee_id FROM app.sessions s WHERE s.token = p_token AND s.expires_at > now(); IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_cust FROM public.customers WHERE id = p_customer_id; IF NOT FOUND THEN RETURN NULL; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_identity_type = 'customer' THEN IF v_cust.identity_id != v_identity_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  ELSIF v_cust.owner_id IS NOT NULL AND NOT (v_cust.owner_id = ANY(v_visible)) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT COALESCE(SUM(o.total_amount), 0), COUNT(*), MAX(o.submitted_at), MIN(o.submitted_at), COALESCE(SUM(o.total_amount), 0) INTO v_total_purchases, v_order_count, v_last_order, v_first_order, v_total_ordered FROM public.orders o WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved');
  v_avg_value := CASE WHEN v_order_count > 0 THEN v_total_purchases / v_order_count ELSE 0 END;
  SELECT MAX(v.check_in_at), COUNT(*) INTO v_last_visit, v_visit_count FROM public.visits v WHERE v.customer_id = p_customer_id;
  SELECT COALESCE(SUM(c.amount) FILTER (WHERE c.method = 'cash'), 0), COALESCE(SUM(c.amount), 0) INTO v_cash_amt, v_total_coll FROM public.collections c WHERE c.customer_id = p_customer_id;
  v_balance := v_total_ordered - v_total_coll;
  SELECT COALESCE(AVG(subq.days), 0) INTO v_reorder_interval FROM (
    SELECT EXTRACT(DAY FROM (o2.submitted_at - LAG(o2.submitted_at) OVER (ORDER BY o2.submitted_at)))::numeric AS days FROM public.orders o2
    WHERE o2.customer_id = p_customer_id AND o2.status IN ('submitted','approved') AND o2.submitted_at IS NOT NULL
  ) subq WHERE subq.days IS NOT NULL AND subq.days > 0;
  SELECT COALESCE(SUM(o3.total_amount), 0) INTO v_prior_total FROM public.orders o3 WHERE o3.customer_id = p_customer_id AND o3.status IN ('submitted','approved') AND o3.submitted_at >= CURRENT_DATE - INTERVAL '180 days' AND o3.submitted_at < CURRENT_DATE - INTERVAL '90 days';
  SELECT COALESCE(SUM(o4.total_amount), 0) INTO v_growth FROM public.orders o4 WHERE o4.customer_id = p_customer_id AND o4.status IN ('submitted','approved') AND o4.submitted_at >= CURRENT_DATE - INTERVAL '90 days';
  v_growth := CASE WHEN v_prior_total > 0 THEN ((v_growth - v_prior_total) / v_prior_total) * 100 ELSE 0 END;
  IF v_last_order IS NOT NULL AND v_reorder_interval > 0 THEN v_expected_next := v_last_order + (v_reorder_interval || ' days')::interval; END IF;
  IF v_last_order IS NOT NULL AND v_reorder_interval > 0 THEN v_potential_revenue := v_total_purchases * GREATEST(0, EXTRACT(DAY FROM now() - v_last_order) / v_reorder_interval); ELSE v_potential_revenue := v_total_purchases * 0.5; END IF;
  RETURN json_build_object('customer_id', v_cust.id, 'code', v_cust.code, 'company_name', v_cust.company_name, 'is_active', v_cust.is_active,
    'purchase_summary', json_build_object('total_purchases', v_total_purchases, 'order_count', v_order_count, 'avg_order_value', v_avg_value, 'last_order_date', v_last_order, 'first_order_date', v_first_order),
    'visit_summary', json_build_object('last_visit_date', v_last_visit, 'days_since_last_visit', CASE WHEN v_last_visit IS NOT NULL THEN EXTRACT(DAY FROM now() - v_last_visit)::int ELSE NULL END, 'total_visits', v_visit_count),
    'credit_status', json_build_object('current_balance', v_balance, 'credit_limit', v_cust.credit_limit, 'credit_utilization_pct', CASE WHEN v_cust.credit_limit > 0 THEN ROUND((v_balance / v_cust.credit_limit) * 100, 1) ELSE 0 END, 'cash_vs_credit_ratio', CASE WHEN v_total_coll > 0 THEN ROUND(v_cash_amt / v_total_coll, 2) ELSE 0 END),
    'risk_indicators', json_build_object('days_since_last_order', CASE WHEN v_last_order IS NOT NULL THEN EXTRACT(DAY FROM now() - v_last_order)::int ELSE NULL END, 'inactive_risk', CASE WHEN v_last_order IS NOT NULL AND EXTRACT(DAY FROM now() - v_last_order) > 30 AND EXTRACT(DAY FROM now() - v_last_order) < 90 THEN true ELSE false END, 'lost_customer_risk', CASE WHEN v_last_order IS NOT NULL AND EXTRACT(DAY FROM now() - v_last_order) >= 90 THEN true ELSE false END),
    'behavior', json_build_object('avg_reorder_interval_days', v_reorder_interval, 'growth_trend_pct', ROUND(v_growth, 1), 'decline_trend_pct', ROUND(LEAST(v_growth, 0), 1)),
    'expected_next_order_date', v_expected_next, 'potential_revenue_score', ROUND(v_potential_revenue, 2));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_collections(p_token uuid, p_customer_id uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', col.id,
      'code', col.code,
      'method', col.method,
      'amount', col.amount,
      'status', col.status,
      'reference_number', col.reference_number,
      'collected_at', col.collected_at,
      'created_by_name', e.full_name
    ) ORDER BY col.created_at DESC
  ) INTO v_result
  FROM collections col
  LEFT JOIN employees e ON e.id = col.created_by
  WHERE col.customer_id = p_customer_id
  LIMIT p_limit;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_companies_analysis(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_total_value numeric;
    v_companies jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    -- Total customer spend in period
    SELECT COALESCE(SUM(oi.total_price), 0) INTO v_total_value
    FROM order_items oi
    JOIN orders o ON o.id = oi.order_id
    WHERE o.customer_id = p_customer_id
      AND public.is_order_in_statistics(o.status)
      AND o.created_at::date >= p_from
      AND o.created_at::date <= p_to;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'company_id', comp.id,
        'company_name', COALESCE(comp.company_name, 'غير متوفر'),
        'orders_count', comp_data.order_count,
        'total_value', comp_data.total_value,
        'percentage_share', CASE WHEN v_total_value > 0 THEN ROUND((comp_data.total_value / v_total_value * 100)::numeric, 1) ELSE 0 END
    ) ORDER BY comp_data.total_value DESC NULLS LAST), '[]'::jsonb) INTO v_companies
    FROM (
        SELECT DISTINCT c.id, c.company_name
        FROM companies c
        WHERE EXISTS (
            SELECT 1 FROM products p
            JOIN order_items oi ON oi.product_id = p.id
            JOIN orders o ON o.id = oi.order_id
            WHERE p.company_id = c.id
              AND o.customer_id = p_customer_id
              AND public.is_order_in_statistics(o.status)
              AND o.created_at::date >= p_from
              AND o.created_at::date <= p_to
        )
    ) comp
    JOIN LATERAL (
        SELECT
            COUNT(DISTINCT o.id)::int AS order_count,
            COALESCE(SUM(oi.total_price), 0) AS total_value
        FROM products p
        JOIN order_items oi ON oi.product_id = p.id
        JOIN orders o ON o.id = oi.order_id
        WHERE p.company_id = comp.id
          AND o.customer_id = p_customer_id
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
    ) comp_data ON true;

    RETURN jsonb_build_object(
        'companies', COALESCE(v_companies, '[]'::jsonb),
        'total_value', COALESCE(v_total_value, 0)
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_delivered_orders(p_token uuid, p_customer_id uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_target_month int; v_target_year int;
  v_month_start timestamptz; v_month_end timestamptz;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
  v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
  v_month_start := date_trunc('month', make_date(v_target_year, v_target_month, 1));
  v_month_end := v_month_start + INTERVAL '1 month';
  SELECT jsonb_agg(jsonb_build_object(
    'order_id', o.id, 'order_code', o.order_number, 'total_amount', o.total_amount,
    'delivered_at', o.delivered_at, 'status', o.status
  ) ORDER BY o.delivered_at DESC) INTO v_result
  FROM public.orders o WHERE o.customer_id = p_customer_id AND o.status = 'delivered'
    AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_first_deliveries(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_is_super boolean;
  v_visible uuid[];
  v_token uuid;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_SESSION');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type != 'employee' THEN
    RETURN jsonb_build_object('error', 'NOT_EMPLOYEE');
  END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);

  IF NOT v_is_super THEN
    v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'customer_id', sub.customer_id,
        'first_delivery_at', sub.first_delivery_at
      )
    ), '[]'::jsonb)
    FROM (
      SELECT o.customer_id,
             MIN(COALESCE(o.delivered_at, o.created_at)) AS first_delivery_at
      FROM public.orders o
      WHERE o.status = 'delivered'
        AND public.is_order_in_statistics(o.status)
        AND (v_is_super OR o.owner_id = ANY(v_visible))
      GROUP BY o.customer_id
    ) sub
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_full_profile(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_customer_info jsonb;
    v_stats jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    -- Customer base info
    SELECT jsonb_build_object(
        'id', c.id,
        'code', COALESCE(c.code, 'غير متوفر'),
        'company_name', COALESCE(c.company_name, 'غير متوفر'),
        'email', COALESCE(c.email, 'غير متوفر'),
        'phone', COALESCE(i.phone, 'غير متوفر'),
        'business_type', COALESCE(c.business_type::text, 'غير متوفر'),
        'responsible_name', COALESCE(c.responsible_name, 'غير متوفر'),
        'credit_limit', COALESCE(c.credit_limit, 0),
        'credit_days', COALESCE(c.credit_days, 0),
        'is_active', COALESCE(c.is_active, false),
        'registered_at', c.registered_at,
        'created_at', c.created_at,
        'owner_name', COALESCE(e.full_name, 'غير متوفر'),
        'tier_name', COALESCE(
            (SELECT t.name FROM tiers t
             JOIN orders o ON o.tier_id = t.id
             WHERE o.customer_id = p_customer_id AND o.tier_id IS NOT NULL
             ORDER BY o.created_at DESC LIMIT 1),
            'غير متوفر'
        )
    ) INTO v_customer_info
    FROM customers c
    LEFT JOIN identities i ON i.id = c.identity_id
    LEFT JOIN employees e ON e.id = c.owner_id
    WHERE c.id = p_customer_id;

    -- Aggregated stats
    WITH ord_stats AS (
        SELECT
            COUNT(*)::int AS total_orders,
            COALESCE(SUM(o.total_amount), 0) AS total_sales,
            CASE WHEN COUNT(*) > 0 THEN ROUND(COALESCE(SUM(o.total_amount), 0) / COUNT(*)::numeric, 2) ELSE 0 END AS avg_order_value,
            MAX(o.created_at) AS last_order_date,
            MIN(o.created_at) AS first_order_date,
            COUNT(DISTINCT o.created_at::date)::int AS active_days
        FROM orders o
        WHERE o.customer_id = p_customer_id
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
    ),
    vis_stats AS (
        SELECT
            COUNT(*)::int AS visit_count,
            COUNT(*) FILTER (WHERE v.status = 'completed')::int AS successful_visits,
            MAX(v.check_in_at) AS last_visit_date
        FROM visits v
        WHERE v.customer_id = p_customer_id
          AND v.check_in_at::date >= p_from
          AND v.check_in_at::date <= p_to
    )
    SELECT jsonb_build_object(
        'total_orders', COALESCE(ord_stats.total_orders, 0),
        'total_sales', COALESCE(ord_stats.total_sales, 0),
        'avg_order_value', COALESCE(ord_stats.avg_order_value, 0),
        'last_order_date', ord_stats.last_order_date,
        'first_order_date', ord_stats.first_order_date,
        'active_days', COALESCE(ord_stats.active_days, 0),
        'visit_count', COALESCE(vis_stats.visit_count, 0),
        'successful_visits', COALESCE(vis_stats.successful_visits, 0),
        'last_visit_date', vis_stats.last_visit_date
    ) INTO v_stats
    FROM ord_stats, vis_stats;

    RETURN jsonb_build_object(
        'customer', COALESCE(v_customer_info, jsonb_build_object()),
        'stats', COALESCE(v_stats, jsonb_build_object(
            'total_orders', 0, 'total_sales', 0, 'avg_order_value', 0,
            'active_days', 0, 'visit_count', 0, 'successful_visits', 0
        ))
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_intelligence(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_summary jsonb;
    v_orders jsonb;
    v_visits jsonb;
    v_products jsonb;
    v_companies jsonb;
    v_insights jsonb;
    v_filter_options jsonb;
    v_total_value numeric;
    v_expected_next date;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    -- ==========================================
    -- SUMMARY
    -- ==========================================
    WITH cust_orders AS (
        SELECT o.id, o.total_amount, o.created_at, o.status
        FROM orders o
        WHERE o.customer_id = p_customer_id
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
    ),
    cust_visits AS (
        SELECT COUNT(*) AS cnt
        FROM visits v
        WHERE v.customer_id = p_customer_id
          AND v.status = 'completed'
          AND v.check_in_at::date >= p_from
          AND v.check_in_at::date <= p_to
    )
    SELECT jsonb_build_object(
        'total_orders', COALESCE((SELECT COUNT(*)::int FROM cust_orders), 0),
        'total_value', COALESCE((SELECT SUM(total_amount) FROM cust_orders), 0),
        'avg_order_value', CASE WHEN (SELECT COUNT(*) FROM cust_orders) > 0 THEN ROUND((SELECT SUM(total_amount) FROM cust_orders) / (SELECT COUNT(*)::numeric FROM cust_orders), 2) ELSE 0 END,
        'last_order_date', (SELECT MAX(created_at) FROM cust_orders),
        'first_order_date', (SELECT MIN(created_at) FROM cust_orders),
        'total_visits', COALESCE((SELECT cnt FROM cust_visits), 0),
        'active_days', COALESCE((SELECT COUNT(DISTINCT created_at::date)::int FROM cust_orders), 0)
    ) INTO v_summary;

    v_total_value := COALESCE((v_summary->>'total_value')::numeric, 0);

    -- ==========================================
    -- ORDERS
    -- ==========================================
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'status', o.status,
        'total_amount', o.total_amount,
        'created_at', o.created_at,
        'item_count', (SELECT COUNT(*)::int FROM order_items oi WHERE oi.order_id = o.id),
        'owner_name', e.full_name
    ) ORDER BY o.created_at DESC)
    INTO v_orders
    FROM orders o
    LEFT JOIN employees e ON e.id = o.created_by
    WHERE o.customer_id = p_customer_id
      AND public.is_order_in_statistics(o.status)
      AND o.created_at::date >= p_from
      AND o.created_at::date <= p_to
      AND (p_filters->>'status' IS NULL OR p_filters->>'status' = '' OR o.status = p_filters->>'status');

    -- ==========================================
    -- VISITS
    -- ==========================================
    SELECT jsonb_agg(jsonb_build_object(
        'id', v.id,
        'code', v.code,
        'status', v.status,
        'visit_result', COALESCE(v.visit_result, '╪║┘è╪▒ ┘à╪ز┘ê┘╪▒'),
        'check_in_at', v.check_in_at,
        'check_out_at', v.check_out_at,
        'duration_minutes', CASE WHEN v.check_out_at IS NOT NULL THEN GREATEST(ROUND(EXTRACT(EPOCH FROM (v.check_out_at - v.check_in_at)) / 60)::int, 0) ELSE NULL END,
        'employee_name', COALESCE(e.full_name, '╪║┘è╪▒ ┘à╪ز┘ê┘╪▒')
    ) ORDER BY v.check_in_at DESC)
    INTO v_visits
    FROM visits v
    LEFT JOIN employees e ON e.id = v.employee_id
    WHERE v.customer_id = p_customer_id
      AND v.check_in_at::date >= p_from
      AND v.check_in_at::date <= p_to;

    -- ==========================================
    -- PRODUCTS ANALYSIS
    -- ==========================================
    SELECT jsonb_agg(jsonb_build_object(
        'product_id', p.id,
        'product_name', p.product_name,
        'company_name', COALESCE(c.company_name, '╪║┘è╪▒ ┘à╪ز┘ê┘╪▒'),
        'total_pieces', SUM(oi.piece_quantity)::int,
        'total_value', SUM(oi.total_price),
        'order_count', COUNT(DISTINCT oi.order_id)::int,
        'last_purchase', MAX(o.created_at),
        'qty_piece', COALESCE(SUM(CASE WHEN oi.unit_type = 'piece' THEN oi.unit_quantity ELSE 0 END), 0)::int,
        'qty_dozen', COALESCE(SUM(CASE WHEN oi.unit_type = 'dozen' THEN oi.unit_quantity ELSE 0 END), 0)::int,
        'qty_carton', COALESCE(SUM(CASE WHEN oi.unit_type = 'carton' THEN oi.unit_quantity ELSE 0 END), 0)::int
    ) ORDER BY SUM(oi.total_price) DESC NULLS LAST)
    INTO v_products
    FROM order_items oi
    JOIN orders o ON o.id = oi.order_id
    JOIN products p ON p.id = oi.product_id
    LEFT JOIN companies c ON c.id = p.company_id
    WHERE o.customer_id = p_customer_id
      AND public.is_order_in_statistics(o.status)
      AND o.created_at::date >= p_from
      AND o.created_at::date <= p_to
      AND (p_filters->>'product_id' IS NULL OR p_filters->>'product_id' = '' OR oi.product_id = (p_filters->>'product_id')::uuid)
      AND (p_filters->>'company_id' IS NULL OR p_filters->>'company_id' = '' OR p.company_id = (p_filters->>'company_id')::uuid)
    GROUP BY p.id, p.product_name, c.company_name;

    -- ==========================================
    -- COMPANIES / BRANDS ANALYSIS
    -- ==========================================
    SELECT jsonb_agg(jsonb_build_object(
        'company_id', comp.id,
        'company_name', comp.company_name,
        'order_count', comp_data.order_count,
        'total_spent', comp_data.total_spent,
        'share_pct', CASE WHEN v_total_value > 0 THEN ROUND((comp_data.total_spent / v_total_value * 100)::numeric, 1) ELSE 0 END
    ) ORDER BY comp_data.total_spent DESC)
    INTO v_companies
    FROM (
        SELECT c.id, c.company_name
        FROM companies c
        WHERE EXISTS (
            SELECT 1 FROM products p
            JOIN order_items oi ON oi.product_id = p.id
            JOIN orders o ON o.id = oi.order_id
            WHERE p.company_id = c.id
              AND o.customer_id = p_customer_id
              AND public.is_order_in_statistics(o.status)
              AND o.created_at::date >= p_from AND o.created_at::date <= p_to
        )
    ) comp
    JOIN LATERAL (
        SELECT COUNT(DISTINCT o.id)::int AS order_count,
               COALESCE(SUM(oi.total_price), 0) AS total_spent
        FROM products p
        JOIN order_items oi ON oi.product_id = p.id
        JOIN orders o ON o.id = oi.order_id
        WHERE p.company_id = comp.id
          AND o.customer_id = p_customer_id
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from AND o.created_at::date <= p_to
    ) comp_data ON true;

    -- ==========================================
    -- BEHAVIOR INSIGHTS
    -- ==========================================
    WITH order_dates AS (
        SELECT created_at::date AS order_date
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
        ORDER BY created_at
    ),
    gaps AS (
        SELECT order_date - LAG(order_date) OVER (ORDER BY order_date) AS gap_days
        FROM order_dates
    ),
    dow AS (
        SELECT EXTRACT(DOW FROM created_at) AS day_of_week,
               COUNT(*)::int AS cnt
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
        GROUP BY EXTRACT(DOW FROM created_at)
    ),
    half_split AS (
        SELECT
            COUNT(*) FILTER (WHERE created_at::date <= (p_from::date + ((p_to - p_from) / 2)::int)) AS first_half,
            COUNT(*) FILTER (WHERE created_at::date > (p_from::date + ((p_to - p_from) / 2)::int)) AS second_half
        FROM orders
        WHERE customer_id = p_customer_id
          AND public.is_order_in_statistics(status)
          AND created_at::date >= p_from
          AND created_at::date <= p_to
    )
    SELECT jsonb_build_object(
        'total_orders', COALESCE((v_summary->>'total_orders')::int, 0),
        'repeat_customer', COALESCE((v_summary->>'total_orders')::int, 0) > 1,
        'avg_days_between_orders', (SELECT ROUND(AVG(gap_days)::numeric, 1) FROM gaps WHERE gap_days IS NOT NULL),
        'peak_day_name', (SELECT CASE
            WHEN day_of_week = 0 THEN '╪د┘╪ث╪ص╪»' WHEN day_of_week = 1 THEN '╪د┘╪ح╪س┘┘è┘'
            WHEN day_of_week = 2 THEN '╪د┘╪س┘╪د╪س╪د╪ة' WHEN day_of_week = 3 THEN '╪د┘╪ث╪▒╪ذ╪╣╪د╪ة'
            WHEN day_of_week = 4 THEN '╪د┘╪«┘à┘è╪│' WHEN day_of_week = 5 THEN '╪د┘╪ش┘à╪╣╪ر'
            WHEN day_of_week = 6 THEN '╪د┘╪│╪ذ╪ز' ELSE '╪║┘è╪▒ ┘à╪ز┘ê┘╪▒'
        END FROM dow ORDER BY cnt DESC LIMIT 1),
        'peak_day_orders', (SELECT cnt FROM dow ORDER BY cnt DESC LIMIT 1),
        'trend', CASE
            WHEN (SELECT COUNT(*) FROM order_dates) >= 3 THEN (
                SELECT CASE
                    WHEN first_half < second_half THEN '╪▓┘è╪د╪»╪ر'
                    WHEN first_half > second_half THEN '╪د┘╪«┘╪د╪╢'
                    ELSE '╪س╪ذ╪د╪ز'
                END FROM half_split
            ) ELSE '╪║┘è╪▒ ┘â╪د┘┘'
        END,
        'first_order_date', (v_summary->>'first_order_date')::text,
        'last_order_date', (v_summary->>'last_order_date')::text,
        'total_months_active', CASE
            WHEN (v_summary->>'first_order_date') IS NOT NULL THEN
                GREATEST(1, (SELECT ROUND(EXTRACT(DAY FROM (p_to::timestamp - (v_summary->>'first_order_date')::timestamp)) / 30.44)::int))
            ELSE 0
        END,
        'value_per_month', CASE
            WHEN (v_summary->>'first_order_date') IS NOT NULL AND v_total_value > 0 THEN
                ROUND(v_total_value / NULLIF(GREATEST(1, (SELECT ROUND(EXTRACT(DAY FROM (p_to::timestamp - (v_summary->>'first_order_date')::timestamp)) / 30.44)::int)), 0), 2)
            ELSE 0
        END
    ) INTO v_insights;

    -- ==========================================
    -- FILTER OPTIONS
    -- ==========================================
    SELECT jsonb_build_object(
        'statuses', COALESCE((SELECT jsonb_agg(DISTINCT o.status) FROM orders o WHERE o.customer_id = p_customer_id AND public.is_order_in_statistics(o.status) AND o.created_at::date >= p_from AND o.created_at::date <= p_to), '[]'::jsonb),
        'products', COALESCE((SELECT jsonb_agg(DISTINCT jsonb_build_object('id', p.id, 'name', p.product_name)) FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.customer_id = p_customer_id AND public.is_order_in_statistics(o.status) AND o.created_at::date >= p_from AND o.created_at::date <= p_to), '[]'::jsonb),
        'companies', COALESCE((SELECT jsonb_agg(DISTINCT jsonb_build_object('id', c.id, 'name', c.company_name)) FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id JOIN companies c ON c.id = p.company_id WHERE o.customer_id = p_customer_id AND public.is_order_in_statistics(o.status) AND o.created_at::date >= p_from AND o.created_at::date <= p_to), '[]'::jsonb)
    ) INTO v_filter_options;

    RETURN jsonb_build_object(
        'summary', COALESCE(v_summary, jsonb_build_object('total_orders', 0, 'total_value', 0, 'avg_order_value', 0, 'total_visits', 0, 'active_days', 0)),
        'orders', COALESCE(v_orders, '[]'::jsonb),
        'visits', COALESCE(v_visits, '[]'::jsonb),
        'products', COALESCE(v_products, '[]'::jsonb),
        'companies', COALESCE(v_companies, '[]'::jsonb),
        'insights', COALESCE(v_insights, '{}'::jsonb),
        'filter_options', COALESCE(v_filter_options, '{}'::jsonb)
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_intelligence_overview(p_token uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_ids uuid[];
    v_customer_ids uuid[];
    v_general jsonb;
    v_top_customers jsonb;
    v_most_diverse jsonb;
    v_most_frequent jsonb;
    v_total_customers int;
    v_total_orders int;
    v_total_value numeric;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    -- Visible customers: get employee IDs then find their owned customers
    v_employee_ids := public.get_visible_employee_ids(p_token);
    IF v_employee_ids IS NULL THEN
        -- Upper Management: all customers
        SELECT array_agg(id) INTO v_customer_ids FROM customers WHERE is_active = true;
    ELSE
        -- Scoped: customers owned by visible employees
        SELECT array_agg(c.id) INTO v_customer_ids
        FROM customers c
        WHERE c.owner_id = ANY(v_employee_ids) AND c.is_active = true;
    END IF;

    IF v_customer_ids IS NULL OR array_length(v_customer_ids, 1) IS NULL THEN
        RETURN jsonb_build_object(
            'general_stats', '{}'::jsonb, 'top_customers', '[]'::jsonb,
            'most_diverse', '[]'::jsonb, 'most_frequent', '[]'::jsonb
        );
    END IF;

    -- ==========================================
    -- GENERAL STATS
    -- ==========================================
    WITH filtered AS (
        SELECT o.customer_id, o.total_amount, oi.product_id, oi.unit_type, oi.unit_quantity, oi.piece_quantity,
               p.company_id
        FROM orders o
        JOIN order_items oi ON oi.order_id = o.id
        JOIN products p ON p.id = oi.product_id
        WHERE o.customer_id = ANY(v_customer_ids)
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
          AND (p_search IS NULL OR p_search = '' OR EXISTS (
              SELECT 1 FROM customers cc WHERE cc.id = o.customer_id AND cc.company_name ILIKE '%' || p_search || '%'
          ))
    )
    SELECT jsonb_build_object(
        'customer_count', COALESCE((SELECT COUNT(DISTINCT customer_id)::int FROM filtered), 0),
        'order_count', COALESCE((SELECT COUNT(*)::int FROM orders o WHERE o.customer_id = ANY(v_customer_ids) AND public.is_order_in_statistics(o.status) AND o.created_at::date >= p_from AND o.created_at::date <= p_to), 0),
        'total_sales', COALESCE((SELECT SUM(total_amount) FROM orders o WHERE o.customer_id = ANY(v_customer_ids) AND public.is_order_in_statistics(o.status) AND o.created_at::date >= p_from AND o.created_at::date <= p_to), 0),
        'companies_count', COALESCE((SELECT COUNT(DISTINCT company_id)::int FROM filtered), 0),
        'products_count', COALESCE((SELECT COUNT(DISTINCT product_id)::int FROM filtered), 0),
        'total_pieces', COALESCE((SELECT SUM(piece_quantity)::int FROM filtered), 0),
        'total_dozens', COALESCE((SELECT SUM(unit_quantity) FILTER (WHERE unit_type = 'dozen')::int FROM filtered), 0),
        'total_cartons', COALESCE((SELECT SUM(unit_quantity) FILTER (WHERE unit_type = 'carton')::int FROM filtered), 0)
    ) INTO v_general;

    -- ==========================================
    -- TOP CUSTOMERS (by purchase value)
    -- ==========================================
    SELECT jsonb_agg(sub.obj) INTO v_top_customers FROM (
        SELECT jsonb_build_object(
            'customer_id', c.id,
            'company_name', c.company_name,
            'total_spent', COALESCE(SUM(o.total_amount), 0),
            'order_count', COUNT(DISTINCT o.id)::int,
            'last_order', MAX(o.created_at)
        ) AS obj
        FROM customers c
        JOIN orders o ON o.customer_id = c.id
        WHERE c.id = ANY(v_customer_ids)
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
          AND (p_search IS NULL OR p_search = '' OR c.company_name ILIKE '%' || p_search || '%')
        GROUP BY c.id, c.company_name
        ORDER BY SUM(o.total_amount) DESC NULLS LAST
        LIMIT 20
    ) sub;

    -- ==========================================
    -- MOST DIVERSE (by unique products + brands)
    -- ==========================================
    SELECT jsonb_agg(sub.obj) INTO v_most_diverse FROM (
        SELECT jsonb_build_object(
            'customer_id', c.id,
            'company_name', c.company_name,
            'unique_products', COALESCE(d.unique_products, 0),
            'unique_brands', COALESCE(d.unique_brands, 0),
            'diversity_score', COALESCE(d.diversity_score, 0)
        ) AS obj
        FROM customers c
        JOIN LATERAL (
            SELECT
                COUNT(DISTINCT oi.product_id)::int AS unique_products,
                COUNT(DISTINCT p.company_id)::int AS unique_brands,
                (COUNT(DISTINCT oi.product_id) + COUNT(DISTINCT p.company_id))::int AS diversity_score
            FROM orders o
            JOIN order_items oi ON oi.order_id = o.id
            JOIN products p ON p.id = oi.product_id
            WHERE o.customer_id = c.id
              AND public.is_order_in_statistics(o.status)
              AND o.created_at::date >= p_from
              AND o.created_at::date <= p_to
        ) d ON true
        WHERE c.id = ANY(v_customer_ids)
          AND (p_search IS NULL OR p_search = '' OR c.company_name ILIKE '%' || p_search || '%')
          AND d.unique_products > 0
        ORDER BY d.diversity_score DESC NULLS LAST
        LIMIT 20
    ) sub;

    -- ==========================================
    -- MOST FREQUENT (by order count)
    -- ==========================================
    SELECT jsonb_agg(sub.obj) INTO v_most_frequent FROM (
        SELECT jsonb_build_object(
            'customer_id', c.id,
            'company_name', c.company_name,
            'order_count', COALESCE(f.order_count, 0),
            'avg_days_between', f.avg_days_between,
            'first_order', f.first_order,
            'last_order', f.last_order
        ) AS obj
        FROM customers c
        JOIN LATERAL (
            SELECT
                COUNT(*)::int AS order_count,
                CASE WHEN COUNT(*) > 1 THEN ROUND((EXTRACT(DAY FROM (MAX(created_at) - MIN(created_at))) / (COUNT(*) - 1)::numeric), 1) ELSE NULL END AS avg_days_between,
                MIN(created_at) AS first_order,
                MAX(created_at) AS last_order
            FROM orders o
            WHERE o.customer_id = c.id
              AND public.is_order_in_statistics(o.status)
              AND o.created_at::date >= p_from
              AND o.created_at::date <= p_to
        ) f ON true
        WHERE c.id = ANY(v_customer_ids)
          AND (p_search IS NULL OR p_search = '' OR c.company_name ILIKE '%' || p_search || '%')
          AND f.order_count > 1
        ORDER BY f.order_count DESC
        LIMIT 20
    ) sub;

    RETURN jsonb_build_object(
        'general_stats', COALESCE(v_general, '{}'::jsonb),
        'top_customers', COALESCE(v_top_customers, '[]'::jsonb),
        'most_diverse', COALESCE(v_most_diverse, '[]'::jsonb),
        'most_frequent', COALESCE(v_most_frequent, '[]'::jsonb)
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_orders(p_token uuid, p_customer_id uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
    v_emp_id uuid;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    PERFORM set_config('app.identity_id', v_session.identity_id::text, true);

    IF v_session.identity_type = 'customer' THEN
        IF p_customer_id != v_session.customer_id THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN');
        END IF;
    ELSE
        v_emp_id := v_session.employee_id;
        IF NOT app.has_capability('customers.read')
           AND NOT EXISTS(SELECT 1 FROM customers c
                          WHERE c.id = p_customer_id
                            AND c.owner_id = ANY(app.get_subtree_ids(v_emp_id))) THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN');
        END IF;
    END IF;

    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id, 'order_number', o.order_number,
        'status', o.status, 'total_amount', o.total_amount,
        'created_at', o.created_at,
        'created_by_name', COALESCE(e.full_name, cu.company_name)
    ) ORDER BY o.created_at DESC) INTO v_result
    FROM orders o
    LEFT JOIN identities i ON i.id = o.created_by
    LEFT JOIN employees e ON e.identity_id = i.id AND i.identity_type = 'employee'
    LEFT JOIN customers cu ON cu.identity_id = i.id AND i.identity_type = 'customer'
    WHERE o.customer_id = p_customer_id
    LIMIT p_limit;

    RETURN COALESCE(v_result, '[]'::jsonb);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', 'INTERNAL_ERROR', 'detail', SQLERRM);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_products(p_token uuid, p_customer_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_identity_type text; v_identity_id uuid; v_employee_id uuid; v_visible uuid[];
  v_cust public.customers; v_top json; v_repeated json; v_stopped json;
BEGIN
  SELECT s.identity_type, s.identity_id, s.employee_id INTO v_identity_type, v_identity_id, v_employee_id FROM app.sessions s WHERE s.token = p_token AND s.expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_cust FROM public.customers WHERE id = p_customer_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_identity_type = 'customer' THEN IF v_cust.identity_id != v_identity_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  ELSIF v_cust.owner_id IS NOT NULL AND NOT (v_cust.owner_id = ANY(v_visible)) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT json_agg(subq ORDER BY subq.total_spent DESC) INTO v_top FROM (
    SELECT p.id AS product_id, p.product_name, co.company_name, oi.unit_type, SUM(oi.total_price) AS total_spent, COUNT(*)::int AS order_count
    FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id JOIN public.products p ON p.id = oi.product_id JOIN public.companies co ON co.id = p.company_id
    WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved')
    GROUP BY p.id, p.product_name, co.company_name, oi.unit_type ORDER BY total_spent DESC LIMIT 10
  ) subq;
  SELECT json_agg(subq ORDER BY subq.repeat_count DESC) INTO v_repeated FROM (
    SELECT p.id AS product_id, p.product_name, COUNT(*)::int AS repeat_count
    FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id JOIN public.products p ON p.id = oi.product_id
    WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved')
    GROUP BY p.id, p.product_name HAVING COUNT(*) > 1 ORDER BY repeat_count DESC LIMIT 10
  ) subq;
  SELECT COALESCE(json_agg(subq ORDER BY subq.last_order_date DESC NULLS LAST), '[]'::json) INTO v_stopped FROM (
    SELECT DISTINCT p.id AS product_id, p.product_name, MAX(o.submitted_at) AS last_order_date
    FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id JOIN public.products p ON p.id = oi.product_id
    WHERE o.customer_id = p_customer_id AND o.status IN ('submitted','approved')
    GROUP BY p.id, p.product_name HAVING MAX(o.submitted_at) < CURRENT_DATE - INTERVAL '90 days' LIMIT 10
  ) subq;
  RETURN json_build_object('top_products', v_top, 'repeated_products', v_repeated, 'stopped_products', v_stopped);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_products_analysis(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_products jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF p_from IS NULL THEN p_from := CURRENT_DATE - INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to := CURRENT_DATE; END IF;

    WITH product_agg AS (
        SELECT
            p.id AS product_id,
            p.product_name,
            c.company_name,
            oi.unit_type,
            SUM(oi.unit_quantity)::int AS total_quantity,
            COALESCE(SUM(oi.piece_quantity), 0)::int AS total_pieces,
            COUNT(DISTINCT oi.order_id)::int AS total_orders_count,
            COALESCE(SUM(oi.total_price), 0) AS total_value,
            MAX(o.created_at) AS last_purchase
        FROM order_items oi
        JOIN orders o ON o.id = oi.order_id
        JOIN products p ON p.id = oi.product_id
        LEFT JOIN companies c ON c.id = p.company_id
        WHERE o.customer_id = p_customer_id
          AND public.is_order_in_statistics(o.status)
          AND o.created_at::date >= p_from
          AND o.created_at::date <= p_to
        GROUP BY p.id, p.product_name, c.company_name, oi.unit_type
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'product_id', product_id,
        'product_name', COALESCE(product_name, 'غير متوفر'),
        'company_name', COALESCE(company_name, 'غير متوفر'),
        'unit_type', COALESCE(unit_type, 'piece'),
        'total_quantity', total_quantity,
        'total_pieces', total_pieces,
        'total_orders_count', total_orders_count,
        'total_value', total_value,
        'last_purchase', last_purchase
    ) ORDER BY total_value DESC NULLS LAST), '[]'::jsonb) INTO v_products
    FROM product_agg;

    RETURN jsonb_build_object('products', COALESCE(v_products, '[]'::jsonb));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_sales_ranking(p_token uuid)
 RETURNS TABLE(customer_id uuid, code character varying, company_name character varying, total_purchases numeric, order_count bigint, customer_ranking bigint, rep_customer_ranking bigint, owner_id uuid, followup_priority_score numeric, potential_revenue_score numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_identity_type text; v_identity_id uuid; v_employee_id uuid; v_visible uuid[];
BEGIN
  SELECT s.identity_type, s.identity_id, s.employee_id INTO v_identity_type, v_identity_id, v_employee_id FROM app.sessions s WHERE s.token = p_token AND s.expires_at > now(); IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY WITH visible_customers AS (
    SELECT c.id, c.code, c.company_name, c.owner_id FROM public.customers c
    WHERE (v_identity_type = 'customer' AND c.identity_id = v_identity_id) OR (c.owner_id = ANY(v_visible))
  ), intervals AS (
    SELECT subq.customer_id, AVG(subq.days)::numeric AS avg_interval FROM (
      SELECT o2.customer_id, EXTRACT(DAY FROM (o2.submitted_at - LAG(o2.submitted_at) OVER (PARTITION BY o2.customer_id ORDER BY o2.submitted_at)))::numeric AS days FROM public.orders o2
      WHERE o2.status IN ('submitted','approved') AND o2.submitted_at IS NOT NULL
    ) subq WHERE subq.days IS NOT NULL AND subq.days > 0 GROUP BY subq.customer_id
  ), order_stats AS (
    SELECT o.customer_id, COALESCE(SUM(o.total_amount), 0) AS total_purchases, COUNT(*)::bigint AS order_count, MAX(o.submitted_at) AS last_order_date FROM public.orders o
    WHERE o.status IN ('submitted','approved') GROUP BY o.customer_id
  ), ranked AS (
    SELECT vc.*, COALESCE(s.total_purchases, 0) AS tp, COALESCE(s.order_count, 0) AS oc, s.last_order_date, i.avg_interval,
      ROW_NUMBER() OVER (ORDER BY COALESCE(s.total_purchases, 0) DESC) AS customer_rank,
      ROW_NUMBER() OVER (PARTITION BY vc.owner_id ORDER BY COALESCE(s.total_purchases, 0) DESC) AS rep_rank
    FROM visible_customers vc
    LEFT JOIN order_stats s ON s.customer_id = vc.id
    LEFT JOIN intervals i ON i.customer_id = vc.id
  )
  SELECT r.id, r.code, r.company_name, r.tp, r.oc, r.customer_rank, r.rep_rank, r.owner_id,
    ROUND(COALESCE(CASE WHEN r.last_order_date IS NOT NULL THEN (EXTRACT(DAY FROM now() - r.last_order_date) * 1.0) + (30.0 / NULLIF(r.oc::numeric, 0)) + (r.tp / 1000.0) ELSE 999 END, 0), 2),
    ROUND(CASE WHEN r.last_order_date IS NOT NULL AND COALESCE(r.avg_interval, 0) > 0 THEN r.tp * GREATEST(0, EXTRACT(DAY FROM now() - r.last_order_date) / r.avg_interval) ELSE r.tp * 0.5 END, 2)
  FROM ranked r ORDER BY r.customer_rank;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_visits(p_token uuid, p_customer_id uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', v.id,
      'code', v.code,
      'status', v.status,
      'visit_result', v.visit_result,
      'check_in_at', v.check_in_at,
      'check_out_at', v.check_out_at,
      'notes', v.notes,
      'employee_name', e.full_name,
      'employee_code', e.code
    ) ORDER BY v.created_at DESC
  ) INTO v_result
  FROM visits v
  LEFT JOIN employees e ON e.id = v.employee_id
  WHERE v.customer_id = p_customer_id
  LIMIT p_limit;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_customer_visits_analysis(p_token uuid, p_customer_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_visits jsonb; v_stats jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error','INVALID_SESSION'); END IF;
    IF p_from IS NULL THEN p_from:=CURRENT_DATE-INTERVAL '12 months'; END IF;
    IF p_to IS NULL THEN p_to:=CURRENT_DATE; END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id',v.id,'code',COALESCE(v.code,'غير متوفر'),'status',COALESCE(v.status,'غير متوفر'),'visit_result',COALESCE(v.visit_result,'غير متوفر'),'check_in_at',v.check_in_at,'check_out_at',v.check_out_at,'duration_minutes',CASE WHEN v.check_out_at IS NOT NULL THEN GREATEST(ROUND(EXTRACT(EPOCH FROM (v.check_out_at-v.check_in_at))/60)::int,0) ELSE NULL END,'employee_name',COALESCE(e.full_name,'غير متوفر')) ORDER BY v.check_in_at DESC NULLS LAST),'[]'::jsonb) INTO v_visits FROM visits v LEFT JOIN employees e ON e.id=v.employee_id WHERE v.customer_id=p_customer_id AND v.check_in_at::date>=p_from AND v.check_in_at::date<=p_to;
    WITH vis_agg AS (SELECT COUNT(*)::int AS total_visits,COUNT(*) FILTER (WHERE v.status='completed')::int AS successful_visits,COUNT(*) FILTER (WHERE v.status!='completed')::int AS failed_visits,CASE WHEN COUNT(*) FILTER (WHERE v.check_out_at IS NOT NULL)>0 THEN ROUND(AVG(EXTRACT(EPOCH FROM (v.check_out_at-v.check_in_at))/60)::numeric,1) ELSE 0 END AS avg_duration_minutes,MAX(v.check_in_at) AS last_visit_date,MIN(v.check_in_at) AS first_visit_date,CASE WHEN COUNT(*)>0 THEN ROUND((COUNT(*) FILTER (WHERE v.status='completed'))::numeric/COUNT(*)::numeric*100,1) ELSE 0 END AS success_rate FROM visits v WHERE v.customer_id=p_customer_id AND v.check_in_at::date>=p_from AND v.check_in_at::date<=p_to) SELECT jsonb_build_object('total_visits',COALESCE(vis_agg.total_visits,0),'successful_visits',COALESCE(vis_agg.successful_visits,0),'failed_visits',COALESCE(vis_agg.failed_visits,0),'avg_duration_minutes',COALESCE(vis_agg.avg_duration_minutes,0),'last_visit_date',vis_agg.last_visit_date,'first_visit_date',vis_agg.first_visit_date,'success_rate',COALESCE(vis_agg.success_rate,0)) INTO v_stats FROM vis_agg;
    RETURN jsonb_build_object('visits',COALESCE(v_visits,'[]'::jsonb),'stats',COALESCE(v_stats,jsonb_build_object('total_visits',0,'successful_visits',0,'failed_visits',0,'avg_duration_minutes',0,'success_rate',0)));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_daily_target_vs_actual(p_token uuid, p_employee_id uuid DEFAULT NULL::uuid, p_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_target_date date;
    v_employee_ids uuid[];
    v_result jsonb;
    v_emp_record record;
    v_policy record;
    v_monthly_target record;
    v_target_hours numeric;
    v_today_net_seconds numeric;
    v_progress_pct numeric;
    v_remaining_seconds numeric;
    v_last_7 jsonb;
    v_kpi jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    v_target_date := COALESCE(p_date, CURRENT_DATE);

    -- Determine which employees to process
    IF p_employee_id IS NOT NULL THEN
        v_employee_ids := ARRAY[p_employee_id];
    ELSE
        -- All governed employees (team scope)
        IF public.check_capability(p_token, 'attendance.view_all') THEN
            SELECT ARRAY(SELECT id FROM public.employees WHERE is_active = true) INTO v_employee_ids;
        ELSE
            v_employee_ids := app.get_subtree_ids(v_session.employee_id);
        END IF;
    END IF;

    IF v_employee_ids IS NULL OR array_length(v_employee_ids, 1) IS NULL THEN
        RETURN jsonb_build_object('error', 'NO_EMPLOYEES');
    END IF;

    -- For single employee: detailed TargetResponse + KPI fields
    IF p_employee_id IS NOT NULL AND array_length(v_employee_ids, 1) = 1 THEN
        SELECT * INTO v_emp_record FROM public.employees WHERE id = p_employee_id;
        SELECT * INTO v_policy FROM public.employee_work_policies WHERE employee_id = p_employee_id;

        v_target_hours := COALESCE(v_policy.required_daily_hours, 8);

        -- Net work seconds for the target date
        SELECT COALESCE(SUM(
            EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) -
            COALESCE((SELECT SUM(COALESCE(wb.duration_seconds, 0)) FROM public.workday_breaks wb WHERE wb.session_id = wds.id), 0)
        ), 0) INTO v_today_net_seconds
        FROM public.workday_sessions wds
        WHERE wds.employee_id = p_employee_id
          AND wds.date = v_target_date
          AND wds.status = 'completed';

        v_progress_pct := CASE WHEN v_target_hours > 0 THEN ROUND((v_today_net_seconds / (v_target_hours * 3600) * 100)::numeric, 1) ELSE 0 END;
        v_remaining_seconds := GREATEST(0, (v_target_hours * 3600) - v_today_net_seconds);

        -- Last 7 days
        SELECT jsonb_agg(jsonb_build_object(
            'date', d.d::text,
            'net_hours', COALESCE(ROUND((
                EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) -
                COALESCE((SELECT SUM(COALESCE(wb.duration_seconds, 0)) FROM public.workday_breaks wb WHERE wb.session_id = wds.id), 0)
            ) / 3600, 1), 0),
            'target_hours', v_target_hours,
            'met_target', COALESCE((
                EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) -
                COALESCE((SELECT SUM(COALESCE(wb.duration_seconds, 0)) FROM public.workday_breaks wb WHERE wb.session_id = wds.id), 0)
            ) / 3600 >= v_target_hours, false)
        ) ORDER BY d.d)
        INTO v_last_7
        FROM (
            SELECT generate_series(v_target_date - 6, v_target_date, '1 day'::interval)::date AS d
        ) d
        LEFT JOIN public.workday_sessions wds ON wds.employee_id = p_employee_id AND wds.date = d.d AND wds.status = 'completed';

        -- Monthly target for KPI fields
        SELECT * INTO v_monthly_target FROM public.employee_monthly_targets
        WHERE employee_id = p_employee_id
          AND target_month = EXTRACT(MONTH FROM v_target_date)
          AND target_year = EXTRACT(YEAR FROM v_target_date);

        RETURN jsonb_build_object(
            -- TargetResponse fields (EmployeeWorkdayDetailPage / get_my_workday_status)
            'target_hours', v_target_hours,
            'current_net_seconds', v_today_net_seconds,
            'current_net_hours', ROUND((v_today_net_seconds / 3600)::numeric, 2),
            'progress_pct', v_progress_pct,
            'remaining_seconds', v_remaining_seconds,
            'schedule_type', COALESCE(v_policy.schedule_type, 'fixed_shift'),
            'last_7_days', COALESCE(v_last_7, '[]'::jsonb),
            -- KPI target/actual fields (HistoryPage / ReportsPage)
            'hours_target', v_target_hours,
            'hours_actual', ROUND((v_today_net_seconds / 3600)::numeric, 2),
            'orders_target', COALESCE(v_monthly_target.orders_target / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)), 0),
            'orders_actual', COALESCE((SELECT COUNT(*)::numeric FROM public.orders WHERE public.resolve_employee_id(owner_id) = p_employee_id AND created_at::date = v_target_date), 0),
            'sales_target', COALESCE(v_monthly_target.sales_target / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)), 0),
            'sales_actual', COALESCE((SELECT SUM(total_amount)::numeric FROM public.orders WHERE public.resolve_employee_id(owner_id) = p_employee_id AND created_at::date = v_target_date), 0),
            'collections_target', COALESCE(v_monthly_target.collections_target / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)), 0),
            'collections_actual', COALESCE((SELECT SUM(amount)::numeric FROM public.collections WHERE public.resolve_employee_id(owner_id) = p_employee_id AND created_at::date = v_target_date), 0),
            'new_customers_target', COALESCE(v_monthly_target.new_customers_target / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)), 0),
            'new_customers_actual', COALESCE((SELECT COUNT(*)::numeric FROM public.customers WHERE public.resolve_employee_id(owner_id) = p_employee_id AND created_at::date = v_target_date), 0)
        );
    END IF;

    -- For team/aggregate: return aggregated KPI fields
    SELECT jsonb_build_object(
        'hours_target', SUM(COALESCE(ewp.required_daily_hours, 8)),
        'hours_actual', ROUND(SUM(COALESCE((
            SELECT EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) -
                COALESCE((SELECT SUM(COALESCE(wb.duration_seconds, 0)) FROM public.workday_breaks wb WHERE wb.session_id = wds.id), 0)
            FROM public.workday_sessions wds
            WHERE wds.employee_id = e.id AND wds.date = v_target_date AND wds.status = 'completed'
        ), 0)) / 3600, 1),
        'orders_target', SUM(COALESCE(emt.orders_target, 0)) / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)),
        'orders_actual', COALESCE((SELECT COUNT(*)::numeric FROM public.orders o WHERE public.resolve_employee_id(o.owner_id) = ANY(v_employee_ids) AND o.created_at::date = v_target_date), 0),
        'sales_target', SUM(COALESCE(emt.sales_target, 0)) / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)),
        'sales_actual', COALESCE((SELECT SUM(total_amount)::numeric FROM public.orders o WHERE public.resolve_employee_id(o.owner_id) = ANY(v_employee_ids) AND o.created_at::date = v_target_date), 0),
        'collections_target', SUM(COALESCE(emt.collections_target, 0)) / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)),
        'collections_actual', COALESCE((SELECT SUM(amount)::numeric FROM public.collections c WHERE public.resolve_employee_id(c.owner_id) = ANY(v_employee_ids) AND c.created_at::date = v_target_date), 0),
        'new_customers_target', SUM(COALESCE(emt.new_customers_target, 0)) / EXTRACT(DAY FROM date_trunc('month', v_target_date) + interval '1 month' - date_trunc('month', v_target_date)),
        'new_customers_actual', COALESCE((SELECT COUNT(*)::numeric FROM public.customers cu WHERE public.resolve_employee_id(cu.owner_id) = ANY(v_employee_ids) AND cu.created_at::date = v_target_date), 0)
    ) INTO v_result
    FROM public.employees e
    LEFT JOIN public.employee_work_policies ewp ON ewp.employee_id = e.id
    LEFT JOIN public.employee_monthly_targets emt ON emt.employee_id = e.id
        AND emt.target_month = EXTRACT(MONTH FROM v_target_date)
        AND emt.target_year = EXTRACT(YEAR FROM v_target_date)
    WHERE e.id = ANY(v_employee_ids);

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_dashboard_management(p_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
  v_session app.sessions; v_is_super_admin boolean;
  v_visible uuid[]; v_ali_id uuid; v_mahmoud_id uuid;
  v_total_orders int; v_pending_orders int; v_approved_orders int;
  v_total_customers int; v_active_visits int; v_pending_collections int;
  v_pending_returns int; v_today_orders int; v_today_visits int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type = 'customer' THEN
    SELECT count(*) INTO v_total_orders FROM public.orders WHERE customer_id = v_session.customer_id;
    SELECT count(*) INTO v_pending_orders FROM public.orders WHERE customer_id = v_session.customer_id AND status IN ('draft','reviewing','submitted');
    SELECT count(*) INTO v_approved_orders FROM public.orders WHERE customer_id = v_session.customer_id AND status = 'approved';
    SELECT count(*) INTO v_total_customers FROM public.customers WHERE id = v_session.customer_id;
    SELECT count(*) INTO v_active_visits FROM public.visits WHERE customer_id = v_session.customer_id AND status = 'active';
    SELECT count(*) INTO v_pending_collections FROM public.collections WHERE customer_id = v_session.customer_id AND status = 'pending';
    SELECT count(*) INTO v_pending_returns FROM public.returns WHERE customer_id = v_session.customer_id AND status = 'pending';
    SELECT count(*) INTO v_today_orders FROM public.orders WHERE customer_id = v_session.customer_id AND created_at >= CURRENT_DATE;
    SELECT count(*) INTO v_today_visits FROM public.visits WHERE customer_id = v_session.customer_id AND created_at >= CURRENT_DATE;
  ELSE
    SELECT EXISTS(SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = v_session.employee_id AND r.name IN ('SUPER_ADMIN','CHAIRMAN','ADMIN')) INTO v_is_super_admin;
    IF v_is_super_admin THEN SELECT array_agg(id) INTO v_visible FROM public.employees;
    ELSE
      SELECT id INTO v_ali_id FROM public.employees WHERE code = 'WRQ1002' LIMIT 1;
      SELECT id INTO v_mahmoud_id FROM public.employees WHERE code = 'WRQ1004' LIMIT 1;
      IF v_session.employee_id IN (v_ali_id, v_mahmoud_id) THEN
        WITH RECURSIVE sub AS (SELECT e.id FROM public.employees e WHERE e.manager_id = (SELECT manager_id FROM public.employees WHERE id = v_ali_id) UNION SELECT e.id FROM public.employees e JOIN sub s ON e.manager_id = s.id) SELECT array_agg(id) INTO v_visible FROM sub;
      ELSE
        WITH RECURSIVE sub AS (SELECT id FROM public.employees WHERE id = v_session.employee_id UNION SELECT e.id FROM public.employees e JOIN sub s ON e.manager_id = s.id) SELECT array_agg(id) INTO v_visible FROM sub;
      END IF;
    END IF;
    SELECT count(*) INTO v_total_orders FROM public.orders WHERE owner_id = ANY(COALESCE(v_visible, '{}'::uuid[]));
    SELECT count(*) INTO v_pending_orders FROM public.orders WHERE owner_id = ANY(COALESCE(v_visible, '{}'::uuid[])) AND status IN ('draft','reviewing','submitted');
    SELECT count(*) INTO v_approved_orders FROM public.orders WHERE owner_id = ANY(COALESCE(v_visible, '{}'::uuid[])) AND status = 'approved';
    SELECT count(*) INTO v_total_customers FROM public.customers WHERE owner_id = ANY(COALESCE(v_visible, '{}'::uuid[]));
    SELECT count(*) INTO v_active_visits FROM public.visits WHERE employee_id = ANY(COALESCE(v_visible, '{}'::uuid[])) AND status = 'active';
    SELECT count(*) INTO v_pending_collections FROM public.collections WHERE created_by = ANY(COALESCE(v_visible, '{}'::uuid[])) AND status = 'pending';
    SELECT count(*) INTO v_pending_returns FROM public.returns WHERE created_by = ANY(COALESCE(v_visible, '{}'::uuid[])) AND status = 'pending';
    SELECT count(*) INTO v_today_orders FROM public.orders WHERE owner_id = ANY(COALESCE(v_visible, '{}'::uuid[])) AND created_at >= CURRENT_DATE;
    SELECT count(*) INTO v_today_visits FROM public.visits WHERE employee_id = ANY(COALESCE(v_visible, '{}'::uuid[])) AND created_at >= CURRENT_DATE;
  END IF;
  RETURN json_build_object('total_orders', COALESCE(v_total_orders, 0), 'pending_orders', COALESCE(v_pending_orders, 0), 'approved_orders', COALESCE(v_approved_orders, 0), 'total_customers', COALESCE(v_total_customers, 0), 'active_visits', COALESCE(v_active_visits, 0), 'pending_collections', COALESCE(v_pending_collections, 0), 'pending_returns', COALESCE(v_pending_returns, 0), 'today_orders', COALESCE(v_today_orders, 0), 'today_visits', COALESCE(v_today_visits, 0));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_dashboard_sales(p_token uuid, p_inactive_days integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_visible uuid[];
  v_identity_ids uuid[];
  v_today_orders bigint;
  v_pending_followup int;
  v_inactive_customers int;
  v_today_visits int;
  v_today_collections_count bigint;
  v_today_collections_amount numeric;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  v_visible := public.get_visible_employee_ids(p_token);

  SELECT COALESCE(array_agg(e.identity_id), '{}'::uuid[])
  INTO v_identity_ids
  FROM public.employees e
  WHERE e.id = ANY(v_visible);

  -- CANONICAL F1/F2: today orders
  SELECT order_count INTO v_today_orders
  FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', v_identity_ids);

  SELECT COUNT(*)::int INTO v_pending_followup
  FROM public.orders
  WHERE created_by = ANY(v_identity_ids) AND status IN ('draft', 'reviewing', 'submitted');

  SELECT COUNT(*)::int INTO v_inactive_customers
  FROM public.customers
  WHERE owner_id = ANY(v_visible)
    AND is_active = true
    AND COALESCE(updated_at, created_at) < CURRENT_DATE - p_inactive_days;

  SELECT COUNT(*)::int INTO v_today_visits
  FROM public.visits
  WHERE employee_id = ANY(v_visible) AND created_at >= CURRENT_DATE;

  -- CANONICAL F3: Collected Amount Today
  SELECT collected_count, collected_amount
  INTO v_today_collections_count, v_today_collections_amount
  FROM public.get_kpi_collections_collected_amount(CURRENT_DATE, CURRENT_DATE + interval '1 day', v_visible);

  RETURN json_build_object(
    'today_orders', v_today_orders,
    'pending_followup', v_pending_followup,
    'inactive_customers', v_inactive_customers,
    'today_visits', v_today_visits,
    -- CANONICAL F3: Collected Amount Today (value is primary, count is secondary)
    'today_collections', v_today_collections_amount,
    'today_collections_count', v_today_collections_count
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_dashboard_transport(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[]; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error','INVALID_SESSION'); END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN jsonb_build_object('ready_delivery',0,'out_delivery',0,'delivery_queue',0,'collection_queue',0,'delivered_today',0,'failed',0,'pending_collections',0,'overdue_collections',0);
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  SELECT jsonb_build_object(
    'ready_delivery', (SELECT count(*) FROM public.orders WHERE status = 'approved' AND owner_id = ANY(v_visible) AND NOT EXISTS (SELECT 1 FROM delivery_tracking WHERE order_id = orders.id)),
    'out_delivery', (SELECT count(*) FROM public.delivery_tracking WHERE status IN ('assigned','out_for_delivery')),
    'delivery_queue', (SELECT count(*) FROM public.delivery_tracking WHERE status NOT IN ('delivered','failed','returned')),
    'collection_queue', (SELECT count(*) FROM public.collections WHERE status = 'pending' AND owner_id = ANY(v_visible)),
    'delivered_today', (SELECT count(*) FROM public.delivery_tracking WHERE status = 'delivered' AND completed_at >= CURRENT_DATE),
    'failed', (SELECT count(*) FROM public.delivery_tracking WHERE status IN ('failed','returned')),
    'pending_collections', (SELECT count(*) FROM public.collections c JOIN public.customers cu ON cu.id = c.customer_id WHERE c.status = 'pending' AND cu.owner_id = ANY(v_visible)),
    'overdue_collections', (SELECT count(*) FROM public.collections c JOIN public.customers cu ON cu.id = c.customer_id WHERE c.status = 'pending' AND c.created_at < now() - interval '30 days' AND cu.owner_id = ANY(v_visible))
  ) INTO v_result;
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_dashboard_warehouse(p_token uuid)
 RETURNS TABLE(counter text, value bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN; END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY
      SELECT 'waiting_preparation'::text, COUNT(*)::bigint FROM public.orders o WHERE o.status = 'approved' AND NOT EXISTS (SELECT 1 FROM public.preparation_records pr WHERE pr.order_id = o.id)
      UNION ALL SELECT 'in_preparation'::text, COUNT(*)::bigint FROM public.preparation_records WHERE status = 'in_progress'
      UNION ALL SELECT 'ready_for_delivery'::text, COUNT(*)::bigint FROM public.preparation_records WHERE status = 'reviewed'
      UNION ALL SELECT 'prepared_today'::text, COUNT(*)::bigint FROM public.preparation_records WHERE completed_at >= CURRENT_DATE
      UNION ALL SELECT 'delayed_preps'::text, COUNT(*)::bigint FROM public.preparation_records WHERE status = 'in_progress' AND started_at < now() - interval '24 hours';
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY
    SELECT 'waiting_preparation'::text, COUNT(*)::bigint FROM public.orders o WHERE o.status = 'approved' AND o.owner_id = ANY(v_visible) AND NOT EXISTS (SELECT 1 FROM public.preparation_records pr WHERE pr.order_id = o.id)
    UNION ALL SELECT 'in_preparation'::text, COUNT(*)::bigint FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id WHERE pr.status = 'in_progress' AND o.owner_id = ANY(v_visible)
    UNION ALL SELECT 'ready_for_delivery'::text, COUNT(*)::bigint FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id WHERE pr.status = 'reviewed' AND o.owner_id = ANY(v_visible)
    UNION ALL SELECT 'prepared_today'::text, COUNT(*)::bigint FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id WHERE pr.completed_at >= CURRENT_DATE AND o.owner_id = ANY(v_visible)
    UNION ALL SELECT 'delayed_preps'::text, COUNT(*)::bigint FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id WHERE pr.status = 'in_progress' AND pr.started_at < now() - interval '24 hours' AND o.owner_id = ANY(v_visible);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_delivery_dashboard_stats(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[]; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error','INVALID_SESSION'); END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN jsonb_build_object('ready_delivery',0,'assigned',0,'out_for_delivery',0,'delivered_today',0,'failed',0,'pending_collections',0,'overdue_collections',0);
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  SELECT jsonb_build_object(
    'ready_delivery', (SELECT count(*) FROM public.orders WHERE status = 'approved' AND owner_id = ANY(v_visible) AND NOT EXISTS (SELECT 1 FROM delivery_tracking WHERE order_id = orders.id)),
    'assigned', (SELECT count(*) FROM public.delivery_tracking WHERE status = 'assigned'),
    'out_for_delivery', (SELECT count(*) FROM public.delivery_tracking WHERE status = 'out_for_delivery'),
    'delivered_today', (SELECT count(*) FROM public.delivery_tracking WHERE status = 'delivered' AND completed_at >= CURRENT_DATE),
    'failed', (SELECT count(*) FROM public.delivery_tracking WHERE status IN ('failed','returned')),
    'pending_collections', (SELECT count(*) FROM public.collections WHERE status = 'pending' AND owner_id = ANY(v_visible)),
    'overdue_collections', (SELECT count(*) FROM public.collections WHERE status = 'pending' AND created_at < now() - interval '30 days')
  ) INTO v_result;
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_effective_customer_location(p_customer_id uuid)
 RETURNS TABLE(latitude numeric, longitude numeric, source text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

BEGIN
    RETURN QUERY
    WITH customer_loc AS (
        SELECT ul.latitude, ul.longitude, 'customer_location'::text AS source
        FROM public.customers c
        JOIN public.unified_locations ul ON ul.id = c.location_id
        WHERE c.id = p_customer_id AND ul.latitude IS NOT NULL
    ),
    visit_loc AS (
        SELECT v.check_out_latitude, v.check_out_longitude, 'visit_gps'::text AS source
        FROM public.visits v
        WHERE v.customer_id = p_customer_id
          AND v.status = 'completed'
          AND v.check_out_latitude IS NOT NULL
          AND v.check_out_longitude IS NOT NULL
        ORDER BY v.check_out_at DESC
        LIMIT 1
    ),
    address_loc AS (
        SELECT caddr.latitude, caddr.longitude, 'address_geocoded'::text AS source
        FROM public.customers c
        LEFT JOIN LATERAL fn_customer_default_address(c.id) caddr ON true
        WHERE c.id = p_customer_id AND caddr.latitude IS NOT NULL
    )
    SELECT * FROM customer_loc
    UNION ALL
    SELECT * FROM visit_loc WHERE NOT EXISTS (SELECT 1 FROM customer_loc)
    UNION ALL
    SELECT * FROM address_loc
    WHERE NOT EXISTS (SELECT 1 FROM customer_loc)
      AND NOT EXISTS (SELECT 1 FROM visit_loc)
    LIMIT 1;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_effective_weights(p_employee_id uuid, p_target_month integer, p_target_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_monthly_targets public.company_monthly_targets;
    v_override public.employee_weight_overrides;
    v_result jsonb;
    v_orders_default numeric := 7.5;
BEGIN
    -- First check for an active override
    SELECT * INTO v_override
    FROM public.employee_weight_overrides
    WHERE employee_id = p_employee_id
        AND target_month = p_target_month
        AND target_year = p_target_year
        AND is_active = true;

    IF FOUND THEN
        v_result := jsonb_build_object(
            'source', 'override',
            'sales_weight_percent', COALESCE(v_override.sales_weight_percent, 35),
            'collections_weight_percent', COALESCE(v_override.collections_weight_percent, 20),
            'visits_weight_percent', COALESCE(v_override.visits_weight_percent, 15),
            'orders_weight_percent', COALESCE(v_override.orders_weight_percent, v_orders_default),
            'new_customers_weight_percent', COALESCE(v_override.new_customers_weight_percent, 15),
            'attendance_weight_percent', COALESCE(v_override.attendance_weight_percent, 15)
        );
        RETURN v_result;
    END IF;

    -- Fall back to company monthly weights (Canonical Source: company_monthly_targets)
    SELECT * INTO v_monthly_targets
    FROM public.company_monthly_targets
    WHERE target_month = p_target_month
      AND target_year = p_target_year;

    IF FOUND THEN
        v_result := jsonb_build_object(
            'source', 'config',
            'sales_weight_percent', v_monthly_targets.sales_weight_percent,
            'collections_weight_percent', v_monthly_targets.collections_weight_percent,
            'visits_weight_percent', v_monthly_targets.visits_weight_percent,
            'orders_weight_percent', COALESCE(v_monthly_targets.orders_weight_percent, v_orders_default),
            'new_customers_weight_percent', v_monthly_targets.new_customers_weight_percent,
            'attendance_weight_percent', v_monthly_targets.attendance_weight_percent
        );
        RETURN v_result;
    END IF;

    -- Hardcoded defaults (no company target row found for this month/year)
    RETURN jsonb_build_object(
        'source', 'default',
        'sales_weight_percent', 35,
        'collections_weight_percent', 20,
        'visits_weight_percent', 15,
        'orders_weight_percent', v_orders_default,
        'new_customers_weight_percent', 15,
        'attendance_weight_percent', 15
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_activity(p_token uuid, p_employee_id uuid, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_emp_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Customer sessions cannot view employee activity
  IF v_session.identity_type = 'customer' THEN
    RETURN '[]'::jsonb;
  END IF;

  PERFORM set_config('app.identity_id', v_session.identity_id::text, true);

  v_emp_id := app.current_employee_id();

  -- If no customers.read capability, restrict to visible subtree
  IF NOT app.has_capability('customers.read') THEN
    IF p_employee_id != ALL(app.get_subtree_ids(v_emp_id)) THEN
      RETURN '[]'::jsonb;
    END IF;
  END IF;

  WITH orders_activity AS (
    SELECT 'order' as activity_type, o.order_number as ref, o.status, o.total_amount, o.created_at
    FROM orders o WHERE o.created_by = (SELECT identity_id FROM employees WHERE id = p_employee_id)
    ORDER BY o.created_at DESC LIMIT p_limit
  ),
  visits_activity AS (
    SELECT 'visit' as activity_type, v.code as ref, v.visit_result as status, NULL::numeric as total_amount, v.created_at
    FROM visits v WHERE v.employee_id = p_employee_id
    ORDER BY v.created_at DESC LIMIT p_limit
  ),
  collections_activity AS (
    SELECT 'collection' as activity_type, c.code as ref, c.status, c.amount as total_amount, c.created_at
    FROM collections c WHERE c.created_by = p_employee_id
    ORDER BY c.created_at DESC LIMIT p_limit
  ),
  combined AS (SELECT * FROM orders_activity UNION ALL SELECT * FROM visits_activity UNION ALL SELECT * FROM collections_activity)
  SELECT jsonb_agg(jsonb_build_object(
    'activity_type', activity_type, 'ref', ref,
    'status', status, 'total_amount', total_amount, 'created_at', created_at
  ) ORDER BY created_at DESC) INTO v_result FROM combined;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_activity_summary_batch(p_token uuid, p_employee_ids uuid[], p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_is_super boolean;
  v_visible uuid[];
  v_effective_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type != 'employee' THEN
    RETURN jsonb_build_object('error', 'NOT_EMPLOYEE');
  END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);

  IF NOT v_is_super THEN
    v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
    SELECT ARRAY_AGG(x) INTO v_effective_ids
    FROM UNNEST(p_employee_ids) u(x)
    WHERE x = ANY(v_visible);
    IF v_effective_ids IS NULL OR array_length(v_effective_ids, 1) IS NULL THEN
      RETURN '[]'::jsonb;
    END IF;
  ELSE
    v_effective_ids := p_employee_ids;
  END IF;

  RETURN (
    WITH order_data AS (
      SELECT
        o.owner_id AS eid,
        COUNT(*)::int AS order_count,
        COALESCE(SUM(o.total_amount), 0) AS sales_total
      FROM public.orders o
      WHERE o.owner_id = ANY(v_effective_ids)
        AND o.created_at::date >= p_from
        AND o.created_at::date <= p_to
        AND public.is_order_in_statistics(o.status)
      GROUP BY o.owner_id
    ),
    visit_data AS (
      SELECT
        v.employee_id AS eid,
        COUNT(*)::int AS visit_count
      FROM public.visits v
      WHERE v.employee_id = ANY(v_effective_ids)
        AND v.check_in_at::date >= p_from
        AND v.check_in_at::date <= p_to
      GROUP BY v.employee_id
    ),
    customer_data AS (
      SELECT
        c.owner_id AS eid,
        COUNT(*)::int AS customer_count
      FROM public.customers c
      WHERE c.owner_id = ANY(v_effective_ids)
        AND c.created_at::date >= p_from
        AND c.created_at::date <= p_to
      GROUP BY c.owner_id
    )
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'employee_id', e.eid,
        'sales', COALESCE(o.sales_total, 0),
        'orders', COALESCE(o.order_count, 0),
        'visits', COALESCE(v.visit_count, 0),
        'customers', COALESCE(c.customer_count, 0)
      )
    ), '[]'::jsonb)
    FROM (SELECT UNNEST(v_effective_ids) AS eid) e
    LEFT JOIN order_data o ON o.eid = e.eid
    LEFT JOIN visit_data v ON v.eid = e.eid
    LEFT JOIN customer_data c ON c.eid = e.eid
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_capabilities(p_token uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_role_id uuid;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT role_id INTO v_role_id FROM public.employee_roles WHERE employee_id = p_employee_id LIMIT 1;

  WITH role_caps AS (
    SELECT c.id FROM role_capabilities rc JOIN capabilities c ON c.id = rc.capability_id
    WHERE rc.role_id = v_role_id
  ),
  direct_caps AS (
    SELECT c.id, ec.grant_type FROM employee_capabilities ec JOIN capabilities c ON c.id = ec.capability_id
    WHERE ec.employee_id = p_employee_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'code', c.code,
      'name', c.name,
      'group', c."group",
      'from_role', COALESCE(rc.id IS NOT NULL, false),
      'grant_type',
        CASE
          WHEN dc.grant_type IS NOT NULL THEN dc.grant_type::text
          WHEN rc.id IS NOT NULL THEN 'grant'
          ELSE NULL
        END
    )
    ORDER BY c."group", c.name
  ) INTO v_result
  FROM capabilities c
  LEFT JOIN role_caps rc ON rc.id = c.id
  LEFT JOIN direct_caps dc ON dc.id = c.id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_current_location(p_token uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN
      IF NOT EXISTS (SELECT 1 FROM public.get_visible_employee_ids(p_token) AS eid WHERE eid = p_employee_id) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
      END IF;
    END IF;
    SELECT jsonb_build_object('employee_id', e.id, 'name', e.full_name, 'latitude', tp.latitude, 'longitude', tp.longitude,
        'address', COALESCE(ea.address, ''), 'status', COALESCE(wds.status, 'inactive'),
        'attendance_status', wds.attendance_status, 'last_updated_at', tp.recorded_at,
        'last_seen_label', CASE WHEN tp.recorded_at > now() - interval '5 minutes' THEN '??? ?????'
            WHEN tp.recorded_at > now() - interval '30 minutes' THEN '??? ????? ' || round(EXTRACT(EPOCH FROM (now() - tp.recorded_at)) / 60) || ' ?????'
            ELSE '??? ???? ?? ??? ????' END)
    INTO v_result
    FROM public.employees e
    LEFT JOIN LATERAL (SELECT latitude, longitude, recorded_at FROM public.tracking_points WHERE employee_id = p_employee_id ORDER BY recorded_at DESC LIMIT 1) tp ON true
    LEFT JOIN LATERAL (SELECT * FROM public.workday_sessions WHERE employee_id = p_employee_id AND date = CURRENT_DATE ORDER BY start_time DESC LIMIT 1) wds ON true
    LEFT JOIN public.employee_addresses ea ON ea.employee_id = e.id AND ea.is_primary = true
    WHERE e.id = p_employee_id;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_day_map(p_token uuid, p_employee_id uuid, p_date date DEFAULT CURRENT_DATE, p_min_distance_threshold numeric DEFAULT 20, p_max_accuracy numeric DEFAULT 50, p_max_speed numeric DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_session_record record;
    v_route jsonb;
    v_stops jsonb;
    v_visit_locations jsonb;
    v_route_arr jsonb[];
    v_pt record;
    v_i int := 0;
    v_prev_time timestamptz;
    v_prev_lat numeric;
    v_prev_lng numeric;
    v_gap_minutes numeric;

    -- Drift-filtered distance tracking (anchor-based)
    v_total_distance numeric := 0;
    v_anchor_lat numeric;
    v_anchor_lng numeric;
    v_anchor_time timestamptz;
    v_anchor_set boolean := false;
    v_dist numeric;
    v_time_diff_sec numeric;
    v_speed numeric;
    v_consecutive_speed_skips int := 0;

    -- Statistics
    v_max_consecutive_distance numeric := 0;
    v_skipped_accuracy int := 0;
    v_skipped_min_distance int := 0;
    v_skipped_speed int := 0;
    v_counted_segments int := 0;
    v_valid_count int := 0;

    -- Fallback pass
    v_use_relaxed_accuracy boolean := false;
    v_effective_max_accuracy numeric;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'attendance.view_timeline') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;
    IF v_subtree_ids IS NOT NULL AND NOT (p_employee_id = ANY(v_subtree_ids)) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT * INTO v_session_record FROM public.workday_sessions wds
    WHERE wds.employee_id = p_employee_id AND wds.date = p_date
    ORDER BY wds.start_time DESC LIMIT 1;

    -- Build route array (unfiltered — always correct for visual map) and calculate distance
    LOOP
        -- Reset per-pass counters (route is kept across passes)
        v_total_distance := 0;
        v_anchor_set := false;
        v_consecutive_speed_skips := 0;
        v_skipped_accuracy := 0;
        v_skipped_min_distance := 0;
        v_skipped_speed := 0;
        v_counted_segments := 0;
        v_valid_count := 0;
        v_i := 0;

        IF v_use_relaxed_accuracy THEN
            v_effective_max_accuracy := GREATEST(p_max_accuracy, 500);
        ELSE
            v_effective_max_accuracy := p_max_accuracy;
        END IF;

        FOR v_pt IN
            SELECT tp.latitude, tp.longitude, tp.recorded_at, tp.point_type, tp.accuracy_meters
            FROM public.tracking_points tp
            WHERE tp.employee_id = p_employee_id AND tp.recorded_at::date = p_date
            ORDER BY tp.recorded_at
        LOOP
            v_i := v_i + 1;

            -- Only build route array on first pass
            IF NOT v_use_relaxed_accuracy THEN
                v_route_arr := array_append(v_route_arr, jsonb_build_object(
                    'latitude', v_pt.latitude,
                    'longitude', v_pt.longitude,
                    'time', v_pt.recorded_at,
                    'type', v_pt.point_type
                ));

                -- Stop detection (uses all consecutive raw points, unfiltered)
                IF v_i > 1 AND v_prev_time IS NOT NULL THEN
                    v_gap_minutes := EXTRACT(EPOCH FROM (v_pt.recorded_at - v_prev_time)) / 60;
                    IF v_gap_minutes > 5 THEN
                        v_stops := COALESCE(v_stops, '[]'::jsonb) || jsonb_build_object(
                            'start_time', v_prev_time,
                            'end_time', v_pt.recorded_at,
                            'duration_minutes', v_gap_minutes::int,
                            'latitude', v_prev_lat,
                            'longitude', v_prev_lng,
                            'type', 'gap'
                        );
                    END IF;
                END IF;
                v_prev_time := v_pt.recorded_at;
                v_prev_lat := v_pt.latitude;
                v_prev_lng := v_pt.longitude;
            END IF;

            -- GPS coordinate validation — skip garbage points
            IF v_pt.latitude < -90 OR v_pt.latitude > 90
               OR v_pt.longitude < -180 OR v_pt.longitude > 180
               OR (ABS(v_pt.latitude) < 0.01 AND ABS(v_pt.longitude) < 0.01) THEN
                CONTINUE;
            END IF;

            v_valid_count := v_valid_count + 1;

            -- Distance calculation with GPS drift filters (anchor-based)
            IF NOT v_anchor_set THEN
                IF v_pt.accuracy_meters IS NULL OR v_pt.accuracy_meters <= v_effective_max_accuracy THEN
                    v_anchor_lat := v_pt.latitude;
                    v_anchor_lng := v_pt.longitude;
                    v_anchor_time := v_pt.recorded_at;
                    v_anchor_set := true;
                END IF;
            ELSE
                -- Filter 1: low-accuracy points excluded from distance
                IF v_pt.accuracy_meters IS NOT NULL AND v_pt.accuracy_meters > v_effective_max_accuracy THEN
                    v_skipped_accuracy := v_skipped_accuracy + 1;
                    CONTINUE;
                END IF;

                -- Haversine distance from anchor in meters
                v_dist := 6371000 * 2 * asin(sqrt(
                    power(sin(radians(v_pt.latitude - v_anchor_lat) / 2), 2) +
                    cos(radians(v_anchor_lat)) * cos(radians(v_pt.latitude)) *
                    power(sin(radians(v_pt.longitude - v_anchor_lng) / 2), 2)
                ));

                -- Filter 2: below threshold = GPS drift, skip
                IF v_dist < p_min_distance_threshold THEN
                    v_skipped_min_distance := v_skipped_min_distance + 1;
                    CONTINUE;
                END IF;

                -- Filter 3: speed-based outlier (phantom jump detection)
                v_time_diff_sec := EXTRACT(EPOCH FROM (v_pt.recorded_at - v_anchor_time));
                IF v_time_diff_sec > 0 THEN
                    v_speed := v_dist / v_time_diff_sec;
                    IF v_speed > p_max_speed THEN
                        v_skipped_speed := v_skipped_speed + 1;
                        v_consecutive_speed_skips := v_consecutive_speed_skips + 1;
                        -- Reset anchor if too many consecutive speed outliers
                        IF v_consecutive_speed_skips >= 5 THEN
                            v_anchor_lat := v_pt.latitude;
                            v_anchor_lng := v_pt.longitude;
                            v_anchor_time := v_pt.recorded_at;
                            v_consecutive_speed_skips := 0;
                        END IF;
                        CONTINUE;
                    END IF;
                END IF;

                -- Passed all filters: count this segment
                v_total_distance := v_total_distance + v_dist;
                v_counted_segments := v_counted_segments + 1;
                v_consecutive_speed_skips := 0;

                -- Track max consecutive distance
                IF v_dist > v_max_consecutive_distance THEN
                    v_max_consecutive_distance := v_dist;
                END IF;

                -- Update anchor to current point
                v_anchor_lat := v_pt.latitude;
                v_anchor_lng := v_pt.longitude;
                v_anchor_time := v_pt.recorded_at;
            END IF;
        END LOOP;

        -- Exit if: result is non-zero, already tried relaxed, or too few valid points
        IF v_total_distance > 0 OR v_use_relaxed_accuracy OR v_valid_count < 2 THEN
            EXIT;
        END IF;

        v_use_relaxed_accuracy := true;
    END LOOP;

    -- Build visit locations (only once)
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'visit_id', v.id,
        'customer_id', v.customer_id,
        'customer_name', c.company_name,
        'latitude', v.check_in_latitude,
        'longitude', v.check_in_longitude,
        'check_in_at', v.check_in_at,
        'check_out_at', v.check_out_at,
        'visit_result', v.visit_result
    ) ORDER BY v.check_in_at), '[]'::jsonb) INTO v_visit_locations
    FROM public.visits v
    LEFT JOIN public.customers c ON c.id = v.customer_id
    WHERE v.employee_id = p_employee_id AND v.check_in_at::date = p_date
    AND v.check_in_latitude IS NOT NULL;

    v_route := COALESCE((SELECT jsonb_agg(elem) FROM unnest(v_route_arr) AS elem), '[]'::jsonb);

    RETURN jsonb_build_object(
        'session', jsonb_build_object(
            'employee_id', v_session_record.employee_id,
            'date', v_session_record.date,
            'start_time', v_session_record.start_time,
            'end_time', v_session_record.end_time,
            'attendance_status', v_session_record.attendance_status
        ),
        'route', COALESCE(v_route, '[]'::jsonb),
        'total_points', v_i,
        'total_distance_meters', v_total_distance::int,
        'total_distance_km', round((v_total_distance / 1000)::numeric, 2),
        'total_counted_segments', v_counted_segments,
        'max_consecutive_distance', v_max_consecutive_distance::int,
        'filter_stats', jsonb_build_object(
            'skipped_accuracy', v_skipped_accuracy,
            'skipped_min_distance', v_skipped_min_distance,
            'skipped_speed', v_skipped_speed,
            'min_distance_threshold', p_min_distance_threshold,
            'max_accuracy', p_max_accuracy,
            'max_speed', p_max_speed
        ),
        'visit_locations', COALESCE(v_visit_locations, '[]'::jsonb),
        'long_stops', COALESCE(v_stops, '[]'::jsonb),
        'long_stops_count', COALESCE(jsonb_array_length(v_stops), 0),
        'long_stops_total_minutes', COALESCE((SELECT SUM((s->>'duration_minutes')::int) FROM jsonb_array_elements(v_stops) s), 0)
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_day_timeline(p_token uuid, p_employee_id uuid, p_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_events jsonb;
    v_session_record record;
    v_employee_info jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'attendance.view_timeline') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;
    IF v_subtree_ids IS NOT NULL AND NOT (p_employee_id = ANY(v_subtree_ids)) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT wds.* INTO v_session_record FROM public.workday_sessions wds
    WHERE wds.employee_id = p_employee_id AND wds.date = p_date
    ORDER BY
        CASE WHEN p_date < CURRENT_DATE AND wds.status = 'completed' THEN 0
             WHEN p_date >= CURRENT_DATE AND wds.status = 'active' THEN 0
             ELSE 1 END,
        wds.start_time DESC
    LIMIT 1;

    SELECT jsonb_build_object(
        'id', e.id, 'full_name', e.full_name, 'code', e.code,
        'role_name', COALESCE(r.name, ''),
        'manager_name', COALESCE(m.full_name, '')
    ) INTO v_employee_info
    FROM public.employees e
    LEFT JOIN public.employee_roles er ON er.employee_id = e.id
    LEFT JOIN public.roles r ON r.id = er.role_id
    LEFT JOIN public.employees m ON m.id = e.manager_id
    WHERE e.id = p_employee_id;

    WITH all_events AS (
        SELECT ws.start_time AS event_time, 'workday_start' AS event_type,
            'بدء يوم العمل' AS title, '' AS description,
            ws.start_latitude::text AS lat, ws.start_longitude::text AS lng,
            jsonb_build_object('session_id', ws.id) AS metadata
        FROM public.workday_sessions ws
        WHERE ws.id = v_session_record.id
        UNION ALL
        SELECT ws.end_time, 'workday_end', 'إنهاء يوم العمل', '',
            ws.end_latitude::text, ws.end_longitude::text,
            jsonb_build_object('session_id', ws.id)
        FROM public.workday_sessions ws
        WHERE ws.id = v_session_record.id AND ws.end_time IS NOT NULL
        UNION ALL
        SELECT wb.break_start, 'break_start', 'بداية استراحة',
            COALESCE(wb.break_reason, ''),
            wb.latitude::text, wb.longitude::text,
            jsonb_build_object('break_id', wb.id, 'reason', wb.break_reason)
        FROM public.workday_breaks wb
        WHERE wb.session_id = v_session_record.id
        UNION ALL
        SELECT wb.break_end, 'break_end', 'نهاية استراحة',
            COALESCE(wb.break_reason, ''),
            wb.latitude::text, wb.longitude::text,
            jsonb_build_object('break_id', wb.id, 'duration_seconds', wb.duration_seconds)
        FROM public.workday_breaks wb
        WHERE wb.session_id = v_session_record.id AND wb.break_end IS NOT NULL
        UNION ALL
        SELECT v.check_in_at, 'visit_start', 'بداية زيارة',
            COALESCE(c.company_name, ''),
            v.check_in_latitude::text, v.check_in_longitude::text,
            jsonb_build_object('visit_id', v.id, 'customer_id', v.customer_id, 'customer_name', c.company_name)
        FROM public.visits v
        LEFT JOIN public.customers c ON c.id = v.customer_id
        WHERE v.employee_id = p_employee_id AND v.check_in_at::date = p_date
        UNION ALL
        SELECT v.check_out_at, 'visit_end', 'نهاية زيارة',
            COALESCE(c.company_name, '') || ' — ' || COALESCE(v.visit_result, ''),
            v.check_out_latitude::text, v.check_out_longitude::text,
            jsonb_build_object('visit_id', v.id, 'customer_id', v.customer_id, 'customer_name', c.company_name, 'visit_result', v.visit_result)
        FROM public.visits v
        LEFT JOIN public.customers c ON c.id = v.customer_id
        WHERE v.employee_id = p_employee_id AND v.check_in_at::date = p_date AND v.check_out_at IS NOT NULL
        UNION ALL
        SELECT o.created_at, 'order_created', 'طلب جديد',
            'طلب رقم ' || o.order_number || ' — ' || o.total_amount || ' ج.م',
            o.execution_latitude::text, o.execution_longitude::text,
            jsonb_build_object('order_id', o.id, 'order_number', o.order_number, 'total_amount', o.total_amount, 'status', o.status)
        FROM public.orders o
        WHERE public.resolve_employee_id(o.owner_id) = p_employee_id AND o.created_at::date = p_date
        UNION ALL
        SELECT c.created_at, 'collection_taken', 'تحصيل',
            c.amount || ' ج.م — ' || COALESCE(c.method, ''),
            NULL, NULL,
            jsonb_build_object('collection_id', c.id, 'amount', c.amount, 'method', c.method, 'status', c.status)
        FROM public.collections c
        WHERE public.resolve_employee_id(c.owner_id) = p_employee_id AND c.created_at::date = p_date
        UNION ALL
        SELECT c2.created_at, 'new_customer', 'عميل جديد',
            COALESCE(c2.company_name, ''),
            NULL, NULL,
            jsonb_build_object('customer_id', c2.id, 'customer_name', c2.company_name)
        FROM public.customers c2
        WHERE public.resolve_employee_id(c2.owner_id) = p_employee_id AND c2.created_at::date = p_date
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'time', ae.event_time,
        'type', ae.event_type,
        'title', ae.title,
        'description', ae.description,
        'latitude', ae.lat,
        'longitude', ae.lng,
        'metadata', ae.metadata
    ) ORDER BY ae.event_time), '[]'::jsonb) INTO v_events
    FROM all_events ae;

    RETURN jsonb_build_object(
        'employee', v_employee_info,
        'session', jsonb_build_object(
            'id', COALESCE(v_session_record.id, NULL),
            'status', v_session_record.status,
            'start_time', v_session_record.start_time,
            'end_time', v_session_record.end_time,
            'attendance_status', v_session_record.attendance_status
        ),
        'events', v_events
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_detail(p_token uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_name text;
    v_role_name text;
    v_workday_start timestamptz;
    v_workday_status text;
    v_workday_duration_minutes numeric;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'attendance.view_employee_detail') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT e.full_name INTO v_employee_name FROM public.employees e WHERE e.id = p_employee_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'EMPLOYEE_NOT_FOUND'); END IF;

    SELECT r.name INTO v_role_name FROM public.employee_roles er
    JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = p_employee_id LIMIT 1;
    v_role_name := COALESCE(v_role_name, '');

    SELECT wds.start_time, wds.status INTO v_workday_start, v_workday_status
    FROM public.workday_sessions wds WHERE wds.date = CURRENT_DATE AND wds.employee_id = p_employee_id
    LIMIT 1;

    WITH last_point AS (
        SELECT tp.latitude, tp.longitude, tp.recorded_at, tp.synced_at
        FROM public.tracking_points tp
        WHERE tp.employee_id = p_employee_id
          AND (tp.accuracy_meters IS NULL OR tp.accuracy_meters <= 100)
        ORDER BY tp.synced_at DESC LIMIT 1
    ),
    today_points AS (
        SELECT tp.latitude, tp.longitude, tp.recorded_at, tp.synced_at, tp.accuracy_meters
        FROM public.tracking_points tp
        WHERE tp.employee_id = p_employee_id AND tp.synced_at >= CURRENT_DATE
        ORDER BY tp.synced_at ASC
    ),
    on_break AS (
        SELECT wb.id FROM public.workday_breaks wb
        WHERE wb.employee_id = p_employee_id AND wb.break_end IS NULL LIMIT 1
    ),
    on_visit AS (
        SELECT v.id FROM public.visits v
        WHERE v.employee_id = p_employee_id AND v.check_in_at::date = CURRENT_DATE AND v.check_out_at IS NULL LIMIT 1
    ),
    today_orders AS (
        SELECT COUNT(*)::int AS order_count, COALESCE(SUM(total_amount), 0) AS sales_value
        FROM public.orders WHERE owner_id = p_employee_id AND created_at::date = CURRENT_DATE
    ),
    today_collections AS (
        SELECT COUNT(*)::int AS collection_count, COALESCE(SUM(amount), 0) AS collection_amount
        FROM public.collections WHERE owner_id = p_employee_id AND created_at::date = CURRENT_DATE
    ),
    today_customers AS (
        SELECT COUNT(*)::int AS new_customer_count
        FROM public.customers WHERE owner_id = p_employee_id AND created_at::date = CURRENT_DATE
    ),
    today_visits AS (
        SELECT COUNT(*)::int AS visit_count
        FROM public.visits WHERE employee_id = p_employee_id AND check_in_at::date = CURRENT_DATE
    )
    SELECT jsonb_build_object(
        'employee', jsonb_build_object(
            'employee_id', p_employee_id, 'name', v_employee_name, 'role_name', v_role_name
        ),
        'workday', CASE WHEN v_workday_start IS NULL THEN NULL ELSE jsonb_build_object(
            'start_time', v_workday_start, 'status', v_workday_status,
            'duration_minutes', EXTRACT(EPOCH FROM (now() - v_workday_start)) / 60,
            'on_break', (SELECT COUNT(*) > 0 FROM on_break),
            'on_visit', (SELECT COUNT(*) > 0 FROM on_visit),
            'last_location', CASE WHEN (SELECT COUNT(*) FROM last_point) = 0 THEN NULL ELSE
                (SELECT jsonb_build_object('latitude', latitude, 'longitude', longitude, 'recorded_at', synced_at)
                 FROM last_point) END
        ) END,
        'point_count', (SELECT COUNT(*) FROM today_points),
        'route', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'latitude', tp.latitude, 'longitude', tp.longitude,
            'recorded_at', tp.synced_at, 'accuracy_meters', tp.accuracy_meters
        )) FROM today_points tp), '[]'::jsonb),
        'orders', COALESCE((SELECT jsonb_agg(jsonb_build_object('order_id', o.id, 'amount', o.total_amount, 'created_at', o.created_at))
            FROM public.orders o WHERE o.owner_id = p_employee_id AND o.created_at::date = CURRENT_DATE ORDER BY o.created_at DESC), '[]'::jsonb),
        'collections', COALESCE((SELECT jsonb_agg(jsonb_build_object('collection_id', c.id, 'amount', c.amount, 'created_at', c.created_at))
            FROM public.collections c WHERE c.owner_id = p_employee_id AND c.created_at::date = CURRENT_DATE ORDER BY c.created_at DESC), '[]'::jsonb),
        'performance', jsonb_build_object(
            'order_count', COALESCE((SELECT order_count FROM today_orders), 0),
            'sales_value', COALESCE((SELECT sales_value FROM today_orders), 0),
            'collection_count', COALESCE((SELECT collection_count FROM today_collections), 0),
            'collection_amount', COALESCE((SELECT collection_amount FROM today_collections), 0),
            'new_customer_count', COALESCE((SELECT new_customer_count FROM today_customers), 0),
            'visit_count', COALESCE((SELECT visit_count FROM today_visits), 0),
            'planned_visit_count', 0
        )
    ) INTO v_result;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_detail(p_token uuid, p_employee_id uuid, p_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'attendance.view_timeline') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;
    IF v_subtree_ids IS NOT NULL AND NOT (p_employee_id = ANY(v_subtree_ids)) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    WITH emp_info AS (
        SELECT e.id, e.full_name, e.code,
            COALESCE(r.name, '') AS role_name,
            COALESCE(m.full_name, '') AS manager_name,
            e.region, e.avatar_url
        FROM public.employees e
        LEFT JOIN public.employee_roles er ON er.employee_id = e.id
        LEFT JOIN public.roles r ON r.id = er.role_id
        LEFT JOIN public.employees m ON m.id = e.manager_id
        WHERE e.id = p_employee_id
    ),
    session_info AS (
        SELECT wds.*
        FROM public.workday_sessions wds
        WHERE wds.employee_id = p_employee_id AND wds.date = p_date
        ORDER BY wds.start_time DESC LIMIT 1
    ),
    last_point AS (
        SELECT tp.latitude, tp.longitude, tp.recorded_at, tp.synced_at
        FROM public.tracking_points tp
        WHERE tp.employee_id = p_employee_id
          AND (tp.accuracy_meters IS NULL OR tp.accuracy_meters <= 100)
        ORDER BY tp.synced_at DESC LIMIT 1
    ),
    today_orders AS (
        SELECT COUNT(*)::int AS total_orders,
            COALESCE(SUM(o.total_amount), 0) AS total_sales
        FROM public.orders o
        WHERE o.owner_id = p_employee_id AND o.created_at::date = p_date
    ),
    today_collections AS (
        SELECT COUNT(*)::int AS total_collections,
            COALESCE(SUM(c.amount), 0) AS total_collections_amount
        FROM public.collections c
        WHERE c.owner_id = p_employee_id AND c.created_at::date = p_date
    ),
    today_customers AS (
        SELECT COUNT(*)::int AS new_customers
        FROM public.customers c
        WHERE c.owner_id = p_employee_id AND c.created_at::date = p_date
    ),
    today_visits AS (
        SELECT COUNT(*)::int AS total_visits,
            COUNT(*) FILTER (WHERE v.check_out_at IS NOT NULL) AS completed_visits
        FROM public.visits v
        WHERE v.employee_id = p_employee_id AND v.check_in_at::date = p_date
    ),
    today_break_minutes AS (
        SELECT COALESCE(SUM(COALESCE(wb.duration_seconds, 0)), 0) / 60 AS break_minutes
        FROM public.workday_breaks wb
        WHERE wb.employee_id = p_employee_id AND wb.break_start::date = p_date
    )
    SELECT jsonb_build_object(
        'employee', jsonb_build_object(
            'id', ei.id, 'full_name', ei.full_name, 'code', ei.code,
            'role_name', ei.role_name, 'region', ei.region, 'avatar_url', ei.avatar_url,
            'manager_name', ei.manager_name
        ),
        'session', CASE WHEN si.id IS NOT NULL THEN jsonb_build_object(
            'id', si.id, 'status', si.status, 'start_time', si.start_time, 'end_time', si.end_time,
            'attendance_status', si.attendance_status, 'late_minutes', si.late_minutes,
            'early_departure_minutes', si.early_departure_minutes,
            'duration_minutes', EXTRACT(EPOCH FROM (COALESCE(si.end_time, now()) - si.start_time)) / 60,
            'net_minutes', GREATEST(EXTRACT(EPOCH FROM (COALESCE(si.end_time, now()) - si.start_time)) / 60 - COALESCE(tbm.break_minutes, 0), 0),
            'break_minutes', COALESCE(tbm.break_minutes, 0)
        ) ELSE NULL END,
        'last_location', CASE WHEN lp.recorded_at IS NOT NULL THEN jsonb_build_object(
            'latitude', lp.latitude, 'longitude', lp.longitude, 'recorded_at', lp.synced_at
        ) ELSE NULL END,
        'summary', jsonb_build_object(
            'total_orders', COALESCE(to2.total_orders, 0),
            'total_sales', COALESCE(to2.total_sales, 0),
            'total_collections', COALESCE(tc2.total_collections, 0),
            'total_collections_amount', COALESCE(tc2.total_collections_amount, 0),
            'new_customers', COALESCE(tc3.new_customers, 0),
            'total_visits', COALESCE(tv.total_visits, 0),
            'completed_visits', COALESCE(tv.completed_visits, 0)
        )
    ) INTO v_result
    FROM emp_info ei
    LEFT JOIN session_info si ON true
    LEFT JOIN last_point lp ON true
    LEFT JOIN today_orders to2 ON true
    LEFT JOIN today_collections tc2 ON true
    LEFT JOIN today_customers tc3 ON true
    LEFT JOIN today_visits tv ON true
    LEFT JOIN today_break_minutes tbm ON true;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_total_sales_company(p_token uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_session app.sessions;
    v_is_super boolean;
    v_visible uuid[];
    v_sales numeric;
    v_count int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF v_session.identity_type != 'employee' THEN
        RETURN jsonb_build_object('error', 'NOT_EMPLOYEE');
    END IF;

    v_is_super := public.is_upper_management(v_session.employee_id);
    v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);

    SELECT COALESCE(SUM(o.total_amount), 0), COUNT(*)::int
    INTO v_sales, v_count
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    WHERE o.created_at::date >= p_from
      AND o.created_at::date <= p_to
      AND public.is_order_in_statistics(o.status)
      AND (v_is_super OR c.owner_id = ANY(v_visible));

    RETURN jsonb_build_object('sales', v_sales, 'count', v_count);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_employee_detail_data(p_token uuid, p_employee_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.is_upper_management(v_session.employee_id) THEN
        IF NOT (p_employee_id = ANY(public.get_visible_employee_ids(p_token))) THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN');
        END IF;
    END IF;

    WITH
    order_detail AS (
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id,
            'order_number', o.order_number,
            'total_amount', o.total_amount,
            'status', o.status,
            'submitted_at', o.submitted_at,
            'customer_name', COALESCE(o.snapshot_customer_name, ''),
            'customer_phone', COALESCE(o.snapshot_customer_phone, '')
        ) ORDER BY o.created_at DESC)
        FROM public.orders o
        WHERE public.resolve_employee_id(o.owner_id) = p_employee_id
          AND o.created_at::date >= p_from AND o.created_at::date <= p_to
          AND public.is_order_in_statistics(o.status)
    ),
    customer_detail AS (
        SELECT jsonb_agg(jsonb_build_object(
            'id', c.id,
            'code', c.code,
            'company_name', c.company_name,
            'created_at', c.created_at,
            'responsible_name', COALESCE(c.responsible_name, '')
        ) ORDER BY c.created_at DESC)
        FROM public.customers c
        WHERE public.resolve_employee_id(c.owner_id) = p_employee_id
          AND c.created_at::date >= p_from AND c.created_at::date <= p_to
    ),
    visit_detail AS (
        SELECT jsonb_agg(jsonb_build_object(
            'id', v.id,
            'code', v.code,
            'customer_name', COALESCE(c.company_name, ''),
            'check_in_at', v.check_in_at,
            'check_out_at', v.check_out_at,
            'status', v.status,
            'visit_result', COALESCE(v.visit_result, ''),
            'latitude', v.check_in_latitude,
            'longitude', v.check_in_longitude
        ) ORDER BY v.check_in_at DESC)
        FROM public.visits v
        LEFT JOIN public.customers c ON c.id = v.customer_id
        WHERE v.employee_id = p_employee_id
          AND v.check_in_at::date >= p_from AND v.check_in_at::date <= p_to
    ),
    collection_detail AS (
        SELECT jsonb_agg(jsonb_build_object(
            'id', col.id,
            'code', col.code,
            'amount', col.amount,
            'status', col.status,
            'created_at', col.created_at,
            'collected_at', col.collected_at,
            'customer_name', COALESCE(c.company_name, ''),
            'reference_number', COALESCE(col.reference_number, '')
        ) ORDER BY col.created_at DESC)
        FROM public.collections col
        LEFT JOIN public.customers c ON c.id = col.customer_id
        WHERE public.resolve_employee_id(col.owner_id) = p_employee_id
          AND col.created_at::date >= p_from AND col.created_at::date <= p_to
    )
    SELECT jsonb_build_object(
        'orders', COALESCE((SELECT * FROM order_detail), '[]'::jsonb),
        'customers', COALESCE((SELECT * FROM customer_detail), '[]'::jsonb),
        'visits', COALESCE((SELECT * FROM visit_detail), '[]'::jsonb),
        'collections', COALESCE((SELECT * FROM collection_detail), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_weight_overrides(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_has_view_all boolean;
    v_target_month int;
    v_target_year int;
    v_subtree_ids uuid[];
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.check_capability(p_token, 'targets.access') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    v_has_view_all := public.check_capability(p_token, 'targets.view_all');
    v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
    v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);

    IF NOT v_has_view_all THEN
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', wo.id,
            'employee_id', wo.employee_id,
            'employee_code', e.code,
            'employee_name', e.full_name,
            'target_month', wo.target_month,
            'target_year', wo.target_year,
            'sales_weight_percent', wo.sales_weight_percent,
            'collections_weight_percent', wo.collections_weight_percent,
            'visits_weight_percent', wo.visits_weight_percent,
            'new_customers_weight_percent', wo.new_customers_weight_percent,
            'attendance_weight_percent', wo.attendance_weight_percent,
            'override_reason', wo.override_reason,
            'is_active', wo.is_active
        )
        ORDER BY e.full_name
    ) INTO v_result
    FROM public.employee_weight_overrides wo
    JOIN public.employees e ON e.id = wo.employee_id
    WHERE wo.target_month = v_target_month
        AND wo.target_year = v_target_year
        AND (v_has_view_all OR wo.employee_id = ANY(v_subtree_ids) OR wo.employee_id = v_session.employee_id);

    RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employee_work_policy(p_token uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_session app.sessions;
    v_policy record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    SELECT * INTO v_policy FROM public.employee_work_policies
    WHERE employee_id = p_employee_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('employee_id', p_employee_id, 'has_policy', false);
    END IF;

    RETURN jsonb_build_object(
        'id', v_policy.id,
        'employee_id', v_policy.employee_id,
        'work_location', v_policy.work_location,
        'schedule_type', v_policy.schedule_type,
        'tracking_required', v_policy.tracking_required,
        'required_daily_hours', v_policy.required_daily_hours,
        'shift_start_time', v_policy.shift_start_time,
        'shift_end_time', v_policy.shift_end_time,
        'late_threshold_minutes', v_policy.late_threshold_minutes,
        'early_departure_threshold_minutes', v_policy.early_departure_threshold_minutes,
        'updated_at', v_policy.updated_at,
        'has_policy', true
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_employee_workday_history(p_token uuid, p_employee_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_sessions_json jsonb;
    v_summary_json jsonb;
    v_policy record;
    v_use_net_calc boolean := true;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN
      IF NOT (p_employee_id = ANY(public.get_visible_employee_ids(p_token))) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
      END IF;
    END IF;

    SELECT * INTO v_policy FROM public.employee_work_policies WHERE employee_id = p_employee_id;
    v_use_net_calc := (v_policy.schedule_type = 'fixed_shift');

    WITH session_data AS (
        SELECT
            wds.id, wds.employee_id, wds.date, wds.start_time, wds.end_time, wds.status,
            EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60 AS duration_minutes,
            COALESCE(wb.break_seconds, 0) / 60 AS break_minutes,
            COALESCE(wb.break_count, 0) AS break_count,
            COALESCE(wds.total_distance_meters, 0) AS distance_meters,
            COALESCE(vd.completed_visit_count, 0) AS visit_count,
            wds.attendance_status, wds.late_minutes, wds.early_departure_minutes,
            COALESCE(od.order_count, 0) AS order_count,
            COALESCE(od.sales_value, 0) AS sales_value,
            COALESCE(cd.collection_count, 0) AS collection_count,
            COALESCE(cd.collection_amount, 0) AS collection_amount,
            COALESCE(nd.new_customer_count, 0) AS new_customer_count,
            COALESCE(tp.tracking_points_count, 0) AS tracking_points_count
        FROM public.workday_sessions wds
        LEFT JOIN (
            SELECT session_id,
                COUNT(*) AS break_count,
                COALESCE(SUM(duration_seconds), 0) AS break_seconds
            FROM public.workday_breaks
            GROUP BY session_id
        ) wb ON wb.session_id = wds.id
        -- CANONICAL: Visits = public.visits WHERE status='completed'
        LEFT JOIN (
            SELECT v.employee_id,
                v.check_out_at::date AS d,
                COUNT(*)::int AS completed_visit_count
            FROM public.visits v
            WHERE v.status = 'completed'
            GROUP BY v.employee_id, v.check_out_at::date
        ) vd ON vd.employee_id = wds.employee_id AND vd.d = wds.date
        -- CANONICAL: Orders = submitted orders, exclude draft/cancelled
        LEFT JOIN (
            SELECT public.resolve_employee_id(o.owner_id) AS resolved_employee_id,
                o.submitted_at::date AS d,
                COUNT(*)::int AS order_count,
                COALESCE(SUM(o.total_amount), 0) AS sales_value
            FROM public.orders o
            WHERE public.is_order_in_statistics(o.status)
            GROUP BY public.resolve_employee_id(o.owner_id), o.submitted_at::date
        ) od ON od.resolved_employee_id = wds.employee_id AND od.d = wds.date
        -- CANONICAL: Collections = public.collections WHERE status='collected', use collected_at
        LEFT JOIN (
            SELECT public.resolve_employee_id(c.owner_id) AS resolved_employee_id,
                c.collected_at::date AS d,
                COUNT(*)::int AS collection_count,
                COALESCE(SUM(c.amount), 0) AS collection_amount
            FROM public.collections c
            WHERE c.status = 'collected'
            GROUP BY public.resolve_employee_id(c.owner_id), c.collected_at::date
        ) cd ON cd.resolved_employee_id = wds.employee_id AND cd.d = wds.date
        LEFT JOIN (
            SELECT public.resolve_employee_id(c2.owner_id) AS resolved_employee_id,
                c2.created_at::date AS d,
                COUNT(*)::int AS new_customer_count
            FROM public.customers c2
            GROUP BY public.resolve_employee_id(c2.owner_id), c2.created_at::date
        ) nd ON nd.resolved_employee_id = wds.employee_id AND nd.d = wds.date
        LEFT JOIN (
            SELECT tp.session_id,
                COUNT(*)::int AS tracking_points_count
            FROM public.tracking_points tp
            GROUP BY tp.session_id
        ) tp ON tp.session_id = wds.id
        WHERE wds.employee_id = p_employee_id AND wds.date >= p_from AND wds.date <= p_to
    ),
    ranked AS (
        SELECT *,
            ROW_NUMBER() OVER (
                PARTITION BY employee_id, date
                ORDER BY
                    CASE WHEN date < CURRENT_DATE AND status = 'completed' THEN 0
                         WHEN date >= CURRENT_DATE AND status = 'active' THEN 0
                         ELSE 1 END,
                    start_time DESC
            ) AS rn
        FROM session_data
    )
    SELECT
        (SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', r.id, 'date', r.date, 'start_time', r.start_time, 'end_time', r.end_time,
            'status', r.status,
            'duration_minutes', r.duration_minutes::int,
            'break_minutes', r.break_minutes::int,
            'net_minutes', CASE WHEN v_use_net_calc
                THEN GREATEST(r.duration_minutes - r.break_minutes, 0)::int
                ELSE r.duration_minutes::int
            END,
            'break_count', r.break_count,
            'visit_count', r.visit_count,
            'order_count', r.order_count,
            'sales_value', r.sales_value,
            'collection_count', r.collection_count,
            'collection_amount', r.collection_amount,
            'new_customer_count', r.new_customer_count,
            'distance_meters', r.distance_meters::int,
            'tracking_points_count', r.tracking_points_count::int,
            'attendance_status', r.attendance_status,
            'late_minutes', r.late_minutes,
            'early_departure_minutes', r.early_departure_minutes
        ) ORDER BY r.date DESC), '[]'::jsonb) FROM ranked r WHERE r.rn = 1),
        jsonb_build_object(
            'total_days', (SELECT COUNT(*) FROM ranked WHERE rn = 1),
            'total_duration_minutes', COALESCE((SELECT SUM(duration_minutes)::int FROM ranked WHERE rn = 1), 0),
            'total_break_minutes', COALESCE((SELECT SUM(break_minutes)::int FROM ranked WHERE rn = 1), 0),
            'total_net_minutes', COALESCE((SELECT SUM(CASE WHEN v_use_net_calc
                THEN GREATEST(duration_minutes - break_minutes, 0)
                ELSE duration_minutes END)::int FROM ranked WHERE rn = 1), 0),
            'avg_net_minutes', COALESCE((SELECT AVG(CASE WHEN v_use_net_calc
                THEN GREATEST(duration_minutes - break_minutes, 0)
                ELSE duration_minutes END)::int FROM ranked WHERE rn = 1), 0),
            'max_net_day', COALESCE((SELECT MAX(CASE WHEN v_use_net_calc
                THEN GREATEST(duration_minutes - break_minutes, 0)
                ELSE duration_minutes END)::int FROM ranked WHERE rn = 1), 0),
            'min_net_day', COALESCE((SELECT MIN(CASE WHEN v_use_net_calc
                THEN GREATEST(duration_minutes - break_minutes, 0)
                ELSE duration_minutes END)::int FROM ranked WHERE rn = 1), 0),
            'total_sales_value', COALESCE((SELECT SUM(sales_value)::int FROM ranked WHERE rn = 1), 0),
            'total_orders', COALESCE((SELECT SUM(order_count)::int FROM ranked WHERE rn = 1), 0),
            'total_visits', COALESCE((SELECT SUM(visit_count)::int FROM ranked WHERE rn = 1), 0),
            'total_collections', COALESCE((SELECT SUM(collection_count)::int FROM ranked WHERE rn = 1), 0),
            'total_collections_amount', COALESCE((SELECT SUM(collection_amount)::int FROM ranked WHERE rn = 1), 0),
            'total_new_customers', COALESCE((SELECT SUM(new_customer_count)::int FROM ranked WHERE rn = 1), 0),
            'total_tracking_points', COALESCE((SELECT SUM(tracking_points_count)::int FROM ranked WHERE rn = 1), 0),
            'late_days', (SELECT COUNT(*) FROM ranked WHERE rn = 1 AND attendance_status = 'late'),
            'early_departure_days', (SELECT COUNT(*) FROM ranked WHERE rn = 1 AND attendance_status = 'early_departure'),
            'ontime_days', (SELECT COUNT(*) FROM ranked WHERE rn = 1 AND attendance_status = 'ontime')
        )
    INTO v_sessions_json, v_summary_json;

    RETURN jsonb_build_object('sessions', v_sessions_json, 'summary', v_summary_json);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employees_attendance_summary(p_token uuid, p_from date, p_to date, p_search text DEFAULT NULL::text, p_sort_by text DEFAULT 'total_net_minutes'::text, p_sort_order text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_per_page integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_offset int;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF public.is_upper_management(v_session.employee_id) THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    v_offset := (p_page - 1) * p_per_page;

    WITH
    visible_employees AS (
        SELECT e.id, e.full_name, e.code, rpl.name AS role_name
        FROM public.employees e
        LEFT JOIN LATERAL (
            SELECT r.name FROM public.employee_roles er
            JOIN public.roles r ON r.id = er.role_id
            WHERE er.employee_id = e.id
            LIMIT 1
        ) rpl ON true
        WHERE e.is_active = true
        AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        AND (
            p_search IS NULL
            OR e.full_name ILIKE '%' || p_search || '%'
            OR e.code ILIKE '%' || p_search || '%'
        )
    ),
    total_count AS (
        SELECT COUNT(*)::int AS cnt FROM visible_employees
    ),
    -- Per-session attendance (deduplicated by employee_id, date)
    session_attendance AS (
        SELECT DISTINCT ON (wds.employee_id, wds.date)
            wds.employee_id,
            wds.date,
            wds.start_time,
            wds.end_time,
            wds.status,
            wds.attendance_status,
            wds.late_minutes,
            wds.early_departure_minutes,
            wds.total_distance_meters,
            GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60) AS duration_minutes,
            COALESCE(wb.break_minutes, 0) AS break_minutes,
            COALESCE(wb.break_count, 0) AS break_count,
            COALESCE(tp.tracking_points_count, 0) AS tracking_points_count
        FROM public.workday_sessions wds
        JOIN visible_employees ve ON ve.id = wds.employee_id
        LEFT JOIN (
            SELECT wb2.session_id,
                COUNT(*)::int AS break_count,
                COALESCE(SUM(COALESCE(wb2.duration_seconds, 0)), 0) / 60.0 AS break_minutes
            FROM public.workday_breaks wb2
            GROUP BY wb2.session_id
        ) wb ON wb.session_id = wds.id
        LEFT JOIN (
            SELECT tp.session_id,
                COUNT(*)::int AS tracking_points_count
            FROM public.tracking_points tp
            GROUP BY tp.session_id
        ) tp ON tp.session_id = wds.id
        WHERE wds.date >= p_from AND wds.date <= p_to
        ORDER BY wds.employee_id, wds.date, wds.start_time DESC
    ),
    -- Aggregated attendance per employee (LEFT JOIN from ALL visible employees)
    emp_aggregated AS (
        SELECT
            sa2.employee_id,
            COUNT(*)::int AS total_days,
            COUNT(*) FILTER (WHERE sa2.attendance_status = 'late')::int AS late_count,
            COUNT(*) FILTER (WHERE sa2.attendance_status = 'ontime')::int AS ontime_count,
            COUNT(*) FILTER (WHERE sa2.attendance_status = 'early_departure')::int AS early_departure_count,
            COALESCE(SUM(GREATEST(COALESCE(sa2.duration_minutes, 0) - COALESCE(sa2.break_minutes, 0), 0))::int, 0) AS total_net_minutes,
            COALESCE(AVG(GREATEST(COALESCE(sa2.duration_minutes, 0) - COALESCE(sa2.break_minutes, 0), 0))::int, 0) AS avg_net_minutes,
            COALESCE(SUM(sa2.total_distance_meters)::int, 0) AS total_distance_meters,
            COALESCE(SUM(sa2.tracking_points_count)::int, 0) AS total_tracking_points
        FROM session_attendance sa2
        GROUP BY sa2.employee_id
    ),
    emp_attendance AS (
        SELECT
            ve.id AS employee_id,
            COALESCE(ea.total_days, 0)::int AS total_days,
            COALESCE(ea.late_count, 0)::int AS late_count,
            COALESCE(ea.ontime_count, 0)::int AS ontime_count,
            COALESCE(ea.early_departure_count, 0)::int AS early_departure_count,
            COALESCE(ea.total_net_minutes, 0)::int AS total_net_minutes,
            COALESCE(ea.avg_net_minutes, 0)::int AS avg_net_minutes,
            COALESCE(ea.total_distance_meters, 0)::int AS total_distance_meters,
            COALESCE(ea.total_tracking_points, 0)::int AS total_tracking_points
        FROM visible_employees ve
        LEFT JOIN emp_aggregated ea ON ea.employee_id = ve.id
    ),
    grand_totals AS (
        SELECT
            COUNT(*)::int AS total_employees,
            COALESCE(SUM(ea.total_days)::int, 0) AS total_days,
            COALESCE(SUM(ea.total_net_minutes)::int, 0) AS total_net_minutes,
            COALESCE(SUM(ea.total_distance_meters)::int, 0) AS total_distance_meters,
            COALESCE(SUM(ea.late_count)::int, 0) AS total_late_days,
            COALESCE(SUM(ea.ontime_count)::int, 0) AS total_ontime_days,
            COALESCE(SUM(ea.early_departure_count)::int, 0) AS total_early_departure_days
        FROM emp_attendance ea
    ),
    paginated AS (
        SELECT *
        FROM emp_attendance
        ORDER BY
            CASE WHEN p_sort_by = 'total_net_minutes' AND p_sort_order = 'desc' THEN total_net_minutes END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'total_net_minutes' AND p_sort_order = 'asc' THEN total_net_minutes END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'total_days' AND p_sort_order = 'desc' THEN total_days END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'total_days' AND p_sort_order = 'asc' THEN total_days END ASC NULLS LAST,
            total_net_minutes DESC NULLS LAST
        LIMIT p_per_page OFFSET v_offset
    )
    SELECT jsonb_build_object(
        'employees', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object(
                'employee_id', p.employee_id,
                'employee_name', ve.full_name,
                'employee_code', ve.code,
                'total_days', p.total_days,
                'total_net_minutes', p.total_net_minutes,
                'avg_net_minutes', p.avg_net_minutes,
                'total_distance_meters', p.total_distance_meters,
                'total_tracking_points', p.total_tracking_points,
                'late_count', p.late_count,
                'ontime_count', p.ontime_count,
                'early_departure_count', p.early_departure_count
            ) ORDER BY p.total_net_minutes DESC)
            FROM paginated p
            JOIN visible_employees ve ON ve.id = p.employee_id),
            '[]'::jsonb
        ),
        'totals', (SELECT jsonb_build_object(
            'total_employees', gt.total_employees,
            'total_days', gt.total_days,
            'total_net_minutes', gt.total_net_minutes,
            'total_distance_meters', gt.total_distance_meters,
            'late_days', gt.total_late_days,
            'ontime_days', gt.total_ontime_days,
            'early_departure_days', gt.total_early_departure_days
        ) FROM grand_totals gt),
        'pagination', jsonb_build_object(
            'page', p_page,
            'per_page', p_per_page,
            'total', (SELECT cnt FROM total_count),
            'total_pages', GREATEST(1, CEIL((SELECT cnt::numeric FROM total_count) / p_per_page)::int)
        )
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_employees_business_activity(p_token uuid, p_from date, p_to date, p_search text DEFAULT NULL::text, p_sort_by text DEFAULT 'sales_value'::text, p_sort_order text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_per_page integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_subtree_ids uuid[];
    v_offset int;
    v_result jsonb;
    v_total_employees int := 0;
BEGIN
    -- Auth
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    -- Scope: visible employees under this manager
    IF public.is_upper_management(v_session.employee_id) THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    v_offset := (p_page - 1) * p_per_page;

    WITH
    -- Step 1: All visible employees (regardless of attendance)
    visible_employees AS (
        SELECT e.id, e.full_name, e.code, rpl.name AS role_name
        FROM public.employees e
        LEFT JOIN LATERAL (
            SELECT r.name FROM public.employee_roles er
            JOIN public.roles r ON r.id = er.role_id
            WHERE er.employee_id = e.id
            LIMIT 1
        ) rpl ON true
        WHERE e.is_active = true
        AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        AND (
            p_search IS NULL
            OR e.full_name ILIKE '%' || p_search || '%'
            OR e.code ILIKE '%' || p_search || '%'
        )
    ),
    total_count AS (
        SELECT COUNT(*)::int AS cnt FROM visible_employees
    ),
    -- Step 2: Business activity — pure, NO session dependency
    biz_orders AS (
        SELECT
            public.resolve_employee_id(o.owner_id) AS employee_id,
            COUNT(*)::int AS order_count,
            COALESCE(SUM(o.total_amount), 0) AS sales_value
        FROM public.orders o
        WHERE o.created_at::date >= p_from AND o.created_at::date <= p_to
        AND public.resolve_employee_id(o.owner_id) = ANY(SELECT id FROM visible_employees)
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    biz_visits AS (
        SELECT
            v.employee_id,
            COUNT(*)::int AS visit_count
        FROM public.visits v
        WHERE v.check_in_at::date >= p_from AND v.check_in_at::date <= p_to
        AND v.employee_id = ANY(SELECT id FROM visible_employees)
        GROUP BY v.employee_id
    ),
    biz_customers AS (
        SELECT
            public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS customer_count
        FROM public.customers c
        WHERE c.created_at::date >= p_from AND c.created_at::date <= p_to
        AND public.resolve_employee_id(c.owner_id) = ANY(SELECT id FROM visible_employees)
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    biz_collections AS (
        SELECT
            public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS collection_count,
            COALESCE(SUM(c.amount), 0) AS collection_amount
        FROM public.collections c
        WHERE c.created_at::date >= p_from AND c.created_at::date <= p_to
        AND public.resolve_employee_id(c.owner_id) = ANY(SELECT id FROM visible_employees)
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    -- Step 3: Merge business activity per employee
    employee_biz AS (
        SELECT
            ve.id AS employee_id,
            COALESCE(bo.order_count, 0) AS order_count,
            COALESCE(bo.sales_value, 0) AS sales_value,
            COALESCE(bv.visit_count, 0) AS visit_count,
            COALESCE(bc.customer_count, 0) AS customer_count,
            COALESCE(bco.collection_count, 0) AS collection_count,
            COALESCE(bco.collection_amount, 0) AS collection_amount
        FROM visible_employees ve
        LEFT JOIN biz_orders bo ON bo.employee_id = ve.id
        LEFT JOIN biz_visits bv ON bv.employee_id = ve.id
        LEFT JOIN biz_customers bc ON bc.employee_id = ve.id
        LEFT JOIN biz_collections bco ON bco.employee_id = ve.id
    ),
    -- Step 4: Grand totals
    grand_totals AS (
        SELECT
            COUNT(*)::int AS total_employees,
            COALESCE(SUM(order_count)::int, 0) AS total_orders,
            COALESCE(SUM(sales_value)::numeric, 0) AS total_sales,
            COALESCE(SUM(visit_count)::int, 0) AS total_visits,
            COALESCE(SUM(customer_count)::int, 0) AS total_customers,
            COALESCE(SUM(collection_count)::int, 0) AS total_collections,
            COALESCE(SUM(collection_amount)::numeric, 0) AS total_collection_amount
        FROM employee_biz
    ),
    -- Step 5: Paginated employees
    paginated AS (
        SELECT *
        FROM employee_biz
        ORDER BY
            CASE WHEN p_sort_by = 'sales_value' AND p_sort_order = 'desc' THEN sales_value END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'sales_value' AND p_sort_order = 'asc' THEN sales_value END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'order_count' AND p_sort_order = 'desc' THEN order_count END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'order_count' AND p_sort_order = 'asc' THEN order_count END ASC NULLS LAST,
            CASE WHEN p_sort_by = 'visit_count' AND p_sort_order = 'desc' THEN visit_count END DESC NULLS LAST,
            CASE WHEN p_sort_by = 'visit_count' AND p_sort_order = 'asc' THEN visit_count END ASC NULLS LAST,
            sales_value DESC NULLS LAST
        LIMIT p_per_page OFFSET v_offset
    )
    SELECT jsonb_build_object(
        'employees', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object(
                'employee_id', p.employee_id,
                'employee_name', ve.full_name,
                'employee_code', ve.code,
                'role_name', ve.role_name,
                'order_count', p.order_count,
                'sales_value', p.sales_value,
                'visit_count', p.visit_count,
                'customer_count', p.customer_count,
                'collection_count', p.collection_count,
                'collection_amount', p.collection_amount
            ) ORDER BY
                CASE WHEN p_sort_by = 'sales_value' AND p_sort_order = 'desc' THEN p.sales_value END DESC NULLS LAST,
                CASE WHEN p_sort_by = 'sales_value' AND p_sort_order = 'asc' THEN p.sales_value END ASC NULLS LAST,
                p.sales_value DESC)
            FROM paginated p
            JOIN visible_employees ve ON ve.id = p.employee_id),
            '[]'::jsonb
        ),
        'totals', (SELECT jsonb_build_object(
            'total_employees', gt.total_employees,
            'total_orders', gt.total_orders,
            'total_sales', gt.total_sales,
            'total_visits', gt.total_visits,
            'total_customers', gt.total_customers,
            'total_collections', gt.total_collections,
            'total_collection_amount', gt.total_collection_amount
        ) FROM grand_totals gt),
        'pagination', jsonb_build_object(
            'page', p_page,
            'per_page', p_per_page,
            'total', (SELECT cnt FROM total_count),
            'total_pages', GREATEST(1, CEIL((SELECT cnt::numeric FROM total_count) / p_per_page)::int)
        )
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_active_daily_deals(p_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_result jsonb;
BEGIN
  -- Public function: accepts optional token for session validation
  -- Returns active (or recently expired/sold_out for visibility) deals

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', d.id,
      'title', d.title,
      'image_url', d.image_url,
      'description', d.description,
      'fixed_price', d.fixed_price,
      'available_quantity', d.available_quantity,
      'original_quantity', d.original_quantity,
      'starts_at', d.starts_at,
      'ends_at', d.ends_at,
      'status', d.status,
      'is_purchasable',
        CASE
          WHEN d.status = 'active' AND d.available_quantity > 0
            AND (d.starts_at IS NULL OR d.starts_at <= now())
            AND (d.ends_at IS NULL OR d.ends_at > now())
          THEN true
          ELSE false
        END,
      'items', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', di.id,
            'product_id', di.product_id,
            'product_name', p.product_name,
            'quantity', di.quantity
          )
        ) FROM daily_deal_items di
        JOIN products p ON p.id = di.product_id
        WHERE di.deal_id = d.id), '[]'::jsonb
      )
    ) ORDER BY d.created_at DESC
  ) INTO v_result FROM daily_deals d
  WHERE d.status IN ('active', 'sold_out', 'expired')
    AND (d.ends_at IS NULL OR d.ends_at > now() - interval '30 days');

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_active_employees(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  SELECT jsonb_agg(
    jsonb_build_object(
      'employee_id', e.id, 'employee_code', e.code, 'employee_name', e.full_name,
      'employee_manager_id', e.manager_id,
      'role_type', CASE
        WHEN EXISTS (SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = e.id AND r.name = 'الإدارة العليا') THEN 'مدير'
        WHEN EXISTS (SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = e.id AND r.name = 'مدير البيع') THEN 'مدير البيع'
        WHEN EXISTS (SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = e.id AND r.name = 'مشرف تنفيذي') THEN 'سوبر فايزر'
        ELSE 'مندوب'
      END,
      'has_team', EXISTS (SELECT 1 FROM public.employees sub WHERE sub.manager_id = e.id)
    ) ORDER BY e.full_name
  ) INTO v_result
  FROM public.employees e
  WHERE e.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id
      WHERE er.employee_id = e.id AND r.name = 'الإدارة العليا'
    );
  RETURN COALESCE(v_result, jsonb_build_array());
END;

$function$;

