CREATE OR REPLACE FUNCTION public.get_governed_auction_detail(p_auction_id uuid, p_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auction public.auctions;
  v_result jsonb;
  v_top_bid public.auction_bids;
  v_leader_name varchar(255);
BEGIN
  IF p_token IS NOT NULL THEN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  END IF;

  SELECT * INTO v_auction FROM public.auctions WHERE id = p_auction_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  SELECT * INTO v_top_bid FROM public.auction_bids
  WHERE auction_id = p_auction_id AND is_winning = true LIMIT 1;

  IF v_top_bid.id IS NOT NULL THEN
    SELECT COALESCE(c.company_name, e.full_name) INTO v_leader_name
    FROM public.auction_participants ap
    LEFT JOIN customers c ON c.id = ap.participant_id AND ap.participant_type = 'customer'
    LEFT JOIN employees e ON e.id = ap.participant_id AND ap.participant_type = 'employee'
    WHERE ap.id = v_top_bid.participant_id;
  END IF;

  SELECT jsonb_build_object(
    'id', a.id,
    'code', a.code,
    'title', a.title,
    'description', a.description,
    'image_url', a.image_url,
    'starting_price', a.starting_price,
    'current_price', a.current_price,
    'bid_increment', a.bid_increment,
    'deposit_amount', a.deposit_amount,
    'start_time', a.start_time,
    'end_time', a.end_time,
    'status', a.status,
    'winner_id', a.winner_id,
    'winner_amount', a.winner_amount,
    'created_at', a.created_at,
    'updated_at', a.updated_at,
    'participant_count', (SELECT COUNT(*) FROM public.auction_participants ap WHERE ap.auction_id = a.id AND ap.status = 'approved'),
    'bid_count', (SELECT COUNT(*) FROM public.auction_bids ab WHERE ab.auction_id = a.id),
    'current_leader_name', v_leader_name,
    'current_leader_bid', v_top_bid.amount,
    'items', COALESCE(
      (SELECT jsonb_agg(
        jsonb_build_object(
          'id', ai.id,
          'product_id', ai.product_id,
          'product_name', p.product_name,
          'quantity', ai.quantity
        )
      ) FROM public.auction_items ai
      JOIN products p ON p.id = ai.product_id
      WHERE ai.auction_id = a.id), '[]'::jsonb
    ),
    'participant_status',
    CASE WHEN v_session.token IS NOT NULL THEN
      public._get_auction_participant_status(a.id, v_session)
    ELSE
      jsonb_build_object('status', 'visitor')
    END,
    'bids', COALESCE(
      (SELECT jsonb_agg(sub) FROM (
        SELECT jsonb_build_object(
          'id', ab.id,
          'participant_id', ab.participant_id,
          'participant_name', COALESCE(c.company_name, e.full_name),
          'amount', ab.amount,
          'is_winning', ab.is_winning,
          'placed_at', ab.placed_at
        ) AS val FROM public.auction_bids ab
        JOIN auction_participants ap ON ap.id = ab.participant_id
        LEFT JOIN customers c ON c.id = ap.participant_id AND ap.participant_type = 'customer'
        LEFT JOIN employees e ON e.id = ap.participant_id AND ap.participant_type = 'employee'
        WHERE ab.auction_id = a.id
        ORDER BY ab.placed_at DESC LIMIT 100
      ) sub), '[]'::jsonb
    ),
    'activity', COALESCE(
      (SELECT jsonb_agg(sub) FROM (
        SELECT jsonb_build_object(
          'id', act.id,
          'activity_type', act.activity_type,
          'actor_name', act.actor_name,
          'message', act.message,
          'metadata', act.metadata,
          'created_at', act.created_at
        ) AS val FROM public.auction_activity act
        WHERE act.auction_id = a.id
        ORDER BY act.created_at DESC LIMIT 50
      ) sub), '[]'::jsonb
    )
  ) INTO v_result FROM public.auctions a WHERE a.id = p_auction_id;

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_auctions(p_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  IF p_token IS NOT NULL THEN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'code', a.code,
      'title', a.title,
      'description', a.description,
      'image_url', a.image_url,
      'starting_price', a.starting_price,
      'current_price', a.current_price,
      'bid_increment', a.bid_increment,
      'deposit_amount', a.deposit_amount,
      'start_time', a.start_time,
      'end_time', a.end_time,
      'status', a.status,
      'winner_id', a.winner_id,
      'winner_amount', a.winner_amount,
      'participant_count', (SELECT COUNT(*) FROM public.auction_participants ap WHERE ap.auction_id = a.id AND ap.status = 'approved'),
      'bid_count', (SELECT COUNT(*) FROM public.auction_bids ab WHERE ab.auction_id = a.id),
      'items', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', ai.id,
            'product_id', ai.product_id,
            'product_name', p.product_name,
            'quantity', ai.quantity
          )
        ) FROM public.auction_items ai
        JOIN products p ON p.id = ai.product_id
        WHERE ai.auction_id = a.id), '[]'::jsonb
      ),
      'created_at', a.created_at,
      'updated_at', a.updated_at,
      'participant_status',
      CASE WHEN v_session.token IS NOT NULL THEN
        public._get_auction_participant_status(a.id, v_session)
      ELSE
        jsonb_build_object('status', 'visitor')
      END
    ) ORDER BY
      CASE a.status WHEN 'live' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END,
      a.end_time ASC
  ) INTO v_result FROM public.auctions a;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_collections(p_token uuid)
 RETURNS SETOF collections
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT c.* FROM public.collections c WHERE c.customer_id = v_session.customer_id;
    RETURN;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY SELECT c.* FROM public.collections c ORDER BY c.created_at DESC;
    RETURN;
  END IF;
  RETURN QUERY SELECT c.* FROM public.collections c
    WHERE c.created_by IN (
      WITH RECURSIVE sub AS (
        SELECT id FROM public.employees WHERE id = v_session.employee_id
        UNION ALL
        SELECT e.id FROM public.employees e JOIN sub s ON e.manager_id = s.id
      )
      SELECT id FROM sub
    )
    ORDER BY c.created_at DESC;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_collections(p_token uuid, p_page integer, p_page_size integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[]; v_total bigint; v_offset int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  v_offset := (p_page - 1) * p_page_size;
  IF v_session.identity_type = 'customer' THEN
    SELECT count(*) INTO v_total FROM public.collections WHERE customer_id = v_session.customer_id;
    RETURN json_build_object('total', v_total, 'data', (SELECT json_agg(row_to_json(c)) FROM (SELECT * FROM public.collections WHERE customer_id = v_session.customer_id ORDER BY created_at DESC LIMIT p_page_size OFFSET v_offset) c));
  END IF;
  SELECT count(*) INTO v_total FROM public.collections co JOIN public.customers cu ON cu.id = co.customer_id WHERE cu.owner_id = ANY(v_visible);
  RETURN json_build_object('total', v_total, 'data', (SELECT json_agg(row_to_json(sub)) FROM (SELECT co.* FROM public.collections co JOIN public.customers cu ON cu.id = co.customer_id WHERE cu.owner_id = ANY(v_visible) ORDER BY co.created_at DESC LIMIT p_page_size OFFSET v_offset) sub));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_companies(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', comp.id,
      'company_name', comp.company_name,
      'legacy_code', comp.legacy_code,
      'is_active', comp.is_active,
      'is_visible', comp.is_visible,
      'logo_url', comp.logo_url,
      'display_order', comp.display_order,
      'created_at', comp.created_at,
      'product_count', (SELECT COUNT(*) FROM products p WHERE p.company_id = comp.id)
    ) ORDER BY comp.display_order, comp.company_name
  ) INTO v_result FROM companies comp;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_company_monthly_target(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_target_month int; v_target_year int; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
    v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
    SELECT jsonb_build_object(
        'id', t.id, 'target_month', t.target_month, 'target_year', t.target_year,
        'sales_target', t.sales_target, 'visits_target', t.visits_target, 'orders_target', t.orders_target,
        'new_customers_target', t.new_customers_target,
        'sales_weight_percent', t.sales_weight_percent, 'visits_weight_percent', t.visits_weight_percent,
        'orders_weight_percent', t.orders_weight_percent, 'new_customers_weight_percent', t.new_customers_weight_percent,
        'collections_weight_percent', t.collections_weight_percent,
        'attendance_weight_percent', t.attendance_weight_percent,
        'is_locked', t.is_locked
    ) INTO v_result
    FROM public.company_monthly_targets t
    WHERE t.target_month = v_target_month AND t.target_year = v_target_year;
    RETURN COALESCE(v_result, 'null'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_credit_application(p_token uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT jsonb_build_object('application', row_to_json(a)::jsonb, 'customer', row_to_json(c)::jsonb, 'program', row_to_json(p)::jsonb, 'contract', (SELECT row_to_json(cc)::jsonb FROM public.credit_contracts cc WHERE cc.application_id = a.id LIMIT 1)) INTO v_result
  FROM public.credit_applications a JOIN public.customers c ON c.id = a.customer_id JOIN public.credit_programs p ON p.id = a.program_id
  WHERE a.id = p_id AND (
    v_session.identity_type = 'customer' AND a.customer_id = v_session.customer_id
    OR v_session.identity_type = 'employee' AND (public.is_upper_management(v_session.employee_id) OR c.owner_id = ANY(public.get_visible_employee_ids(p_token)))
  );
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_credit_applications(p_token uuid)
 RETURNS TABLE(id uuid, customer_id uuid, customer_name character varying, program_name character varying, credit_limit numeric, credit_days integer, status credit_application_status, doc_confirmed boolean, submitted_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT a.id, a.customer_id, c.company_name, p.name, p.credit_limit, p.credit_days, a.status, (a.doc_confirmed_by IS NOT NULL), a.submitted_at, a.created_at, a.updated_at
    FROM public.credit_applications a JOIN public.customers c ON c.id = a.customer_id JOIN public.credit_programs p ON p.id = a.program_id
    WHERE a.customer_id = v_session.customer_id ORDER BY a.created_at DESC;
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY SELECT a.id, a.customer_id, c.company_name, p.name, p.credit_limit, p.credit_days, a.status, (a.doc_confirmed_by IS NOT NULL), a.submitted_at, a.created_at, a.updated_at
    FROM public.credit_applications a JOIN public.customers c ON c.id = a.customer_id JOIN public.credit_programs p ON p.id = a.program_id ORDER BY a.created_at DESC;
  ELSE
    RETURN QUERY SELECT a.id, a.customer_id, c.company_name, p.name, p.credit_limit, p.credit_days, a.status, (a.doc_confirmed_by IS NOT NULL), a.submitted_at, a.created_at, a.updated_at
    FROM public.credit_applications a JOIN public.customers c ON c.id = a.customer_id JOIN public.credit_programs p ON p.id = a.program_id
    WHERE c.owner_id = ANY(v_visible) ORDER BY a.created_at DESC;
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_credit_dashboard(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_stats jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT jsonb_build_object(
    'total_accounts', (SELECT COUNT(*) FROM public.customer_credit_accounts),
    'active_accounts', (SELECT COUNT(*) FROM public.customer_credit_accounts WHERE credit_status = 'active'),
    'suspended_accounts', (SELECT COUNT(*) FROM public.customer_credit_accounts WHERE credit_status = 'suspended'),
    'total_outstanding', (SELECT COALESCE(SUM(outstanding_credit), 0) FROM public.customer_credit_accounts),
    'total_reserved', (SELECT COALESCE(SUM(reserved_credit), 0) FROM public.customer_credit_accounts),
    'total_credit_limit', (SELECT COALESCE(SUM(credit_limit), 0) FROM public.customer_credit_accounts),
    'open_invoices', (SELECT COUNT(*) FROM public.credit_invoices WHERE status = 'open'),
    'overdue_invoices', (SELECT COUNT(*) FROM public.credit_invoices WHERE status = 'overdue' OR (status = 'open' AND due_date < CURRENT_DATE)),
    'pending_applications', (SELECT COUNT(*) FROM public.credit_applications WHERE status IN ('submitted', 'under_review', 'documents_received'))
  ) INTO v_stats;

  RETURN v_stats;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_credit_invoice_detail(p_token uuid, p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_invoice jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_build_object(
    'invoice', row_to_json(ci.*),
    'cheque', row_to_json(cic.*),
    'order', row_to_json(o.*)
  ) INTO v_invoice
  FROM public.credit_invoices ci
  LEFT JOIN public.credit_invoice_cheques cic ON cic.invoice_id = ci.id
  JOIN orders o ON o.id = ci.order_id
  WHERE ci.id = p_invoice_id;

  RETURN COALESCE(v_invoice, jsonb_build_object('error', 'NOT_FOUND'));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_credit_invoices(p_token uuid, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_customer_id uuid;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- If employee, use p_customer_id. If customer, use their own.
  IF v_session.identity_type = 'employee' THEN
    v_customer_id := p_customer_id;
  ELSIF v_session.customer_id IS NOT NULL THEN
    v_customer_id := v_session.customer_id;
  ELSE
    RETURN jsonb_build_object('error', 'ACCESS_DENIED');
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ci.id,
      'invoice_number', ci.invoice_number,
      'order_id', ci.order_id,
      'order_number', o.order_number,
      'invoice_amount', ci.invoice_amount,
      'issue_date', ci.issue_date,
      'due_date', ci.due_date,
      'status', ci.status,
      'days_overdue', CASE WHEN ci.status != 'paid' AND ci.due_date < CURRENT_DATE THEN (CURRENT_DATE - ci.due_date) ELSE 0 END,
      'cheque_status', (SELECT cic.status FROM public.credit_invoice_cheques cic WHERE cic.invoice_id = ci.id)
    ) ORDER BY ci.issue_date DESC
  ) INTO v_result
  FROM public.credit_invoices ci
  JOIN orders o ON o.id = ci.order_id
  WHERE ci.customer_id = v_customer_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customer(p_token uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_build_object(
    'id', c.id,
    'code', c.code,
    'company_name', c.company_name,
    'responsible_name', c.responsible_name,
    'business_type', c.business_type,
    'email', c.email,
    'phone', i.phone,
    'credit_limit', c.credit_limit,
    'credit_days', c.credit_days,
    'owner_id', c.owner_id,
    'owner_name', e.full_name,
    'owner_code', e.code,
    'is_active', c.is_active,
    'location_id', c.location_id,
    'registered_at', c.registered_at,
    'created_at', c.created_at,
    'governorate_id', addr.governorate_id,
    'city_id', addr.city_id,
    'street_address', addr.street_address,
    'landmark', addr.landmark,
    'location_accuracy', addr.location_accuracy,
    'governorate_name', COALESCE(addr.governorate, (SELECT rg.name_ar FROM reference_governorates rg WHERE rg.id = addr.governorate_id)),
    'city_name', COALESCE(addr.city, (SELECT rc.name_ar FROM reference_cities rc WHERE rc.id = addr.city_id)),
    'registered_address', addr.address_line1
  ) INTO v_result
  FROM customers c
  JOIN identities i ON i.id = c.identity_id
  LEFT JOIN employees e ON e.id = c.owner_id
  LEFT JOIN LATERAL fn_customer_default_address(c.id) addr ON true
  WHERE c.id = p_id;

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customer_addresses(p_token uuid, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type = 'customer' THEN
    IF p_customer_id IS NOT NULL AND p_customer_id != v_session.customer_id THEN
      RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    SELECT jsonb_agg(jsonb_build_object(
      'id', ca.id, 'customer_id', ca.customer_id, 'label', ca.label,
      'address_line1', ca.address_line1, 'address_line2', ca.address_line2,
      'city', ca.city, 'governorate', ca.governorate, 'postal_code', ca.postal_code,
      'latitude', ca.latitude, 'longitude', ca.longitude, 'is_default', ca.is_default,
      'governorate_id', ca.governorate_id, 'city_id', ca.city_id,
      'street_address', ca.street_address, 'landmark', ca.landmark,
      'location_accuracy', ca.location_accuracy,
      'governorate_name', (SELECT name_ar FROM reference_governorates WHERE id = ca.governorate_id),
      'city_name', (SELECT name_ar FROM reference_cities WHERE id = ca.city_id)
    ) ORDER BY ca.is_default DESC) INTO v_result
    FROM customer_addresses ca WHERE ca.customer_id = COALESCE(p_customer_id, v_session.customer_id);
  ELSE
    WITH v_visible_customers AS (
      SELECT c.id FROM customers c
      WHERE (p_customer_id IS NULL OR c.id = p_customer_id)
        AND (public.is_upper_management(v_session.employee_id)
             OR c.owner_id = v_session.employee_id
             OR c.owner_id = ANY(public.get_visible_employee_ids(p_token)))
    )
    SELECT jsonb_agg(jsonb_build_object(
      'id', ca.id, 'customer_id', ca.customer_id, 'label', ca.label,
      'address_line1', ca.address_line1, 'address_line2', ca.address_line2,
      'city', ca.city, 'governorate', ca.governorate, 'postal_code', ca.postal_code,
      'latitude', ca.latitude, 'longitude', ca.longitude, 'is_default', ca.is_default,
      'governorate_id', ca.governorate_id, 'city_id', ca.city_id,
      'street_address', ca.street_address, 'landmark', ca.landmark,
      'location_accuracy', ca.location_accuracy,
      'governorate_name', (SELECT name_ar FROM reference_governorates WHERE id = ca.governorate_id),
      'city_name', (SELECT name_ar FROM reference_cities WHERE id = ca.city_id)
    ) ORDER BY ca.is_default DESC) INTO v_result
    FROM customer_addresses ca WHERE ca.customer_id IN (SELECT id FROM v_visible_customers);

    IF v_result IS NULL AND p_customer_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id) THEN
        RETURN jsonb_build_object('error', 'CUSTOMER_NOT_FOUND');
      END IF;
    END IF;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customer_contacts(p_token uuid, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type = 'customer' THEN
    IF p_customer_id IS NOT NULL AND p_customer_id != v_session.customer_id THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    SELECT jsonb_agg(jsonb_build_object('id', cc.id, 'customer_id', cc.customer_id, 'phone', cc.phone, 'full_name', cc.full_name, 'is_primary', cc.is_primary, 'email', cc.email, 'role', cc.role) ORDER BY cc.is_primary DESC NULLS LAST) INTO v_result
    FROM customer_contacts cc WHERE cc.customer_id = COALESCE(p_customer_id, v_session.customer_id);
  ELSE
    WITH v_visible_customers AS (
      SELECT c.id FROM customers c
      WHERE (p_customer_id IS NULL OR c.id = p_customer_id)
        AND (public.is_upper_management(v_session.employee_id) OR c.owner_id = v_session.employee_id OR c.owner_id = ANY(public.get_visible_employee_ids(p_token)))
    )
    SELECT jsonb_agg(jsonb_build_object('id', cc.id, 'customer_id', cc.customer_id, 'phone', cc.phone, 'full_name', cc.full_name, 'is_primary', cc.is_primary, 'email', cc.email, 'role', cc.role) ORDER BY cc.is_primary DESC NULLS LAST) INTO v_result
    FROM customer_contacts cc WHERE cc.customer_id IN (SELECT id FROM v_visible_customers);
    IF v_result IS NULL AND p_customer_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id) THEN RETURN jsonb_build_object('error', 'CUSTOMER_NOT_FOUND'); END IF;
    END IF;
  END IF;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customer_credit_account(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_account jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.customer_id IS NULL THEN
    RETURN jsonb_build_object('error', 'NOT_CUSTOMER');
  END IF;

  SELECT jsonb_build_object(
    'id', cca.id,
    'customer_id', cca.customer_id,
    'program_id', cca.credit_program_id,
    'program_name', cp.name,
    'credit_limit', cca.credit_limit,
    'payment_term_days', cca.payment_term_days,
    'outstanding_credit', cca.outstanding_credit,
    'reserved_credit', cca.reserved_credit,
    'available_credit', cca.credit_limit - cca.outstanding_credit - cca.reserved_credit,
    'guarantee_cheque_amount', cca.guarantee_cheque_amount,
    'credit_status', cca.credit_status,
    'activated_at', cca.activated_at
  ) INTO v_account
  FROM public.customer_credit_accounts cca
  JOIN credit_programs cp ON cp.id = cca.credit_program_id
  WHERE cca.customer_id = v_session.customer_id;

  RETURN COALESCE(v_account, jsonb_build_object('error', 'NOT_FOUND'));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customer_ownership_history(p_token uuid, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', coh.id, 'customer_id', coh.customer_id,
      'previous_owner_id', coh.previous_owner_id,
      'new_owner_id', coh.new_owner_id,
      'changed_by', coh.changed_by,
      'reason', coh.reason,
      'changed_at', coh.changed_at
    )
    ORDER BY coh.changed_at DESC
  ) INTO v_result
  FROM customer_ownership_history coh
  WHERE coh.customer_id = p_customer_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_customers(p_token text, p_search text DEFAULT NULL::text, p_employee_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_no_orders boolean DEFAULT false, p_no_visits boolean DEFAULT false, p_no_location boolean DEFAULT false, p_governorate_id uuid DEFAULT NULL::uuid, p_needs_address_correction boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_emp_id uuid;
  v_is_customer boolean;
  v_filter_no_orders boolean;
  v_filter_no_visits boolean;
  v_filter_no_location boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM set_config('app.identity_id', v_session.identity_id::text, true);

  v_emp_id := app.current_employee_id();
  v_is_customer := (v_session.identity_type = 'customer');
  v_filter_no_orders := COALESCE(p_no_orders, false);
  v_filter_no_visits := COALESCE(p_no_visits, false);
  v_filter_no_location := COALESCE(p_no_location, false);

  -- Customer sessions: show only their own customer record
  IF v_is_customer THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', c.id, 'code', c.code, 'company_name', c.company_name,
      'responsible_name', c.responsible_name, 'business_type', c.business_type,
      'email', c.email, 'phone', i.phone,
      'credit_limit', c.credit_limit, 'credit_days', c.credit_days,
      'owner_id', c.owner_id, 'owner_name', e.full_name,
      'is_active', c.is_active, 'location_id', c.location_id,
      'registered_address', addr.registered_address,
      'location_address', loc.formatted_address,
      'needs_address_correction', COALESCE(c.needs_address_correction, false),
      'manual_governorate_id', addr.manual_governorate_id,
      'registered_at', c.registered_at, 'created_at', c.created_at,
      'previous_order_count', ps.order_count,
      'previous_orders_total', ps.orders_total,
      'last_order_number', ps.last_order_number,
      'last_order_date', ps.last_order_date,
      'last_order_total', ps.last_order_total,
      'delivered_total', ps.delivered_total,
      'last_visit_date', vs.last_visit_date,
      'visit_count', vs.visit_count,
      'current_balance', (COALESCE(ps.orders_total, 0) - COALESCE(col.total_collected, 0))
    )) INTO v_result
    FROM customers c
    JOIN identities i ON i.id = c.identity_id
    LEFT JOIN employees e ON e.id = c.owner_id
    LEFT JOIN LATERAL (
      SELECT
        trim(both '- ' from concat_ws(' - ',
          NULLIF(TRIM(ca3.governorate), ''),
          NULLIF(TRIM(ca3.city), ''),
          NULLIF(TRIM(COALESCE(ca3.street_address, ca3.address_line1, '')), '')
        )) AS registered_address,
        ca3.governorate_id AS manual_governorate_id
      FROM customer_addresses ca3
      WHERE ca3.customer_id = c.id AND ca3.is_default = true
      LIMIT 1
    ) addr ON true
    LEFT JOIN LATERAL (
      SELECT formatted_address
      FROM public.unified_locations ul
      WHERE ul.id = c.location_id
      LIMIT 1
    ) loc ON true
    LEFT JOIN LATERAL (
      SELECT
        count(*)::bigint AS order_count,
        COALESCE(sum(total_amount), 0) AS orders_total,
        (array_agg(order_number ORDER BY created_at DESC))[1] AS last_order_number,
        max(created_at) AS last_order_date,
        (array_agg(total_amount ORDER BY created_at DESC))[1] AS last_order_total,
        COALESCE(sum(total_amount) FILTER (WHERE o2.status = 'delivered'), 0) AS delivered_total
      FROM public.orders o2
      WHERE o2.customer_id = c.id
    ) ps ON true
    LEFT JOIN LATERAL (
      SELECT
        MAX(v.check_in_at) AS last_visit_date,
        COUNT(*)::bigint AS visit_count
      FROM public.visits v
      WHERE v.customer_id = c.id AND v.check_in_at IS NOT NULL
    ) vs ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(cl.amount), 0) AS total_collected
      FROM public.collections cl
      WHERE cl.customer_id = c.id AND (cl.status IS NULL OR cl.status = 'approved')
    ) col ON true
    WHERE c.identity_id = v_session.identity_id
      AND (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.code ILIKE '%' || p_search || '%' OR i.phone ILIKE '%' || p_search || '%' OR EXISTS (SELECT 1 FROM customer_addresses ca2 WHERE ca2.customer_id = c.id AND (ca2.address_line1 ILIKE '%' || p_search || '%' OR ca2.address_line2 ILIKE '%' || p_search || '%' OR ca2.city ILIKE '%' || p_search || '%' OR ca2.governorate ILIKE '%' || p_search || '%')))
      AND (p_date_from IS NULL OR c.created_at >= p_date_from)
      AND (p_date_to IS NULL OR c.created_at <= p_date_to)
      AND (NOT v_filter_no_orders OR NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.customer_id = c.id))
      AND (NOT v_filter_no_visits OR NOT EXISTS (SELECT 1 FROM public.visits v WHERE v.customer_id = c.id))
      AND (NOT v_filter_no_location OR c.location_id IS NULL)
      AND (p_governorate_id IS NULL OR addr.manual_governorate_id = p_governorate_id)
      AND (p_needs_address_correction IS NULL OR c.needs_address_correction = p_needs_address_correction);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  -- Employees with customers.read capability: all customers
  IF app.has_capability('customers.read') THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', c.id, 'code', c.code, 'company_name', c.company_name,
      'responsible_name', c.responsible_name, 'business_type', c.business_type,
      'email', c.email, 'phone', i.phone,
      'credit_limit', c.credit_limit, 'credit_days', c.credit_days,
      'owner_id', c.owner_id, 'owner_name', e.full_name,
      'is_active', c.is_active, 'location_id', c.location_id,
      'registered_address', addr.registered_address,
      'location_address', loc.formatted_address,
      'needs_address_correction', COALESCE(c.needs_address_correction, false),
      'manual_governorate_id', addr.manual_governorate_id,
      'registered_at', c.registered_at, 'created_at', c.created_at,
      'previous_order_count', ps.order_count,
      'previous_orders_total', ps.orders_total,
      'last_order_number', ps.last_order_number,
      'last_order_date', ps.last_order_date,
      'last_order_total', ps.last_order_total,
      'delivered_total', ps.delivered_total,
      'last_visit_date', vs.last_visit_date,
      'visit_count', vs.visit_count,
      'current_balance', (COALESCE(ps.orders_total, 0) - COALESCE(col.total_collected, 0))
    )) INTO v_result
    FROM customers c
    JOIN identities i ON i.id = c.identity_id
    LEFT JOIN employees e ON e.id = c.owner_id
    LEFT JOIN LATERAL (
      SELECT
        trim(both '- ' from concat_ws(' - ',
          NULLIF(TRIM(ca3.governorate), ''),
          NULLIF(TRIM(ca3.city), ''),
          NULLIF(TRIM(COALESCE(ca3.street_address, ca3.address_line1, '')), '')
        )) AS registered_address,
        ca3.governorate_id AS manual_governorate_id
      FROM customer_addresses ca3
      WHERE ca3.customer_id = c.id AND ca3.is_default = true
      LIMIT 1
    ) addr ON true
    LEFT JOIN LATERAL (
      SELECT formatted_address
      FROM public.unified_locations ul
      WHERE ul.id = c.location_id
      LIMIT 1
    ) loc ON true
    LEFT JOIN LATERAL (
      SELECT
        count(*)::bigint AS order_count,
        COALESCE(sum(total_amount), 0) AS orders_total,
        (array_agg(order_number ORDER BY created_at DESC))[1] AS last_order_number,
        max(created_at) AS last_order_date,
        (array_agg(total_amount ORDER BY created_at DESC))[1] AS last_order_total,
        COALESCE(sum(total_amount) FILTER (WHERE o2.status = 'delivered'), 0) AS delivered_total
      FROM public.orders o2
      WHERE o2.customer_id = c.id
    ) ps ON true
    LEFT JOIN LATERAL (
      SELECT
        MAX(v.check_in_at) AS last_visit_date,
        COUNT(*)::bigint AS visit_count
      FROM public.visits v
      WHERE v.customer_id = c.id AND v.check_in_at IS NOT NULL
    ) vs ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(cl.amount), 0) AS total_collected
      FROM public.collections cl
      WHERE cl.customer_id = c.id AND (cl.status IS NULL OR cl.status = 'approved')
    ) col ON true
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.code ILIKE '%' || p_search || '%' OR i.phone ILIKE '%' || p_search || '%' OR EXISTS (SELECT 1 FROM customer_addresses ca2 WHERE ca2.customer_id = c.id AND (ca2.address_line1 ILIKE '%' || p_search || '%' OR ca2.address_line2 ILIKE '%' || p_search || '%' OR ca2.city ILIKE '%' || p_search || '%' OR ca2.governorate ILIKE '%' || p_search || '%')))
      AND (p_employee_id IS NULL OR c.owner_id = p_employee_id)
      AND (p_date_from IS NULL OR c.created_at >= p_date_from)
      AND (p_date_to IS NULL OR c.created_at <= p_date_to)
      AND (NOT v_filter_no_orders OR NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.customer_id = c.id))
      AND (NOT v_filter_no_visits OR NOT EXISTS (SELECT 1 FROM public.visits v WHERE v.customer_id = c.id))
      AND (NOT v_filter_no_location OR c.location_id IS NULL)
      AND (p_governorate_id IS NULL OR addr.manual_governorate_id = p_governorate_id)
      AND (p_needs_address_correction IS NULL OR c.needs_address_correction = p_needs_address_correction);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  -- Employees without customers.read: own + reports' customers
  SELECT jsonb_agg(jsonb_build_object(
    'id', c.id, 'code', c.code, 'company_name', c.company_name,
    'responsible_name', c.responsible_name, 'business_type', c.business_type,
    'email', c.email, 'phone', i.phone,
    'credit_limit', c.credit_limit, 'credit_days', c.credit_days,
    'owner_id', c.owner_id, 'owner_name', e.full_name,
    'is_active', c.is_active, 'location_id', c.location_id,
    'registered_address', addr.registered_address,
    'location_address', loc.formatted_address,
    'needs_address_correction', COALESCE(c.needs_address_correction, false),
    'manual_governorate_id', addr.manual_governorate_id,
    'registered_at', c.registered_at, 'created_at', c.created_at,
    'previous_order_count', ps.order_count,
    'previous_orders_total', ps.orders_total,
    'last_order_number', ps.last_order_number,
    'last_order_date', ps.last_order_date,
    'last_order_total', ps.last_order_total,
    'delivered_total', ps.delivered_total,
    'last_visit_date', vs.last_visit_date,
    'visit_count', vs.visit_count,
    'current_balance', (COALESCE(ps.orders_total, 0) - COALESCE(col.total_collected, 0))
  )) INTO v_result
  FROM customers c
  JOIN identities i ON i.id = c.identity_id
  LEFT JOIN employees e ON e.id = c.owner_id
  LEFT JOIN LATERAL (
    SELECT
      trim(both '- ' from concat_ws(' - ',
        NULLIF(TRIM(ca3.governorate), ''),
        NULLIF(TRIM(ca3.city), ''),
        NULLIF(TRIM(COALESCE(ca3.street_address, ca3.address_line1, '')), '')
      )) AS registered_address,
      ca3.governorate_id AS manual_governorate_id
    FROM customer_addresses ca3
    WHERE ca3.customer_id = c.id AND ca3.is_default = true
    LIMIT 1
  ) addr ON true
  LEFT JOIN LATERAL (
    SELECT formatted_address
    FROM public.unified_locations ul
    WHERE ul.id = c.location_id
    LIMIT 1
  ) loc ON true
  LEFT JOIN LATERAL (
    SELECT
      count(*)::bigint AS order_count,
      COALESCE(sum(total_amount), 0) AS orders_total,
      (array_agg(order_number ORDER BY created_at DESC))[1] AS last_order_number,
      max(created_at) AS last_order_date,
      (array_agg(total_amount ORDER BY created_at DESC))[1] AS last_order_total,
      COALESCE(sum(total_amount) FILTER (WHERE o2.status = 'delivered'), 0) AS delivered_total
    FROM public.orders o2
    WHERE o2.customer_id = c.id
  ) ps ON true
  LEFT JOIN LATERAL (
    SELECT
      MAX(v.check_in_at) AS last_visit_date,
      COUNT(*)::bigint AS visit_count
    FROM public.visits v
    WHERE v.customer_id = c.id AND v.check_in_at IS NOT NULL
  ) vs ON true
  LEFT JOIN LATERAL (
    SELECT COALESCE(sum(cl.amount), 0) AS total_collected
    FROM public.collections cl
    WHERE cl.customer_id = c.id AND (cl.status IS NULL OR cl.status = 'approved')
  ) col ON true
  WHERE c.owner_id = ANY(app.get_subtree_ids(v_emp_id))
    AND (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.code ILIKE '%' || p_search || '%' OR i.phone ILIKE '%' || p_search || '%' OR EXISTS (SELECT 1 FROM customer_addresses ca2 WHERE ca2.customer_id = c.id AND (ca2.address_line1 ILIKE '%' || p_search || '%' OR ca2.address_line2 ILIKE '%' || p_search || '%' OR ca2.city ILIKE '%' || p_search || '%' OR ca2.governorate ILIKE '%' || p_search || '%')))
    AND (p_employee_id IS NULL OR c.owner_id = p_employee_id)
    AND (p_date_from IS NULL OR c.created_at >= p_date_from)
    AND (p_date_to IS NULL OR c.created_at <= p_date_to)
    AND (NOT v_filter_no_orders OR NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.customer_id = c.id))
    AND (NOT v_filter_no_visits OR NOT EXISTS (SELECT 1 FROM public.visits v WHERE v.customer_id = c.id))
    AND (NOT v_filter_no_location OR c.location_id IS NULL)
    AND (p_governorate_id IS NULL OR addr.manual_governorate_id = p_governorate_id)
    AND (p_needs_address_correction IS NULL OR c.needs_address_correction = p_needs_address_correction);

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_daily_deals(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', d.id,
      'title', d.title,
      'image_url', d.image_url,
      'description', d.description,
      'fixed_price', d.fixed_price,
      'available_quantity', d.available_quantity,
      'original_quantity', d.original_quantity,
      'starts_at', d.starts_at,
      'ends_at', d.ends_at,
      'status', d.status,
      'created_by', d.created_by,
      'created_at', d.created_at,
      'updated_at', d.updated_at,
      'items', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', di.id,
            'product_id', di.product_id,
            'product_name', p.product_name,
            'quantity', di.quantity
          )
        ) FROM daily_deal_items di
        JOIN products p ON p.id = di.product_id
        WHERE di.deal_id = d.id), '[]'::jsonb
      )
    ) ORDER BY d.created_at DESC
  ) INTO v_result FROM daily_deals d;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_dashboard_counts(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp_count bigint;
  v_comp_count bigint;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT COUNT(*) INTO v_emp_count FROM employees;
  SELECT COUNT(*) INTO v_comp_count FROM companies;

  RETURN jsonb_build_object(
    'employees_count', v_emp_count,
    'companies_count', v_comp_count
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_data_quality_report(p_token uuid, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_total bigint;
  v_with_address bigint;
  v_with_gps bigint;
  v_with_governorate_only bigint;
  v_with_city_only bigint;
  v_with_address_no_gps bigint;
  v_with_gps_no_address bigint;
  v_complete bigint;
  v_needs_review bigint;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'locations.view_all') THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN');
  END IF;

  -- Helper: filter by employee scope when p_employee_id is provided
  CREATE TEMP TABLE v_customer_ids ON COMMIT DROP AS
  SELECT c.id FROM customers c
  WHERE c.is_active = true
    AND (p_employee_id IS NULL OR c.owner_id = p_employee_id);

  SELECT COUNT(*) INTO v_total FROM v_customer_ids;

  -- Have city AND governorate in default address
  SELECT COUNT(*) INTO v_with_address
  FROM v_customer_ids v
  WHERE EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND ca.city IS NOT NULL AND ca.city != ''
      AND ca.governorate IS NOT NULL AND ca.governorate != ''
  );

  -- Have GPS (location_id)
  SELECT COUNT(*) INTO v_with_gps
  FROM v_customer_ids v
  JOIN customers c ON c.id = v.id AND c.location_id IS NOT NULL;

  -- Have governorate only (no city)
  SELECT COUNT(*) INTO v_with_governorate_only
  FROM v_customer_ids v
  WHERE EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND (ca.governorate IS NOT NULL AND ca.governorate != '')
      AND (ca.city IS NULL OR ca.city = '')
  );

  -- Have city only (no governorate)
  SELECT COUNT(*) INTO v_with_city_only
  FROM v_customer_ids v
  WHERE EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND (ca.city IS NOT NULL AND ca.city != '')
      AND (ca.governorate IS NULL OR ca.governorate = '')
  );

  -- Have address but no GPS
  SELECT COUNT(*) INTO v_with_address_no_gps
  FROM v_customer_ids v
  JOIN customers c ON c.id = v.id AND c.location_id IS NULL
  WHERE EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND ca.city IS NOT NULL AND ca.city != ''
      AND ca.governorate IS NOT NULL AND ca.governorate != ''
  );

  -- Have GPS but no address
  SELECT COUNT(*) INTO v_with_gps_no_address
  FROM v_customer_ids v
  JOIN customers c ON c.id = v.id AND c.location_id IS NOT NULL
  WHERE NOT EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND ca.city IS NOT NULL AND ca.city != ''
      AND ca.governorate IS NOT NULL AND ca.governorate != ''
  );

  -- Complete (GPS + city + governorate + city_id + governorate_id)
  SELECT COUNT(*) INTO v_complete
  FROM v_customer_ids v
  JOIN customers c ON c.id = v.id AND c.location_id IS NOT NULL
  WHERE EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND ca.city IS NOT NULL AND ca.city != ''
      AND ca.governorate IS NOT NULL AND ca.governorate != ''
      AND ca.city_id IS NOT NULL
      AND ca.governorate_id IS NOT NULL
  );

  -- Need review (missing any core field)
  SELECT COUNT(*) INTO v_needs_review
  FROM v_customer_ids v
  WHERE NOT EXISTS (
    SELECT 1 FROM customer_addresses ca
    WHERE ca.customer_id = v.id AND ca.is_default = true
      AND ca.city IS NOT NULL AND ca.city != ''
      AND ca.governorate IS NOT NULL AND ca.governorate != ''
      AND ca.city_id IS NOT NULL
      AND ca.governorate_id IS NOT NULL
  )
  OR NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = v.id AND c.location_id IS NOT NULL);

  v_result := jsonb_build_object(
    'total_customers', v_total,
    'with_gps', v_with_gps,
    'with_address_city_governorate', v_with_address,
    'with_governorate_only', v_with_governorate_only,
    'with_city_only', v_with_city_only,
    'with_address_no_gps', v_with_address_no_gps,
    'with_gps_no_address', v_with_gps_no_address,
    'complete_data', v_complete,
    'needs_review', v_needs_review,
    'gps_percentage', CASE WHEN v_total > 0 THEN ROUND((v_with_gps::numeric / v_total) * 100, 1) ELSE 0 END,
    'address_percentage', CASE WHEN v_total > 0 THEN ROUND((v_with_address::numeric / v_total) * 100, 1) ELSE 0 END,
    'complete_percentage', CASE WHEN v_total > 0 THEN ROUND((v_complete::numeric / v_total) * 100, 1) ELSE 0 END
  );

  DROP TABLE IF EXISTS v_customer_ids;

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_deliveries(p_token uuid, p_status_filter character varying DEFAULT NULL::character varying)
 RETURNS TABLE(id uuid, order_id uuid, order_number character varying, customer_name character varying, status character varying, assigned_to_name character varying, assigned_at timestamp with time zone, started_at timestamp with time zone, completed_at timestamp with time zone, failure_reason character varying, notes text, total_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_session app.sessions; v_visible uuid[]; v_is_super boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  v_is_super := public.is_upper_management(v_session.employee_id);
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY
  SELECT dt.id, o.id, o.order_number, c.company_name, dt.status,
         ast.code, dt.assigned_at, dt.started_at, dt.completed_at,
         dt.failure_reason, dt.notes, o.total_amount
  FROM public.delivery_tracking dt
  JOIN public.orders o ON o.id = dt.order_id
  JOIN public.customers c ON c.id = o.customer_id
  LEFT JOIN public.employees ast ON ast.id = dt.assigned_to
  WHERE dt.is_active = true
    AND (v_is_super OR o.owner_id = ANY(v_visible))
    AND (p_status_filter IS NULL OR dt.status = p_status_filter)
  ORDER BY dt.created_at DESC;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_governed_employee(p_token uuid, p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp public.employees;
  v_role text;
  v_phone text;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN
    RETURN json_build_object('error', 'INVALID_SESSION');
  END IF;

  SELECT e.*, i.phone
  INTO v_emp.id, v_emp.identity_id, v_emp.code, v_emp.full_name, v_emp.email,
       v_emp.manager_id, v_emp.is_active, v_emp.created_at, v_emp.updated_at,
       v_emp.address, v_phone
  FROM public.employees e
  LEFT JOIN public.identities i ON i.id = e.identity_id
  WHERE e.id = p_employee_id;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'NOT_FOUND');
  END IF;

  SELECT r.name INTO v_role
  FROM public.employee_roles er
  JOIN public.roles r ON r.id = er.role_id
  WHERE er.employee_id = p_employee_id
  LIMIT 1;

  RETURN json_build_object(
    'id', v_emp.id,
    'full_name', v_emp.full_name,
    'phone', COALESCE(v_phone, ''),
    'code', v_emp.code,
    'role', COALESCE(v_role, ''),
    'address', COALESCE(v_emp.address, ''),
    'is_active', v_emp.is_active
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_employee_by_identity(p_token uuid, p_identity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp public.employees;
  v_role text;
  v_phone text;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN
    RETURN json_build_object('error', 'INVALID_SESSION');
  END IF;

  SELECT e.*, i.phone
  INTO v_emp.id, v_emp.identity_id, v_emp.code, v_emp.full_name, v_emp.email,
       v_emp.manager_id, v_emp.is_active, v_emp.created_at, v_emp.updated_at,
       v_emp.address, v_phone
  FROM public.employees e
  LEFT JOIN public.identities i ON i.id = e.identity_id
  WHERE e.identity_id = p_identity_id;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'NOT_FOUND');
  END IF;

  SELECT r.name INTO v_role
  FROM public.employee_roles er
