  WHERE er.employee_id = v_emp.id
  LIMIT 1;

  RETURN json_build_object(
    'id', v_emp.id,
    'identity_id', v_emp.identity_id,
    'full_name', v_emp.full_name,
    'phone', COALESCE(v_phone, ''),
    'code', v_emp.code,
    'role', COALESCE(v_role, ''),
    'address', COALESCE(v_emp.address, ''),
    'is_active', v_emp.is_active
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_employee_monthly_targets(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions; v_target_month int; v_target_year int; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
    v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id, 'employee_id', t.employee_id, 'employee_code', e.code, 'employee_name', e.full_name,
        'target_month', t.target_month, 'target_year', t.target_year,
        'sales_target', t.sales_target, 'visits_target', t.visits_target, 'orders_target', t.orders_target,
        'new_customers_target', t.new_customers_target, 'collections_target', t.collections_target, 'is_locked', t.is_locked
    ) ORDER BY e.full_name) INTO v_result
    FROM public.employee_monthly_targets t
    JOIN public.employees e ON e.id = t.employee_id
    WHERE t.target_month = v_target_month AND t.target_year = v_target_year;
    RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_employees(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
  v_is_super_admin boolean; v_subtree_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  -- Upper Management: all employees
  SELECT public.is_upper_management(v_session.employee_id) INTO v_is_super_admin;
  IF v_is_super_admin THEN
    SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'identity_id', e.identity_id, 'code', e.code, 'full_name', e.full_name,
        'email', e.email, 'phone', i.phone, 'manager_id', e.manager_id,
        'is_active', e.is_active, 'address', e.address,
        'created_at', e.created_at,
        'roles', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name))
             FROM employee_roles er JOIN roles r ON r.id = er.role_id
             WHERE er.employee_id = e.id), '[]'::jsonb),
        'role_names', COALESCE((SELECT string_agg(r.name, ', ')
             FROM employee_roles er JOIN roles r ON r.id = er.role_id
             WHERE er.employee_id = e.id), ''),
        'direct_capabilities', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', c.id, 'code', c.code, 'grant_type', ec.grant_type))
             FROM employee_capabilities ec JOIN capabilities c ON c.id = ec.capability_id
             WHERE ec.employee_id = e.id), '[]'::jsonb)
      ) ORDER BY e.created_at DESC
    ) INTO v_result FROM employees e JOIN identities i ON i.id = e.identity_id;
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  -- Non-admin: subtree only
  v_subtree_ids := app.get_subtree_ids(v_session.employee_id);

  SELECT jsonb_agg(jsonb_build_object(
      'id', e.id, 'identity_id', e.identity_id, 'code', e.code, 'full_name', e.full_name,
      'email', e.email, 'phone', i.phone, 'manager_id', e.manager_id,
      'is_active', e.is_active, 'address', e.address,
      'created_at', e.created_at,
      'roles', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name))
           FROM employee_roles er JOIN roles r ON r.id = er.role_id
           WHERE er.employee_id = e.id), '[]'::jsonb),
      'role_names', COALESCE((SELECT string_agg(r.name, ', ')
           FROM employee_roles er JOIN roles r ON r.id = er.role_id
           WHERE er.employee_id = e.id), ''),
      'direct_capabilities', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', c.id, 'code', c.code, 'grant_type', ec.grant_type))
           FROM employee_capabilities ec JOIN capabilities c ON c.id = ec.capability_id
           WHERE ec.employee_id = e.id), '[]'::jsonb)
    ) ORDER BY e.created_at DESC
  ) INTO v_result FROM employees e JOIN identities i ON i.id = e.identity_id
  WHERE e.id = ANY(v_subtree_ids);

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_executive_kpis(p_token uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_visible uuid[];
  v_is_super boolean;
  v_can_see_all boolean;
  v_waiting_prep bigint;
  v_in_prep bigint;
  v_ready_for_dispatch bigint;
  v_in_delivery bigint;
  v_delivered bigint;
  v_uncollected bigint;
  v_partially_collected bigint;
  v_fully_collected bigint;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_can_see_all := v_is_super OR public.check_capability(p_token, 'orders.manage');
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);

  SELECT count(*) INTO v_waiting_prep FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'approved'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'));

  SELECT count(*) INTO v_in_prep FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'preparing'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'));

  SELECT count(*) INTO v_ready_for_dispatch FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'prepared'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'));

  SELECT count(*) INTO v_in_delivery FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status IN ('dispatched', 'sent_to_delivery', 'deferred')
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'));

  SELECT count(*) INTO v_delivered FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'));

  SELECT count(*) INTO v_uncollected FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'))
    AND NOT EXISTS (
      SELECT 1 FROM public.collections col
      WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
        AND col.status IN ('approved', 'treasury_posted')
    );

  SELECT count(*) INTO v_fully_collected FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'))
    AND (
      SELECT COALESCE(SUM(col.amount), 0) FROM public.collections col
      WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
        AND col.status IN ('approved', 'treasury_posted')
    ) >= o.total_amount;

  SELECT count(*) INTO v_partially_collected FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
    AND (v_can_see_all OR c.owner_id = ANY(v_visible))
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'))
    AND EXISTS (
      SELECT 1 FROM public.collections col
      WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
        AND col.status IN ('approved', 'treasury_posted')
    )
    AND (
      SELECT COALESCE(SUM(col.amount), 0) FROM public.collections col
      WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
        AND col.status IN ('approved', 'treasury_posted')
    ) < o.total_amount;

  RETURN jsonb_build_object(
    'waiting_preparation', v_waiting_prep,
    'in_preparation', v_in_prep,
    'ready_for_dispatch', v_ready_for_dispatch,
    'in_delivery', v_in_delivery,
    'delivered', v_delivered,
    'uncollected', v_uncollected,
    'partially_collected', v_partially_collected,
    'fully_collected', v_fully_collected
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_executive_queue(p_token uuid, p_status character varying DEFAULT NULL::character varying, p_search text DEFAULT NULL::text, p_governorate character varying DEFAULT NULL::character varying, p_delivery_mode character varying DEFAULT NULL::character varying, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_employee_name text DEFAULT NULL::text, p_date_filter character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_visible uuid[];
  v_is_super boolean;
  v_can_see_all boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_can_see_all := v_is_super OR public.check_capability(p_token, 'orders.manage');
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'status', o.status,
        'delivery_mode', o.delivery_mode,
        'payment_method', o.payment_method,
        'total_amount', o.total_amount,
        'revision_number', o.revision_number,
        'customer_id', o.customer_id,
        'customer_name', COALESCE(o.snapshot_customer_name, c.company_name),
        'customer_code', o.snapshot_customer_code,
        'customer_phone', COALESCE(o.snapshot_customer_phone, ci.phone),
        'governorate', ca.governorate,
        'owner_name', e.full_name,
        'owner_id', o.owner_id,
        'created_by_name', COALESCE(o.snapshot_sender_name, oc_emp.full_name, oc_cust.company_name, ''),
        'created_by_id', CASE
          WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
          WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
          ELSE NULL
        END,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'submitted_at', o.submitted_at,
        'approved_at', o.approved_at,
        'current_delivery_status', (
          SELECT dt.status FROM public.delivery_tracking dt
          WHERE dt.order_id = o.id AND dt.is_active = true LIMIT 1
        ),
        'has_collections', EXISTS(
          SELECT 1 FROM public.collections col
          WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
        ),
        'collected_amount', (
          SELECT COALESCE(SUM(col.amount), 0) FROM public.collections col
          WHERE (col.order_id = o.id OR col.customer_id = o.customer_id)
            AND col.status IN ('approved', 'treasury_posted')
        ),
        'item_count', (SELECT count(*) FROM public.order_items oi WHERE oi.order_id = o.id),
        'customer_owner_name', COALESCE(co_emp.full_name, ''),
        'customer_owner_role', COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = c.owner_id LIMIT 1), '')
      )
      ORDER BY o.updated_at DESC
    ), '[]'::jsonb)
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    LEFT JOIN public.identities ci ON ci.id = c.identity_id
    LEFT JOIN public.customer_addresses ca ON ca.customer_id = c.id AND ca.is_default = true
    LEFT JOIN public.employees co_emp ON co_emp.id = c.owner_id
    LEFT JOIN public.employees e ON e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    WHERE (v_can_see_all OR c.owner_id = ANY(v_visible))
      AND o.status IN ('submitted', 'reviewing', 'approved', 'preparing', 'prepared', 'ready_for_dispatch', 'dispatched', 'sent_to_delivery', 'delivered', 'deferred', 'returned_for_revision')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_delivery_mode IS NULL OR o.delivery_mode = p_delivery_mode)
      AND (p_governorate IS NULL OR ca.governorate = p_governorate)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= (p_date_to + interval '1 day'))
      AND (p_employee_name IS NULL OR
           e.full_name ILIKE '%' || p_employee_name || '%' OR
           oc_emp.full_name ILIKE '%' || p_employee_name || '%')
      AND (p_search IS NULL OR
           o.order_number ILIKE '%' || p_search || '%' OR
           c.company_name ILIKE '%' || p_search || '%' OR
           o.snapshot_customer_name ILIKE '%' || p_search || '%')
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_external_carriers(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 DECLARE v_session app.sessions; BEGIN SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now(); IF NOT FOUND THEN RETURN '[]'::jsonb; END IF; RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'code', code)), '[]'::jsonb) FROM public.external_carriers WHERE is_active = true); END; 
$function$;

CREATE OR REPLACE FUNCTION public.get_governed_flash_offers(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', d.id,
      'title', d.title,
      'image_url', d.image_url,
      'description', d.description,
      'fixed_price', d.fixed_price,
      'available_quantity', d.available_quantity,
      'original_quantity', d.original_quantity,
      'starts_at', d.starts_at,
      'ends_at', d.ends_at,
      'status', d.status,
      'created_by', d.created_by,
      'created_at', d.created_at,
      'updated_at', d.updated_at,
      'items', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', di.id,
            'product_id', di.product_id,
            'product_name', p.product_name,
            'quantity', di.quantity
          )
        ) FROM flash_offer_items di
        JOIN products p ON p.id = di.product_id
        WHERE di.offer_id = d.id), '[]'::jsonb
      )
    ) ORDER BY d.created_at DESC
  ) INTO v_result FROM flash_offers d;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_location(p_token uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_authorized boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.employee_id IS NOT NULL THEN
    v_authorized := EXISTS (SELECT 1 FROM customers WHERE location_id = p_id AND owner_id = v_session.employee_id)
      OR EXISTS (SELECT 1 FROM visits WHERE (start_location_id = p_id OR end_location_id = p_id) AND employee_id = v_session.employee_id)
      OR EXISTS (SELECT 1 FROM orders WHERE execution_location_id = p_id AND (created_by = v_session.employee_id OR owner_id = v_session.employee_id))
      OR public.check_capability(p_token, 'locations.view_all');
  ELSIF v_session.customer_id IS NOT NULL THEN
    v_authorized := EXISTS (SELECT 1 FROM customers WHERE location_id = p_id AND id = v_session.customer_id);
  ELSE
    v_authorized := false;
  END IF;
  IF v_authorized IS NOT TRUE THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  SELECT jsonb_build_object(
    'id', ul.id, 'latitude', ul.latitude, 'longitude', ul.longitude,
    'accuracy_meters', ul.accuracy_meters, 'google_maps_url', ul.google_maps_url,
    'formatted_address', ul.formatted_address,
    'governorate_id', ul.governorate_id, 'city_id', ul.city_id, 'road', ul.road,
    'enriched_at', ul.enriched_at, 'enrichment_status', ul.enrichment_status,
    'geocoding_provider', ul.geocoding_provider, 'enrichment_version', ul.enrichment_version,
    'governorate_name', (SELECT rg.name_ar FROM reference_governorates rg WHERE rg.id = ul.governorate_id),
    'city_name', (SELECT rc.name_ar FROM reference_cities rc WHERE rc.id = ul.city_id),
    'captured_at', ul.captured_at, 'created_at', ul.created_at
  ) INTO v_result FROM unified_locations ul WHERE ul.id = p_id;
  RETURN COALESCE(v_result, jsonb_build_object('error', 'NOT_FOUND'));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_locations(p_token uuid, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_has_view_all boolean;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.employee_id IS NOT NULL THEN v_has_view_all := public.check_capability(p_token, 'locations.view_all'); END IF;
  SELECT jsonb_agg(jsonb_build_object(
    'id', ul.id, 'latitude', ul.latitude, 'longitude', ul.longitude,
    'accuracy_meters', ul.accuracy_meters, 'google_maps_url', ul.google_maps_url,
    'formatted_address', ul.formatted_address,
    'governorate_id', ul.governorate_id, 'city_id', ul.city_id, 'road', ul.road,
    'enriched_at', ul.enriched_at, 'enrichment_status', ul.enrichment_status,
    'geocoding_provider', ul.geocoding_provider, 'enrichment_version', ul.enrichment_version,
    'governorate_name', (SELECT rg.name_ar FROM reference_governorates rg WHERE rg.id = ul.governorate_id),
    'city_name', (SELECT rc.name_ar FROM reference_cities rc WHERE rc.id = ul.city_id),
    'captured_at', ul.captured_at, 'created_at', ul.created_at
  )) INTO v_result
  FROM unified_locations ul WHERE ul.id = ANY(p_ids)
    AND ((v_session.employee_id IS NOT NULL AND (v_has_view_all
      OR ul.id IN (SELECT location_id FROM customers WHERE owner_id = v_session.employee_id AND location_id IS NOT NULL)
      OR ul.id IN (SELECT start_location_id FROM visits WHERE employee_id = v_session.employee_id AND start_location_id IS NOT NULL)
      OR ul.id IN (SELECT end_location_id FROM visits WHERE employee_id = v_session.employee_id AND end_location_id IS NOT NULL)
      OR ul.id IN (SELECT execution_location_id FROM orders WHERE (created_by = v_session.employee_id OR owner_id = v_session.employee_id) AND execution_location_id IS NOT NULL)))
      OR (v_session.customer_id IS NOT NULL AND ul.id IN (SELECT location_id FROM customers WHERE id = v_session.customer_id AND location_id IS NOT NULL)));
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_order(p_token uuid, p_id uuid)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_order public.orders; v_subtree_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_session.identity_type = 'customer' THEN
    IF v_order.customer_id != v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    RETURN v_order;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN RETURN v_order; END IF;
  v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
  IF EXISTS (SELECT 1 FROM public.customers c WHERE c.id = v_order.customer_id AND c.owner_id = ANY(v_subtree_ids)) THEN RETURN v_order; END IF;
  RAISE EXCEPTION 'FORBIDDEN';
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_order_daily_deals(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', odd.id,
      'order_id', odd.order_id,
      'deal_id', odd.deal_id,
      'title', d.title,
      'quantity', odd.quantity,
      'fixed_price', odd.fixed_price,
      'total_price', odd.total_price,
      'image_url', d.image_url
    )
  ) INTO v_result
  FROM order_daily_deals odd
  JOIN daily_deals d ON d.id = odd.deal_id
  WHERE odd.order_id = p_order_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_order_flash_offers(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ofo.id,
      'order_id', ofo.order_id,
      'offer_id', ofo.offer_id,
      'title', d.title,
      'quantity', ofo.quantity,
      'fixed_price', ofo.fixed_price,
      'total_price', ofo.total_price,
      'image_url', d.image_url
    )
  ) INTO v_result
  FROM order_flash_offers ofo
  JOIN flash_offers d ON d.id = ofo.offer_id
  WHERE ofo.order_id = p_order_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_order_history(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_order_exists boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT EXISTS (SELECT 1 FROM orders WHERE id = p_order_id) INTO v_order_exists;
  IF NOT v_order_exists THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', osh.id,
      'order_id', osh.order_id,
      'from_status', osh.from_status,
      'to_status', osh.to_status,
      'changed_by', osh.changed_by,
      'reason', osh.reason,
      'changed_at', osh.changed_at
    )
    ORDER BY osh.changed_at ASC
  ) INTO v_result
  FROM order_status_history osh
  WHERE osh.order_id = p_order_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_order_items(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Customers can see items of their own orders only
  IF v_session.identity_type = 'customer' THEN
    IF NOT EXISTS (SELECT 1 FROM public.orders WHERE id = p_order_id AND customer_id = v_session.customer_id) THEN
      RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
  ELSIF v_session.identity_type != 'employee' THEN
    RETURN jsonb_build_object('error', 'NOT_EMPLOYEE');
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', oi.id,
      'order_id', oi.order_id,
      'product_id', oi.product_id,
      'unit_type', oi.unit_type,
      'unit_quantity', oi.unit_quantity,
      'piece_quantity', oi.piece_quantity,
      'unit_price', oi.unit_price,
      'total_price', oi.total_price,
      'product_name', p.product_name,
      'legacy_code', p.legacy_code,
      'image_url', p.image_url,
      'company_id', p.company_id,
      'company_name', comp.company_name
    )
  ) INTO v_result
  FROM order_items oi
  JOIN products p ON p.id = oi.product_id
  JOIN companies comp ON comp.id = p.company_id
  WHERE oi.order_id = p_order_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_orders(p_token uuid, p_search text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_customer_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
  v_subtree_ids uuid[]; v_identity_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  -- Customer: own orders only
  IF v_session.identity_type = 'customer' THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', o.id, 'order_number', o.order_number,
      'customer_id', o.customer_id, 'customer_code', COALESCE(o.snapshot_customer_code, ''),
      'customer_name', COALESCE(o.snapshot_customer_name, ''),
      'customer_phone', COALESCE(o.snapshot_customer_phone, ''),
      'customer_address', COALESCE(o.snapshot_customer_address, ''),
      'customer_maps_url', '', 'owner_type', o.owner_type, 'owner_id', o.owner_id,
      'owner_name', e.full_name,
      'owner_phone', COALESCE(o.snapshot_owner_phone, ''),
      'owner_address', COALESCE(o.snapshot_owner_address, ''),
      'status', o.status, 'subtotal', o.subtotal, 'discount_amount', o.discount_amount,
      'total_amount', o.total_amount, 'notes', o.notes, 'revision_number', o.revision_number,
      'created_by', o.created_by, 'created_by_name', COALESCE(o.snapshot_sender_name, ''),
      'created_by_id', CASE
        WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
        WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
        ELSE NULL
      END,
      'created_by_phone', COALESCE(o.snapshot_sender_phone, ''),
      'created_by_address', COALESCE(o.snapshot_sender_address, ''),
      'created_at', o.created_at, 'updated_at', o.updated_at,
      'approved_at', o.approved_at, 'submitted_at', o.submitted_at,
      'item_count', (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id = o.id)
    ) ORDER BY o.created_at DESC) INTO v_result
    FROM orders o
    LEFT JOIN public.employees e ON e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    WHERE o.created_by = v_session.identity_id
      AND (p_search IS NULL OR o.order_number ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_employee_id IS NULL OR public.resolve_employee_id(o.created_by) = p_employee_id)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;
  -- Upper management: all orders
  IF public.is_upper_management(v_session.employee_id) THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', o.id, 'order_number', o.order_number,
      'customer_id', o.customer_id, 'customer_code', COALESCE(o.snapshot_customer_code, ''),
      'customer_name', COALESCE(o.snapshot_customer_name, ''),
      'customer_phone', COALESCE(o.snapshot_customer_phone, ''),
      'customer_address', COALESCE(o.snapshot_customer_address, ''),
      'customer_maps_url', '', 'owner_type', o.owner_type, 'owner_id', o.owner_id,
      'owner_name', e.full_name,
      'owner_phone', COALESCE(o.snapshot_owner_phone, ''),
      'owner_address', COALESCE(o.snapshot_owner_address, ''),
      'status', o.status, 'subtotal', o.subtotal, 'discount_amount', o.discount_amount,
      'total_amount', o.total_amount, 'notes', o.notes, 'revision_number', o.revision_number,
      'created_by', o.created_by, 'created_by_name', COALESCE(o.snapshot_sender_name, ''),
      'created_by_id', CASE
        WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
        WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
        ELSE NULL
      END,
      'created_by_phone', COALESCE(o.snapshot_sender_phone, ''),
      'created_by_address', COALESCE(o.snapshot_sender_address, ''),
      'created_at', o.created_at, 'updated_at', o.updated_at,
      'approved_at', o.approved_at, 'submitted_at', o.submitted_at,
      'item_count', (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id = o.id)
    ) ORDER BY o.created_at DESC) INTO v_result
    FROM orders o
    LEFT JOIN public.employees e ON e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    WHERE (p_search IS NULL OR o.order_number ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_employee_id IS NULL OR public.resolve_employee_id(o.created_by) = p_employee_id)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;
  -- Others: tree-scoped orders
  v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
  SELECT COALESCE(array_agg(identity_id), '{}'::uuid[]) INTO v_identity_ids
  FROM public.employees WHERE id = ANY(v_subtree_ids);
  SELECT jsonb_agg(jsonb_build_object(
    'id', o.id, 'order_number', o.order_number,
    'customer_id', o.customer_id, 'customer_code', COALESCE(o.snapshot_customer_code, ''),
    'customer_name', COALESCE(o.snapshot_customer_name, ''),
    'customer_phone', COALESCE(o.snapshot_customer_phone, ''),
    'customer_address', COALESCE(o.snapshot_customer_address, ''),
    'customer_maps_url', '', 'owner_type', o.owner_type, 'owner_id', o.owner_id,
    'owner_name', e.full_name,
    'owner_phone', COALESCE(o.snapshot_owner_phone, ''),
    'owner_address', COALESCE(o.snapshot_owner_address, ''),
    'status', o.status, 'subtotal', o.subtotal, 'discount_amount', o.discount_amount,
    'total_amount', o.total_amount, 'notes', o.notes, 'revision_number', o.revision_number,
    'created_by', o.created_by, 'created_by_name', COALESCE(o.snapshot_sender_name, ''),
    'created_by_id', CASE
      WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
      WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
      ELSE NULL
    END,
    'created_by_phone', COALESCE(o.snapshot_sender_phone, ''),
    'created_by_address', COALESCE(o.snapshot_sender_address, ''),
    'created_at', o.created_at, 'updated_at', o.updated_at,
    'approved_at', o.approved_at, 'submitted_at', o.submitted_at,
    'item_count', (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id = o.id)
  ) ORDER BY o.created_at DESC) INTO v_result
  FROM orders o
  LEFT JOIN public.employees e ON e.id = o.owner_id
  LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
  LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
  LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
  WHERE (o.created_by = ANY(v_identity_ids) OR o.customer_id IN (SELECT c2.id FROM customers c2 WHERE c2.owner_id = ANY(v_subtree_ids)))
    AND (p_search IS NULL OR o.order_number ILIKE '%' || p_search || '%')
    AND (p_status IS NULL OR o.status = p_status)
    AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
    AND (p_employee_id IS NULL OR public.resolve_employee_id(o.created_by) = p_employee_id)
    AND (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= p_date_to);
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_preparation_detail(p_token uuid, p_preparation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_prep_rec record;
  v_order_data jsonb;
  v_status_history jsonb;
  v_modification_history jsonb;
  v_exceptions jsonb;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT * INTO v_prep_rec FROM preparation_records WHERE id = p_preparation_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;

  SELECT jsonb_build_object(
    'id', o.id, 'order_number', o.order_number, 'customer_id', o.customer_id,
    'customer_name_snapshot', c.company_name, 'owner_id', o.owner_id,
    'status', o.status, 'total_amount', o.total_amount,
    'subtotal', o.subtotal, 'discount_amount', o.discount_amount,
    'created_at', o.created_at, 'updated_at', o.updated_at
  ) INTO v_order_data
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  WHERE o.id = v_prep_rec.order_id;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', osh.id, 'order_id', osh.order_id, 'from_status', osh.from_status,
      'to_status', osh.to_status, 'changed_by', osh.changed_by,
      'reason', osh.reason, 'changed_at', osh.changed_at
    )
    ORDER BY osh.changed_at ASC
  ) INTO v_status_history
  FROM order_status_history osh
  WHERE osh.order_id = v_prep_rec.order_id;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', omh.id, 'order_id', omh.order_id, 'revision_number', omh.revision_number,
      'field_name', omh.field_name, 'old_value', omh.old_value, 'new_value', omh.new_value,
      'modified_by', omh.modified_by, 'reason', omh.reason, 'modified_at', omh.modified_at
    )
    ORDER BY omh.modified_at ASC
  ) INTO v_modification_history
  FROM order_modification_history omh
  WHERE omh.order_id = v_prep_rec.order_id;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', pe.id, 'preparation_id', pe.preparation_id,
      'exception_type', pe.exception_type, 'notes', pe.notes, 'created_at', pe.created_at
    )
    ORDER BY pe.created_at DESC
  ) INTO v_exceptions
  FROM preparation_exceptions pe
  WHERE pe.preparation_id = p_preparation_id;

  SELECT jsonb_build_object(
    'id', v_prep_rec.id,
    'order_id', v_prep_rec.order_id,
    'status', v_prep_rec.status,
    'started_at', v_prep_rec.started_at,
    'completed_at', v_prep_rec.completed_at,
    'reviewed_at', v_prep_rec.reviewed_at,
    'cancelled_at', v_prep_rec.cancelled_at,
    'notes', v_prep_rec.notes,
    'order', v_order_data,
    'status_history', COALESCE(v_status_history, '[]'::jsonb),
    'modification_history', COALESCE(v_modification_history, '[]'::jsonb),
    'exceptions', COALESCE(v_exceptions, '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_preparation_queue(p_token uuid, p_status_filter text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, order_id uuid, order_code text, customer_name text, status text, started_by uuid, started_at timestamp with time zone, completed_by uuid, completed_at timestamp with time zone, reviewed_by uuid, reviewed_at timestamp with time zone, notes text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN; END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY
      SELECT pr.id, pr.order_id, o.order_number::text, cust.company_name::text, pr.status::text,
             pr.started_by, pr.started_at, pr.completed_by, pr.completed_at,
             pr.reviewed_by, pr.reviewed_at, pr.notes::text
      FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id
      JOIN public.customers cust ON cust.id = o.customer_id
      WHERE (p_status_filter IS NULL OR pr.status::text = p_status_filter)
      ORDER BY pr.created_at DESC;
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY
    SELECT pr.id, pr.order_id, o.order_number::text, cust.company_name::text, pr.status::text,
           pr.started_by, pr.started_at, pr.completed_by, pr.completed_at,
           pr.reviewed_by, pr.reviewed_at, pr.notes::text
    FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id
    JOIN public.customers cust ON cust.id = o.customer_id
    WHERE o.owner_id = ANY(v_visible)
      AND (p_status_filter IS NULL OR pr.status::text = p_status_filter)
    ORDER BY pr.created_at DESC;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_products(p_token text, p_active_only boolean DEFAULT false, p_visible_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_count_only boolean DEFAULT false, p_page integer DEFAULT NULL::integer, p_per_page integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_offset integer;
  v_limit integer;
  v_token uuid;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_SESSION');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF p_count_only THEN
    SELECT jsonb_build_object('count', COUNT(*)) INTO v_result
    FROM products p
    WHERE (NOT p_active_only OR p.is_active = true)
      AND (NOT p_visible_only OR p.is_visible = true)
      AND (NOT p_active_only OR (p.carton_price IS NOT NULL AND p.carton_price > 0))
      AND (p_search IS NULL OR p.product_name ILIKE '%' || p_search || '%' OR p.legacy_code ILIKE '%' || p_search || '%')
      AND (p_company_id IS NULL OR p.company_id = p_company_id);
    RETURN v_result;
  END IF;

  v_limit := COALESCE(p_per_page, 1000000);
  v_offset := COALESCE((p_page - 1) * v_limit, 0);

  SELECT jsonb_agg(sub.data)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id', p.id,
      'product_name', p.product_name,
      'legacy_code', p.legacy_code,
      'description', p.description,
      'company_id', p.company_id,
      'company_name', comp.company_name,
      'is_active', p.is_active,
      'is_visible', p.is_visible,
      'is_out_of_stock', p.is_out_of_stock,
      'image_url', p.image_url,
      'carton_price', p.carton_price,
      'carton_quantity', p.carton_quantity,
      'piece_price', p.piece_price,
      'dozen_price', p.dozen_price,
      'created_at', p.created_at,
      'recently_available_at', p.recently_available_at,
      'negative_selling_allowed', p.negative_selling_allowed,
      'inventory_deduction_status', p.inventory_deduction_status,
      'oos_source', p.oos_source,
      'product_units', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object('id', pu.id, 'unit_type', pu.unit_type, 'is_active', pu.is_active)
          ORDER BY pu.unit_type
        ) FROM product_units pu WHERE pu.product_id = p.id),
        '[]'::jsonb
      ),
      'inventory', (SELECT jsonb_build_object('quantity', inv.quantity) FROM inventory inv WHERE inv.product_id = p.id LIMIT 1)
    ) AS data
    FROM products p
    JOIN companies comp ON comp.id = p.company_id
    WHERE (NOT p_active_only OR p.is_active = true)
      AND (NOT p_visible_only OR p.is_visible = true)
      AND (NOT p_active_only OR (p.carton_price IS NOT NULL AND p.carton_price > 0))
      AND (p_search IS NULL OR p.product_name ILIKE '%' || p_search || '%' OR p.legacy_code ILIKE '%' || p_search || '%')
      AND (p_company_id IS NULL OR p.company_id = p_company_id)
    ORDER BY p.product_name
    LIMIT v_limit
    OFFSET v_offset
  ) sub;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_return(p_token uuid, p_id uuid)
 RETURNS returns
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_return public.returns; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_return FROM public.returns WHERE id = p_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_session.identity_type = 'customer' THEN
    IF v_return.customer_id != v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    RETURN v_return;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN RETURN v_return; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_return.created_by = ANY(v_visible) THEN RETURN v_return; END IF;
  RAISE EXCEPTION 'FORBIDDEN';
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_return_items(p_token uuid, p_return_id uuid)
 RETURNS SETOF return_items
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_return public.returns; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_return FROM public.returns WHERE id = p_return_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    IF v_return.customer_id != v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    RETURN QUERY SELECT ri.* FROM public.return_items ri WHERE ri.return_id = p_return_id; RETURN;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY SELECT ri.* FROM public.return_items ri WHERE ri.return_id = p_return_id; RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_return.created_by = ANY(v_visible) THEN
    RETURN QUERY SELECT ri.* FROM public.return_items ri WHERE ri.return_id = p_return_id;
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_returns(p_token uuid)
 RETURNS SETOF returns
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT r.* FROM public.returns r WHERE r.customer_id = v_session.customer_id; RETURN;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY SELECT r.* FROM public.returns r ORDER BY r.created_at DESC; RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY SELECT r.* FROM public.returns r WHERE r.created_by = ANY(v_visible) ORDER BY r.created_at DESC;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_roles(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN
    RETURN jsonb_build_object('error', 'NOT_EMPLOYEE');
  END IF;
  SELECT jsonb_agg(
    jsonb_build_object('id', r.id, 'name', r.name, 'description', r.description, 'created_at', r.created_at)
    ORDER BY r.name
  ) INTO v_result FROM roles r;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_target_performance(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_target_month int; v_target_year int;
    v_comp_sales_weight numeric := 75;
    v_comp_visits_weight numeric := 7.5;
    v_comp_orders_weight numeric := 7.5;
    v_comp_new_customers_weight numeric := 10;
    v_comp_collections_weight numeric := 0;
    v_comp_attendance_weight numeric := 0;
    v_company_sales_target numeric;
    v_company_visits_target int;
    v_company_orders_target int;
    v_company_new_customers_target int;
    v_company_delivered_sales numeric; v_company_completed_visits int;
    v_company_delivered_orders int; v_company_new_customers int;
    v_company_return_deductions numeric; v_company_full_returns int;
    v_company_effective_sales numeric; v_company_effective_orders int;
    v_company_collections_actual numeric;
    v_company_sales_pct numeric; v_company_visits_pct numeric;
    v_company_orders_pct numeric; v_company_new_customers_pct numeric;
    v_company_collections_pct numeric;
    v_company_overall numeric;
    v_employee_perf jsonb; v_best_employee jsonb; v_weakest_employee jsonb;
    v_company_info jsonb;
    v_hierarchy jsonb;
    v_month_start timestamptz; v_month_end timestamptz;
    v_visible_ids uuid[];
    v_has_target boolean;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_visible_ids := public.get_visible_employee_ids(p_token);
    v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
    v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
    v_month_start := date_trunc('month', to_timestamp(v_target_year || '-' || v_target_month || '-01', 'YYYY-MM-DD'));
    v_month_end := v_month_start + INTERVAL '1 month';

    -- Read company-level weights from company_monthly_targets (Canonical Source)
    SELECT
        COALESCE(sales_weight_percent, 75),
        COALESCE(visits_weight_percent, 7.5),
        COALESCE(orders_weight_percent, 7.5),
        COALESCE(new_customers_weight_percent, 10),
        COALESCE(collections_weight_percent, 0),
        COALESCE(attendance_weight_percent, 0)
    INTO v_comp_sales_weight, v_comp_visits_weight, v_comp_orders_weight,
         v_comp_new_customers_weight, v_comp_collections_weight, v_comp_attendance_weight
    FROM public.company_monthly_targets
    WHERE target_month = v_target_month
      AND target_year = v_target_year;

    -- Company targets = read from company_monthly_targets
    SELECT
        sales_target,
        visits_target::int,
        orders_target::int,
        new_customers_target::int
    INTO v_company_sales_target, v_company_visits_target, v_company_orders_target, v_company_new_customers_target
    FROM public.company_monthly_targets
    WHERE target_month = v_target_month
      AND target_year = v_target_year;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('has_target', false, 'company', 'null'::jsonb, 'employees', '[]'::jsonb, 'best_employee', 'null'::jsonb, 'weakest_employee', 'null'::jsonb, 'hierarchy', 'null'::jsonb);
    END IF;

    v_has_target := (v_company_sales_target > 0 OR v_company_visits_target > 0 OR v_company_orders_target > 0 OR v_company_new_customers_target > 0);
    IF NOT v_has_target THEN
        RETURN jsonb_build_object('has_target', false, 'company', 'null'::jsonb, 'employees', '[]'::jsonb, 'best_employee', 'null'::jsonb, 'weakest_employee', 'null'::jsonb, 'hierarchy', 'null'::jsonb);
    END IF;

    SELECT COALESCE(SUM(o.total_amount), 0) INTO v_company_delivered_sales
    FROM public.orders o WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end;
    SELECT COUNT(*)::int INTO v_company_completed_visits
    FROM public.visits v WHERE v.status = 'completed' AND v.check_out_at >= v_month_start AND v.check_out_at < v_month_end;
    SELECT COUNT(*)::int INTO v_company_delivered_orders
    FROM public.orders o WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end;
    SELECT COUNT(*)::int INTO v_company_new_customers
    FROM public.customers c WHERE EXISTS (
        SELECT 1 FROM public.orders o WHERE o.customer_id = c.id AND o.status = 'delivered'
        AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end
        AND o.delivered_at = (SELECT MIN(o2.delivered_at) FROM public.orders o2 WHERE o2.customer_id = c.id AND o2.status = 'delivered'));
    SELECT COALESCE(SUM(c.amount), 0) INTO v_company_collections_actual
    FROM public.collections c
    WHERE c.status = 'collected' AND c.collected_at >= v_month_start AND c.collected_at < v_month_end;
    SELECT COALESCE(SUM(r.credit_note_amount), 0), COUNT(DISTINCT CASE WHEN fr.order_id IS NOT NULL THEN r.order_id END)::int
    INTO v_company_return_deductions, v_company_full_returns
    FROM public.returns r LEFT JOIN (
        SELECT r2.order_id FROM public.returns r2 JOIN public.return_items ri ON ri.return_id = r2.id
        JOIN public.products p ON p.id = ri.product_id
        JOIN (SELECT oi.order_id, SUM(oi.piece_quantity) AS total_pieces FROM public.order_items oi GROUP BY oi.order_id) oi ON oi.order_id = r2.order_id
        WHERE r2.status = 'approved' AND r2.created_at >= v_month_start AND r2.created_at < v_month_end
        GROUP BY r2.order_id, oi.total_pieces
        HAVING SUM(CASE WHEN ri.unit_type = 'piece' THEN ri.quantity WHEN ri.unit_type = 'dozen' THEN ri.quantity * 12 WHEN ri.unit_type = 'carton' THEN ri.quantity * p.carton_quantity END) >= oi.total_pieces
    ) fr ON fr.order_id = r.order_id
    WHERE r.status = 'approved' AND r.created_at >= v_month_start AND r.created_at < v_month_end;
    v_company_effective_sales := GREATEST(v_company_delivered_sales - v_company_return_deductions, 0);
    v_company_effective_orders := GREATEST(v_company_delivered_orders - v_company_full_returns, 0);

    -- Achievement percentages with LEAST cap at 100%
    v_company_sales_pct := CASE WHEN v_company_sales_target > 0
        THEN LEAST(ROUND((v_company_effective_sales / v_company_sales_target * 100)::numeric, 2), 100)
        ELSE 0 END;
    v_company_visits_pct := CASE WHEN v_company_visits_target > 0
        THEN LEAST(ROUND((v_company_completed_visits::numeric / v_company_visits_target * 100)::numeric, 2), 100)
        ELSE 0 END;
    v_company_orders_pct := CASE WHEN v_company_orders_target > 0
        THEN LEAST(ROUND((v_company_effective_orders::numeric / v_company_orders_target * 100)::numeric, 2), 100)
        ELSE 0 END;
    v_company_new_customers_pct := CASE WHEN v_company_new_customers_target > 0
        THEN LEAST(ROUND((v_company_new_customers::numeric / v_company_new_customers_target * 100)::numeric, 2), 100)
        ELSE 0 END;
    v_company_collections_pct := CASE WHEN v_company_collections_actual > 0
        THEN 100 ELSE 0 END;

    -- Company overall weighted score
    v_company_overall := ROUND(
        (v_company_sales_pct * v_comp_sales_weight / 100) +
        (v_company_visits_pct * v_comp_visits_weight / 100) +
        (v_company_orders_pct * v_comp_orders_weight / 100) +
        (v_company_new_customers_pct * v_comp_new_customers_weight / 100), 2);

    v_company_info := jsonb_build_object(
        'sales_target', v_company_sales_target, 'visits_target', v_company_visits_target,
        'orders_target', v_company_orders_target, 'new_customers_target', v_company_new_customers_target,
        'sales_actual', v_company_effective_sales, 'visits_actual', v_company_completed_visits,
        'orders_actual', v_company_effective_orders, 'new_customers_actual', v_company_new_customers,
        'collections_actual', v_company_collections_actual,
        'return_deductions', v_company_return_deductions, 'full_returns', v_company_full_returns,
        'sales_weight_percent', v_comp_sales_weight, 'visits_weight_percent', v_comp_visits_weight,
        'orders_weight_percent', v_comp_orders_weight, 'new_customers_weight_percent', v_comp_new_customers_weight,
        'collections_weight_percent', v_comp_collections_weight, 'attendance_weight_percent', v_comp_attendance_weight,
        'sales_achievement_pct', v_company_sales_pct, 'visits_achievement_pct', v_company_visits_pct,
        'orders_achievement_pct', v_company_orders_pct, 'new_customers_achievement_pct', v_company_new_customers_pct,
        'collections_achievement_pct', v_company_collections_pct,
        'overall_achievement_pct', v_company_overall
    );

    -- --------------------------------------------------------------------------
    -- Employee performance with dynamic weights per employee
    -- --------------------------------------------------------------------------
    WITH employee_orders AS (
        SELECT COALESCE(emp.id, emp2.id) AS employee_id, o.total_amount, o.id AS order_id, o.customer_id, o.delivered_at
        FROM public.orders o LEFT JOIN public.employees emp ON o.owner_id = emp.id LEFT JOIN public.employees emp2 ON o.owner_id = emp2.identity_id
        WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end
    ), employee_sales AS (
        SELECT employee_id, COALESCE(SUM(total_amount), 0) AS sales_actual, COUNT(DISTINCT order_id)::int AS orders_actual
        FROM employee_orders GROUP BY employee_id
    ), employee_visits AS (
        SELECT v.employee_id, COUNT(*)::int AS visits_actual FROM public.visits v
        WHERE v.status = 'completed' AND v.check_out_at >= v_month_start AND v.check_out_at < v_month_end GROUP BY v.employee_id
    ), employee_new_customers AS (
        SELECT eo.employee_id, COUNT(DISTINCT eo.customer_id)::int AS new_customers_actual
        FROM employee_orders eo WHERE eo.delivered_at = (SELECT MIN(o2.delivered_at) FROM public.orders o2 WHERE o2.customer_id = eo.customer_id AND o2.status = 'delivered')
        GROUP BY eo.employee_id
    ), employee_returns AS (
        SELECT COALESCE(emp.id, emp2.id) AS employee_id,
            COALESCE(SUM(r.credit_note_amount), 0) AS return_deduction,
            COUNT(DISTINCT CASE WHEN fr.order_id IS NOT NULL THEN r.order_id END)::int AS full_returns
        FROM public.returns r JOIN public.orders o ON o.id = r.order_id
        LEFT JOIN public.employees emp ON o.owner_id = emp.id LEFT JOIN public.employees emp2 ON o.owner_id = emp2.identity_id
        LEFT JOIN (
            SELECT r3.order_id FROM public.returns r3 JOIN public.return_items ri ON ri.return_id = r3.id
            JOIN public.products p ON p.id = ri.product_id
            JOIN (SELECT oi2.order_id, SUM(oi2.piece_quantity) AS total_pieces FROM public.order_items oi2 GROUP BY oi2.order_id) oi3 ON oi3.order_id = r3.order_id
            WHERE r3.status = 'approved' AND r3.created_at >= v_month_start AND r3.created_at < v_month_end
            GROUP BY r3.order_id, oi3.total_pieces
            HAVING SUM(CASE WHEN ri.unit_type = 'piece' THEN ri.quantity WHEN ri.unit_type = 'dozen' THEN ri.quantity * 12 WHEN ri.unit_type = 'carton' THEN ri.quantity * p.carton_quantity END) >= oi3.total_pieces
        ) fr ON fr.order_id = r.order_id
        WHERE r.status = 'approved' AND r.created_at >= v_month_start AND r.created_at < v_month_end
        GROUP BY COALESCE(emp.id, emp2.id)
    ), employee_collections AS (
        -- CANONICAL: Collections = public.collections WHERE status='collected', use collected_at
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COALESCE(SUM(c.amount), 0) AS collections_actual
        FROM public.collections c
        WHERE c.status = 'collected'
          AND c.collected_at >= v_month_start AND c.collected_at < v_month_end
        GROUP BY public.resolve_employee_id(c.owner_id)
    ), employee_calc AS (
        SELECT e.id AS employee_id, e.code AS employee_code, e.full_name AS employee_name,
            e.manager_id,
            m.full_name AS manager_name,
            COALESCE(et.sales_target, 0) AS sales_target,
            COALESCE(et.visits_target, 0) AS visits_target,
            COALESCE(et.orders_target, 0) AS orders_target,
            COALESCE(et.new_customers_target, 0) AS new_customers_target,
            COALESCE(et.collections_target, 0) AS collections_target,
            COALESCE(s.sales_actual, 0) AS gross_sales,
            COALESCE(v.visits_actual, 0) AS visits_actual,
            COALESCE(s.orders_actual, 0) AS gross_orders,
            COALESCE(nc.new_customers_actual, 0) AS new_customers_actual,
            COALESCE(rd.return_deduction, 0) AS return_deduction,
            COALESCE(rd.full_returns, 0) AS full_returns,
            COALESCE(cl.collections_actual, 0) AS collections_actual,
            GREATEST(COALESCE(s.sales_actual, 0) - COALESCE(rd.return_deduction, 0), 0) AS effective_sales,
            GREATEST(COALESCE(s.orders_actual, 0) - COALESCE(rd.full_returns, 0), 0) AS effective_orders,
            CASE WHEN et.id IS NOT NULL THEN et.is_locked ELSE NULL END AS is_locked,
            et.id IS NOT NULL AS has_target,
            (COALESCE(s.sales_actual, 0) > 0 OR COALESCE(v.visits_actual, 0) > 0
             OR COALESCE(s.orders_actual, 0) > 0 OR COALESCE(nc.new_customers_actual, 0) > 0) AS has_activity,
            public.get_effective_weights(e.id, v_target_month, v_target_year) AS emp_weights
        FROM public.employees e
        LEFT JOIN public.employees m ON m.id = e.manager_id
        LEFT JOIN public.employee_monthly_targets et
            ON et.employee_id = e.id AND et.target_month = v_target_month AND et.target_year = v_target_year
        LEFT JOIN employee_sales s ON s.employee_id = e.id
        LEFT JOIN employee_visits v ON v.employee_id = e.id
        LEFT JOIN employee_new_customers nc ON nc.employee_id = e.id
        LEFT JOIN employee_returns rd ON rd.employee_id = e.id
        LEFT JOIN employee_collections cl ON cl.employee_id = e.id
        WHERE e.is_active = true AND e.id = ANY(v_visible_ids)
    ), employee_with_kpis AS (
        SELECT ec.*,
            0 AS attendance_target,
            0 AS attendance_actual,
            CASE WHEN ec.sales_target > 0
                THEN LEAST(ROUND((ec.effective_sales / ec.sales_target * 100)::numeric, 2), 100)
                ELSE NULL END AS sales_achievement_pct,
            CASE WHEN ec.visits_target > 0
                THEN LEAST(ROUND((ec.visits_actual::numeric / ec.visits_target * 100)::numeric, 2), 100)
                ELSE NULL END AS visits_achievement_pct,
            CASE WHEN ec.orders_target > 0
                THEN LEAST(ROUND((ec.effective_orders::numeric / ec.orders_target * 100)::numeric, 2), 100)
                ELSE NULL END AS orders_achievement_pct,
            CASE WHEN ec.new_customers_target > 0
                THEN LEAST(ROUND((ec.new_customers_actual::numeric / ec.new_customers_target * 100)::numeric, 2), 100)
                ELSE NULL END AS new_customers_achievement_pct,
            CASE WHEN ec.collections_target > 0
                THEN LEAST(ROUND((ec.collections_actual::numeric / ec.collections_target * 100)::numeric, 2), 100)
                ELSE NULL END AS collections_achievement_pct,
            NULL::numeric AS attendance_achievement_pct,
            CASE WHEN ec.has_target AND (ec.sales_target > 0 OR ec.visits_target > 0 OR ec.orders_target > 0 OR ec.new_customers_target > 0)
                THEN ROUND(
                    (CASE WHEN ec.sales_target > 0 THEN LEAST(ROUND((ec.effective_sales / ec.sales_target * 100)::numeric, 2), 100) ELSE 0 END *
                        COALESCE((ec.emp_weights->>'sales_weight_percent')::numeric, 75) / 100) +
                    (CASE WHEN ec.visits_target > 0 THEN LEAST(ROUND((ec.visits_actual::numeric / ec.visits_target * 100)::numeric, 2), 100) ELSE 0 END *
                        COALESCE((ec.emp_weights->>'visits_weight_percent')::numeric, 7.5) / 100) +
                    (CASE WHEN ec.orders_target > 0 THEN LEAST(ROUND((ec.effective_orders::numeric / ec.orders_target * 100)::numeric, 2), 100) ELSE 0 END *
                        COALESCE((ec.emp_weights->>'orders_weight_percent')::numeric, 7.5) / 100) +
                    (CASE WHEN ec.new_customers_target > 0 THEN LEAST(ROUND((ec.new_customers_actual::numeric / ec.new_customers_target * 100)::numeric, 2), 100) ELSE 0 END *
                        COALESCE((ec.emp_weights->>'new_customers_weight_percent')::numeric, 10) / 100), 2)
                ELSE NULL END AS overall_achievement_score
        FROM employee_calc ec
    ), kpi_json AS (
        SELECT ewk.employee_id,
            jsonb_build_object(
                'sales', jsonb_build_object('target', ewk.sales_target, 'actual', ewk.effective_sales, 'pct', ewk.sales_achievement_pct),
                'visits', jsonb_build_object('target', ewk.visits_target, 'actual', ewk.visits_actual, 'pct', ewk.visits_achievement_pct),
                'orders', jsonb_build_object('target', ewk.orders_target, 'actual', ewk.effective_orders, 'pct', ewk.orders_achievement_pct),
                'new_customers', jsonb_build_object('target', ewk.new_customers_target, 'actual', ewk.new_customers_actual, 'pct', ewk.new_customers_achievement_pct),
                'collections', jsonb_build_object('target', ewk.collections_target, 'actual', ewk.collections_actual, 'pct', ewk.collections_achievement_pct),
                'attendance', jsonb_build_object('target', ewk.attendance_target, 'actual', ewk.attendance_actual, 'pct', ewk.attendance_achievement_pct)
            ) AS kpis
        FROM employee_with_kpis ewk
    ), team_managers AS (
        SELECT DISTINCT ewk.employee_id, ewk.employee_code, ewk.employee_name,
            ewk.overall_achievement_score
        FROM employee_with_kpis ewk
        WHERE EXISTS (
            SELECT 1 FROM employee_with_kpis sub
            WHERE sub.manager_id = ewk.employee_id
        )
    ), team_raw AS (
        SELECT
            tm.employee_id AS mgr_id, tm.employee_code AS mgr_code, tm.employee_name AS mgr_name,
            tm.overall_achievement_score AS mgr_overall,
            ewk.employee_id, ewk.employee_code, ewk.employee_name, ewk.manager_id,
            ewk.sales_target, ewk.visits_target, ewk.orders_target, ewk.new_customers_target,
            ewk.collections_target, ewk.attendance_target,
            ewk.effective_sales, ewk.visits_actual, ewk.effective_orders, ewk.new_customers_actual,
            ewk.collections_actual, ewk.attendance_actual,
            ewk.sales_achievement_pct, ewk.visits_achievement_pct, ewk.orders_achievement_pct,
            ewk.new_customers_achievement_pct, ewk.collections_achievement_pct, ewk.attendance_achievement_pct,
            ewk.overall_achievement_score,
            ewk.has_target, ewk.has_activity, ewk.is_locked, ewk.emp_weights,
            kj.kpis
        FROM team_managers tm
        JOIN employee_with_kpis ewk ON ewk.employee_id = tm.employee_id
        JOIN kpi_json kj ON kj.employee_id = ewk.employee_id
        UNION ALL
        SELECT
            tm.employee_id AS mgr_id, tm.employee_code AS mgr_code, tm.employee_name AS mgr_name,
            tm.overall_achievement_score AS mgr_overall,
            ewk.employee_id, ewk.employee_code, ewk.employee_name, ewk.manager_id,
            ewk.sales_target, ewk.visits_target, ewk.orders_target, ewk.new_customers_target,
            ewk.collections_target, ewk.attendance_target,
            ewk.effective_sales, ewk.visits_actual, ewk.effective_orders, ewk.new_customers_actual,
            ewk.collections_actual, ewk.attendance_actual,
            ewk.sales_achievement_pct, ewk.visits_achievement_pct, ewk.orders_achievement_pct,
            ewk.new_customers_achievement_pct, ewk.collections_achievement_pct, ewk.attendance_achievement_pct,
            ewk.overall_achievement_score,
            ewk.has_target, ewk.has_activity, ewk.is_locked, ewk.emp_weights,
            kj.kpis
        FROM team_managers tm
        JOIN employee_with_kpis ewk ON ewk.manager_id = tm.employee_id AND ewk.employee_id != tm.employee_id
        JOIN kpi_json kj ON kj.employee_id = ewk.employee_id
    ), team_agg AS (
        SELECT
            mgr_id, mgr_code, mgr_name, mgr_overall,
            COUNT(*) AS member_count,
            SUM(sales_target) AS sum_sales_target, SUM(visits_target) AS sum_visits_target,
            SUM(orders_target) AS sum_orders_target, SUM(new_customers_target) AS sum_new_cust_target,
            SUM(collections_target) AS sum_coll_target, SUM(attendance_target) AS sum_attend_target,
            SUM(effective_sales) AS sum_sales_actual, SUM(visits_actual) AS sum_visits_actual,
            SUM(effective_orders) AS sum_orders_actual, SUM(new_customers_actual) AS sum_new_cust_actual,
            SUM(collections_actual) AS sum_coll_actual, SUM(attendance_actual) AS sum_attend_actual,
            jsonb_agg(
                jsonb_build_object(
                    'employee_id', employee_id, 'employee_code', employee_code, 'employee_name', employee_name,
                    'is_manager', employee_id = mgr_id,
                    'has_target', has_target, 'has_activity', has_activity, 'is_locked', is_locked,
                    'overall_achievement_score', overall_achievement_score,
                    'weights', emp_weights,
                    'kpis', kpis
                ) ORDER BY (CASE WHEN employee_id = mgr_id THEN 0 ELSE 1 END), overall_achievement_score DESC NULLS LAST, employee_name ASC
            ) AS members
        FROM team_raw
        GROUP BY mgr_id, mgr_code, mgr_name, mgr_overall
    ), hierarchy_data AS (
        SELECT jsonb_build_object(
            'manager_count', (SELECT COUNT(*) FROM team_managers),
            'managers', COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'manager_id', ta.mgr_id,
                        'manager_code', ta.mgr_code,
                        'manager_name', ta.mgr_name,
                        'own_overall_score', ta.mgr_overall,
                        'own_kpis', (SELECT kj.kpis FROM kpi_json kj WHERE kj.employee_id = ta.mgr_id),
                        'team_summary', jsonb_build_object(
                            'team_target', jsonb_build_object(
                                'sales', ta.sum_sales_target, 'visits', ta.sum_visits_target,
                                'orders', ta.sum_orders_target, 'new_customers', ta.sum_new_cust_target,
                                'collections', ta.sum_coll_target, 'attendance', ta.sum_attend_target
                            ),
                            'team_actual', jsonb_build_object(
                                'sales', ta.sum_sales_actual, 'visits', ta.sum_visits_actual,
                                'orders', ta.sum_orders_actual, 'new_customers', ta.sum_new_cust_actual,
                                'collections', ta.sum_coll_actual, 'attendance', ta.sum_attend_actual
                            ),
                            'team_achievement_pct', jsonb_build_object(
                                'sales', CASE WHEN ta.sum_sales_target > 0 THEN LEAST(ROUND((ta.sum_sales_actual / ta.sum_sales_target * 100)::numeric, 2), 100) ELSE NULL END,
                                'visits', CASE WHEN ta.sum_visits_target > 0 THEN LEAST(ROUND((ta.sum_visits_actual::numeric / ta.sum_visits_target * 100)::numeric, 2), 100) ELSE NULL END,
                                'orders', CASE WHEN ta.sum_orders_target > 0 THEN LEAST(ROUND((ta.sum_orders_actual::numeric / ta.sum_orders_target * 100)::numeric, 2), 100) ELSE NULL END,
                                'new_customers', CASE WHEN ta.sum_new_cust_target > 0 THEN LEAST(ROUND((ta.sum_new_cust_actual::numeric / ta.sum_new_cust_target * 100)::numeric, 2), 100) ELSE NULL END,
                                'collections', CASE WHEN ta.sum_coll_target > 0 THEN LEAST(ROUND((ta.sum_coll_actual / ta.sum_coll_target * 100)::numeric, 2), 100) ELSE NULL END,
                                'attendance', NULL::numeric
                            ),
                            'team_overall_pct', ROUND(
                                COALESCE(CASE WHEN ta.sum_sales_target > 0 THEN LEAST(ROUND((ta.sum_sales_actual / ta.sum_sales_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_sales_weight / 100, 0) +
                                COALESCE(CASE WHEN ta.sum_visits_target > 0 THEN LEAST(ROUND((ta.sum_visits_actual::numeric / ta.sum_visits_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_visits_weight / 100, 0) +
                                COALESCE(CASE WHEN ta.sum_orders_target > 0 THEN LEAST(ROUND((ta.sum_orders_actual::numeric / ta.sum_orders_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_orders_weight / 100, 0) +
                                COALESCE(CASE WHEN ta.sum_new_cust_target > 0 THEN LEAST(ROUND((ta.sum_new_cust_actual::numeric / ta.sum_new_cust_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_new_customers_weight / 100, 0),
                            2),
                            'team_member_count', ta.member_count
                        ),
                        'members', ta.members
                    ) ORDER BY ROUND(
                        COALESCE(CASE WHEN ta.sum_sales_target > 0 THEN LEAST(ROUND((ta.sum_sales_actual / ta.sum_sales_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_sales_weight / 100, 0) +
                        COALESCE(CASE WHEN ta.sum_visits_target > 0 THEN LEAST(ROUND((ta.sum_visits_actual::numeric / ta.sum_visits_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_visits_weight / 100, 0) +
                        COALESCE(CASE WHEN ta.sum_orders_target > 0 THEN LEAST(ROUND((ta.sum_orders_actual::numeric / ta.sum_orders_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_orders_weight / 100, 0) +
                        COALESCE(CASE WHEN ta.sum_new_cust_target > 0 THEN LEAST(ROUND((ta.sum_new_cust_actual::numeric / ta.sum_new_cust_target * 100)::numeric, 2), 100) ELSE 0 END * v_comp_new_customers_weight / 100, 0),
                    2) DESC NULLS LAST, ta.mgr_name ASC
                ) FROM team_agg ta),
                '[]'::jsonb
            ),
            'unassigned_count', (SELECT COUNT(*) FROM employee_with_kpis ewk
                WHERE ewk.manager_id IS NULL
                   OR NOT EXISTS (SELECT 1 FROM employee_with_kpis sub WHERE sub.employee_id = ewk.manager_id)
            ),
            'unassigned', COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'employee_id', ewk.employee_id, 'employee_code', ewk.employee_code, 'employee_name', ewk.employee_name,
                        'is_manager', false,
                        'has_target', ewk.has_target, 'has_activity', ewk.has_activity, 'is_locked', ewk.is_locked,
                        'overall_achievement_score', ewk.overall_achievement_score,
                        'weights', ewk.emp_weights,
                        'kpis', kj.kpis
                    ) ORDER BY ewk.overall_achievement_score DESC NULLS LAST, ewk.employee_name ASC
                ) FROM employee_with_kpis ewk
                JOIN kpi_json kj ON kj.employee_id = ewk.employee_id
                WHERE ewk.manager_id IS NULL
                   OR NOT EXISTS (SELECT 1 FROM employee_with_kpis sub WHERE sub.employee_id = ewk.manager_id)),
                '[]'::jsonb
            )
            ) AS h_json
    ), final_result AS (
        SELECT
            COALESCE(
                (SELECT jsonb_agg(jsonb_build_object(
                    'employee_id', ec.employee_id, 'employee_code', ec.employee_code, 'employee_name', ec.employee_name,
                    'sales_target', ec.sales_target, 'visits_target', ec.visits_target, 'orders_target', ec.orders_target,
                    'new_customers_target', ec.new_customers_target,
                    'gross_sales', ec.gross_sales, 'visits_actual', ec.visits_actual, 'gross_orders', ec.gross_orders,
                    'new_customers_actual', ec.new_customers_actual,
                    'return_deduction', ec.return_deduction, 'full_returns', ec.full_returns,
                    'effective_sales', ec.effective_sales, 'effective_orders', ec.effective_orders,
                    'has_target', ec.has_target, 'has_activity', ec.has_activity,
                    'sales_achievement_pct', CASE WHEN ec.sales_target > 0
                        THEN LEAST(ROUND((ec.effective_sales / ec.sales_target * 100)::numeric, 2), 100) ELSE NULL END,
                    'visits_achievement_pct', CASE WHEN ec.visits_target > 0
                        THEN LEAST(ROUND((ec.visits_actual::numeric / ec.visits_target * 100)::numeric, 2), 100) ELSE NULL END,
                    'orders_achievement_pct', CASE WHEN ec.orders_target > 0
                        THEN LEAST(ROUND((ec.effective_orders::numeric / ec.orders_target * 100)::numeric, 2), 100) ELSE NULL END,
                    'new_customers_achievement_pct', CASE WHEN ec.new_customers_target > 0
                        THEN LEAST(ROUND((ec.new_customers_actual::numeric / ec.new_customers_target * 100)::numeric, 2), 100) ELSE NULL END,
                    'overall_achievement_score', CASE WHEN ec.has_target AND (ec.sales_target > 0 OR ec.visits_target > 0 OR ec.orders_target > 0 OR ec.new_customers_target > 0)
                        THEN ROUND(
                            (LEAST(CASE WHEN ec.sales_target > 0 THEN ROUND((ec.effective_sales / ec.sales_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'sales_weight_percent')::numeric, 75) / 100) +
                            (LEAST(CASE WHEN ec.visits_target > 0 THEN ROUND((ec.visits_actual::numeric / ec.visits_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'visits_weight_percent')::numeric, 7.5) / 100) +
                            (LEAST(CASE WHEN ec.orders_target > 0 THEN ROUND((ec.effective_orders::numeric / ec.orders_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'orders_weight_percent')::numeric, 7.5) / 100) +
                            (LEAST(CASE WHEN ec.new_customers_target > 0 THEN ROUND((ec.new_customers_actual::numeric / ec.new_customers_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'new_customers_weight_percent')::numeric, 10) / 100), 2)
                        ELSE NULL END,
                    'weights', ec.emp_weights,
                    'is_locked', ec.is_locked
                ) ORDER BY
                    CASE WHEN ec.has_target AND (ec.sales_target > 0 OR ec.visits_target > 0 OR ec.orders_target > 0 OR ec.new_customers_target > 0)
                        THEN (LEAST(CASE WHEN ec.sales_target > 0 THEN ROUND((ec.effective_sales / ec.sales_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'sales_weight_percent')::numeric, 75) / 100) +
                             (LEAST(CASE WHEN ec.visits_target > 0 THEN ROUND((ec.visits_actual::numeric / ec.visits_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'visits_weight_percent')::numeric, 7.5) / 100) +
                             (LEAST(CASE WHEN ec.orders_target > 0 THEN ROUND((ec.effective_orders::numeric / ec.orders_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'orders_weight_percent')::numeric, 7.5) / 100) +
                             (LEAST(CASE WHEN ec.new_customers_target > 0 THEN ROUND((ec.new_customers_actual::numeric / ec.new_customers_target * 100)::numeric, 2) ELSE 0 END, 100) *
                                COALESCE((ec.emp_weights->>'new_customers_weight_percent')::numeric, 10) / 100)
                        ELSE NULL
                    END DESC NULLS LAST,
                    ec.employee_name ASC
                ) FROM employee_calc ec),
                '[]'::jsonb
            ) AS emp_perf,
            (SELECT h_json FROM hierarchy_data) AS h_json
    )
    SELECT emp_perf, h_json INTO v_employee_perf, v_hierarchy FROM final_result;

    -- Compute best/worst from jsonb
    IF v_employee_perf IS NOT NULL AND jsonb_array_length(v_employee_perf) > 0 THEN
        SELECT value INTO v_best_employee
        FROM jsonb_array_elements(v_employee_perf) elem
        WHERE (elem->>'overall_achievement_score')::numeric IS NOT NULL
        ORDER BY (elem->>'overall_achievement_score')::numeric DESC
        LIMIT 1;

        SELECT value INTO v_weakest_employee
        FROM jsonb_array_elements(v_employee_perf) elem
        WHERE (elem->>'overall_achievement_score')::numeric IS NOT NULL
        ORDER BY (elem->>'overall_achievement_score')::numeric ASC
        LIMIT 1;
    END IF;

    RETURN jsonb_build_object(
        'has_target', true,
        'company', v_company_info,
        'employees', COALESCE(v_employee_perf, '[]'::jsonb),
        'best_employee', v_best_employee,
        'weakest_employee', v_weakest_employee,
        'hierarchy', COALESCE(v_hierarchy, 'null'::jsonb)
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_tiers(p_token uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  IF p_token IS NOT NULL THEN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', t.id,
      'name', t.name,
      'description', t.description,
      'sort_order', t.sort_order,
      'is_active', t.is_active,
      'is_visible', t.is_visible,
      'discount_percent', t.discount_percent,
      'minimum_order_amount', t.minimum_order_amount,
      'icon_url', t.icon_url,
      'color', t.color,
      'starts_at', t.starts_at,
      'ends_at', t.ends_at,
      'created_at', t.created_at,
      'updated_at', t.updated_at,
      'company_exceptions', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', ce.id,
            'company_id', ce.company_id,
            'company_name', c.company_name,
            'discount_percent', ce.discount_percent
          )
        ) FROM tier_company_exceptions ce
        JOIN companies c ON c.id = ce.company_id
        WHERE ce.tier_id = t.id), '[]'::jsonb
      ),
      'product_exceptions', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', pe.id,
            'product_id', pe.product_id,
            'product_name', p.product_name,
            'discount_percent', pe.discount_percent,
            'applies_to_all_tiers', pe.applies_to_all_tiers
          )
        ) FROM tier_product_exceptions pe
        JOIN products p ON p.id = pe.product_id
        WHERE pe.tier_id = t.id OR (pe.tier_id IS NULL AND pe.applies_to_all_tiers = true)), '[]'::jsonb
      )
    ) ORDER BY t.sort_order ASC
  ) INTO v_result FROM tiers t WHERE t.is_active = true;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_visit(p_token uuid, p_id uuid)
 RETURNS visits
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visit public.visits; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_visit FROM public.visits WHERE id = p_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_session.identity_type = 'customer' THEN
    IF v_visit.customer_id != v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    RETURN v_visit;
  END IF;
  IF public.is_upper_management(v_session.employee_id) THEN RETURN v_visit; END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF v_visit.employee_id = ANY(v_visible) THEN RETURN v_visit; END IF;
  RAISE EXCEPTION 'FORBIDDEN';
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_visits(p_token uuid, p_search text DEFAULT NULL::text, p_employee_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Customer: own visits
  IF v_session.identity_type = 'customer' THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', v.id, 'code', v.code, 'employee_id', v.employee_id,
      'customer_id', v.customer_id, 'customer_name', c.company_name,
      'employee_name', e.full_name,
      'status', v.status, 'visit_result', v.visit_result,
      'notes', v.notes, 'check_in_at', v.check_in_at,
      'check_out_at', v.check_out_at,
      'check_in_latitude', v.check_in_latitude, 'check_in_longitude', v.check_in_longitude,
      'check_out_latitude', v.check_out_latitude, 'check_out_longitude', v.check_out_longitude,
      'start_location_id', v.start_location_id, 'created_at', v.created_at
    ) ORDER BY v.created_at DESC) INTO v_result
    FROM public.visits v
    LEFT JOIN customers c ON c.id = v.customer_id
    LEFT JOIN employees e ON e.id = v.employee_id
    WHERE v.customer_id = v_session.customer_id
      AND (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR v.code ILIKE '%' || p_search || '%')
      AND (p_employee_id IS NULL OR v.employee_id = p_employee_id)
      AND (p_date_from IS NULL OR v.check_in_at >= p_date_from)
      AND (p_date_to IS NULL OR v.check_in_at <= p_date_to);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  -- Upper management: all visits
  IF public.is_upper_management(v_session.employee_id) THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', v.id, 'code', v.code, 'employee_id', v.employee_id,
      'customer_id', v.customer_id, 'customer_name', c.company_name,
      'employee_name', e.full_name,
      'status', v.status, 'visit_result', v.visit_result,
      'notes', v.notes, 'check_in_at', v.check_in_at,
      'check_out_at', v.check_out_at,
      'check_in_latitude', v.check_in_latitude, 'check_in_longitude', v.check_in_longitude,
      'check_out_latitude', v.check_out_latitude, 'check_out_longitude', v.check_out_longitude,
      'start_location_id', v.start_location_id, 'created_at', v.created_at
    ) ORDER BY v.created_at DESC) INTO v_result
    FROM public.visits v
    LEFT JOIN customers c ON c.id = v.customer_id
    LEFT JOIN employees e ON e.id = v.employee_id
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR v.code ILIKE '%' || p_search || '%')
      AND (p_employee_id IS NULL OR v.employee_id = p_employee_id)
      AND (p_date_from IS NULL OR v.check_in_at >= p_date_from)
      AND (p_date_to IS NULL OR v.check_in_at <= p_date_to);
    RETURN COALESCE(v_result, '[]'::jsonb);
  END IF;

  -- Others: tree-scoped visits
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  SELECT jsonb_agg(jsonb_build_object(
    'id', v.id, 'code', v.code, 'employee_id', v.employee_id,
    'customer_id', v.customer_id, 'customer_name', c.company_name,
    'employee_name', e.full_name,
    'status', v.status, 'visit_result', v.visit_result,
    'notes', v.notes, 'check_in_at', v.check_in_at,
    'check_out_at', v.check_out_at,
    'check_in_latitude', v.check_in_latitude, 'check_in_longitude', v.check_in_longitude,
    'check_out_latitude', v.check_out_latitude, 'check_out_longitude', v.check_out_longitude,
    'start_location_id', v.start_location_id, 'created_at', v.created_at
  ) ORDER BY v.created_at DESC) INTO v_result
  FROM public.visits v
  LEFT JOIN customers c ON c.id = v.customer_id
  LEFT JOIN employees e ON e.id = v.employee_id
  WHERE v.employee_id = ANY(v_visible)
    AND (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR v.code ILIKE '%' || p_search || '%')
    AND (p_employee_id IS NULL OR v.employee_id = p_employee_id)
    AND (p_date_from IS NULL OR v.check_in_at >= p_date_from)
    AND (p_date_to IS NULL OR v.check_in_at <= p_date_to);

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_governed_waiting_preparations(p_token uuid)
 RETURNS TABLE(id uuid, code text, customer_name text, total numeric, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN; END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    RETURN QUERY
      SELECT o.id, o.order_number::text, cust.company_name::text, o.total_amount, o.created_at
      FROM public.orders o JOIN public.customers cust ON cust.id = o.customer_id
      WHERE o.status = 'approved' AND NOT EXISTS (SELECT 1 FROM public.preparation_records pr WHERE pr.order_id = o.id)
      ORDER BY o.created_at ASC;
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY
    SELECT o.id, o.order_number::text, cust.company_name::text, o.total_amount, o.created_at
    FROM public.orders o JOIN public.customers cust ON cust.id = o.customer_id
    WHERE o.status = 'approved' AND o.owner_id = ANY(v_visible)
      AND NOT EXISTS (SELECT 1 FROM public.preparation_records pr WHERE pr.order_id = o.id)
    ORDER BY o.created_at ASC;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_kpi_contributors(p_token uuid, p_kpi_type text, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_target_month int; v_target_year int;
  v_month_start timestamptz; v_month_end timestamptz;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
  v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
  v_month_start := date_trunc('month', make_date(v_target_year, v_target_month, 1));
  v_month_end := v_month_start + INTERVAL '1 month';
  WITH RECURSIVE ancestor_map AS (
    SELECT id AS descendant_id, id AS ancestor_id FROM public.employees WHERE is_active = true
    UNION ALL
    SELECT am.descendant_id, e.manager_id FROM ancestor_map am
    JOIN public.employees e ON e.id = am.ancestor_id WHERE e.manager_id IS NOT NULL
  ), delivered_orders AS (
    SELECT o.*, COALESCE(emp.id, emp2.id) AS resolved_employee_id
    FROM public.orders o LEFT JOIN public.employees emp ON o.owner_id = emp.id LEFT JOIN public.employees emp2 ON o.owner_id = emp2.identity_id
    WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end
  ), completed_visits AS (
    SELECT * FROM public.visits v WHERE v.status = 'completed' AND v.check_out_at >= v_month_start AND v.check_out_at < v_month_end
  ), emp_orders AS (
    SELECT resolved_employee_id AS employee_id, COUNT(DISTINCT id)::int AS order_count, COALESCE(SUM(total_amount), 0) AS sales_amount
    FROM delivered_orders GROUP BY resolved_employee_id
  ), emp_visits AS (
    SELECT employee_id, COUNT(*)::int AS visit_count FROM completed_visits GROUP BY employee_id
  ), emp_new_customers AS (
    SELECT resolved_employee_id AS employee_id, COUNT(DISTINCT customer_id)::int AS new_customer_count
    FROM delivered_orders do2 WHERE do2.delivered_at = (SELECT MIN(o3.delivered_at) FROM public.orders o3 WHERE o3.customer_id = do2.customer_id AND o3.status = 'delivered')
    GROUP BY resolved_employee_id
  ), approved_returns AS (
    SELECT r.*, o.resolved_employee_id FROM public.returns r JOIN delivered_orders o ON o.id = r.order_id
    WHERE r.status = 'approved' AND r.created_at >= v_month_start AND r.created_at < v_month_end
  ), emp_returns AS (
    SELECT resolved_employee_id AS employee_id, COALESCE(SUM(credit_note_amount), 0) AS return_deduction,
      COUNT(DISTINCT CASE WHEN fr.order_id IS NOT NULL THEN r.order_id END)::int AS full_returns
    FROM approved_returns r LEFT JOIN (
      SELECT r2.order_id FROM public.returns r2 JOIN public.return_items ri ON ri.return_id = r2.id JOIN public.products p ON p.id = ri.product_id
      JOIN (SELECT oi2.order_id, SUM(oi2.piece_quantity) AS total_pieces FROM public.order_items oi2 GROUP BY oi2.order_id) oi3 ON oi3.order_id = r2.order_id
      WHERE r2.status = 'approved' AND r2.created_at >= v_month_start AND r2.created_at < v_month_end
      GROUP BY r2.order_id, oi3.total_pieces
      HAVING SUM(CASE WHEN ri.unit_type = 'piece' THEN ri.quantity WHEN ri.unit_type = 'dozen' THEN ri.quantity * 12 WHEN ri.unit_type = 'carton' THEN ri.quantity * p.carton_quantity END) >= oi3.total_pieces
    ) fr ON fr.order_id = r.order_id
    GROUP BY resolved_employee_id
  ), personal_kpis AS (
    SELECT e.id AS employee_id, e.code, e.full_name, e.manager_id,
      COALESCE(emt.sales_target, 0) AS sales_target, COALESCE(emt.visits_target, 0) AS visits_target,
      COALESCE(emt.orders_target, 0) AS orders_target, COALESCE(emt.new_customers_target, 0) AS new_customers_target,
      GREATEST(COALESCE(eo.sales_amount, 0) - COALESCE(er.return_deduction, 0), 0) AS personal_sales,
      COALESCE(ev.visit_count, 0) AS personal_visits,
      GREATEST(COALESCE(eo.order_count, 0) - COALESCE(er.full_returns, 0), 0) AS personal_orders,
      COALESCE(enc.new_customer_count, 0) AS personal_new_customers,
      CASE
        WHEN EXISTS (SELECT 1 FROM public.employee_roles er2 JOIN public.roles r2 ON r2.id = er2.role_id WHERE er2.employee_id = e.id AND r2.name = 'مدير المبيعات') THEN 'مدير مبيعات'
        WHEN EXISTS (SELECT 1 FROM public.employee_roles er2 JOIN public.roles r2 ON r2.id = er2.role_id WHERE er2.employee_id = e.id AND r2.name = 'مشرف تنفيذي') THEN 'سوبر فايزر'
        ELSE 'مندوب'
      END AS role_type,
      EXISTS (SELECT 1 FROM public.employees sub WHERE sub.manager_id = e.id AND sub.is_active = true) AS has_team
    FROM public.employees e
    LEFT JOIN public.employee_monthly_targets emt ON emt.employee_id = e.id AND emt.target_month = v_target_month AND emt.target_year = v_target_year
    LEFT JOIN emp_orders eo ON eo.employee_id = e.id LEFT JOIN emp_visits ev ON ev.employee_id = e.id
    LEFT JOIN emp_new_customers enc ON enc.employee_id = e.id LEFT JOIN emp_returns er ON er.employee_id = e.id
    WHERE e.is_active = true AND e.code NOT IN ('SYS-OWNER', 'ADMIN-001')
      AND NOT EXISTS (
        SELECT 1 FROM public.employee_roles er2 JOIN public.roles r2 ON r2.id = er2.role_id
        WHERE er2.employee_id = e.id AND r2.name = 'الإدارة العليا')
      AND (emt.id IS NOT NULL OR COALESCE(eo.sales_amount, 0) > 0 OR COALESCE(ev.visit_count, 0) > 0 OR COALESCE(enc.new_customer_count, 0) > 0 OR COALESCE(eo.order_count, 0) > 0)
  ), team_kpis AS (
    SELECT am.ancestor_id, SUM(pk.sales_target) AS team_sales_target, SUM(pk.visits_target) AS team_visits_target,
      SUM(pk.orders_target) AS team_orders_target, SUM(pk.new_customers_target) AS team_new_customers_target,
      SUM(pk.personal_sales) AS team_sales, SUM(pk.personal_visits) AS team_visits,
      SUM(pk.personal_orders) AS team_orders, SUM(pk.personal_new_customers) AS team_new_customers
    FROM ancestor_map am JOIN personal_kpis pk ON pk.employee_id = am.descendant_id GROUP BY am.ancestor_id
  ), final_data AS (
    SELECT pk.employee_id, pk.code, pk.full_name, pk.role_type, pk.has_team,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_sales_target, 0) ELSE pk.sales_target END AS disp_sales_target,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_sales, 0) ELSE pk.personal_sales END AS disp_sales,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_visits_target, 0) ELSE pk.visits_target END AS disp_visits_target,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_visits, 0) ELSE pk.personal_visits END AS disp_visits,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_orders_target, 0) ELSE pk.orders_target END AS disp_orders_target,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_orders, 0) ELSE pk.personal_orders END AS disp_orders,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_new_customers_target, 0) ELSE pk.new_customers_target END AS disp_nc_target,
      CASE WHEN pk.has_team THEN COALESCE(tk.team_new_customers, 0) ELSE pk.personal_new_customers END AS disp_nc
    FROM personal_kpis pk LEFT JOIN team_kpis tk ON tk.ancestor_id = pk.employee_id
  )
  SELECT jsonb_agg(jsonb_build_object(
    'employee_id', fd.employee_id, 'employee_code', fd.code, 'employee_name', fd.full_name,
    'role_type', fd.role_type, 'has_team', fd.has_team,
    'actual', CASE p_kpi_type WHEN 'sales' THEN fd.disp_sales WHEN 'orders' THEN fd.disp_orders WHEN 'visits' THEN fd.disp_visits WHEN 'new_customers' THEN fd.disp_nc ELSE 0 END,
    'target', CASE p_kpi_type WHEN 'sales' THEN fd.disp_sales_target WHEN 'orders' THEN fd.disp_orders_target WHEN 'visits' THEN fd.disp_visits_target WHEN 'new_customers' THEN fd.disp_nc_target ELSE 0 END,
    'achievement_pct', ROUND(CASE WHEN CASE p_kpi_type WHEN 'sales' THEN fd.disp_sales_target WHEN 'orders' THEN fd.disp_orders_target WHEN 'visits' THEN fd.disp_visits_target WHEN 'new_customers' THEN fd.disp_nc_target ELSE 0 END > 0
      THEN (CASE p_kpi_type WHEN 'sales' THEN fd.disp_sales WHEN 'orders' THEN fd.disp_orders WHEN 'visits' THEN fd.disp_visits WHEN 'new_customers' THEN fd.disp_nc ELSE 0 END::numeric / CASE p_kpi_type WHEN 'sales' THEN fd.disp_sales_target WHEN 'orders' THEN fd.disp_orders_target WHEN 'visits' THEN fd.disp_visits_target WHEN 'new_customers' THEN fd.disp_nc_target ELSE 1 END::numeric * 100) ELSE 0 END, 2)
  ) ORDER BY fd.role_type, fd.full_name) INTO v_result
  FROM final_data fd;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_live_activity_center(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_subtree_ids uuid[];
    v_kpis jsonb;
    v_activity jsonb;
    v_anomalies jsonb;
    v_overview jsonb;
    v_today_orders jsonb;
    v_today_visits jsonb;
    v_today_customers jsonb;
    v_today_collections jsonb;
    v_now_panel jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_employee_id);
    END IF;

    -- 1 - Reuse existing employee overview
    v_overview := public.get_live_workday_overview(p_token);

    -- 2 - Executive KPIs (daily totals + hourly pulse)
    SELECT jsonb_build_object(
        'today_orders', COALESCE((SELECT COUNT(*)::int FROM public.orders o
            WHERE o.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))), 0),
        'today_sales', COALESCE((SELECT SUM(o.total_amount)::numeric FROM public.orders o
            WHERE o.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))), 0),
        'today_collections', COALESCE((SELECT COUNT(*)::int FROM public.collections cl
            WHERE cl.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR cl.created_by = ANY(v_subtree_ids))), 0),
        'today_collections_amount', COALESCE((SELECT SUM(cl.amount)::numeric FROM public.collections cl
            WHERE cl.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR cl.created_by = ANY(v_subtree_ids))), 0),
        'today_visits', COALESCE((SELECT COUNT(*)::int FROM public.visits v
            WHERE v.check_in_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR v.employee_id = ANY(v_subtree_ids))), 0),
        'today_new_customers', COALESCE((SELECT COUNT(*)::int FROM public.customers cu
            WHERE cu.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(cu.owner_id) = ANY(v_subtree_ids))), 0),
        'active_employees', COALESCE((SELECT COUNT(*)::int FROM public.workday_sessions wds
            WHERE wds.date = CURRENT_DATE AND wds.status = 'active'), 0),
        'active_visits', COALESCE((SELECT COUNT(*)::int FROM public.visits v
            WHERE v.check_in_at::date = CURRENT_DATE AND v.check_out_at IS NULL), 0),
        'served_customers', COALESCE((SELECT COUNT(DISTINCT o.customer_id)::int FROM public.orders o
            WHERE o.created_at::date = CURRENT_DATE
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))), 0),
        'hourly_orders', COALESCE((SELECT COUNT(*)::int FROM public.orders o
            WHERE o.created_at > now() - interval '1 hour'
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))), 0),
        'hourly_sales', COALESCE((SELECT SUM(o.total_amount)::numeric FROM public.orders o
            WHERE o.created_at > now() - interval '1 hour'
            AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))), 0)
    ) INTO v_kpis;

    -- 3 - Activity feed (last 24h, up to 50 events)
    WITH activity_union AS (
        SELECT aal.created_at AS event_time,
            aal.event_type,
            e.full_name AS actor_name,
            e.id AS actor_id,
            CASE aal.event_type
                WHEN 'workday_start' THEN '??? ??? ?????'
                WHEN 'manual_close' THEN '????? ??? ?????'
                WHEN 'auto_closed' THEN '????? ??????'
                WHEN 'day_rollover' THEN '????? ????? ?????'
                WHEN 'admin_closed' THEN '????? ?????? ???????'
                WHEN 'warning_sent' THEN '????? ?????'
                WHEN 'warning_cleared' THEN '????? ???????'
                ELSE aal.event_type
            END AS summary,
            'attendance' AS ref_type,
            aal.session_id::text AS ref_id
        FROM public.attendance_audit_log aal
        JOIN public.employees e ON e.id = aal.employee_id
        WHERE (v_subtree_ids IS NULL OR aal.employee_id = ANY(v_subtree_ids))
        AND aal.created_at > now() - interval '24 hours'

        UNION ALL

        SELECT o.created_at,
            'order_created',
            COALESCE(e.full_name, '??????'),
            COALESCE(public.resolve_employee_id(o.owner_id), o.created_by),
            '??? ???? - ' || COALESCE(o.order_number, '#' || o.id::text) || ' (' || o.total_amount::text || ' ?.?)',
            'order',
            o.id::text
        FROM public.orders o
        LEFT JOIN public.employees e ON e.id = public.resolve_employee_id(o.owner_id)
        WHERE (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids))
        AND o.created_at > now() - interval '24 hours'

        UNION ALL

        SELECT v.check_in_at,
            CASE WHEN v.check_out_at IS NULL THEN 'visit_started' ELSE 'visit_completed' END,
            e.full_name,
            v.employee_id,
            COALESCE(c.company_name, '????') || CASE WHEN v.check_out_at IS NULL THEN ' ??? ???????' ELSE ' ??? ???????' END,
            'visit',
            v.id::text
        FROM public.visits v
        JOIN public.employees e ON e.id = v.employee_id
        LEFT JOIN public.customers c ON c.id = v.customer_id
        WHERE (v_subtree_ids IS NULL OR v.employee_id = ANY(v_subtree_ids))
        AND v.check_in_at > now() - interval '24 hours'

        UNION ALL

        SELECT cl.created_at,
            'collection_made',
            e.full_name,
            cl.created_by,
            '????? ' || cl.amount::text || ' ?.?',
            'collection',
            cl.id::text
        FROM public.collections cl
        JOIN public.employees e ON e.id = cl.created_by
        WHERE (v_subtree_ids IS NULL OR cl.created_by = ANY(v_subtree_ids))
        AND cl.created_at > now() - interval '24 hours'

        UNION ALL

        SELECT cu.created_at,
            'customer_registered',
            COALESCE(e.full_name, '??????'),
            COALESCE(public.resolve_employee_id(cu.owner_id), cu.owner_id),
            cu.company_name || ' (???? ????)',
            'customer',
            cu.id::text
        FROM public.customers cu
        LEFT JOIN public.employees e ON e.id = public.resolve_employee_id(cu.owner_id)
        WHERE (v_subtree_ids IS NULL OR public.resolve_employee_id(cu.owner_id) = ANY(v_subtree_ids))
        AND cu.created_at > now() - interval '24 hours'
    )
    SELECT jsonb_agg(jsonb_build_object(
        'time', au.event_time,
        'type', au.event_type,
        'actor', au.actor_name,
        'actor_id', au.actor_id,
        'summary', au.summary,
        'ref_type', au.ref_type,
        'ref_id', au.ref_id
    ) ORDER BY au.event_time DESC)
    INTO v_activity FROM activity_union au;

    IF v_activity IS NULL THEN v_activity := '[]'::jsonb; END IF;

    -- 4 - Anomaly detection
    WITH active_sessions AS (
        SELECT wds.id, wds.employee_id, e.full_name, wds.last_seen_at, wds.start_time, wds.visit_count
        FROM public.workday_sessions wds
        JOIN public.employees e ON e.id = wds.employee_id
        WHERE wds.date = CURRENT_DATE AND wds.status = 'active'
    )
    SELECT jsonb_agg(sub.anomaly) INTO v_anomalies FROM (
        SELECT jsonb_build_object(
            'type', 'stale_session', 'severity', 'high',
            'employee_id', a.employee_id, 'employee_name', a.full_name,
            'detail', '???? ????? - ??? ???? ??? ' || EXTRACT(EPOCH FROM (now() - COALESCE(a.last_seen_at, a.start_time)))::int / 60 || ' ?????'
        ) AS anomaly
        FROM active_sessions a
        WHERE COALESCE(a.last_seen_at, a.start_time) < now() - interval '30 minutes'

        UNION ALL

        SELECT jsonb_build_object(
            'type', 'no_gps', 'severity', 'medium',
            'employee_id', a.employee_id, 'employee_name', a.full_name,
            'detail', '?? ???? ???? GPS ?????'
        )
        FROM active_sessions a
        WHERE NOT EXISTS (
            SELECT 1 FROM public.tracking_points tp
            WHERE tp.employee_id = a.employee_id
            AND tp.recorded_at > now() - interval '5 minutes'
        )

        UNION ALL

        SELECT jsonb_build_object(
            'type', 'no_heartbeat', 'severity', 'medium',
            'employee_id', a.employee_id, 'employee_name', a.full_name,
            'detail', '??? Heartbeat ??? ' || EXTRACT(EPOCH FROM (now() - COALESCE(a.last_seen_at, a.start_time)))::int / 60 || ' ?????'
        )
        FROM active_sessions a
        WHERE COALESCE(a.last_seen_at, a.start_time) < now() - interval '10 minutes'

        UNION ALL

        SELECT jsonb_build_object(
            'type', 'no_visits', 'severity', 'low',
            'employee_id', a.employee_id, 'employee_name', a.full_name,
            'detail', '???? ?????? ??? ' || EXTRACT(EPOCH FROM (now() - a.start_time))::int / 60 || ' ?????'
        )
        FROM active_sessions a
        WHERE a.start_time < now() - interval '2 hours'
        AND NOT EXISTS (
            SELECT 1 FROM public.visits v
            WHERE v.employee_id = a.employee_id AND v.check_in_at::date = CURRENT_DATE
        )

        UNION ALL

        SELECT jsonb_build_object(
            'type', 'no_orders', 'severity', 'low',
            'employee_id', a.employee_id, 'employee_name', a.full_name,
            'detail', '???? ????? ??? ' || EXTRACT(EPOCH FROM (now() - a.start_time))::int / 60 || ' ?????'
        )
        FROM active_sessions a
        WHERE a.start_time < now() - interval '4 hours'
        AND NOT EXISTS (
            SELECT 1 FROM public.orders o
            WHERE public.resolve_employee_id(o.owner_id) = a.employee_id
            AND o.created_at::date = CURRENT_DATE
        )
    ) sub;

    IF v_anomalies IS NULL THEN v_anomalies := '[]'::jsonb; END IF;

    -- 5 - Today orders (drill-down)
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'customer_name', c.company_name,
        'employee_name', COALESCE(e.full_name, '-'),
        'total_amount', o.total_amount,
        'status', o.status,
        'created_at', o.created_at
    ) ORDER BY o.created_at DESC)
    INTO v_today_orders
    FROM public.orders o
    LEFT JOIN public.customers c ON c.id = o.customer_id
    LEFT JOIN public.employees e ON e.id = public.resolve_employee_id(o.owner_id)
    WHERE o.created_at::date = CURRENT_DATE
    AND (v_subtree_ids IS NULL OR public.resolve_employee_id(o.owner_id) = ANY(v_subtree_ids));

    IF v_today_orders IS NULL THEN v_today_orders := '[]'::jsonb; END IF;

    -- 6 - Today visits (drill-down)
    SELECT jsonb_agg(jsonb_build_object(
        'id', v.id,
        'customer_name', c.company_name,
        'employee_name', e.full_name,
        'check_in_at', v.check_in_at,
        'check_out_at', v.check_out_at,
        'status', CASE WHEN v.check_out_at IS NULL THEN 'active' ELSE 'completed' END
    ) ORDER BY v.check_in_at DESC)
    INTO v_today_visits
    FROM public.visits v
    JOIN public.customers c ON c.id = v.customer_id
    JOIN public.employees e ON e.id = v.employee_id
    WHERE v.check_in_at::date = CURRENT_DATE
    AND (v_subtree_ids IS NULL OR v.employee_id = ANY(v_subtree_ids));

    IF v_today_visits IS NULL THEN v_today_visits := '[]'::jsonb; END IF;

    -- 7 - Today new customers (drill-down)
    SELECT jsonb_agg(jsonb_build_object(
        'id', cu.id,
        'code', cu.code,
        'company_name', cu.company_name,
        'employee_name', COALESCE(e.full_name, '-'),
        'registered_at', cu.registered_at,
        'created_at', cu.created_at
    ) ORDER BY cu.created_at DESC)
    INTO v_today_customers
    FROM public.customers cu
    LEFT JOIN public.employees e ON e.id = public.resolve_employee_id(cu.owner_id)
    WHERE cu.created_at::date = CURRENT_DATE
    AND (v_subtree_ids IS NULL OR public.resolve_employee_id(cu.owner_id) = ANY(v_subtree_ids));

    IF v_today_customers IS NULL THEN v_today_customers := '[]'::jsonb; END IF;

    -- 8 - Today collections (drill-down)
    SELECT jsonb_agg(jsonb_build_object(
        'id', cl.id,
        'amount', cl.amount,
        'employee_name', e.full_name,
        'created_at', cl.created_at
    ) ORDER BY cl.created_at DESC)
    INTO v_today_collections
    FROM public.collections cl
    JOIN public.employees e ON e.id = cl.created_by
    WHERE cl.created_at::date = CURRENT_DATE
    AND (v_subtree_ids IS NULL OR cl.created_by = ANY(v_subtree_ids));

    IF v_today_collections IS NULL THEN v_today_collections := '[]'::jsonb; END IF;

    -- 9 - Now Panel (???? ????)
    SELECT jsonb_build_object(
        'employees_in_visit', COALESCE((SELECT COUNT(*)::int FROM public.visits v2
            WHERE v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL), 0),
        'employees_working', COALESCE((SELECT COUNT(*)::int FROM public.workday_sessions wds2
            WHERE wds2.date = CURRENT_DATE AND wds2.status = 'active'
            AND NOT EXISTS (SELECT 1 FROM public.visits v3 WHERE v3.employee_id = wds2.employee_id AND v3.check_out_at IS NULL)), 0),
        'employees_on_break', COALESCE((SELECT COUNT(*)::int FROM public.workday_sessions wds3
            WHERE wds3.date = CURRENT_DATE AND wds3.status = 'on_break'), 0),
        'orders_in_progress', COALESCE((SELECT COUNT(*)::int FROM public.orders o2
            WHERE o2.created_at::date = CURRENT_DATE AND o2.status IN ('pending','approved')), 0),
        'collection_in_progress', COALESCE((SELECT COUNT(*)::int FROM public.collections cl2
            WHERE cl2.created_at::date = CURRENT_DATE), 0)
    ) INTO v_now_panel;

    RETURN v_overview || jsonb_build_object(
        'kpis', v_kpis,
        'activity', v_activity,
        'anomalies', v_anomalies,
        'today_orders', v_today_orders,
        'today_visits', v_today_visits,
        'today_customers', v_today_customers,
        'today_collections', v_today_collections,
        'now_panel', v_now_panel
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_live_workday_overview(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_interval_seconds int;
    v_subtree_ids uuid[];
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;

    SELECT location_interval_seconds INTO v_interval_seconds FROM public.workday_settings LIMIT 1;
    v_interval_seconds := COALESCE(v_interval_seconds, 300);

    WITH active_sessions AS (
        SELECT wds.id, wds.employee_id, wds.start_time, wds.status,
            wds.last_seen_at, e.full_name AS employee_name
        FROM public.workday_sessions wds
        JOIN public.employees e ON e.id = wds.employee_id
            AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
            AND NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id AND ewp.attendance_enabled = false)
        WHERE wds.date = CURRENT_DATE AND wds.status = 'active'
    ),
    session_activity AS (
        SELECT ws.employee_id, ws.last_seen_at AS activity_at,
            'heartbeat'::text AS activity_type
        FROM active_sessions ws
        WHERE ws.last_seen_at IS NOT NULL
    ),
    tracking_activity AS (
        SELECT DISTINCT ON (tp.employee_id)
            tp.employee_id, tp.recorded_at AS activity_at,
            'gps'::text AS activity_type
        FROM public.tracking_points tp
        WHERE tp.recorded_at >= CURRENT_DATE
        ORDER BY tp.employee_id, tp.recorded_at DESC
    ),
    visit_activity AS (
        SELECT v.employee_id, MAX(v.check_in_at) AS activity_at,
            'visit'::text AS activity_type
        FROM public.visits v WHERE v.check_in_at::date = CURRENT_DATE
        GROUP BY v.employee_id
    ),
    order_activity AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            MAX(o.created_at) AS activity_at,
            'order'::text AS activity_type
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    collection_activity AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            MAX(c.created_at) AS activity_at,
            'collection'::text AS activity_type
        FROM public.collections c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    combined_activity AS (
        SELECT employee_id, activity_at, activity_type FROM session_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM tracking_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM visit_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM order_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM collection_activity
    ),
    last_activity AS (
        SELECT DISTINCT ON (employee_id)
            employee_id, activity_at AS last_activity_at,
            activity_type AS last_activity_type
        FROM combined_activity
        ORDER BY employee_id, activity_at DESC NULLS LAST
    ),
    last_location AS (
        SELECT DISTINCT ON (tp.employee_id)
            tp.employee_id, tp.latitude, tp.longitude,
            tp.recorded_at AS last_location_at, tp.accuracy_meters
        FROM public.tracking_points tp
        WHERE tp.recorded_at >= CURRENT_DATE
          AND tp.latitude IS NOT NULL AND tp.longitude IS NOT NULL
        ORDER BY tp.employee_id, tp.recorded_at DESC
    ),
    active_breaks AS (
        SELECT wb.session_id, wb.employee_id
        FROM public.workday_breaks wb WHERE wb.break_end IS NULL
    ),
    today_orders AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            COUNT(*)::int AS order_count,
            COALESCE(SUM(o.total_amount), 0) AS sales_value
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    today_collections AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS collection_count,
            COALESCE(SUM(c.amount), 0) AS collection_amount
        FROM public.collections c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    today_customers AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS new_customer_count
        FROM public.customers c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    today_visits AS (
        SELECT v.employee_id, COUNT(*)::int AS visit_count
        FROM public.visits v WHERE v.check_in_at::date = CURRENT_DATE GROUP BY v.employee_id
    ),
    employee_summary AS (
        SELECT
            as2.id AS session_id,
            as2.employee_id,
            as2.employee_name,
            as2.start_time,
            EXTRACT(EPOCH FROM (now() - as2.start_time)) / 60 AS duration_minutes,
            CASE WHEN ab.employee_id IS NOT NULL THEN 'on_break'
                 WHEN vl.employee_id IS NOT NULL THEN 'on_visit'
                 ELSE 'working'
            END AS work_status,
            ll.latitude, ll.longitude, ll.last_location_at,
            la.last_activity_at,
            la.last_activity_type,
            CASE
                WHEN la.last_activity_at IS NOT NULL AND ll.last_location_at IS NOT NULL
                    THEN GREATEST(la.last_activity_at, ll.last_location_at)
                WHEN la.last_activity_at IS NOT NULL THEN la.last_activity_at
                WHEN ll.last_location_at IS NOT NULL THEN ll.last_location_at
                ELSE NULL
            END AS last_seen_at,
            CASE
                WHEN la.last_activity_at IS NULL THEN 'no_data'
                WHEN la.last_activity_at > now() - (v_interval_seconds || ' seconds')::interval THEN 'connected'
                WHEN la.last_activity_at > now() - ((v_interval_seconds * 5) || ' seconds')::interval THEN 'delayed'
                ELSE 'lost'
            END AS connection_status,
            as2.status AS session_status,
            COALESCE(to2.order_count, 0) AS order_count,
            COALESCE(to2.sales_value, 0) AS sales_value,
            COALESCE(tc.collection_count, 0) AS collection_count,
            COALESCE(tc.collection_amount, 0) AS collection_amount,
            COALESCE(tcu.new_customer_count, 0) AS new_customer_count,
            COALESCE(tv.visit_count, 0) AS visit_count
        FROM active_sessions as2
        LEFT JOIN active_breaks ab ON ab.session_id = as2.id
        LEFT JOIN LATERAL (
            SELECT v2.id, v2.employee_id FROM public.visits v2
            WHERE v2.employee_id = as2.employee_id AND v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL
            LIMIT 1
        ) vl ON true
        LEFT JOIN last_activity la ON la.employee_id = as2.employee_id
        LEFT JOIN last_location ll ON ll.employee_id = as2.employee_id
        LEFT JOIN today_orders to2 ON to2.employee_id = as2.employee_id
        LEFT JOIN today_collections tc ON tc.employee_id = as2.employee_id
        LEFT JOIN today_customers tcu ON tcu.employee_id = as2.employee_id
        LEFT JOIN today_visits tv ON tv.employee_id = as2.employee_id
    ),
    no_start AS (
        SELECT e.id AS employee_id, e.full_name AS employee_name
        FROM public.employees e
        WHERE (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        AND e.id NOT IN (SELECT employee_id FROM active_sessions)
        AND e.id NOT IN (
            SELECT employee_id FROM public.workday_sessions
            WHERE date = CURRENT_DATE AND status = 'completed'
        )
        AND e.is_active = true
        AND NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id AND ewp.attendance_enabled = false)
    ),
    ended AS (
        SELECT wds.employee_id, e.full_name AS employee_name, wds.end_time,
            EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) / 60 AS duration_minutes,
            wds.visit_count,
            COALESCE(to2.order_count, 0) AS order_count,
            COALESCE(to2.sales_value, 0) AS sales_value,
            COALESCE(tc.collection_count, 0) AS collection_count,
            COALESCE(tc.collection_amount, 0) AS collection_amount,
            COALESCE(tcu.new_customer_count, 0) AS new_customer_count
        FROM public.workday_sessions wds
        JOIN public.employees e ON e.id = wds.employee_id
            AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        LEFT JOIN today_orders to2 ON to2.employee_id = wds.employee_id
        LEFT JOIN today_collections tc ON tc.employee_id = wds.employee_id
        LEFT JOIN today_customers tcu ON tcu.employee_id = wds.employee_id
        WHERE wds.date = CURRENT_DATE AND wds.status = 'completed'
    )
    SELECT jsonb_build_object(
        'active_count', (SELECT COUNT(*) FROM employee_summary),
        'on_visit_count', (SELECT COUNT(*) FROM employee_summary WHERE work_status = 'on_visit'),
        'on_break_count', (SELECT COUNT(*) FROM employee_summary WHERE work_status = 'on_break'),
        'connection_loss_count', (SELECT COUNT(*) FROM employee_summary WHERE connection_status = 'lost'),
        'no_start_count', (SELECT COUNT(*) FROM no_start),
        'ended_count', (SELECT COUNT(*) FROM ended),
        'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', es.employee_id,
            'name', es.employee_name,
            'status', es.work_status,
            'session_status', es.session_status,
            'started_at', es.start_time,
            'duration_minutes', es.duration_minutes::int,
            'latitude', es.latitude,
            'longitude', es.longitude,
            'last_seen_at', es.last_seen_at,
            'connection_status', es.connection_status,
            'last_activity_at', es.last_activity_at,
            'last_activity_type', es.last_activity_type,
            'last_location_at', es.last_location_at,
            'last_seen_label',
                CASE es.connection_status
                    WHEN 'connected' THEN 'متصل الآن'
                    WHEN 'delayed' THEN
                        'آخر نشاط منذ ' || EXTRACT(EPOCH FROM (now() - es.last_seen_at))::int / 60 || ' دقيقة'
                    WHEN 'lost' THEN 'مفقود الاتصال'
                    ELSE 'لا توجد بيانات كافية'
                END,
            'order_count', es.order_count,
            'sales_value', es.sales_value,
            'collection_count', es.collection_count,
            'collection_amount', es.collection_amount,
            'new_customer_count', es.new_customer_count,
            'visit_count', es.visit_count
        ) ORDER BY
            CASE es.work_status
                WHEN 'working' THEN 1
                WHEN 'on_visit' THEN 2
                WHEN 'on_break' THEN 3
                ELSE 4
            END
        ) FROM employee_summary es), '[]'::jsonb),
        'no_start_employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', ns.employee_id,
            'name', ns.employee_name
        )) FROM no_start ns), '[]'::jsonb),
        'ended_employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', ed.employee_id,
            'name', ed.employee_name,
            'ended_at', ed.end_time,
            'duration_minutes', ed.duration_minutes::int,
            'visit_count', ed.visit_count,
            'order_count', ed.order_count,
            'sales_value', ed.sales_value,
            'collection_count', ed.collection_count,
            'collection_amount', ed.collection_amount,
            'new_customer_count', ed.new_customer_count
        ) ORDER BY ed.end_time DESC) FROM ended ed), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_module_detail(p_token uuid, p_module_key character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_module jsonb; v_decisions jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only');
  END IF;
  SELECT row_to_json(m)::jsonb FROM (
    SELECT id, module_key, display_name, description, icon, status, implementation_level, validated_at, broken_since, deprecated_at, owner_approved, routes, core_rpcs, core_tables, services, page_dirs, pipeline_steps, pipeline_health_pct, last_health_check, health_status, readiness_score, business_priority, kb_file, decisions_total, decisions_verified, decisions_pct, depends_on, created_at, updated_at
    FROM public.system_modules WHERE module_key = p_module_key
  ) m INTO v_module;
  IF v_module IS NULL THEN RETURN jsonb_build_object('error', 'MODULE_NOT_FOUND', 'module_key', p_module_key); END IF;
  SELECT COALESCE(jsonb_agg(d ORDER BY d.created_at), '[]'::jsonb) FROM (
    SELECT id, decision_text, rationale, category, source_file, source_line, verifiable, verification_method, verified, verified_at, failure_reason, decided_at, tags, created_at
    FROM public.owner_decisions WHERE module_key = p_module_key
  ) d INTO v_decisions;
  RETURN jsonb_build_object('module', v_module, 'decisions', v_decisions);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_my_notifications(p_token uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_employee_id := v_session.employee_id;
  IF v_employee_id IS NULL THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  RETURN (
    SELECT jsonb_build_object(
      'notifications', COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', n.id,
            'type', n.type,
            'title', n.title,
            'message', n.message,
            'entity_type', n.entity_type,
            'entity_id', n.entity_id,
            'target_path', n.target_path,
            'is_read', n.is_read,
            'created_at', n.created_at
          ) ORDER BY n.created_at DESC
        ),
        '[]'::jsonb
      ),
      'total', (SELECT count(*) FROM public.notifications WHERE recipient_employee_id = v_employee_id)
    )
    FROM (
      SELECT * FROM public.notifications
      WHERE recipient_employee_id = v_employee_id
      ORDER BY created_at DESC
      LIMIT p_limit OFFSET p_offset
    ) n
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_my_unread_count(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
  v_count integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_employee_id := v_session.employee_id;
  IF v_employee_id IS NULL THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT count(*) INTO v_count
  FROM public.notifications
