  RETURN jsonb_build_object('count', v_count);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_my_work_policy(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_policy record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF v_session.identity_type != 'employee' THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    v_employee_id := v_session.employee_id;

    SELECT * INTO v_policy FROM public.employee_work_policies
    WHERE employee_id = v_employee_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('employee_id', v_employee_id, 'has_policy', false);
    END IF;

    RETURN jsonb_build_object(
        'id', v_policy.id,
        'work_location', v_policy.work_location,
        'schedule_type', v_policy.schedule_type,
        'tracking_required', v_policy.tracking_required,
        'required_daily_hours', v_policy.required_daily_hours,
        'shift_start_time', v_policy.shift_start_time,
        'shift_end_time', v_policy.shift_end_time,
        'has_policy', true
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_workday_status(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_employee record;
    v_policy record;
    v_session_data record;
    v_break_count int := 0;
    v_break_total_seconds int := 0;
    v_visit_count int := 0;
    v_on_break boolean := false;
    v_open_break_id uuid := NULL;
    v_today_orders int := 0;
    v_today_sales numeric := 0;
    v_today_collections int := 0;
    v_today_collection_amount numeric := 0;
    v_today_new_customers int := 0;
    v_target_data jsonb := NULL;
    v_duration_minutes numeric := 0;
    v_net_work_minutes numeric := 0;
    v_ended_at timestamptz := NULL;
    v_started_at timestamptz := NULL;
    v_session_status text := NULL;
    v_session_id uuid := NULL;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    SELECT id, full_name, code INTO v_employee FROM public.employees WHERE id = v_employee_id;
    SELECT ep.* INTO v_policy FROM public.employee_work_policies ep WHERE ep.employee_id = v_employee_id;

    SELECT * INTO v_session_data FROM public.workday_sessions
    WHERE employee_id = v_employee_id AND date = CURRENT_DATE
    ORDER BY CASE WHEN status = 'active' THEN 0 ELSE 1 END, start_time DESC
    LIMIT 1;

    IF FOUND THEN
        v_session_id := v_session_data.id;
        v_session_status := v_session_data.status;
        v_started_at := v_session_data.start_time;
        v_ended_at := v_session_data.end_time;

        IF v_session_data.status = 'active' THEN
            v_duration_minutes := EXTRACT(EPOCH FROM (now() - v_session_data.start_time)) / 60;
            SELECT COUNT(*), COALESCE(SUM(duration_seconds), 0) INTO v_break_count, v_break_total_seconds
            FROM public.workday_breaks WHERE session_id = v_session_data.id;
            SELECT COUNT(*) INTO v_visit_count FROM public.visits
            WHERE employee_id = v_employee_id AND check_in_at::date = CURRENT_DATE;
            SELECT EXISTS(SELECT 1 FROM public.workday_breaks
                          WHERE session_id = v_session_data.id AND break_end IS NULL) INTO v_on_break;
            SELECT id INTO v_open_break_id FROM public.workday_breaks
            WHERE session_id = v_session_data.id AND break_end IS NULL LIMIT 1;
        ELSE
            v_duration_minutes := EXTRACT(EPOCH FROM (v_session_data.end_time - v_session_data.start_time)) / 60;
            SELECT COUNT(*), COALESCE(SUM(duration_seconds), 0) INTO v_break_count, v_break_total_seconds
            FROM public.workday_breaks WHERE session_id = v_session_data.id;
        END IF;

        v_net_work_minutes := v_duration_minutes - (v_break_total_seconds / 60);
    END IF;

    SELECT COUNT(*)::int, COALESCE(SUM(total_amount), 0) INTO v_today_orders, v_today_sales
    FROM public.orders WHERE public.resolve_employee_id(owner_id) = v_employee_id AND created_at::date = CURRENT_DATE;
    SELECT COUNT(*)::int, COALESCE(SUM(amount), 0) INTO v_today_collections, v_today_collection_amount
    FROM public.collections WHERE public.resolve_employee_id(owner_id) = v_employee_id AND created_at::date = CURRENT_DATE;
    SELECT COUNT(*)::int INTO v_today_new_customers
    FROM public.customers WHERE public.resolve_employee_id(owner_id) = v_employee_id AND created_at::date = CURRENT_DATE;

    BEGIN
        v_target_data := public.get_daily_target_vs_actual(p_token, v_employee_id, CURRENT_DATE);
    EXCEPTION WHEN OTHERS THEN
        v_target_data := NULL;
    END;

    RETURN jsonb_build_object(
        'status', v_session_status,
        'employee_name', v_employee.full_name,
        'employee_code', v_employee.code,
        'session_id', v_session_id,
        'started_at', v_started_at,
        'ended_at', v_ended_at,
        'duration_minutes', v_duration_minutes,
        'break_count', v_break_count,
        'break_minutes', v_break_total_seconds / 60,
        'visit_count', v_visit_count,
        'net_work_minutes', v_net_work_minutes,
        'on_break', CASE WHEN v_session_status = 'active' THEN v_on_break ELSE false END,
        'open_break_id', CASE WHEN v_session_status = 'active' THEN v_open_break_id ELSE NULL::uuid END,
        'work_location', v_policy.work_location,
        'schedule_type', v_policy.schedule_type,
        'required_daily_hours', v_policy.required_daily_hours,
        'attendance_enabled', v_policy.attendance_enabled,
        'today_orders', v_today_orders,
        'today_sales', v_today_sales,
        'today_collections', v_today_collections,
        'today_new_customers', v_today_new_customers,
        'daily_target_vs_actual', v_target_data
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_order_report(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  WITH t AS (
    SELECT o.status, COUNT(o.id) as count, COALESCE(SUM(o.total_amount), 0) as total_amount
    FROM orders o
    WHERE (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
    GROUP BY o.status
  )
  SELECT jsonb_agg(
    jsonb_build_object('status', status, 'count', count, 'total_amount', total_amount)
    ORDER BY status
  ) INTO v_result FROM t;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_order_status_counts(p_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

    DECLARE
      v_session app.sessions;
      statuses text[] := ARRAY['draft','submitted','reviewing','returned_for_revision','approved','preparing','prepared','ready_for_dispatch','sent_to_delivery','dispatched','deferred','cancelled','delivered'];
      result json;
    BEGIN
      SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
      IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

      WITH counts AS (
        SELECT status::text, COUNT(*)::int AS count
        FROM orders
        GROUP BY status::text
      ),
      all_statuses AS (
        SELECT unnest(statuses) AS status
      )
      SELECT json_agg(json_build_object('status', a.status, 'count', COALESCE(c.count, 0))
        ORDER BY array_position(statuses, a.status))
      INTO result
      FROM all_statuses a
      LEFT JOIN counts c ON c.status = a.status;

      RETURN COALESCE(result, '[]'::json);
    END;
    
$function$;

CREATE OR REPLACE FUNCTION public.get_order_timeline(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', osh.id,
      'from_status', osh.from_status,
      'to_status', osh.to_status,
      'changed_by_name', e.full_name,
      'reason', osh.reason,
      'changed_at', osh.changed_at
    ) ORDER BY osh.changed_at ASC
  ) INTO v_result
  FROM order_status_history osh
  LEFT JOIN employees e ON e.id = osh.changed_by
  WHERE osh.order_id = p_order_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_public_company_profile()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 DECLARE v_row public.company_profile; BEGIN SELECT * INTO v_row FROM public.company_profile WHERE id = 1; IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'NOT_FOUND'); END IF; RETURN json_build_object('success', true, 'data', json_build_object('company_name', v_row.company_name, 'company_banner_url', v_row.company_banner_url, 'facebook_url', v_row.facebook_url, 'sales_phone_1', v_row.sales_phone_1, 'sales_phone_2', v_row.sales_phone_2, 'sales_whatsapp_1', v_row.sales_whatsapp_1, 'sales_whatsapp_2', v_row.sales_whatsapp_2, 'technical_support_phone', v_row.technical_support_phone, 'is_active', v_row.is_active, 'updated_at', v_row.updated_at)); END; 
$function$;

CREATE OR REPLACE FUNCTION public.get_recently_available_products(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_token uuid;
  v_days int;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_SESSION');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT COALESCE((value #>> '{}')::int, 7) INTO v_days
  FROM app.app_settings
  WHERE key = 'recently_available_days';

  IF v_days IS NULL OR v_days < 1 THEN v_days := 7; END IF;

  SELECT jsonb_agg(sub.data)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id', p.id,
      'product_name', p.product_name,
      'legacy_code', p.legacy_code,
      'description', p.description,
      'company_id', p.company_id,
      'company_name', comp.company_name,
      'is_active', p.is_active,
      'is_visible', p.is_visible,
      'is_out_of_stock', p.is_out_of_stock,
      'image_url', p.image_url,
      'carton_price', p.carton_price,
      'carton_quantity', p.carton_quantity,
      'piece_price', p.piece_price,
      'dozen_price', p.dozen_price,
      'created_at', p.created_at,
      'recently_available_at', p.recently_available_at,
      'product_units', COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object('id', pu.id, 'unit_type', pu.unit_type, 'is_active', pu.is_active)
          ORDER BY pu.unit_type
        ) FROM product_units pu WHERE pu.product_id = p.id),
        '[]'::jsonb
      ),
      'inventory', (SELECT jsonb_build_object('quantity', inv.quantity) FROM inventory inv WHERE inv.product_id = p.id LIMIT 1)
    ) AS data
    FROM products p
    JOIN companies comp ON comp.id = p.company_id
    WHERE p.is_active = true
      AND p.is_visible = true
      AND p.is_out_of_stock = false
      AND (p.carton_price IS NOT NULL AND p.carton_price > 0)
      AND p.recently_available_at IS NOT NULL
      AND p.recently_available_at >= now() - (v_days || ' days')::interval
    ORDER BY p.recently_available_at DESC
  ) sub;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_reference_cities(p_token uuid, p_governorate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
    v_session app.sessions;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
