CREATE OR REPLACE FUNCTION public.get_rep_customer_kpis(p_token uuid, p_employee_id uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_target_month int; v_target_year int;
  v_month_start timestamptz; v_month_end timestamptz;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
  v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
  v_month_start := date_trunc('month', make_date(v_target_year, v_target_month, 1));
  v_month_end := v_month_start + INTERVAL '1 month';
  WITH customer_delivered_orders AS (
    SELECT o.customer_id, o.id AS order_id, o.total_amount, o.delivered_at
    FROM public.orders o JOIN public.customers c ON c.id = o.customer_id
    WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end
      AND (c.owner_id = p_employee_id OR c.id IN (SELECT c2.id FROM public.customers c2 JOIN public.employees e ON e.identity_id = c2.owner_id WHERE e.id = p_employee_id))
  ), customer_visits AS (
    SELECT v.customer_id, COUNT(*)::int AS visit_count FROM public.visits v
    WHERE v.status = 'completed' AND v.check_out_at >= v_month_start AND v.check_out_at < v_month_end
      AND v.employee_id = p_employee_id GROUP BY v.customer_id
  ), customer_agg AS (
    SELECT c.id AS customer_id, c.company_name AS customer_name,
      COALESCE(SUM(cdo.total_amount), 0) AS total_sales, COUNT(DISTINCT cdo.order_id)::int AS total_orders,
      COALESCE(cv.visit_count, 0) AS total_visits,
      EXISTS (SELECT 1 FROM public.orders o2 WHERE o2.customer_id = c.id AND o2.status = 'delivered'
        AND o2.delivered_at = (SELECT MIN(o3.delivered_at) FROM public.orders o3 WHERE o3.customer_id = c.id AND o3.status = 'delivered')
        AND o2.delivered_at >= v_month_start AND o2.delivered_at < v_month_end) AS is_new_customer
    FROM public.customers c LEFT JOIN customer_delivered_orders cdo ON cdo.customer_id = c.id
    LEFT JOIN customer_visits cv ON cv.customer_id = c.id
    WHERE (c.owner_id = p_employee_id OR c.owner_id IN (SELECT identity_id FROM public.employees WHERE id = p_employee_id))
      AND c.is_active = true
    GROUP BY c.id, c.company_name, cv.visit_count
  )
  SELECT jsonb_agg(jsonb_build_object(
    'customer_id', ca.customer_id, 'customer_name', ca.customer_name,
    'total_sales', ca.total_sales, 'total_orders', ca.total_orders, 'total_visits', ca.total_visits,
    'is_new_customer', ca.is_new_customer
  ) ORDER BY ca.total_sales DESC) INTO v_result
  FROM customer_agg ca WHERE ca.total_sales > 0 OR ca.total_visits > 0 OR ca.is_new_customer = true;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_role_capabilities(p_token uuid, p_role_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_array(); END IF;
  SELECT jsonb_agg(
    jsonb_build_object(
      'capability_id', c.id,
      'code', c.code,
      'name', c.name,
      'group', c.group,
      'is_granted', CASE WHEN rc.id IS NOT NULL THEN true ELSE false END
    )
    ORDER BY c.group, c.name
  ) INTO v_result
  FROM public.capabilities c
  LEFT JOIN public.role_capabilities rc ON rc.capability_id = c.id AND rc.role_id = p_role_id;
  RETURN COALESCE(v_result, jsonb_build_array());
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_analytics(p_token text, p_search text DEFAULT NULL::text, p_owner_id uuid DEFAULT NULL::uuid, p_owner_ids uuid[] DEFAULT NULL::uuid[], p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid;
  v_session app.sessions;
  v_visible uuid[];
  v_is_super boolean;
  v_result jsonb;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_TOKEN');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type = 'customer' THEN
    RETURN jsonb_build_object(
      'customers', '[]'::jsonb, 'companies', '[]'::jsonb,
      'products', '[]'::jsonb,
      'totals', jsonb_build_object('total_activity', 0, 'total_target', 0)
    );
  END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_visible := COALESCE(public.get_visible_employee_ids(v_token), '{}'::uuid[]);

  SELECT jsonb_build_object(
    'customers', COALESCE(cust.json, '[]'::jsonb),
    'companies', COALESCE(comp.json, '[]'::jsonb),
    'products', COALESCE(prod.json, '[]'::jsonb),
    'totals', jsonb_build_object(
      'total_activity', COALESCE(t.total_activity, 0),
      'total_target', COALESCE(t.total_target, 0)
    )
  ) INTO v_result
  FROM (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', x.name,
        'activity', x.activity,
        'target', x.target,
        'order_count', x.order_count
      ) ORDER BY x.activity DESC
    ) AS json
    FROM (
      SELECT
        COALESCE(o.snapshot_customer_name, c.company_name) AS name,
        SUM(o.total_amount) AS activity,
        SUM(CASE WHEN o.status = 'delivered' THEN o.total_amount ELSE 0 END) AS target,
        COUNT(*)::int AS order_count
      FROM public.orders o
      JOIN public.customers c ON c.id = o.customer_id
      WHERE public.is_order_in_statistics(o.status)
        AND (v_is_super OR c.owner_id = ANY(v_visible))
        AND (p_owner_id IS NULL OR o.owner_id = p_owner_id)
        AND (p_owner_ids IS NULL OR o.owner_id = ANY(p_owner_ids))
        AND (p_search IS NULL OR
             o.order_number ILIKE '%' || p_search || '%' OR
             c.company_name ILIKE '%' || p_search || '%' OR
             o.snapshot_customer_name ILIKE '%' || p_search || '%')
        AND (p_date_from IS NULL OR o.created_at >= p_date_from)
        AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      GROUP BY COALESCE(o.snapshot_customer_name, c.company_name)
    ) x
  ) cust,
  (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', x.name,
        'activity', x.activity,
        'target', x.target
      ) ORDER BY x.activity DESC
    ) AS json
    FROM (
      SELECT
        comp.company_name AS name,
        SUM(oi.total_price) AS activity,
        SUM(CASE WHEN o.status = 'delivered' THEN oi.total_price ELSE 0 END) AS target
      FROM public.order_items oi
      JOIN public.orders o ON o.id = oi.order_id
      JOIN public.products pr ON pr.id = oi.product_id
      JOIN public.companies comp ON comp.id = pr.company_id
      JOIN public.customers c ON c.id = o.customer_id
      WHERE public.is_order_in_statistics(o.status)
        AND (v_is_super OR c.owner_id = ANY(v_visible))
        AND (p_owner_id IS NULL OR o.owner_id = p_owner_id)
        AND (p_owner_ids IS NULL OR o.owner_id = ANY(p_owner_ids))
        AND (p_date_from IS NULL OR o.created_at >= p_date_from)
        AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      GROUP BY comp.company_name
    ) x
  ) comp,
  (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', x.name,
        'activity', x.activity,
        'target', x.target
      ) ORDER BY x.activity DESC
    ) AS json
    FROM (
      SELECT
        pr.product_name AS name,
        SUM(oi.total_price) AS activity,
        SUM(CASE WHEN o.status = 'delivered' THEN oi.total_price ELSE 0 END) AS target
      FROM public.order_items oi
      JOIN public.orders o ON o.id = oi.order_id
      JOIN public.products pr ON pr.id = oi.product_id
      JOIN public.customers c ON c.id = o.customer_id
      WHERE public.is_order_in_statistics(o.status)
        AND (v_is_super OR c.owner_id = ANY(v_visible))
        AND (p_owner_id IS NULL OR o.owner_id = p_owner_id)
        AND (p_owner_ids IS NULL OR o.owner_id = ANY(p_owner_ids))
        AND (p_date_from IS NULL OR o.created_at >= p_date_from)
        AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      GROUP BY pr.product_name
    ) x
  ) prod,
  (
    SELECT
      COALESCE(SUM(o.total_amount) FILTER (WHERE public.is_order_in_statistics(o.status)), 0) AS total_activity,
      COALESCE(SUM(o.total_amount) FILTER (WHERE o.status = 'delivered'), 0) AS total_target
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    WHERE (v_is_super OR c.owner_id = ANY(v_visible))
      AND (p_owner_id IS NULL OR o.owner_id = p_owner_id)
      AND (p_owner_ids IS NULL OR o.owner_id = ANY(p_owner_ids))
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
  ) t;

  RETURN COALESCE(v_result, jsonb_build_object(
    'customers', '[]'::jsonb, 'companies', '[]'::jsonb,
    'products', '[]'::jsonb,
    'totals', jsonb_build_object('total_activity', 0, 'total_target', 0)
  ));
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_analytics_order_items(p_token text, p_order_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid;
  v_session app.sessions;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_TOKEN');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'order_id', oi.order_id,
      'product_name', p.product_name,
      'company_name', comp.company_name,
      'total_price', oi.total_price
    ))
    FROM public.order_items oi
    JOIN public.products p ON p.id = oi.product_id
    LEFT JOIN public.companies comp ON comp.id = p.company_id
    WHERE oi.order_id = ANY(p_order_ids)
  ), '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_analytics_orders(p_token text, p_order_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid;
  v_session app.sessions;
  v_visible uuid[];
  v_is_super boolean;
  v_result jsonb;
BEGIN
  BEGIN
    v_token := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error', 'INVALID_TOKEN');
  END;

  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type = 'customer' THEN RETURN '[]'::jsonb; END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_visible := COALESCE(public.get_visible_employee_ids(v_token), '{}'::uuid[]);

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'order_number', o.order_number,
      'customer_name', COALESCE(o.snapshot_customer_name, c.company_name),
      'total_amount', o.total_amount,
      'status', o.status,
      'created_at', o.created_at,
      'owner_id', o.owner_id
    ) ORDER BY o.created_at DESC
  ), '[]'::jsonb) INTO v_result
  FROM public.orders o
  JOIN public.customers c ON c.id = o.customer_id
  WHERE o.id = ANY(p_order_ids)
    AND (v_is_super OR c.owner_id = ANY(v_visible));

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_company(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'company_id', comp.id,
      'company_name', comp.company_name,
      'total_quantity', SUM(oi.piece_quantity),
      'total_amount', SUM(oi.total_price),
      'product_count', COUNT(DISTINCT oi.product_id),
      'order_count', COUNT(DISTINCT oi.order_id)
    ) ORDER BY SUM(oi.total_price) DESC NULLS LAST
  ) INTO v_result
  FROM order_items oi
  JOIN products pr ON pr.id = oi.product_id
  JOIN companies comp ON comp.id = pr.company_id
  JOIN orders o ON o.id = oi.order_id
  WHERE (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= p_date_to)
    AND public.is_order_in_statistics(o.status)
  GROUP BY comp.id, comp.company_name;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_customer(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'customer_id', c.id,
      'customer_name', c.company_name,
      'total_orders', COUNT(o.id),
      'total_amount', COALESCE(SUM(o.total_amount), 0)
    ) ORDER BY SUM(o.total_amount) DESC NULLS LAST
  ) INTO v_result
  FROM customers c
  JOIN orders o ON o.customer_id = c.id
  WHERE (p_date_from IS NULL OR o.created_at >= p_date_from)
    AND (p_date_to IS NULL OR o.created_at <= p_date_to)
    AND public.is_order_in_statistics(o.status)
  GROUP BY c.id, c.company_name;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_manager(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_emp_id uuid;
  v_visible_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type = 'customer' THEN
    RETURN '[]'::jsonb;
  END IF;

  PERFORM set_config('app.identity_id', v_session.identity_id::text, true);

  v_emp_id := app.current_employee_id();

  IF app.has_capability('customers.read') THEN
    SELECT array_agg(id) INTO v_visible_ids FROM employees;
  ELSE
    v_visible_ids := app.get_subtree_ids(v_emp_id);
  END IF;

  WITH combined AS (
    -- Direct reports' orders
    SELECT m.id AS manager_id, m.full_name AS manager_name,
      o.id AS order_id, o.total_amount,
      e.id AS employee_id
    FROM employees m
    JOIN employees e ON e.manager_id = m.id
    JOIN identities i ON i.id = e.identity_id
    JOIN orders o ON o.created_by = i.id
    WHERE m.id = ANY(v_visible_ids)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND public.is_order_in_statistics(o.status)

    UNION ALL

    -- Manager's own orders (as a team member)
    SELECT m.id, m.full_name,
      o.id, o.total_amount,
      m.id
    FROM employees m
    JOIN identities i ON i.id = m.identity_id
    JOIN orders o ON o.created_by = i.id
    WHERE m.id = ANY(v_visible_ids)
      AND EXISTS (SELECT 1 FROM employees sub WHERE sub.manager_id = m.id)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND public.is_order_in_statistics(o.status)
  )
  SELECT jsonb_agg(jsonb_build_object(
    'manager_id', g.manager_id, 'manager_name', g.manager_name,
    'total_orders', g.total_orders, 'total_amount', g.total_amount,
    'rep_count', g.rep_count
  ) ORDER BY g.total_amount DESC NULLS LAST) INTO v_result
  FROM (
    SELECT c.manager_id, c.manager_name,
      COUNT(c.order_id)::int AS total_orders,
      COALESCE(SUM(c.total_amount), 0) AS total_amount,
      COUNT(DISTINCT c.employee_id)::int AS rep_count
    FROM combined c
    GROUP BY c.manager_id, c.manager_name
  ) g;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_product(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
