  GROUP BY pr.id, pr.product_name, comp.company_name;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_rep(p_token uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
  v_emp_id uuid;
  v_visible_ids uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type = 'customer' THEN
    RETURN '[]'::jsonb;
  END IF;

  PERFORM set_config('app.identity_id', v_session.identity_id::text, true);

  v_emp_id := app.current_employee_id();

  IF app.has_capability('customers.read') THEN
    SELECT array_agg(id) INTO v_visible_ids FROM employees;
  ELSE
    v_visible_ids := app.get_subtree_ids(v_emp_id);
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'employee_id', s.employee_id, 'employee_name', s.employee_name,
    'employee_code', s.employee_code, 'total_orders', s.total_orders,
    'total_amount', s.total_amount, 'customer_count', s.customer_count
  ) ORDER BY s.total_amount DESC NULLS LAST) INTO v_result
  FROM (
    SELECT e.id AS employee_id, e.full_name AS employee_name, e.code AS employee_code,
      COUNT(o.id) AS total_orders,
      COALESCE(SUM(o.total_amount), 0) AS total_amount,
      COUNT(DISTINCT o.customer_id) AS customer_count
    FROM employees e
    JOIN identities i ON i.id = e.identity_id
    JOIN orders o ON o.created_by = i.id
    WHERE e.id = ANY(v_visible_ids)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND public.is_order_in_statistics(o.status)
    GROUP BY e.id, e.full_name, e.code
  ) s;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_by_time(p_token uuid, p_grouping character varying DEFAULT 'day'::character varying, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF p_grouping = 'month' THEN
    SELECT jsonb_agg(
      jsonb_build_object(
        'period', TO_CHAR(o.created_at, 'YYYY-MM'),
        'total_orders', COUNT(o.id),
        'total_amount', COALESCE(SUM(o.total_amount), 0)
      ) ORDER BY 1
    ) INTO v_result
    FROM orders o
    WHERE (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND public.is_order_in_statistics(o.status)
    GROUP BY TO_CHAR(o.created_at, 'YYYY-MM');
  ELSE
    SELECT jsonb_agg(
      jsonb_build_object(
        'period', o.created_at::date::text,
        'total_orders', COUNT(o.id),
        'total_amount', COALESCE(SUM(o.total_amount), 0)
      ) ORDER BY 1
    ) INTO v_result
    FROM orders o
    WHERE (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND public.is_order_in_statistics(o.status)
    GROUP BY o.created_at::date;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_manager_cc(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp_id uuid;
  v_identity_id uuid;
  v_subtree_ids uuid[];
  v_identity_ids uuid[];
  v_member_count int;
  v_active_today int;
  v_customer_count int;
  v_active_sessions jsonb := '[]'::jsonb;
  v_no_start jsonb := '[]'::jsonb;
  v_ended jsonb := '[]'::jsonb;
  v_today_orders bigint;
  v_today_sales numeric;
  v_month_orders bigint;
  v_month_sales numeric;
  v_pending_followup int;
  v_pending_collections numeric;
  v_active_visits int;
  v_today_visits int;
  v_month_visits int;
  v_new_customers_month int;
  v_inactive_customers int;
  v_member_record record;
  v_members jsonb := '[]'::jsonb;
  v_team_sales_target numeric := 0;
  v_team_visits_target numeric := 0;
  v_team_orders_target numeric := 0;
  v_team_new_customers_target numeric := 0;
  v_team_sales_achievement numeric := 0;
  v_team_visits_achievement int := 0;
  v_team_orders_achievement int := 0;
  v_team_new_customers_achievement int := 0;
  v_personal_customer_count int;
  v_personal_month_orders int;
  v_personal_month_sales numeric;
  v_personal_today_orders int;
  v_personal_active_visits int;
  v_personal_today_visits int;
  v_personal_month_visits int;
  v_personal_pending_collections numeric;
  v_target_month int;
  v_target_year int;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;
  v_emp_id := v_session.employee_id;
  v_identity_id := v_session.identity_id;
  v_target_month := EXTRACT(MONTH FROM CURRENT_DATE)::int;
  v_target_year := EXTRACT(YEAR FROM CURRENT_DATE)::int;
  v_subtree_ids := app.get_subtree_ids(v_emp_id);
  SELECT COALESCE(array_agg(identity_id), '{}'::uuid[]) INTO v_identity_ids FROM public.employees WHERE id = ANY(v_subtree_ids);
  SELECT count(*) INTO v_member_count FROM unnest(v_subtree_ids);
  SELECT count(DISTINCT employee_id) INTO v_active_today FROM public.workday_sessions WHERE date = CURRENT_DATE AND status = 'active' AND employee_id = ANY(v_subtree_ids);
  SELECT count(*) INTO v_customer_count FROM public.customers WHERE owner_id = ANY(v_subtree_ids) AND is_active = true;
  WITH active_sessions AS (
    SELECT wds.id AS session_id, wds.employee_id, e.full_name AS employee_name, wds.start_time, wds.status AS session_status,
      EXTRACT(EPOCH FROM (now() - wds.start_time)) / 60 AS duration_minutes
    FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id
    WHERE wds.date = CURRENT_DATE AND wds.status = 'active' AND wds.employee_id = ANY(v_subtree_ids)
  ),
  last_points AS (
    SELECT DISTINCT ON (tp.employee_id) tp.employee_id, tp.latitude, tp.longitude, tp.recorded_at
    FROM public.tracking_points tp WHERE tp.recorded_at >= CURRENT_DATE AND tp.employee_id = ANY(v_subtree_ids)
    ORDER BY tp.employee_id, tp.recorded_at DESC
  ),
  active_breaks AS (
    SELECT wb.session_id, wb.employee_id, EXTRACT(EPOCH FROM (now() - wb.break_start)) / 60 AS break_minutes
    FROM public.workday_breaks wb WHERE wb.break_end IS NULL AND wb.employee_id = ANY(v_subtree_ids)
  ),
  today_orders AS (
    SELECT o.created_by AS identity_id, COUNT(*)::int AS order_count, COALESCE(SUM(o.total_amount), 0) AS sales_value
    FROM public.orders o WHERE o.submitted_at::date = CURRENT_DATE AND public.is_order_in_statistics(o.status) AND o.created_by = ANY(v_identity_ids)
    GROUP BY o.created_by
  ),
  total_breaks AS (
    SELECT wb.employee_id, COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(wb.break_end, now()) - wb.break_start))), 0) / 60 AS total_break_minutes, ewp.schedule_type
    FROM public.workday_breaks wb JOIN public.workday_sessions ws ON ws.id = wb.session_id AND ws.date = CURRENT_DATE
    LEFT JOIN public.employee_work_policies ewp ON ewp.employee_id = wb.employee_id
    WHERE wb.employee_id = ANY(v_subtree_ids) GROUP BY wb.employee_id, ewp.schedule_type
  )
  SELECT jsonb_agg(jsonb_build_object(
    'employee_id', as2.employee_id,
    'employee_name', as2.employee_name,
    'session_status', as2.session_status,
    'started_at', as2.start_time,
    'duration_minutes', as2.duration_minutes::int,
    'net_minutes', GREATEST(CASE WHEN COALESCE(tb.schedule_type, 'flexible') = 'fixed_shift' THEN as2.duration_minutes::int - COALESCE(tb.total_break_minutes, 0)::int ELSE as2.duration_minutes::int END, 0),
    'break_minutes', COALESCE(tb.total_break_minutes, 0)::int,
    'work_status', CASE WHEN ab.employee_id IS NOT NULL THEN 'on_break' WHEN vl.employee_id IS NOT NULL THEN 'on_visit' ELSE 'working' END,
    'order_count', COALESCE(too.order_count, 0),
    'sales_value', COALESCE(too.sales_value, 0),
    'latitude', lp.latitude,
    'longitude', lp.longitude,
    'last_seen_at', lp.recorded_at,
    'connection_status', CASE WHEN lp.recorded_at IS NULL THEN 'no_data' WHEN lp.recorded_at > now() - interval '5 minutes' THEN 'connected' WHEN lp.recorded_at > now() - interval '25 minutes' THEN 'delayed' ELSE 'lost' END
  ) ORDER BY CASE WHEN ab.employee_id IS NOT NULL THEN 3 WHEN vl.employee_id IS NOT NULL THEN 2 ELSE 1 END)
  INTO v_active_sessions
  FROM active_sessions as2
  LEFT JOIN active_breaks ab ON ab.session_id = as2.session_id
  LEFT JOIN LATERAL (SELECT v2.id, v2.employee_id FROM public.visits v2 WHERE v2.employee_id = as2.employee_id AND v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL LIMIT 1) vl ON true
  LEFT JOIN last_points lp ON lp.employee_id = as2.employee_id
  LEFT JOIN today_orders too ON too.identity_id = (SELECT identity_id FROM public.employees WHERE id = as2.employee_id)
  LEFT JOIN total_breaks tb ON tb.employee_id = as2.employee_id;
  v_active_sessions := COALESCE(v_active_sessions, '[]'::jsonb);
  SELECT jsonb_agg(jsonb_build_object('employee_id', e.id, 'employee_name', e.full_name)) INTO v_no_start
  FROM public.employees e WHERE e.id = ANY(v_subtree_ids) AND e.is_active = true AND e.id NOT IN (SELECT employee_id FROM public.workday_sessions WHERE date = CURRENT_DATE);
  v_no_start := COALESCE(v_no_start, '[]'::jsonb);
  SELECT jsonb_agg(jsonb_build_object('employee_id', wds.employee_id, 'employee_name', e.full_name, 'ended_at', wds.end_time, 'duration_minutes', EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) / 60::int, 'visit_count', wds.visit_count) ORDER BY wds.end_time DESC) INTO v_ended
  FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id
  WHERE wds.date = CURRENT_DATE AND wds.status = 'completed' AND wds.employee_id = ANY(v_subtree_ids);
  v_ended := COALESCE(v_ended, '[]'::jsonb);
  SELECT order_count, sales_value INTO v_today_orders, v_today_sales FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', v_identity_ids);
  SELECT order_count, sales_value INTO v_month_orders, v_month_sales FROM public.get_kpi_orders_count(date_trunc('month', CURRENT_DATE), date_trunc('month', CURRENT_DATE) + interval '1 month', v_identity_ids);
  SELECT count(*) INTO v_pending_followup FROM public.orders WHERE created_by = ANY(v_identity_ids) AND status IN ('draft', 'reviewing', 'submitted');
  SELECT pending_amount INTO v_pending_collections FROM public.get_kpi_collections_pending_value(v_subtree_ids);
  SELECT count(*) INTO v_active_visits FROM public.visits WHERE employee_id = ANY(v_subtree_ids) AND status = 'active';
  SELECT count(*) INTO v_today_visits FROM public.visits WHERE employee_id = ANY(v_subtree_ids) AND created_at >= CURRENT_DATE;
  SELECT count(*) INTO v_month_visits FROM public.visits WHERE employee_id = ANY(v_subtree_ids) AND created_at >= date_trunc('month', CURRENT_DATE) AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';
  SELECT count(*) INTO v_new_customers_month FROM public.customers WHERE owner_id = ANY(v_subtree_ids) AND created_at >= date_trunc('month', CURRENT_DATE) AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';
  SELECT count(*) INTO v_inactive_customers FROM public.customers WHERE owner_id = ANY(v_subtree_ids) AND is_active = true AND COALESCE(updated_at, created_at) < CURRENT_DATE - 30;
  FOR v_member_record IN SELECT e.id, e.code, e.full_name, e.identity_id FROM public.employees e WHERE e.id = ANY(v_subtree_ids) AND e.is_active = true ORDER BY e.full_name
  LOOP
    DECLARE v_mem_customer_count int; v_mem_month_orders int; v_mem_month_sales numeric; v_mem_today_orders int; v_mem_today_visits int; v_mem_month_visits int; v_mem_sales_target numeric; v_mem_visits_target numeric; v_mem_orders_target numeric; v_mem_new_customers_target numeric; v_mem_achievement_pct numeric;
    BEGIN
      SELECT count(*) INTO v_mem_customer_count FROM public.customers WHERE owner_id = v_member_record.id AND is_active = true;
      SELECT order_count, sales_value INTO v_mem_month_orders, v_mem_month_sales FROM public.get_kpi_orders_count(date_trunc('month', CURRENT_DATE), date_trunc('month', CURRENT_DATE) + interval '1 month', ARRAY[v_member_record.identity_id]);
      SELECT order_count INTO v_mem_today_orders FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', ARRAY[v_member_record.identity_id]);
      SELECT count(*) INTO v_mem_today_visits FROM public.visits WHERE employee_id = v_member_record.id AND created_at >= CURRENT_DATE;
      SELECT count(*) INTO v_mem_month_visits FROM public.visits WHERE employee_id = v_member_record.id AND created_at >= date_trunc('month', CURRENT_DATE) AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';
      SELECT COALESCE(SUM(sales_target), 0), COALESCE(SUM(visits_target), 0), COALESCE(SUM(orders_target), 0), COALESCE(SUM(new_customers_target), 0)
      INTO v_mem_sales_target, v_mem_visits_target, v_mem_orders_target, v_mem_new_customers_target
      FROM public.employee_monthly_targets WHERE employee_id = v_member_record.id AND target_month = v_target_month AND target_year = v_target_year;
      IF v_mem_sales_target > 0 THEN v_team_sales_achievement := v_team_sales_achievement + (v_mem_month_sales / v_mem_sales_target * 100); v_team_sales_target := v_team_sales_target + v_mem_sales_target; END IF;
      v_team_visits_achievement := v_team_visits_achievement + v_mem_today_visits;
      v_team_visits_target := v_team_visits_target + v_mem_visits_target;
      v_team_orders_achievement := v_team_orders_achievement + v_mem_today_orders;
      v_team_orders_target := v_team_orders_target + v_mem_orders_target;
      v_team_new_customers_achievement := v_team_new_customers_achievement + v_mem_month_orders;
      v_team_new_customers_target := v_team_new_customers_target + v_mem_new_customers_target;
      v_members := v_members || jsonb_build_object(
        'employee_id', v_member_record.id, 'employee_code', v_member_record.code, 'employee_name', v_member_record.full_name,
        'customer_count', v_mem_customer_count, 'month_orders', v_mem_month_orders, 'month_sales', v_mem_month_sales,
        'today_orders', v_mem_today_orders, 'today_visits', v_mem_today_visits, 'month_visits', v_mem_month_visits,
        'sales_target', v_mem_sales_target, 'visits_target', v_mem_visits_target, 'orders_target', v_mem_orders_target, 'new_customers_target', v_mem_new_customers_target,
        'achievement_pct', CASE WHEN v_mem_sales_target > 0 THEN ROUND((v_mem_month_sales / v_mem_sales_target * 100)::numeric, 1) ELSE NULL END
      );
    END;
  END LOOP;
  SELECT count(*) INTO v_personal_customer_count FROM public.customers WHERE owner_id = v_emp_id AND is_active = true;
  SELECT order_count, sales_value INTO v_personal_month_orders, v_personal_month_sales FROM public.get_kpi_orders_count(date_trunc('month', CURRENT_DATE), date_trunc('month', CURRENT_DATE) + interval '1 month', ARRAY[v_identity_id]);
  SELECT order_count INTO v_personal_today_orders FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', ARRAY[v_identity_id]);
  SELECT count(*) INTO v_personal_active_visits FROM public.visits WHERE employee_id = ANY(v_subtree_ids) AND status = 'active';
  SELECT count(*) INTO v_personal_today_visits FROM public.visits WHERE employee_id = v_emp_id AND created_at >= CURRENT_DATE;
  SELECT count(*) INTO v_personal_month_visits FROM public.visits WHERE employee_id = v_emp_id AND created_at >= date_trunc('month', CURRENT_DATE) AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';
  SELECT pending_amount INTO v_personal_pending_collections FROM public.get_kpi_collections_pending_value(ARRAY[v_emp_id]);
  SELECT jsonb_build_object(
    'team_overview', jsonb_build_object('member_count', v_member_count, 'active_today', v_active_today, 'customer_count', v_customer_count),
    'attendance', jsonb_build_object('active_sessions', v_active_sessions, 'no_start_employees', v_no_start, 'ended_employees', v_ended, 'active_count', (SELECT COUNT(*) FROM jsonb_array_elements(v_active_sessions)), 'no_start_count', (SELECT COUNT(*) FROM jsonb_array_elements(v_no_start)), 'ended_count', (SELECT COUNT(*) FROM jsonb_array_elements(v_ended))),
    'orders', jsonb_build_object('today_orders', v_today_orders, 'today_sales', v_today_sales, 'month_orders', v_month_orders, 'month_sales', v_month_sales, 'pending_followup', v_pending_followup, 'pending_collections', v_pending_collections),
    'visits', jsonb_build_object('active_visits', v_active_visits, 'today_visits', v_today_visits, 'month_visits', v_month_visits),
    'customers', jsonb_build_object('total_customers', v_customer_count, 'new_customers_month', v_new_customers_month, 'inactive_customers', v_inactive_customers),
    'team_performance', jsonb_build_object('members', v_members, 'team_targets', jsonb_build_object('sales_target', v_team_sales_target, 'sales_achievement', ROUND(v_team_sales_achievement::numeric, 1), 'visits_target', v_team_visits_target, 'visits_achievement', v_team_visits_achievement, 'orders_target', v_team_orders_target, 'orders_achievement', v_team_orders_achievement, 'new_customers_target', v_team_new_customers_target, 'new_customers_achievement', v_team_new_customers_achievement)),
    'personal_summary', jsonb_build_object('customer_count', v_personal_customer_count, 'month_orders', v_personal_month_orders, 'month_sales', v_personal_month_sales, 'today_orders', v_personal_today_orders, 'active_visits', v_personal_active_visits, 'today_visits', v_personal_today_visits, 'month_visits', v_personal_month_visits, 'pending_collections', v_personal_pending_collections)
  ) INTO v_result;
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_sales_reps_effort(p_token uuid, p_from date, p_to date, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_ids uuid[];
    v_total_days int;
    v_result jsonb;
    v_employee record;
    v_emp_data jsonb;
    v_emp_list jsonb;
    v_summary jsonb;
    v_top jsonb;
    v_worst jsonb;
    v_avg_score numeric;
    v_total_sales numeric;
    v_total_orders int;
    v_total_visits int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF public.check_capability(p_token, 'attendance.view_all') THEN
        SELECT array_agg(e.id) INTO v_employee_ids FROM public.employees e WHERE e.is_active = true;
    ELSE
        v_employee_ids := public.get_visible_employee_ids(p_token);
    END IF;

    IF v_employee_ids IS NULL OR array_length(v_employee_ids, 1) IS NULL THEN
        RETURN jsonb_build_object('employees', '[]'::jsonb, 'summary', jsonb_build_object(
            'total_employees', 0, 'total_sales', 0, 'total_orders', 0, 'total_visits', 0,
            'avg_performance_score', 0
        ));
    END IF;

    v_total_days := (p_to - p_from) + 1;

    WITH employee_sessions AS (
        SELECT wds.employee_id,
            COUNT(DISTINCT wds.date)::int AS active_days,
            MAX(wds.start_time) AS last_activity,
            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60), 0)::int AS total_minutes,
            COALESCE(SUM(wds.total_distance_meters), 0)::int AS total_distance
        FROM public.workday_sessions wds
        WHERE wds.employee_id = ANY(v_employee_ids)
          AND wds.date >= p_from AND wds.date <= p_to
          AND wds.status = 'completed'
        GROUP BY wds.employee_id
    ),
    emp_sales AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            COUNT(*)::int AS order_count,
            COALESCE(SUM(o.total_amount), 0) AS sales_value,
            COUNT(*) FILTER (WHERE o.status = 'cancelled')::int AS cancelled_count
        FROM public.orders o
        WHERE public.resolve_employee_id(o.owner_id) = ANY(v_employee_ids)
          AND o.created_at::date >= p_from AND o.created_at::date <= p_to
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    emp_customers AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS new_customers
        FROM public.customers c
        WHERE public.resolve_employee_id(c.owner_id) = ANY(v_employee_ids)
          AND c.created_at::date >= p_from AND c.created_at::date <= p_to
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    emp_total_customers AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS total_customers
        FROM public.customers c
        WHERE public.resolve_employee_id(c.owner_id) = ANY(v_employee_ids)
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    emp_visits AS (
        SELECT v.employee_id,
            COUNT(*)::int AS total_visits,
            COUNT(*) FILTER (WHERE v.status = 'completed')::int AS successful_visits,
            COUNT(*) FILTER (WHERE v.status != 'completed')::int AS incomplete_visits
        FROM public.visits v
        WHERE v.employee_id = ANY(v_employee_ids)
          AND v.check_in_at::date >= p_from AND v.check_in_at::date <= p_to
        GROUP BY v.employee_id
    ),
    emp_targets AS (
        SELECT emt.employee_id,
            COALESCE(SUM(emt.sales_target), 0) AS sales_target,
            COALESCE(SUM(emt.orders_target), 0) AS orders_target
        FROM public.employee_monthly_targets emt
        WHERE emt.employee_id = ANY(v_employee_ids)
          AND (emt.target_year * 100 + emt.target_month) BETWEEN (EXTRACT(YEAR FROM p_from) * 100 + EXTRACT(MONTH FROM p_from))
          AND (EXTRACT(YEAR FROM p_to) * 100 + EXTRACT(MONTH FROM p_to))
        GROUP BY emt.employee_id
    )
    SELECT jsonb_agg(jsonb_build_object(
        'employee_id', e.id,
        'name', e.full_name,
        'code', e.code,
        'role_name', (SELECT r.name FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id WHERE er.employee_id = e.id LIMIT 1),
        'active_days', COALESCE(es.active_days, 0),
        'total_days_in_range', v_total_days,
        'last_activity', es.last_activity,
        'status', CASE WHEN es.last_activity IS NOT NULL AND es.last_activity >= now() - interval '7 days' THEN 'active' ELSE 'idle' END,
        'total_minutes', COALESCE(es.total_minutes, 0),
        'total_distance', COALESCE(es.total_distance, 0),
        'sales', jsonb_build_object(
            'total_value', COALESCE(s.sales_value, 0),
            'order_count', COALESCE(s.order_count, 0),
            'avg_order_value', CASE WHEN COALESCE(s.order_count, 0) > 0 THEN ROUND((COALESCE(s.sales_value, 0) / s.order_count)::numeric, 2) ELSE 0 END
        ),
        'orders', jsonb_build_object(
            'total', COALESCE(s.order_count, 0),
            'completed', GREATEST(COALESCE(s.order_count, 0) - COALESCE(s.cancelled_count, 0), 0),
            'cancelled', COALESCE(s.cancelled_count, 0)
        ),
        'customers', jsonb_build_object(
            'new_count', COALESCE(ec.new_customers, 0),
            'total_linked', COALESCE(etc.total_customers, 0)
        ),
        'visits', jsonb_build_object(
            'total', COALESCE(ev.total_visits, 0),
            'successful', COALESCE(ev.successful_visits, 0),
            'incomplete', COALESCE(ev.incomplete_visits, 0),
            'success_rate', CASE WHEN COALESCE(ev.total_visits, 0) > 0 THEN ROUND((COALESCE(ev.successful_visits, 0)::numeric / ev.total_visits) * 100, 1) ELSE 0 END
        ),
        'targets', jsonb_build_object(
            'sales_target', COALESCE(t.sales_target, 0),
            'sales_actual', COALESCE(s.sales_value, 0),
            'achievement_pct', CASE WHEN COALESCE(t.sales_target, 0) > 0 THEN ROUND((COALESCE(s.sales_value, 0) / t.sales_target * 100)::numeric, 1) ELSE 0 END,
            'orders_target', COALESCE(t.orders_target, 0),
            'orders_actual', COALESCE(s.order_count, 0)
        ),
        'performance_score', ROUND((
            CASE WHEN COALESCE(es.active_days, 0) > 0 THEN LEAST((es.active_days::numeric / v_total_days) * 40, 40) ELSE 0 END +
            CASE WHEN COALESCE(t.sales_target, 0) > 0 THEN LEAST((COALESCE(s.sales_value, 0) / t.sales_target) * 30, 30) ELSE 0 END +
            CASE WHEN COALESCE(ev.total_visits, 0) > 0 THEN LEAST((COALESCE(ev.successful_visits, 0)::numeric / ev.total_visits) * 20, 20) ELSE 0 END +
            CASE WHEN COALESCE(ec.new_customers, 0) > 0 THEN LEAST(ec.new_customers::numeric * 5, 10) ELSE 0 END
        )::numeric, 1)
    ) ORDER BY
        CASE WHEN es.last_activity IS NOT NULL AND es.last_activity >= now() - interval '7 days' THEN 0 ELSE 1 END,
        COALESCE(s.sales_value, 0) DESC
    ) INTO v_emp_list
    FROM public.employees e
    LEFT JOIN employee_sessions es ON es.employee_id = e.id
    LEFT JOIN emp_sales s ON s.employee_id = e.id
    LEFT JOIN emp_customers ec ON ec.employee_id = e.id
    LEFT JOIN emp_total_customers etc ON etc.employee_id = e.id
    LEFT JOIN emp_visits ev ON ev.employee_id = e.id
    LEFT JOIN emp_targets t ON t.employee_id = e.id
    WHERE e.id = ANY(v_employee_ids)
      AND (p_search IS NULL OR p_search = '' OR e.full_name ILIKE '%' || p_search || '%' OR e.code ILIKE '%' || p_search || '%');

    -- Summary stats
    SELECT
        ROUND(AVG(score)::numeric, 1),
        COALESCE(SUM((d->'sales'->>'total_value')::numeric), 0),
        COALESCE(SUM((d->'orders'->>'total')::int), 0),
        COALESCE(SUM((d->'visits'->>'total')::int), 0)
    INTO v_avg_score, v_total_sales, v_total_orders, v_total_visits
    FROM jsonb_array_elements(COALESCE(v_emp_list, '[]'::jsonb)) AS d,
    LATERAL (
        SELECT (
            CASE WHEN (d->>'active_days')::int > 0 THEN LEAST(((d->>'active_days')::numeric / v_total_days) * 40, 40) ELSE 0 END +
            CASE WHEN ((d->'targets'->>'sales_target')::numeric) > 0 THEN LEAST(((d->'targets'->>'sales_actual')::numeric / NULLIF((d->'targets'->>'sales_target')::numeric, 0)) * 30, 30) ELSE 0 END +
            CASE WHEN ((d->'visits'->>'total')::int) > 0 THEN LEAST(((d->'visits'->>'successful')::numeric / NULLIF((d->'visits'->>'total')::numeric, 0)) * 20, 20) ELSE 0 END +
            CASE WHEN ((d->'customers'->>'new_count')::int) > 0 THEN LEAST(((d->'customers'->>'new_count')::int * 5)::numeric, 10) ELSE 0 END
        ) AS score
    ) AS scores;

    -- Top performer
    SELECT jsonb_build_object('employee_id', d->>'employee_id', 'name', d->>'name', 'score', (d->>'performance_score')::numeric)
    INTO v_top
    FROM jsonb_array_elements(COALESCE(v_emp_list, '[]'::jsonb)) AS d
    ORDER BY (d->>'performance_score')::numeric DESC LIMIT 1;

    -- Worst performer
    SELECT jsonb_build_object('employee_id', d->>'employee_id', 'name', d->>'name', 'score', (d->>'performance_score')::numeric)
    INTO v_worst
    FROM jsonb_array_elements(COALESCE(v_emp_list, '[]'::jsonb)) AS d
    ORDER BY (d->>'performance_score')::numeric ASC LIMIT 1;

    v_summary := jsonb_build_object(
        'total_employees', COALESCE(jsonb_array_length(v_emp_list), 0),
        'total_sales', v_total_sales,
        'total_orders', v_total_orders,
        'total_visits', v_total_visits,
        'avg_performance_score', COALESCE(v_avg_score, 0),
        'top_performer', v_top,
        'worst_performer', COALESCE(v_worst, jsonb_build_object('score', 0))
    );

    RETURN jsonb_build_object('employees', COALESCE(v_emp_list, '[]'::jsonb), 'summary', v_summary);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_stale_sessions(p_token uuid, p_min_hours integer DEFAULT 16)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.check_capability(p_token, 'attendance.view_all') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT jsonb_agg(jsonb_build_object(
        'session_id', wds.id,
        'employee_id', e.id,
        'employee_name', e.full_name,
        'employee_code', e.code,
        'date', wds.date,
        'start_time', wds.start_time,
        'hours_open', ROUND(EXTRACT(EPOCH FROM (now() - wds.start_time)) / 3600, 1),
        'status', wds.status
    ) ORDER BY wds.start_time DESC)
    INTO v_result
    FROM public.workday_sessions wds
    JOIN public.employees e ON e.id = wds.employee_id
    WHERE wds.status = 'active'
      AND EXTRACT(EPOCH FROM (now() - wds.start_time)) / 3600 > p_min_hours;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_statistical_orders(p_token text, p_search text DEFAULT NULL::text, p_customer_id uuid DEFAULT NULL::uuid, p_owner_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid := p_token::uuid;
  v_session app.sessions;
  v_visible uuid[];
  v_is_super boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;

  IF v_session.identity_type = 'customer' THEN
    RETURN '[]'::jsonb;
  END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_visible := COALESCE(public.get_visible_employee_ids(v_token), '{}'::uuid[]);

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'status', o.status,
        'delivery_mode', o.delivery_mode,
        'payment_method', o.payment_method,
        'order_type', o.order_type,
        'total_amount', o.total_amount,
        'revision_number', o.revision_number,
        'customer_id', o.customer_id,
        'customer_name', COALESCE(o.snapshot_customer_name, c.company_name),
        'customer_code', o.snapshot_customer_code,
        'customer_phone', COALESCE(o.snapshot_customer_phone, ci.phone),
        'owner_name', e.full_name,
        'owner_id', o.owner_id,
        'created_by', o.created_by,
        'created_by_name', COALESCE(o.snapshot_sender_name, oc_emp.full_name, oc_cust.company_name, ''),
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'submitted_at', o.submitted_at,
        'approved_at', o.approved_at,
        'notes', o.notes,
        'item_count', (SELECT count(*) FROM public.order_items oi WHERE oi.order_id = o.id),
        'items', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', oi.id,
            'product_id', oi.product_id,
            'product_name', p.product_name,
            'legacy_code', p.legacy_code,
            'image_url', p.image_url,
            'company_id', p.company_id,
            'company_name', comp.company_name,
            'unit_type', oi.unit_type,
            'unit_quantity', oi.unit_quantity,
            'piece_quantity', oi.piece_quantity,
            'unit_price', oi.unit_price,
            'total_price', oi.total_price
          ) ORDER BY oi.id)
          FROM public.order_items oi
          LEFT JOIN public.products p ON p.id = oi.product_id
          LEFT JOIN public.companies comp ON comp.id = p.company_id
          WHERE oi.order_id = o.id
        ), '[]'::jsonb),
        'current_delivery_status', (
          SELECT dt.status FROM public.delivery_tracking dt
          WHERE dt.order_id = o.id AND dt.is_active = true LIMIT 1
        ),
        'customer_owner_name', COALESCE(co_emp.full_name, ''),
        'customer_owner_role', COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = c.owner_id LIMIT 1), ''),
        'customer_owner_id', c.owner_id,
        'created_by_id', CASE
          WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
          WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
          ELSE NULL
        END,
        'created_by_type', oc_i.identity_type
      )
      ORDER BY o.created_at DESC
    ), '[]'::jsonb)
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    LEFT JOIN public.identities ci ON ci.id = c.identity_id
    LEFT JOIN public.employees co_emp ON co_emp.id = c.owner_id
    LEFT JOIN public.employees e ON e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    WHERE public.is_order_in_statistics(o.status)
      AND (v_is_super OR c.owner_id = ANY(v_visible))
      AND (p_search IS NULL OR
           o.order_number ILIKE '%' || p_search || '%' OR
           c.company_name ILIKE '%' || p_search || '%' OR
           o.snapshot_customer_name ILIKE '%' || p_search || '%')
      AND (p_owner_id IS NULL OR o.owner_id = p_owner_id)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_supervisor_dashboard(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp_id uuid;
  v_identity_id uuid;
  v_subtree_ids uuid[];
  v_identity_ids uuid[];
  v_target_month int;
  v_target_year int;

  -- Team summary
  v_member_count int;
  v_customer_count int;

  -- Orders (identity_id based)
  v_month_orders int;
  v_month_sales numeric;
  v_month_visits int;
  v_today_orders int;
  v_today_sales numeric;
  v_today_visits int;

  -- Visits (employee_id based)
  v_active_visits int;

  -- Collections (employee_id based)
  v_pending_collections int;

  -- New customers this month (employee_id based)
  v_new_customers_month int;

  -- Per-member data
  v_member_record record;
  v_members jsonb := '[]'::jsonb;

  -- Team targets
  v_team_sales_target numeric := 0;
  v_team_visits_target numeric := 0;
  v_team_orders_target numeric := 0;
  v_team_new_customers_target numeric := 0;
  v_team_sales_achievement numeric := 0;
  v_team_visits_achievement int := 0;
  v_team_orders_achievement int := 0;
  v_team_new_customers_achievement int := 0;

  -- Personal summary
  v_personal_customer_count int;
  v_personal_month_orders int;
  v_personal_month_sales numeric;
  v_personal_today_orders int;
  v_personal_active_visits int;
  v_personal_today_visits int;
  v_personal_month_visits int;
  v_personal_pending_collections int;

  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  v_emp_id := v_session.employee_id;
  v_identity_id := v_session.identity_id;

  v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
  v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);

  -- Get subtree employee IDs
  v_subtree_ids := app.get_subtree_ids(v_emp_id);

  -- Get corresponding identity IDs for orders queries
  SELECT COALESCE(array_agg(identity_id), '{}'::uuid[])
  INTO v_identity_ids
  FROM public.employees
  WHERE id = ANY(v_subtree_ids);

  -- ── Team summary ──

  SELECT count(*) INTO v_member_count FROM unnest(v_subtree_ids);

  SELECT count(*) INTO v_customer_count
  FROM public.customers
  WHERE owner_id = ANY(v_subtree_ids) AND is_active = true;

  SELECT count(*) INTO v_active_visits
  FROM public.visits
  WHERE employee_id = ANY(v_subtree_ids) AND status = 'active';

  SELECT count(*) INTO v_today_visits
  FROM public.visits
  WHERE employee_id = ANY(v_subtree_ids) AND created_at >= CURRENT_DATE;

  SELECT count(*), COALESCE(sum(total_amount), 0)
  INTO v_month_orders, v_month_sales
  FROM public.orders
  WHERE created_by = ANY(v_identity_ids)
    AND created_at >= date_trunc('month', CURRENT_DATE)
    AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

  SELECT count(*), COALESCE(sum(total_amount), 0)
  INTO v_today_orders, v_today_sales
  FROM public.orders
  WHERE created_by = ANY(v_identity_ids)
    AND created_at >= CURRENT_DATE;

  SELECT count(*) INTO v_month_visits
  FROM public.visits
  WHERE employee_id = ANY(v_subtree_ids)
    AND created_at >= date_trunc('month', CURRENT_DATE)
    AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

  SELECT count(*) INTO v_pending_collections
  FROM public.collections
  WHERE created_by = ANY(v_subtree_ids) AND status = 'pending';

  SELECT count(*) INTO v_new_customers_month
  FROM public.customers
  WHERE owner_id = ANY(v_subtree_ids)
    AND created_at >= date_trunc('month', CURRENT_DATE)
    AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

  -- ── Per-member performance ──

  FOR v_member_record IN
    SELECT
      e.id,
      e.code,
      e.full_name,
      e.identity_id
    FROM public.employees e
    WHERE e.id = ANY(v_subtree_ids)
      AND e.is_active = true
    ORDER BY e.full_name
  LOOP
    DECLARE
      v_mem_customer_count int;
      v_mem_month_orders int;
      v_mem_month_sales numeric;
      v_mem_today_orders int;
      v_mem_today_visits int;
      v_mem_month_visits int;
      v_mem_sales_target numeric;
      v_mem_visits_target numeric;
      v_mem_orders_target numeric;
      v_mem_new_customers_target numeric;
      v_mem_achievement_pct numeric;
    BEGIN
      SELECT count(*) INTO v_mem_customer_count
      FROM public.customers
      WHERE owner_id = v_member_record.id AND is_active = true;

      SELECT count(*), COALESCE(sum(total_amount), 0)
      INTO v_mem_month_orders, v_mem_month_sales
      FROM public.orders
      WHERE created_by = v_member_record.identity_id
        AND created_at >= date_trunc('month', CURRENT_DATE)
        AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

      SELECT count(*) INTO v_mem_today_orders
      FROM public.orders
      WHERE created_by = v_member_record.identity_id
        AND created_at >= CURRENT_DATE;

      SELECT count(*) INTO v_mem_today_visits
      FROM public.visits
      WHERE employee_id = v_member_record.id
        AND created_at >= CURRENT_DATE;

      SELECT count(*) INTO v_mem_month_visits
      FROM public.visits
      WHERE employee_id = v_member_record.id
        AND created_at >= date_trunc('month', CURRENT_DATE)
        AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

      SELECT
        COALESCE(sales_target, 0),
        COALESCE(visits_target, 0),
        COALESCE(orders_target, 0),
        COALESCE(new_customers_target, 0)
      INTO
        v_mem_sales_target,
        v_mem_visits_target,
        v_mem_orders_target,
        v_mem_new_customers_target
      FROM public.employee_monthly_targets
      WHERE employee_id = v_member_record.id
        AND target_month = v_target_month
        AND target_year = v_target_year;

      IF v_mem_sales_target > 0 THEN
        v_mem_achievement_pct := ROUND((v_mem_month_sales / v_mem_sales_target * 100)::numeric, 1);
      ELSE
        v_mem_achievement_pct := 0;
      END IF;

      v_members := v_members || jsonb_build_object(
        'employee_id', v_member_record.id,
        'employee_code', v_member_record.code,
        'employee_name', v_member_record.full_name,
        'customer_count', v_mem_customer_count,
        'month_orders', v_mem_month_orders,
        'month_sales', v_mem_month_sales,
        'today_orders', v_mem_today_orders,
        'today_visits', v_mem_today_visits,
        'month_visits', v_mem_month_visits,
        'sales_target', v_mem_sales_target,
        'visits_target', v_mem_visits_target,
        'orders_target', v_mem_orders_target,
        'new_customers_target', v_mem_new_customers_target,
        'achievement_pct', v_mem_achievement_pct
      );

      -- Accumulate team targets
      v_team_sales_target := v_team_sales_target + COALESCE(v_mem_sales_target, 0);
      v_team_visits_target := v_team_visits_target + COALESCE(v_mem_visits_target, 0);
      v_team_orders_target := v_team_orders_target + COALESCE(v_mem_orders_target, 0);
      v_team_new_customers_target := v_team_new_customers_target + COALESCE(v_mem_new_customers_target, 0);

      v_team_sales_achievement := v_team_sales_achievement + v_mem_month_sales;
      v_team_visits_achievement := v_team_visits_achievement + v_mem_month_visits;
      v_team_orders_achievement := v_team_orders_achievement + v_mem_month_orders;
      v_team_new_customers_achievement := v_team_new_customers_achievement + COALESCE(v_mem_new_customers_target, 0);
    END;
  END LOOP;

  -- ── Personal summary (supervisor's own data) ──

  SELECT count(*) INTO v_personal_customer_count
  FROM public.customers
  WHERE owner_id = v_emp_id AND is_active = true;

  SELECT count(*), COALESCE(sum(total_amount), 0)
  INTO v_personal_month_orders, v_personal_month_sales
  FROM public.orders
  WHERE created_by = v_identity_id
    AND created_at >= date_trunc('month', CURRENT_DATE)
    AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

  SELECT count(*) INTO v_personal_today_orders
  FROM public.orders
  WHERE created_by = v_identity_id AND created_at >= CURRENT_DATE;

  SELECT count(*) INTO v_personal_active_visits
  FROM public.visits
  WHERE employee_id = v_emp_id AND status = 'active';

  SELECT count(*) INTO v_personal_today_visits
  FROM public.visits
  WHERE employee_id = v_emp_id AND created_at >= CURRENT_DATE;

  SELECT count(*) INTO v_personal_month_visits
  FROM public.visits
  WHERE employee_id = v_emp_id
    AND created_at >= date_trunc('month', CURRENT_DATE)
    AND created_at < date_trunc('month', CURRENT_DATE) + interval '1 month';

  SELECT count(*) INTO v_personal_pending_collections
  FROM public.collections
  WHERE created_by = v_emp_id AND status = 'pending';

  -- ── Build result ──

  v_result := jsonb_build_object(
    'team_summary', jsonb_build_object(
      'member_count', v_member_count,
      'customer_count', v_customer_count,
      'active_visits', v_active_visits,
      'today_visits', v_today_visits,
      'month_visits', v_month_visits,
      'today_orders', v_today_orders,
      'today_sales', v_today_sales,
      'month_orders', v_month_orders,
      'month_sales', v_month_sales,
      'pending_collections', v_pending_collections,
      'new_customers_month', v_new_customers_month
    ),
    'members', COALESCE(v_members, '[]'::jsonb),
    'team_targets', jsonb_build_object(
      'sales_target', v_team_sales_target,
      'visits_target', v_team_visits_target,
      'orders_target', v_team_orders_target,
      'new_customers_target', v_team_new_customers_target,
      'sales_achievement', v_team_sales_achievement,
      'visits_achievement', v_team_visits_achievement,
      'orders_achievement', v_team_orders_achievement,
      'new_customers_achievement', v_team_new_customers_achievement,
      'sales_achievement_pct', CASE WHEN v_team_sales_target > 0 THEN ROUND((v_team_sales_achievement / v_team_sales_target * 100)::numeric, 1) ELSE 0 END,
      'visits_achievement_pct', CASE WHEN v_team_visits_target > 0 THEN ROUND((v_team_visits_achievement::numeric / v_team_visits_target * 100)::numeric, 1) ELSE 0 END,
      'orders_achievement_pct', CASE WHEN v_team_orders_target > 0 THEN ROUND((v_team_orders_achievement::numeric / v_team_orders_target * 100)::numeric, 1) ELSE 0 END,
      'new_customers_achievement_pct', CASE WHEN v_team_new_customers_target > 0 THEN ROUND((v_team_new_customers_achievement::numeric / v_team_new_customers_target * 100)::numeric, 1) ELSE 0 END
    ),
    'personal_summary', jsonb_build_object(
      'customer_count', v_personal_customer_count,
      'month_orders', v_personal_month_orders,
      'month_sales', v_personal_month_sales,
      'today_orders', v_personal_today_orders,
      'active_visits', v_personal_active_visits,
      'today_visits', v_personal_today_visits,
      'month_visits', v_personal_month_visits,
      'pending_collections', v_personal_pending_collections
    )
  );

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_team_map(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_interval_seconds int;
    v_subtree_ids uuid[];
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'attendance.view_team_map') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    IF public.check_capability(p_token, 'attendance.view_all') THEN
        v_subtree_ids := NULL;
    ELSE
        v_subtree_ids := app.get_subtree_ids(v_session.employee_id);
    END IF;
    SELECT location_interval_seconds INTO v_interval_seconds FROM public.workday_settings LIMIT 1;
    v_interval_seconds := COALESCE(v_interval_seconds, 300);

    WITH filtered_employees AS (
        SELECT e.id FROM public.employees e WHERE e.is_active = true
        AND (v_subtree_ids IS NULL OR e.id = ANY(v_subtree_ids))
        AND NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id AND ewp.attendance_enabled = false)
    ),
    active_sessions AS (
        SELECT wds.id, wds.employee_id, wds.start_time, wds.status,
            wds.last_seen_at, e.full_name AS employee_name
        FROM public.workday_sessions wds
        JOIN public.employees e ON e.id = wds.employee_id
        WHERE wds.date = CURRENT_DATE AND wds.status = 'active'
        AND (v_subtree_ids IS NULL OR wds.employee_id = ANY(v_subtree_ids))
    ),
    -- ============================================================
    -- 5 sources of activity + combined + last_activity
    -- ============================================================
    session_activity AS (
        SELECT ws.employee_id, ws.last_seen_at AS activity_at,
            'heartbeat'::text AS activity_type
        FROM active_sessions ws WHERE ws.last_seen_at IS NOT NULL
    ),
    tracking_activity AS (
        SELECT DISTINCT ON (tp.employee_id)
            tp.employee_id, tp.recorded_at AS activity_at,
            'gps'::text AS activity_type
        FROM public.tracking_points tp WHERE tp.recorded_at >= CURRENT_DATE
        ORDER BY tp.employee_id, tp.recorded_at DESC
    ),
    visit_activity AS (
        SELECT v.employee_id, MAX(v.check_in_at) AS activity_at,
            'visit'::text AS activity_type
        FROM public.visits v WHERE v.check_in_at::date = CURRENT_DATE
        GROUP BY v.employee_id
    ),
    order_activity AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            MAX(o.created_at) AS activity_at,
            'order'::text AS activity_type
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    collection_activity AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            MAX(c.created_at) AS activity_at,
            'collection'::text AS activity_type
        FROM public.collections c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    combined_activity AS (
        SELECT employee_id, activity_at, activity_type FROM session_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM tracking_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM visit_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM order_activity
        UNION ALL
        SELECT employee_id, activity_at, activity_type FROM collection_activity
    ),
    last_activity AS (
        SELECT DISTINCT ON (employee_id)
            employee_id, activity_at AS last_activity_at,
            activity_type AS last_activity_type
        FROM combined_activity
        ORDER BY employee_id, activity_at DESC NULLS LAST
    ),
    -- ============================================================
    -- Last GPS position (separate)
    -- ============================================================
    last_location AS (
        SELECT DISTINCT ON (tp.employee_id)
            tp.employee_id, tp.latitude, tp.longitude,
            tp.recorded_at AS last_location_at, tp.accuracy_meters
        FROM public.tracking_points tp
        WHERE tp.recorded_at >= CURRENT_DATE
          AND tp.latitude IS NOT NULL AND tp.longitude IS NOT NULL
        ORDER BY tp.employee_id, tp.recorded_at DESC
    ),
    -- ============================================================
    -- Existing CTEs (unchanged)
    -- ============================================================
    active_breaks AS (
        SELECT wb.session_id, wb.employee_id FROM public.workday_breaks wb WHERE wb.break_end IS NULL
    ),
    today_orders AS (
        SELECT public.resolve_employee_id(o.owner_id) AS employee_id,
            COUNT(*)::int AS order_count,
            COALESCE(SUM(o.total_amount), 0) AS sales_value
        FROM public.orders o WHERE o.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(o.owner_id)
    ),
    today_collections AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS collection_count,
            COALESCE(SUM(c.amount), 0) AS collection_amount
        FROM public.collections c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    today_customers AS (
        SELECT public.resolve_employee_id(c.owner_id) AS employee_id,
            COUNT(*)::int AS new_customer_count
        FROM public.customers c WHERE c.created_at::date = CURRENT_DATE
        GROUP BY public.resolve_employee_id(c.owner_id)
    ),
    today_visits AS (
        SELECT v.employee_id, COUNT(*)::int AS visit_count
        FROM public.visits v WHERE v.check_in_at::date = CURRENT_DATE GROUP BY v.employee_id
    )
    SELECT jsonb_build_object(
        'counters', jsonb_build_object(
            'active', (SELECT COUNT(*) FROM active_sessions),
            'on_break', (SELECT COUNT(DISTINCT ab.employee_id) FROM active_sessions as2 JOIN active_breaks ab ON ab.session_id = as2.id),
            'on_visit', (SELECT COUNT(*) FROM active_sessions as2 WHERE EXISTS (SELECT 1 FROM public.visits v2 WHERE v2.employee_id = as2.employee_id AND v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL)),
            'not_started', (SELECT COUNT(*) FROM filtered_employees fe WHERE fe.id NOT IN (SELECT employee_id FROM active_sessions) AND fe.id NOT IN (SELECT employee_id FROM public.workday_sessions WHERE date = CURRENT_DATE AND status = 'completed')),
            -- connection_lost now uses last_activity_at (not tracking_points)
            'connection_lost', (SELECT COUNT(*) FROM active_sessions as2
                LEFT JOIN last_activity la ON la.employee_id = as2.employee_id
                WHERE la.last_activity_at IS NULL
                   OR la.last_activity_at < now() - ((v_interval_seconds * 5) || ' seconds')::interval),
            'zero_visits_today', (SELECT COUNT(*) FROM active_sessions as2 LEFT JOIN today_visits tv2 ON tv2.employee_id = as2.employee_id WHERE COALESCE(tv2.visit_count, 0) = 0),
            'zero_orders_today', (SELECT COUNT(*) FROM active_sessions as2 LEFT JOIN today_orders too2 ON too2.employee_id = as2.employee_id WHERE COALESCE(too2.order_count, 0) = 0),
            -- inactive_over_2h now uses last_activity_at
            'inactive_over_2h', (SELECT COUNT(*) FROM active_sessions as2
                LEFT JOIN last_activity la2 ON la2.employee_id = as2.employee_id
                WHERE EXTRACT(EPOCH FROM (now() - as2.start_time)) / 3600 > 2
                  AND (la2.last_activity_at IS NULL OR la2.last_activity_at < now() - interval '30 minutes'))
        ),
        'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', as2.employee_id, 'name', as2.employee_name,
            'role_name', COALESCE(role_info.name, ''),
            'status', CASE WHEN ab.employee_id IS NOT NULL THEN 'on_break'
                           WHEN vl.employee_id IS NOT NULL THEN 'on_visit'
                           ELSE 'working' END,
            -- connection_status from last_activity_at
            'connection_status', CASE WHEN la.last_activity_at IS NULL THEN 'no_data'
                 WHEN la.last_activity_at > now() - (v_interval_seconds || ' seconds')::interval THEN 'connected'
                 WHEN la.last_activity_at > now() - ((v_interval_seconds * 5) || ' seconds')::interval THEN 'delayed'
                 ELSE 'lost' END,
            -- GPS position from last_location (separate)
            'latitude', ll.latitude, 'longitude', ll.longitude,
            -- Backward-compat last_seen_at
            'last_seen_at', CASE
                WHEN la.last_activity_at IS NOT NULL AND ll.last_location_at IS NOT NULL
                    THEN GREATEST(la.last_activity_at, ll.last_location_at)
                WHEN la.last_activity_at IS NOT NULL THEN la.last_activity_at
                WHEN ll.last_location_at IS NOT NULL THEN ll.last_location_at
                ELSE NULL END,
            -- NEW: separate activity and location fields
            'last_activity_at', la.last_activity_at,
            'last_activity_type', la.last_activity_type,
            'last_location_at', ll.last_location_at,
            'duration_minutes', EXTRACT(EPOCH FROM (now() - as2.start_time)) / 60,
            'order_count', COALESCE(too.order_count, 0), 'sales_value', COALESCE(too.sales_value, 0),
            'collection_count', COALESCE(tco.collection_count, 0), 'collection_amount', COALESCE(tco.collection_amount, 0),
            'new_customer_count', COALESCE(tc.new_customer_count, 0),
            'visit_count', COALESCE(tv.visit_count, 0)
        )) FROM active_sessions as2
        LEFT JOIN active_breaks ab ON ab.session_id = as2.id
        LEFT JOIN LATERAL (SELECT v2.id, v2.employee_id FROM public.visits v2 WHERE v2.employee_id = as2.employee_id AND v2.check_in_at::date = CURRENT_DATE AND v2.check_out_at IS NULL LIMIT 1) vl ON true
        LEFT JOIN last_activity la ON la.employee_id = as2.employee_id
        LEFT JOIN last_location ll ON ll.employee_id = as2.employee_id
        LEFT JOIN today_orders too ON too.employee_id = as2.employee_id
        LEFT JOIN today_collections tco ON tco.employee_id = as2.employee_id
        LEFT JOIN today_customers tc ON tc.employee_id = as2.employee_id
        LEFT JOIN today_visits tv ON tv.employee_id = as2.employee_id
        LEFT JOIN LATERAL (
            SELECT r.name FROM public.employee_roles er
            JOIN public.roles r ON r.id = er.role_id
            WHERE er.employee_id = as2.employee_id LIMIT 1
        ) role_info ON true), '[]'::jsonb)
    ) INTO v_result;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_team_members_kpis(p_token uuid, p_manager_id uuid, p_kpi_type text, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_target_month int; v_target_year int;
  v_month_start timestamptz; v_month_end timestamptz;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
  v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);
  v_month_start := date_trunc('month', make_date(v_target_year, v_target_month, 1));
  v_month_end := v_month_start + INTERVAL '1 month';
  WITH delivered_orders AS (
    SELECT o.*, COALESCE(emp.id, emp2.id) AS resolved_employee_id
    FROM public.orders o LEFT JOIN public.employees emp ON o.owner_id = emp.id LEFT JOIN public.employees emp2 ON o.owner_id = emp2.identity_id
    WHERE o.status = 'delivered' AND o.delivered_at >= v_month_start AND o.delivered_at < v_month_end
  ), completed_visits AS (
    SELECT * FROM public.visits v WHERE v.status = 'completed' AND v.check_out_at >= v_month_start AND v.check_out_at < v_month_end
  ), emp_orders AS (
    SELECT resolved_employee_id AS employee_id, COUNT(DISTINCT id)::int AS order_count, COALESCE(SUM(total_amount), 0) AS sales_amount
    FROM delivered_orders GROUP BY resolved_employee_id
  ), emp_visits AS (
    SELECT employee_id, COUNT(*)::int AS visit_count FROM completed_visits GROUP BY employee_id
  ), emp_new_customers AS (
    SELECT resolved_employee_id AS employee_id, COUNT(DISTINCT customer_id)::int AS new_customer_count
    FROM delivered_orders do2 WHERE do2.delivered_at = (SELECT MIN(o3.delivered_at) FROM public.orders o3 WHERE o3.customer_id = do2.customer_id AND o3.status = 'delivered')
    GROUP BY resolved_employee_id
  ), approved_returns AS (
    SELECT r.*, o.resolved_employee_id FROM public.returns r JOIN delivered_orders o ON o.id = r.order_id
    WHERE r.status = 'approved' AND r.created_at >= v_month_start AND r.created_at < v_month_end
  ), emp_returns AS (
    SELECT resolved_employee_id AS employee_id, COALESCE(SUM(credit_note_amount), 0) AS return_deduction,
      COUNT(DISTINCT CASE WHEN fr.order_id IS NOT NULL THEN r.order_id END)::int AS full_returns
    FROM approved_returns r LEFT JOIN (
      SELECT r2.order_id FROM public.returns r2 JOIN public.return_items ri ON ri.return_id = r2.id JOIN public.products p ON p.id = ri.product_id
      JOIN (SELECT oi2.order_id, SUM(oi2.piece_quantity) AS total_pieces FROM public.order_items oi2 GROUP BY oi2.order_id) oi3 ON oi3.order_id = r2.order_id
      WHERE r2.status = 'approved' AND r2.created_at >= v_month_start AND r2.created_at < v_month_end
      GROUP BY r2.order_id, oi3.total_pieces
      HAVING SUM(CASE WHEN ri.unit_type = 'piece' THEN ri.quantity WHEN ri.unit_type = 'dozen' THEN ri.quantity * 12 WHEN ri.unit_type = 'carton' THEN ri.quantity * p.carton_quantity END) >= oi3.total_pieces
    ) fr ON fr.order_id = r.order_id
    GROUP BY resolved_employee_id
  ), personal_kpis AS (
    SELECT e.id AS employee_id, e.code, e.full_name,
      COALESCE(emt.sales_target, 0) AS sales_target, COALESCE(emt.visits_target, 0) AS visits_target,
      COALESCE(emt.orders_target, 0) AS orders_target, COALESCE(emt.new_customers_target, 0) AS new_customers_target,
      GREATEST(COALESCE(eo.sales_amount, 0) - COALESCE(er.return_deduction, 0), 0) AS personal_sales,
      COALESCE(ev.visit_count, 0) AS personal_visits,
      GREATEST(COALESCE(eo.order_count, 0) - COALESCE(er.full_returns, 0), 0) AS personal_orders,
      COALESCE(enc.new_customer_count, 0) AS personal_new_customers,
      EXISTS (SELECT 1 FROM public.employees sub WHERE sub.manager_id = e.id AND sub.is_active = true) AS has_team
    FROM public.employees e
    LEFT JOIN public.employee_monthly_targets emt ON emt.employee_id = e.id AND emt.target_month = v_target_month AND emt.target_year = v_target_year
    LEFT JOIN emp_orders eo ON eo.employee_id = e.id LEFT JOIN emp_visits ev ON ev.employee_id = e.id
    LEFT JOIN emp_new_customers enc ON enc.employee_id = e.id LEFT JOIN emp_returns er ON er.employee_id = e.id
    WHERE e.is_active = true AND e.manager_id = p_manager_id AND (emt.id IS NOT NULL OR COALESCE(eo.sales_amount, 0) > 0 OR COALESCE(ev.visit_count, 0) > 0 OR COALESCE(enc.new_customer_count, 0) > 0 OR COALESCE(eo.order_count, 0) > 0)
  )
  SELECT jsonb_agg(jsonb_build_object(
    'employee_id', pk.employee_id, 'employee_code', pk.code, 'employee_name', pk.full_name, 'has_team', pk.has_team,
    'actual', CASE p_kpi_type WHEN 'sales' THEN pk.personal_sales WHEN 'orders' THEN pk.personal_orders WHEN 'visits' THEN pk.personal_visits WHEN 'new_customers' THEN pk.personal_new_customers ELSE 0 END,
    'target', CASE p_kpi_type WHEN 'sales' THEN pk.sales_target WHEN 'orders' THEN pk.orders_target WHEN 'visits' THEN pk.visits_target WHEN 'new_customers' THEN pk.new_customers_target ELSE 0 END,
    'achievement_pct', ROUND(CASE WHEN CASE p_kpi_type WHEN 'sales' THEN pk.sales_target WHEN 'orders' THEN pk.orders_target WHEN 'visits' THEN pk.visits_target WHEN 'new_customers' THEN pk.new_customers_target ELSE 0 END > 0
      THEN (CASE p_kpi_type WHEN 'sales' THEN pk.personal_sales WHEN 'orders' THEN pk.personal_orders WHEN 'visits' THEN pk.personal_visits WHEN 'new_customers' THEN pk.personal_new_customers ELSE 0 END::numeric / CASE p_kpi_type WHEN 'sales' THEN pk.sales_target WHEN 'orders' THEN pk.orders_target WHEN 'visits' THEN pk.visits_target WHEN 'new_customers' THEN pk.new_customers_target ELSE 1 END::numeric * 100) ELSE 0 END, 2)
  ) ORDER BY pk.full_name) INTO v_result
  FROM personal_kpis pk;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_tracking_session_stats(p_token uuid, p_employee_id uuid DEFAULT NULL::uuid, p_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(employee_id uuid, employee_code text, employee_name text, session_id uuid, session_date date, start_time timestamp with time zone, end_time timestamp with time zone, duration_minutes integer, expected_points integer, captured_points integer, capture_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

BEGIN
    IF NOT EXISTS (SELECT 1 FROM app.sessions WHERE token = p_token AND expires_at > now()) THEN
        RAISE EXCEPTION 'invalid_token';
    END IF;

    RETURN QUERY
    SELECT
        e.id,
        e.code::text,
        e.full_name::text,
        ws.id,
        ws.date,
        ws.start_time,
        COALESCE(ws.end_time, now()),
        GREATEST(ROUND(EXTRACT(EPOCH FROM (COALESCE(ws.end_time, now()) - ws.start_time)) / 60)::int, 0),
        GREATEST(ROUND(EXTRACT(EPOCH FROM (COALESCE(ws.end_time, now()) - ws.start_time)) / 300)::int, 0),
        COALESCE(tp.cnt, 0)::int,
        CASE
            WHEN GREATEST(ROUND(EXTRACT(EPOCH FROM (COALESCE(ws.end_time, now()) - ws.start_time)) / 300)::int, 0) > 0
            THEN LEAST(ROUND(COALESCE(tp.cnt, 0)::numeric / GREATEST(ROUND(EXTRACT(EPOCH FROM (COALESCE(ws.end_time, now()) - ws.start_time)) / 300)::int, 1) * 100, 1), 100)::numeric
            ELSE 0::numeric
        END
    FROM workday_sessions ws
    JOIN employees e ON e.id = ws.employee_id
    LEFT JOIN LATERAL (
        SELECT COUNT(*) AS cnt
        FROM tracking_points tp
        WHERE tp.session_id = ws.id
    ) tp ON true
    WHERE (p_employee_id IS NULL OR ws.employee_id = p_employee_id)
      AND ws.date = p_date
    ORDER BY ws.start_time;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_unified_order(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid := p_token::uuid;
  v_session app.sessions;
  v_order public.orders;
  v_visible uuid[];
  v_is_super boolean;
  v_customer_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  IF v_session.identity_type = 'customer' THEN
    IF v_order.customer_id != v_session.customer_id THEN
      RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
  ELSE
    v_is_super := public.is_upper_management(v_session.employee_id);
    IF NOT v_is_super THEN
      v_visible := COALESCE(public.get_visible_employee_ids(v_token), '{}'::uuid[]);
      IF NOT EXISTS (
        SELECT 1 FROM public.customers c
        WHERE c.id = v_order.customer_id AND c.owner_id = ANY(v_visible)
      ) THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
      END IF;
    END IF;
  END IF;

  v_customer_id := v_order.customer_id;

  RETURN (
    SELECT jsonb_build_object(
      'order', (
        SELECT jsonb_build_object(
          'id', o.id,
          'order_number', o.order_number,
          'status', o.status,
          'delivery_mode', o.delivery_mode,
          'payment_method', o.payment_method,
          'subtotal', o.subtotal,
          'discount_amount', o.discount_amount,
          'tax_amount', o.tax_amount,
          'total_amount', o.total_amount,
          'notes', o.notes,
          'revision_number', o.revision_number,
          'last_revised_at', o.last_revised_at,
          'customer_id', o.customer_id,
          'owner_type', o.owner_type,
          'owner_id', o.owner_id,
          'created_by', o.created_by,
          'submitted_at', o.submitted_at,
          'approved_at', o.approved_at,
          'delivered_at', o.delivered_at,
          'cancelled_at', o.cancelled_at,
          'created_at', o.created_at,
          'updated_at', o.updated_at,
          'deferred_until', o.deferred_until,
          'defer_reason', o.defer_reason,
          'cancel_reason', o.cancel_reason,
          'execution_latitude', o.execution_latitude,
          'execution_longitude', o.execution_longitude,
          'execution_accuracy_meters', o.execution_accuracy_meters,
          'execution_captured_at', o.execution_captured_at,
          'execution_location_id', o.execution_location_id,
          'tier_id', o.tier_id,
          'effective_discount_percent', o.effective_discount_percent,
          'snapshot_customer_name', o.snapshot_customer_name,
          'snapshot_customer_phone', o.snapshot_customer_phone,
          'snapshot_customer_address', o.snapshot_customer_address,
          'snapshot_customer_code', o.snapshot_customer_code,
          'snapshot_owner_name', o.snapshot_owner_name,
          'snapshot_owner_phone', o.snapshot_owner_phone,
          'snapshot_owner_address', o.snapshot_owner_address,
          'snapshot_sender_name', o.snapshot_sender_name,
          'snapshot_sender_phone', o.snapshot_sender_phone,
          'snapshot_sender_address', o.snapshot_sender_address,
          'reference_number', o.reference_number
        )
        || jsonb_build_object(
          'customer_owner_name', COALESCE(co_emp.full_name, ''),
          'customer_owner_role', COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = c.owner_id LIMIT 1), ''),
          'order_creator_name', COALESCE(oc_emp.full_name, oc_cust.company_name, ''),
          'order_creator_role', CASE
            WHEN oc_i.identity_type = 'employee' THEN COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = oc_emp.id LIMIT 1), '')
            ELSE NULL
          END,
          'customer_owner_id', c.owner_id,
          'order_creator_id', CASE
            WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
            WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
            ELSE NULL
          END,
          'order_creator_type', oc_i.identity_type,
          'current_owner_name', COALESCE(owner_e.full_name, o.snapshot_owner_name, '')
        )
      ),
      'customer', (
        SELECT jsonb_build_object(
          'id', c2.id,
          'code', c2.code,
          'company_name', c2.company_name,
          'phone', i.phone,
          'address_line1', ca.address_line1,
          'address_line2', ca.address_line2,
          'city', ca.city,
          'governorate', ca.governorate,
          'address_latitude', ca.latitude,
          'address_longitude', ca.longitude,
          'display_address',
            COALESCE(
              NULLIF(concat_ws(' - ', ca.address_line1, ca.city, ca.governorate), ''),
              o.snapshot_customer_address
            ),
          'previous_order_count', ps.order_count,
          'previous_orders_total', ps.orders_total,
          'previous_order_number', ps.last_order_number,
          'previous_order_date', ps.last_order_date,
          'previous_order_total', ps.last_order_total
        )
        FROM public.customers c2
        LEFT JOIN public.identities i ON i.id = c2.identity_id
        LEFT JOIN public.customer_addresses ca ON ca.customer_id = c2.id AND ca.is_default = true
        LEFT JOIN LATERAL (
          SELECT
            count(*)::bigint AS order_count,
            COALESCE(sum(total_amount), 0) AS orders_total,
            (array_agg(order_number ORDER BY created_at DESC))[1] AS last_order_number,
            max(created_at) AS last_order_date,
            (array_agg(total_amount ORDER BY created_at DESC))[1] AS last_order_total
          FROM public.orders o2
          WHERE o2.customer_id = c2.id AND o2.id <> o.id
        ) ps ON true
        WHERE c2.id = v_customer_id
        LIMIT 1
      ),
      'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', oi.id,
          'product_id', oi.product_id,
          'product_name', p.product_name,
          'legacy_code', p.legacy_code,
          'image_url', p.image_url,
          'company_id', p.company_id,
          'company_name', comp.company_name,
          'unit_type', oi.unit_type,
          'unit_quantity', oi.unit_quantity,
          'piece_quantity', oi.piece_quantity,
          'unit_price', oi.unit_price,
          'total_price', oi.total_price
        ) ORDER BY oi.id)
        FROM public.order_items oi
        LEFT JOIN public.products p ON p.id = oi.product_id
        LEFT JOIN public.companies comp ON comp.id = p.company_id
        WHERE oi.order_id = o.id
      ), '[]'::jsonb),
      'status_history', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', osh.id,
          'from_status', osh.from_status,
          'to_status', osh.to_status,
          'changed_by', osh.changed_by,
          'changed_by_name', e_changed.full_name,
          'changed_at', osh.changed_at
        ) ORDER BY osh.changed_at)
        FROM public.order_status_history osh
        LEFT JOIN public.employees e_changed ON e_changed.identity_id = osh.changed_by
        WHERE osh.order_id = o.id
      ), '[]'::jsonb),
      'modification_history', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', omh.id,
          'revision_number', omh.revision_number,
          'field_name', omh.field_name,
          'old_value', omh.old_value,
          'new_value', omh.new_value,
          'old_order_items', omh.old_order_items,
          'new_order_items', omh.new_order_items,
          'old_daily_deals', omh.old_daily_deals,
          'new_daily_deals', omh.new_daily_deals,
          'old_flash_offers', omh.old_flash_offers,
          'new_flash_offers', omh.new_flash_offers,
          'modified_by', omh.modified_by,
          'modified_by_name', e_modified.full_name,
          'reason', omh.reason,
          'modified_at', omh.modified_at
        ) ORDER BY omh.modified_at DESC)
        FROM public.order_modification_history omh
        LEFT JOIN public.employees e_modified ON e_modified.identity_id = omh.modified_by
        WHERE omh.order_id = o.id
      ), '[]'::jsonb),
      'current_delivery', (
        SELECT jsonb_build_object(
          'id', dt.id,
          'status', dt.status,
          'attempt_number', dt.attempt_number,
          'assigned_to', dt.assigned_to,
          'assigned_by', dt.assigned_by,
          'assigned_at', dt.assigned_at,
          'started_at', dt.started_at,
          'completed_at', dt.completed_at,
          'failure_reason', dt.failure_reason,
          'failure_notes', dt.failure_notes,
          'notes', dt.notes,
          'returned_at', dt.returned_at,
          'external_carrier_id', dt.external_carrier_id,
          'waybill_number', dt.waybill_number,
          'tracking_url', dt.tracking_url,
          'delivery_mode', o.delivery_mode,
          'assigned_to_name', ast.code,
          'external_carrier_name', ec.name,
          'updated_at', dt.updated_at
        )
        FROM public.delivery_tracking dt
        LEFT JOIN public.employees ast ON ast.id = dt.assigned_to
        LEFT JOIN public.external_carriers ec ON ec.id = dt.external_carrier_id
        WHERE dt.order_id = o.id AND dt.is_active = true
        LIMIT 1
      ),
      'delivery_history', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', dt.id,
          'status', dt.status,
          'attempt_number', dt.attempt_number,
          'is_active', dt.is_active,
          'assigned_to', dt.assigned_to,
          'assigned_by', dt.assigned_by,
          'assigned_at', dt.assigned_at,
          'started_at', dt.started_at,
          'completed_at', dt.completed_at,
          'failure_reason', dt.failure_reason,
          'failure_notes', dt.failure_notes,
          'notes', dt.notes,
          'returned_at', dt.returned_at,
          'external_carrier_id', dt.external_carrier_id,
          'waybill_number', dt.waybill_number,
          'tracking_url', dt.tracking_url,
          'assigned_to_name', ast.code,
          'external_carrier_name', ec.name
        ) ORDER BY dt.attempt_number)
        FROM public.delivery_tracking dt
        LEFT JOIN public.employees ast ON ast.id = dt.assigned_to
        LEFT JOIN public.external_carriers ec ON ec.id = dt.external_carrier_id
        WHERE dt.order_id = o.id
      ), '[]'::jsonb),
      'preparation', (
        SELECT jsonb_build_object(
          'id', pr.id,
          'status', pr.status,
          'started_by', pr.started_by,
          'started_at', pr.started_at,
          'completed_by', pr.completed_by,
          'completed_at', pr.completed_at,
          'reviewed_by', pr.reviewed_by,
          'reviewed_at', pr.reviewed_at,
          'cancelled_by', pr.cancelled_by,
          'cancelled_at', pr.cancelled_at,
          'notes', pr.notes
        )
        FROM public.preparation_records pr
        WHERE pr.order_id = o.id
        ORDER BY pr.created_at DESC
        LIMIT 1
      ),
      'returns', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', r.id,
          'code', r.code,
          'status', r.status,
          'credit_note_amount', r.credit_note_amount,
          'notes', r.notes,
          'created_at', r.created_at
        ) ORDER BY r.created_at)
        FROM public.returns r
        WHERE r.order_id = o.id
      ), '[]'::jsonb),
      'collections', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', col.id,
          'code', col.code,
          'method', col.method,
          'amount', col.amount,
          'status', col.status,
          'reference_number', col.reference_number,
          'collected_at', col.collected_at,
          'order_id', col.order_id
        ) ORDER BY col.created_at)
        FROM public.collections col
        WHERE col.order_id = o.id
           OR (col.customer_id = v_customer_id AND col.order_id IS NULL)
      ), '[]'::jsonb)
    )
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    LEFT JOIN public.employees co_emp ON co_emp.id = c.owner_id
    LEFT JOIN public.employees owner_e ON owner_e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    WHERE o.id = p_id
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_unified_orders(p_token uuid, p_search text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_customer_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_governorate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_is_super boolean;
  v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_is_super := public.is_upper_management(v_session.employee_id);
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'status', o.status,
        'delivery_mode', o.delivery_mode,
        'payment_method', o.payment_method,
        'order_type', o.order_type,
        'total_amount', o.total_amount,
        'revision_number', o.revision_number,
        'reference_number', o.reference_number,
        'customer_id', o.customer_id,
        'customer_name', COALESCE(o.snapshot_customer_name, c.company_name),
        'customer_code', o.snapshot_customer_code,
        'customer_phone', COALESCE(o.snapshot_customer_phone, ci.phone),
        'owner_name', e.full_name,
        'owner_id', o.owner_id,
        'created_by', o.created_by,
        'created_by_name', COALESCE(o.snapshot_sender_name, oc_emp.full_name, oc_cust.company_name, ''),
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'submitted_at', o.submitted_at,
        'item_count', (SELECT count(*) FROM public.order_items oi WHERE oi.order_id = o.id),
        'current_delivery_status', (
          SELECT dt.status FROM public.delivery_tracking dt
          WHERE dt.order_id = o.id AND dt.is_active = true LIMIT 1
        ),
        'has_collections', EXISTS(
          SELECT 1 FROM public.collections col
          WHERE col.customer_id = o.customer_id
        ),
        'customer_owner_name', COALESCE(co_emp.full_name, ''),
        'customer_owner_role', COALESCE((SELECT r.name FROM public.employee_roles er2 JOIN public.roles r ON r.id = er2.role_id WHERE er2.employee_id = c.owner_id LIMIT 1), ''),
        'customer_owner_id', c.owner_id,
        'created_by_id', CASE
          WHEN oc_i.identity_type = 'employee' THEN oc_emp.id
          WHEN oc_i.identity_type = 'customer' THEN oc_cust.id
          ELSE NULL
        END,
        'customer_display_address',
          COALESCE(
            NULLIF(concat_ws(' - ',
              NULLIF(TRIM(ca.governorate), ''),
              NULLIF(TRIM(ca.city), ''),
              NULLIF(TRIM(COALESCE(ca.street_address, ca.address_line1, '')), '')
            ), ''),
            o.snapshot_customer_address
          ),
        'customer_governorate_id', ca.governorate_id,
        'previous_order_count', ps.order_count,
        'previous_orders_total', ps.orders_total,
        'previous_order_number', ps.last_order_number,
        'previous_order_date', ps.last_order_date,
        'previous_order_total', ps.last_order_total
      )
      ORDER BY o.created_at DESC
    ), '[]'::jsonb)
    FROM public.orders o
    JOIN public.customers c ON c.id = o.customer_id
    LEFT JOIN public.identities ci ON ci.id = c.identity_id
    LEFT JOIN public.employees co_emp ON co_emp.id = c.owner_id
    LEFT JOIN public.employees e ON e.id = o.owner_id
    LEFT JOIN public.identities oc_i ON oc_i.id = o.created_by
    LEFT JOIN public.employees oc_emp ON oc_emp.identity_id = oc_i.id AND oc_i.identity_type = 'employee'
    LEFT JOIN public.customers oc_cust ON oc_cust.identity_id = oc_i.id AND oc_i.identity_type = 'customer'
    LEFT JOIN public.customer_addresses ca ON ca.customer_id = c.id AND ca.is_default = true
    LEFT JOIN LATERAL (
      SELECT
        count(*)::bigint AS order_count,
        COALESCE(sum(total_amount), 0) AS orders_total,
        (array_agg(order_number ORDER BY created_at DESC))[1] AS last_order_number,
        max(created_at) AS last_order_date,
        (array_agg(total_amount ORDER BY created_at DESC))[1] AS last_order_total
      FROM public.orders o2
      WHERE o2.customer_id = o.customer_id AND o2.id <> o.id
    ) ps ON true
    WHERE (v_is_super OR c.owner_id = ANY(v_visible))
      AND (p_search IS NULL OR
           o.order_number ILIKE '%' || p_search || '%' OR
           o.reference_number ILIKE '%' || p_search || '%' OR
           c.company_name ILIKE '%' || p_search || '%' OR
           o.snapshot_customer_name ILIKE '%' || p_search || '%' OR
           COALESCE(o.snapshot_customer_phone, ci.phone) ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_created_by IS NULL OR o.created_by = p_created_by)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from)
      AND (p_date_to IS NULL OR o.created_at <= p_date_to)
      AND (p_governorate_id IS NULL OR ca.governorate_id = p_governorate_id)
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_upper_management_dashboard(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_emp_id uuid;
  v_month_start date;
  v_company_id uuid;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(p_token) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;

  v_emp_id := v_session.employee_id;
  v_month_start := date_trunc('month', CURRENT_DATE)::date;

  SELECT company_id INTO v_company_id FROM public.employees WHERE id = v_emp_id;

  WITH
  -- CANONICAL F1/F2: today total orders (unscoped for executive view)
  today_orders_cte AS (
    SELECT order_count AS today_total_orders, sales_value AS today_total_sales
    FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', NULL)
  ),
  -- CANONICAL F1/F2: month total orders (unscoped)
  month_orders_cte AS (
    SELECT order_count AS month_total_orders, sales_value AS month_total_sales
    FROM public.get_kpi_orders_count(v_month_start::timestamptz, (v_month_start + interval '1 month')::timestamptz, NULL)
  ),
  -- today_total_orders (kept for backward compat, now same as today_orders_cte)
  today_total AS (
    SELECT order_count AS val FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', NULL)
  ),
  -- daily_sales_total (kept for backward compat, now same canonical definition)
  daily_sales AS (
    SELECT sales_value AS val FROM public.get_kpi_orders_count(CURRENT_DATE, CURRENT_DATE + interval '1 day', NULL)
  ),
  -- CANONICAL F4: New Customers (Registered — تم تسجيلهم)
  v_new_customers AS (
    SELECT COUNT(*) AS val FROM public.customers WHERE created_at >= v_month_start
  ),
  -- CANONICAL F4: New Customers (First Delivered Order — أول طلب تم تسليمه)
  company_new_customers_actual AS (
    SELECT COUNT(DISTINCT c.id) AS val
    FROM public.customers c
    WHERE EXISTS (
      SELECT 1 FROM public.orders o
      WHERE o.customer_id = c.id
        AND o.status = 'delivered'
        AND o.delivered_at >= v_month_start
    )
  ),
  today_visits_cte AS (
    SELECT COUNT(*) AS val FROM public.visits WHERE created_at >= CURRENT_DATE
  ),
  active_visits_cte AS (
    SELECT COUNT(*) AS val FROM public.visits WHERE status = 'active'
  ),
  company_profile_cte AS (
    SELECT company_name, commercial_registration_no, tax_no, logo_url
    FROM public.company_profile LIMIT 1
  ),
  -- Company monthly targets
  company_targets_cte AS (
    SELECT sales_target, visits_target, orders_target, new_customers_target
    FROM public.company_monthly_targets
    WHERE target_month = EXTRACT(MONTH FROM CURRENT_DATE)::int
      AND target_year = EXTRACT(YEAR FROM CURRENT_DATE)::int
    LIMIT 1
  ),
  -- Top/Bottom performers by sales value (CANONICAL)
  top_reps_cte AS (
    SELECT e.full_name, kpi.sales_value
    FROM public.employees e
    CROSS JOIN LATERAL (
      SELECT sales_value FROM public.get_kpi_orders_count(
        v_month_start::timestamptz,
        (v_month_start + interval '1 month')::timestamptz,
        ARRAY[e.identity_id]
      )
    ) kpi
    WHERE e.is_active = true AND e.manager_id IS NOT NULL
    ORDER BY kpi.sales_value DESC
    LIMIT 5
  ),
  bottom_reps_cte AS (
    SELECT e.full_name, kpi.sales_value
    FROM public.employees e
    CROSS JOIN LATERAL (
      SELECT sales_value FROM public.get_kpi_orders_count(
        v_month_start::timestamptz,
        (v_month_start + interval '1 month')::timestamptz,
        ARRAY[e.identity_id]
      )
    ) kpi
    WHERE e.is_active = true AND e.manager_id IS NOT NULL
    ORDER BY kpi.sales_value ASC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'today_total_orders', (SELECT val FROM today_total),
    'today_total_sales', (SELECT val FROM daily_sales),
    'daily_sales', jsonb_build_object(
      'total', (SELECT val FROM daily_sales),
      'count', (SELECT val FROM today_total)
    ),
    'new_customers', jsonb_build_object(
      -- CANONICAL F4: distinct Arabic labels
      'تم تسجيلهم', (SELECT val FROM v_new_customers),
      'أول طلب تم تسليمه', (SELECT val FROM company_new_customers_actual)
    ),
    'today_visits', (SELECT val FROM today_visits_cte),
    'active_visits', (SELECT val FROM active_visits_cte),
    'today_total_orders_unscoped', (SELECT today_total_orders FROM today_orders_cte),
    'today_total_sales_unscoped', (SELECT today_total_sales FROM today_orders_cte),
    'month_total_orders', (SELECT month_total_orders FROM month_orders_cte),
    'month_total_sales', (SELECT month_total_sales FROM month_orders_cte),
    'company_name', (SELECT company_name FROM company_profile_cte),
    'commercial_registration_no', (SELECT commercial_registration_no FROM company_profile_cte),
    'tax_no', (SELECT tax_no FROM company_profile_cte),
    'logo_url', (SELECT logo_url FROM company_profile_cte),
    'company_targets', COALESCE((SELECT row_to_json(cte.*)::jsonb FROM company_targets_cte cte), '{}'::jsonb),
    'best_performers', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', full_name, 'sales', sales_value)) FROM top_reps_cte), '[]'::jsonb),
    'weakest_performers', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', full_name, 'sales', sales_value)) FROM bottom_reps_cte), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_visible_customer_ids(p_token uuid)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' THEN
    RETURN QUERY SELECT c.id FROM public.customers c WHERE c.identity_id = v_session.identity_id; RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  RETURN QUERY SELECT DISTINCT c.id FROM public.customers c WHERE c.owner_id = ANY(v_visible);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_visible_employee_ids(p_token text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid := p_token::uuid;
  v_session app.sessions;
  v_result uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN '{}'::uuid[]; END IF;
  IF v_session.identity_type = 'customer' THEN RETURN '{}'::uuid[]; END IF;

  IF public.is_upper_management(v_session.employee_id) THEN
    SELECT array_agg(id) INTO v_result FROM employees;
    RETURN COALESCE(v_result, '{}'::uuid[]);
  END IF;

  WITH RECURSIVE subtree AS (
    SELECT id FROM employees WHERE id = v_session.employee_id
    UNION ALL
    SELECT e.id FROM employees e JOIN subtree s ON e.manager_id = s.id
  )
  SELECT array_agg(id) INTO v_result FROM subtree;

  RETURN COALESCE(v_result, '{}'::uuid[]);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_visible_employees(p_token uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN ARRAY[]::uuid[]; END IF;
  IF v_session.identity_type = 'customer' THEN RETURN ARRAY[]::uuid[]; END IF;
  RETURN COALESCE(public.get_visible_employee_ids(p_token), ARRAY[]::uuid[]);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_visit_report(p_token uuid, p_report_type character varying DEFAULT 'rep_activity'::character varying, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF p_report_type = 'customer_coverage' THEN
    WITH t AS (
      SELECT c.id as customer_id, c.company_name as customer_name,
             e.full_name as owner_name,
             COUNT(v.id) as total_visits,
             MAX(v.created_at) as last_visit
      FROM customers c
      LEFT JOIN visits v ON v.customer_id = c.id
        AND (p_date_from IS NULL OR v.created_at >= p_date_from)
        AND (p_date_to IS NULL OR v.created_at <= p_date_to)
      LEFT JOIN employees e ON e.id = c.owner_id
      GROUP BY c.id, c.company_name, e.full_name
    )
    SELECT jsonb_agg(
      jsonb_build_object(
        'customer_id', customer_id, 'customer_name', customer_name,
        'owner_name', owner_name, 'total_visits', total_visits,
        'last_visit', last_visit
      ) ORDER BY total_visits DESC
    ) INTO v_result FROM t;
  ELSE
    WITH t AS (
      SELECT e.id as employee_id, e.full_name as employee_name,
             COUNT(v.id) as total_visits,
             COUNT(v.id) FILTER (WHERE v.status = 'completed') as completed_visits,
             COUNT(v.id) FILTER (WHERE v.status = 'active') as active_visits
      FROM employees e
      LEFT JOIN visits v ON v.employee_id = e.id
        AND (p_date_from IS NULL OR v.created_at >= p_date_from)
        AND (p_date_to IS NULL OR v.created_at <= p_date_to)
      GROUP BY e.id, e.full_name
    )
    SELECT jsonb_agg(
      jsonb_build_object(
        'employee_id', employee_id, 'employee_name', employee_name,
        'total_visits', total_visits, 'completed_visits', completed_visits,
        'active_visits', active_visits
      ) ORDER BY total_visits DESC
    ) INTO v_result FROM t;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_warehouse_analytics(p_token uuid)
 RETURNS TABLE(metric text, value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions; v_visible uuid[]; v_avg_interval interval;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN; END IF;
  IF public.is_upper_management(v_session.employee_id) THEN
    SELECT avg(pr.completed_at - pr.started_at) INTO v_avg_interval FROM public.preparation_records pr WHERE pr.completed_at IS NOT NULL;
    RETURN QUERY
      SELECT 'prepared_today'::text, COUNT(*)::text FROM public.preparation_records WHERE completed_at >= CURRENT_DATE
      UNION ALL SELECT 'avg_prep_time'::text, COALESCE(EXTRACT(EPOCH FROM v_avg_interval)::text, '0')
      UNION ALL SELECT 'queue_size'::text, COUNT(*)::text FROM public.preparation_records WHERE status IN ('in_progress', 'completed');
    RETURN;
  END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  SELECT avg(pr.completed_at - pr.started_at) INTO v_avg_interval
  FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id
  WHERE pr.completed_at IS NOT NULL AND o.owner_id = ANY(v_visible);
  RETURN QUERY
    SELECT 'prepared_today'::text, COUNT(*)::text FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id
    WHERE pr.completed_at >= CURRENT_DATE AND o.owner_id = ANY(v_visible)
    UNION ALL SELECT 'avg_prep_time'::text, COALESCE(EXTRACT(EPOCH FROM v_avg_interval)::text, '0')
    UNION ALL SELECT 'queue_size'::text, COUNT(*)::text FROM public.preparation_records pr JOIN public.orders o ON o.id = pr.order_id
    WHERE pr.status IN ('in_progress', 'completed') AND o.owner_id = ANY(v_visible);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_work_hours_ledger(p_token uuid, p_employee_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_policy public.employee_work_policies;
    v_ledger jsonb;
    v_schedule_info jsonb;
    v_total_presence numeric := 0;
    v_session_count int := 0;
    v_min_start timestamptz;
    v_max_end timestamptz;
    v_total_break_seconds numeric := 0;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.is_upper_management(v_session.employee_id) THEN
        IF NOT public.check_capability(p_token, 'attendance.view_history') THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN');
        END IF;
        IF NOT (p_employee_id = ANY(public.get_visible_employee_ids(p_token))) THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN');
        END IF;
    END IF;

    SELECT * INTO v_policy FROM public.employee_work_policies WHERE employee_id = p_employee_id;

    IF v_policy.schedule_type = 'fixed_shift' THEN
        -- Fixed shift: ledger entries = session work periods + schedule_info مع net/break
        SELECT
            jsonb_agg(jsonb_build_object(
                'start_time', wds.start_time,
                'end_time', wds.end_time,
                'activity_type', 'work',
                'duration_minutes', COALESCE(EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60, 0)::int,
                'description', wds.status
            ) ORDER BY wds.start_time),

            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60), 0)::int,
            COUNT(*),
            MIN(wds.start_time),
            MAX(COALESCE(wds.end_time, now())),

            COALESCE(SUM(COALESCE(wb.total_break_seconds, 0)), 0)
        INTO v_ledger, v_total_presence, v_session_count, v_min_start, v_max_end, v_total_break_seconds
        FROM public.workday_sessions wds
        LEFT JOIN (
            SELECT session_id, SUM(COALESCE(duration_seconds, 0)) AS total_break_seconds
            FROM public.workday_breaks
            GROUP BY session_id
        ) wb ON wb.session_id = wds.id
        WHERE wds.employee_id = p_employee_id AND wds.date >= p_from AND wds.date <= p_to
        AND wds.status IN ('completed', 'active');

        v_ledger := COALESCE(v_ledger, '[]'::jsonb);

        v_schedule_info := jsonb_build_object(
            'schedule_type', 'fixed_shift',
            'presence_minutes', v_total_presence,
            'net_minutes', GREATEST(v_total_presence - (v_total_break_seconds / 60)::int, 0),
            'break_minutes', (v_total_break_seconds / 60)::int,
            'late_minutes', COALESCE((SELECT SUM(late_minutes) FROM public.workday_sessions
                WHERE employee_id = p_employee_id AND date >= p_from AND date <= p_to
                AND status IN ('completed', 'active')), 0),
            'early_departure_minutes', COALESCE((SELECT SUM(early_departure_minutes) FROM public.workday_sessions
                WHERE employee_id = p_employee_id AND date >= p_from AND date <= p_to
                AND status IN ('completed', 'active')), 0),
            'sessions_count', v_session_count
        );
    ELSE
        -- Flexible or Hourly: ledger entries = presence periods (no break deduction)
        SELECT
            jsonb_agg(jsonb_build_object(
                'start_time', wds.start_time,
                'end_time', wds.end_time,
                'activity_type', 'presence',
                'duration_minutes', COALESCE(EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60, 0)::int,
                'description', CASE WHEN wds.status = 'active' THEN 'جاري' ELSE NULL END
            ) ORDER BY wds.start_time),

            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(wds.end_time, now()) - wds.start_time)) / 60), 0)::int,
            COUNT(*),
            MIN(wds.start_time),
            MAX(COALESCE(wds.end_time, now()))
        INTO v_ledger, v_total_presence, v_session_count, v_min_start, v_max_end
        FROM public.workday_sessions wds
        WHERE wds.employee_id = p_employee_id AND wds.date >= p_from AND wds.date <= p_to
        AND wds.status IN ('completed', 'active');

        v_ledger := COALESCE(v_ledger, '[]'::jsonb);

        v_schedule_info := jsonb_build_object(
            'schedule_type', v_policy.schedule_type,
            'presence_minutes', v_total_presence,
            'sessions_count', v_session_count,
            'day_start', v_min_start,
            'day_end', v_max_end
        );
    END IF;

    RETURN jsonb_build_object(
        'schedule_type', COALESCE(v_policy.schedule_type, 'flexible'),
        'schedule_info', COALESCE(v_schedule_info, '{}'::jsonb),
        'ledger', v_ledger
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_work_policies_report(p_token uuid, p_from date, p_to date, p_employee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'total_work_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND status = 'completed' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'ontime_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'ontime' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'late_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'late' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'total_late_minutes', (SELECT COALESCE(SUM(late_minutes), 0) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'late' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'early_departure_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'early_departure' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'total_early_departure_minutes', (SELECT COALESCE(SUM(early_departure_minutes), 0) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'early_departure' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids))),
      'absent_days', (SELECT COUNT(*) FROM public.workday_sessions WHERE date >= p_from AND date <= p_to AND attendance_status = 'absent' AND (p_employee_ids IS NULL OR employee_id = ANY(p_employee_ids)))
    ),
    'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'employee_id', sub.employee_id, 'name', sub.employee_name,
      'work_days', sub.work_days, 'ontime_days', sub.ontime_days, 'late_days', sub.late_days,
      'late_minutes', sub.late_minutes, 'early_departure_days', sub.early_departure_days,
      'early_departure_minutes', sub.early_departure_minutes, 'absent_days', sub.absent_days,
      'compliance_rate', CASE WHEN sub.work_days > 0 THEN ROUND((sub.ontime_days::numeric / sub.work_days) * 100, 1) ELSE 0 END
    ) ORDER BY sub.compliance_rate DESC)), '[]'::jsonb)
  ) INTO v_result
  FROM (
    SELECT wds.employee_id, e.full_name AS employee_name,
      COUNT(*) AS work_days,
      COUNT(*) FILTER (WHERE wds.attendance_status = 'ontime') AS ontime_days,
      COUNT(*) FILTER (WHERE wds.attendance_status = 'late') AS late_days,
      COALESCE(SUM(wds.late_minutes) FILTER (WHERE wds.attendance_status = 'late'), 0) AS late_minutes,
      COUNT(*) FILTER (WHERE wds.attendance_status = 'early_departure') AS early_departure_days,
      COALESCE(SUM(wds.early_departure_minutes) FILTER (WHERE wds.attendance_status = 'early_departure'), 0) AS early_departure_minutes,
      COUNT(*) FILTER (WHERE wds.attendance_status IN ('absent', 'unknown')) AS absent_days
    FROM public.workday_sessions wds JOIN public.employees e ON e.id = wds.employee_id
      AND NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id AND ewp.attendance_enabled = false)
    WHERE wds.date >= p_from AND wds.date <= p_to AND wds.status = 'completed'
      AND (p_employee_ids IS NULL OR wds.employee_id = ANY(p_employee_ids))
    GROUP BY wds.employee_id, e.full_name
  ) sub;
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_workday_cleanup_log(p_token uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_logs jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.executed_at DESC), '[]'::jsonb) INTO v_logs
    FROM (SELECT * FROM public.tracking_cleanup_log ORDER BY executed_at DESC LIMIT p_limit) t;
    RETURN jsonb_build_object('logs', v_logs);
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_workday_report(p_token uuid, p_from date, p_to date, p_employee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
    v_session app.sessions;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    SELECT jsonb_build_object(
        'summary', jsonb_build_object(
            'total_sessions', COUNT(*),
            'total_net_hours', COALESCE(SUM(
                EXTRACT(EPOCH FROM (end_time - start_time)) / 3600 -
                COALESCE((SELECT SUM(COALESCE(duration_seconds, 0)) FROM public.workday_breaks wb WHERE wb.session_id = wds.id)::numeric / 3600, 0)
            ), 0),
            'total_visits', COALESCE(SUM(visit_count), 0),
            'total_distance_km', COALESCE(SUM(total_distance_meters), 0) / 1000,
            'late_days', COUNT(*) FILTER (WHERE attendance_status = 'late'),
            'total_late_minutes', COALESCE(SUM(late_minutes), 0),
            'early_departure_days', COUNT(*) FILTER (WHERE attendance_status = 'early_departure'),
            'total_early_departure_minutes', COALESCE(SUM(early_departure_minutes), 0),
            'ontime_days', COUNT(*) FILTER (WHERE attendance_status = 'ontime'),
            'absent_days', COUNT(*) FILTER (WHERE attendance_status = 'absent')
        ),
        'employees', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'employee_id', sub.employee_id,
            'name', sub.employee_name,
            'sessions', sub.session_count,
            'net_hours', sub.net_hours,
            'total_visits', sub.total_visits,
            'late_days', sub.late_days,
            'late_minutes', sub.late_minutes,
            'early_departure_days', sub.early_departure_days,
            'early_departure_minutes', sub.early_departure_minutes,
            'ontime_days', sub.ontime_days
        ) ORDER BY sub.session_count DESC)), '[]'::jsonb)
    ) INTO v_result
    FROM (
        SELECT
            wds.employee_id, e.full_name AS employee_name,
            COUNT(*) AS session_count,
            ROUND(COALESCE(SUM(
                EXTRACT(EPOCH FROM (wds.end_time - wds.start_time)) / 3600 -
                COALESCE((SELECT SUM(COALESCE(wb2.duration_seconds, 0)) FROM public.workday_breaks wb2 WHERE wb2.session_id = wds.id)::numeric / 3600, 0)
            ), 0)::numeric, 2) AS net_hours,
            SUM(wds.visit_count) AS total_visits,
            COUNT(*) FILTER (WHERE wds.attendance_status = 'late') AS late_days,
            SUM(wds.late_minutes) AS late_minutes,
            COUNT(*) FILTER (WHERE wds.attendance_status = 'early_departure') AS early_departure_days,
            SUM(wds.early_departure_minutes) AS early_departure_minutes,
            COUNT(*) FILTER (WHERE wds.attendance_status = 'ontime') AS ontime_days
        FROM public.workday_sessions wds
        JOIN public.employees e ON e.id = wds.employee_id
            AND NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id AND ewp.attendance_enabled = false)
        WHERE wds.date >= p_from AND wds.date <= p_to AND wds.status = 'completed'
        AND (p_employee_ids IS NULL OR wds.employee_id = ANY(p_employee_ids))
        GROUP BY wds.employee_id, e.full_name
    ) sub;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.get_workday_settings(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_settings jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.is_upper_management(v_session.employee_id) THEN RETURN jsonb_build_object('error', 'FORBIDDEN'); END IF;
    SELECT row_to_json(s)::jsonb INTO v_settings FROM (SELECT * FROM public.workday_settings LIMIT 1) s;
    RETURN COALESCE(v_settings, '{}'::jsonb);
END;

$function$;

