CREATE OR REPLACE FUNCTION public.governed_add_order_daily_deals(p_token uuid, p_order_id uuid, p_deals jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_deal jsonb;
  v_deal_record daily_deals;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  FOR v_deal IN SELECT * FROM jsonb_array_elements(p_deals)
  LOOP
    SELECT * INTO v_deal_record FROM public.daily_deals WHERE id = (v_deal->>'deal_id')::uuid;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'DEAL_NOT_FOUND'); END IF;

    IF v_deal_record.status != 'active' THEN RETURN jsonb_build_object('error', 'DEAL_NOT_ACTIVE'); END IF;
    IF v_deal_record.available_quantity < (v_deal->>'quantity')::int THEN
      RETURN jsonb_build_object('error', 'DEAL_INSUFFICIENT_QUANTITY');
    END IF;

    INSERT INTO public.order_daily_deals (order_id, deal_id, quantity, fixed_price, total_price)
    VALUES (
      p_order_id,
      (v_deal->>'deal_id')::uuid,
      (v_deal->>'quantity')::int,
      v_deal_record.fixed_price,
      v_deal_record.fixed_price * (v_deal->>'quantity')::int
    );
  END LOOP;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_add_order_flash_offers(p_token uuid, p_order_id uuid, p_offers jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_offer jsonb;
  v_offer_record flash_offers;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  FOR v_offer IN SELECT * FROM jsonb_array_elements(p_offers)
  LOOP
    SELECT * INTO v_offer_record FROM public.flash_offers WHERE id = (v_offer->>'offer_id')::uuid;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'OFFER_NOT_FOUND'); END IF;

    IF v_offer_record.status != 'active' THEN RETURN jsonb_build_object('error', 'OFFER_NOT_ACTIVE'); END IF;
    IF v_offer_record.available_quantity < (v_offer->>'quantity')::int THEN
      RETURN jsonb_build_object('error', 'OFFER_INSUFFICIENT_QUANTITY');
    END IF;

    INSERT INTO public.order_flash_offers (order_id, offer_id, quantity, fixed_price, total_price)
    VALUES (
      p_order_id,
      (v_offer->>'offer_id')::uuid,
      (v_offer->>'quantity')::int,
      v_offer_record.fixed_price,
      v_offer_record.fixed_price * (v_offer->>'quantity')::int
    );
  END LOOP;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_approve_collection(p_token uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_old_status varchar(30);
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'collections.approve');

  SELECT status INTO v_old_status FROM collections WHERE id = p_id;
  IF v_old_status IS NULL THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;
  IF v_old_status != 'pending' THEN RETURN jsonb_build_object('error', 'INVALID_STATE'); END IF;

  UPDATE collections
  SET status = 'approved', approved_by = v_session.employee_id, approved_at = now(), updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_approve_credit(p_token uuid, p_id uuid)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications; v_prog public.credit_programs; v_template public.credit_contract_templates;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.approve') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status NOT IN ('documents_received','under_review') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  SELECT * INTO v_prog FROM public.credit_programs WHERE id = v_app.program_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PROGRAM_NOT_FOUND'; END IF;
  UPDATE public.customers SET credit_limit = v_prog.credit_limit, credit_days = v_prog.credit_days, updated_at = now() WHERE id = v_app.customer_id;
  UPDATE public.credit_applications SET status = 'approved', approved_by = v_session.employee_id, approved_at = now(), updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  SELECT * INTO v_template FROM public.credit_contract_templates WHERE is_active = true LIMIT 1;
  INSERT INTO public.credit_contracts (application_id, customer_id, program_snapshot, terms_text) VALUES (p_id, v_app.customer_id, row_to_json(v_prog)::jsonb, COALESCE(v_template.template_text, ''));
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_approve_order(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
  v_old_status varchar(30);
  v_order record;
  v_deduct_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_employee_id := v_session.identity_id;

  PERFORM check_capability(p_token, 'orders.approve');

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  v_old_status := v_order.status;
  IF v_old_status NOT IN ('submitted', 'reviewing') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE');
  END IF;

  -- If order's configured deduction status is 'approved', deduct now
  IF v_order.order_inventory_deduction_status = 'approved' THEN
    v_deduct_result := public.governed_inventory_deduct(p_id);
    IF (v_deduct_result->>'error') IS NOT NULL THEN
      RETURN v_deduct_result;
    END IF;
  END IF;

  UPDATE public.orders
  SET status = 'approved', approved_at = now(), updated_at = now()
  WHERE id = p_id AND status IN ('submitted', 'reviewing');

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, changed_at)
  VALUES (p_id, v_old_status, 'approved', v_employee_id, now());

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_approve_participant(p_token uuid, p_participant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_participant public.auction_participants;
  v_company_name varchar(255);
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'auctions.manage');

  SELECT * INTO v_participant FROM public.auction_participants WHERE id = p_participant_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PARTICIPANT_NOT_FOUND'); END IF;
  IF v_participant.status != 'pending' THEN RETURN jsonb_build_object('error', 'INVALID_STATE'); END IF;

  UPDATE public.auction_participants SET
    status = 'approved', approved_by = v_session.employee_id, approved_at = now()
  WHERE id = p_participant_id;

  -- Get company name
  SELECT COALESCE(c.company_name, e.full_name) INTO v_company_name
  FROM public.auction_participants ap
  LEFT JOIN customers c ON c.id = ap.participant_id AND ap.participant_type = 'customer'
  LEFT JOIN employees e ON e.id = ap.participant_id AND ap.participant_type = 'employee'
  WHERE ap.id = p_participant_id;

  INSERT INTO public.auction_activity (auction_id, activity_type, actor_name, message)
  VALUES (v_participant.auction_id, 'participant_approved', v_company_name, v_company_name || ' تم اعتمادها للمشاركة');

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_approve_return(p_token uuid, p_return_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_visible uuid[];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
  IF NOT public.is_upper_management(v_session.employee_id) AND NOT EXISTS (SELECT 1 FROM public.returns r JOIN public.customers c ON c.id = r.customer_id WHERE r.id = p_return_id AND c.owner_id = ANY(v_visible)) THEN
    RETURN json_build_object('error', 'FORBIDDEN');
  END IF;
  UPDATE public.returns SET status = 'approved' WHERE id = p_return_id;
  RETURN json_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_assign_delivery(p_token uuid, p_delivery_id uuid, p_employee_id uuid)
 RETURNS delivery_tracking
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'delivery.dispatch') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_dt FROM public.delivery_tracking WHERE id = p_delivery_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  UPDATE public.delivery_tracking SET assigned_to = p_employee_id, assigned_by = v_session.employee_id, assigned_at = now(), updated_at = now() WHERE id = p_delivery_id RETURNING * INTO v_dt;
  RETURN v_dt;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_auto_suspend_overdue_accounts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_suspended int := 0;
  v_customer RECORD;
BEGIN
  FOR v_customer IN
    SELECT DISTINCT ci.customer_id
    FROM public.credit_invoices ci
    JOIN public.customer_credit_accounts cca ON cca.customer_id = ci.customer_id AND cca.credit_status = 'active'
    WHERE ci.status = 'open' AND ci.due_date < CURRENT_DATE
  LOOP
    UPDATE public.customer_credit_accounts SET
      credit_status = 'suspended', updated_at = now()
    WHERE customer_id = v_customer.customer_id AND credit_status = 'active';

    INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, notes, created_by)
    SELECT v_customer.customer_id, 'debit', 0, outstanding_credit,
      'إيقاف تلقائي بسبب فواتير متأخرة', (SELECT id FROM public.employees ORDER BY created_at ASC LIMIT 1)
    FROM public.customer_credit_accounts WHERE customer_id = v_customer.customer_id;

    v_suspended := v_suspended + 1;
  END LOOP;

  -- Mark overdue invoices
  UPDATE public.credit_invoices SET status = 'overdue', updated_at = now()
  WHERE status = 'open' AND due_date < CURRENT_DATE;

  RETURN jsonb_build_object('success', true, 'suspended', v_suspended);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_cancel_daily_deal(p_token uuid, p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
