CREATE OR REPLACE FUNCTION public.governed_cancel_order(p_token text, p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
  v_old_status varchar(30);
  v_customer_id uuid;
  v_total_amount decimal(12,2);
  v_payment_method varchar(20);
  v_restore_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_employee_id := v_session.employee_id;

  PERFORM check_capability(p_token, 'orders.cancel');

  SELECT status, customer_id, total_amount, payment_method
  INTO v_old_status, v_customer_id, v_total_amount, v_payment_method
  FROM public.orders WHERE id = p_id;
  IF v_old_status IS NULL THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;
  IF v_old_status IN ('cancelled', 'delivered', 'collected') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE');
  END IF;

  -- Restore inventory if previously deducted
  v_restore_result := public.governed_inventory_restore(p_id);

  UPDATE public.orders SET status = 'cancelled', updated_at = now() WHERE id = p_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason, changed_at)
  VALUES (p_id, v_old_status, 'cancelled', v_employee_id, p_reason, now());

  IF v_payment_method = 'credit' THEN
    UPDATE public.customer_credit_accounts SET
      reserved_credit = GREATEST(0, reserved_credit - v_total_amount),
      updated_at = now()
    WHERE customer_id = v_customer_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_cancel_preparation(p_token uuid, p_preparation_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE
  v_employee_id uuid;
  v_rec public.preparation_records;
BEGIN
  SELECT employee_id INTO v_employee_id FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'warehouse.prepare') THEN
    RETURN json_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT INTO v_rec FROM public.preparation_records WHERE id = p_preparation_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_rec.status IN ('reviewed', 'failed') THEN RETURN json_build_object('error', 'INVALID_STATUS'); END IF;

  UPDATE public.preparation_records
  SET status = 'failed', cancelled_by = v_employee_id, cancelled_at = now(),
      notes = COALESCE(p_notes, notes), updated_at = now()
  WHERE id = p_preparation_id;

  RETURN json_build_object('id', p_preparation_id, 'status', 'failed', 'cancelled_by', v_employee_id, 'cancelled_at', now());
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_customer_ownership(p_token uuid, p_customer_id uuid, p_new_owner_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auth jsonb;
  v_prev_owner_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT owner_id INTO v_prev_owner_id FROM public.customers WHERE id = p_customer_id;
  IF v_prev_owner_id IS NULL THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  -- Rule 2: Hierarchy Authorization (both owners must be in scope)
  v_auth := public.require_hierarchy_scope(v_session.employee_id, v_prev_owner_id);
  IF v_auth ? 'error' THEN RETURN v_auth; END IF;
  v_auth := public.require_hierarchy_scope(v_session.employee_id, p_new_owner_id);
  IF v_auth ? 'error' THEN RETURN v_auth; END IF;

  PERFORM check_capability(p_token, 'customers.manage');

  -- Record ownership history
  INSERT INTO public.customer_ownership_history (customer_id, previous_owner_id, new_owner_id, changed_by, reason)
  VALUES (p_customer_id, v_prev_owner_id, p_new_owner_id, v_session.employee_id, p_reason);

  -- Update ownership
  UPDATE public.customers SET owner_id = p_new_owner_id, updated_at = now() WHERE id = p_customer_id;

  RETURN jsonb_build_object('success', true, 'previous_owner_id', v_prev_owner_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_employee_manager(p_token uuid, p_id uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auth jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Rule 2: Hierarchy Authorization
  v_auth := public.require_hierarchy_scope(v_session.employee_id, p_id);
  IF v_auth ? 'error' THEN RETURN v_auth; END IF;

  PERFORM check_capability(p_token, 'employees.manage');

  -- Prevent self-manager
  IF p_id = p_manager_id THEN RETURN jsonb_build_object('error', 'SELF_MANAGER'); END IF;

  UPDATE public.employees SET manager_id = p_manager_id, updated_at = now() WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_employee_role(p_token uuid, p_id uuid, p_role_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auth jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Rule 2: Hierarchy Authorization
  v_auth := public.require_hierarchy_scope(v_session.employee_id, p_id);
  IF v_auth ? 'error' THEN RETURN v_auth; END IF;

  PERFORM check_capability(p_token, 'employees.manage');

  -- Remove existing roles
  DELETE FROM public.employee_roles WHERE employee_id = p_id;

  -- Assign new role
  INSERT INTO public.employee_roles (employee_id, role_id, assigned_by)
  VALUES (p_id, p_role_id, v_session.employee_id);

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_negative_selling_policy(p_token uuid, p_product_id uuid, p_negative_selling boolean, p_scope character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_product record;
  v_old_value boolean;
  v_order record;
  v_has_unavailable boolean;
  v_has_insufficient boolean;
  v_restore_result jsonb;
  v_moved_count integer := 0;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'products.manage') THEN
    RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: products.manage');
  END IF;

  IF p_scope NOT IN ('new_orders', 'previous_and_new') THEN
    RETURN jsonb_build_object('error', 'INVALID_SCOPE');
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND'); END IF;

  v_old_value := v_product.negative_selling_allowed;

  UPDATE public.products
  SET negative_selling_allowed = p_negative_selling, updated_at = now()
  WHERE id = p_product_id;

  IF p_scope = 'previous_and_new' AND v_old_value = true AND p_negative_selling = false THEN
    FOR v_order IN
      SELECT DISTINCT o.id, o.status, o.inventory_deducted_at
      FROM public.orders o
      JOIN public.order_items oi ON oi.order_id = o.id
      WHERE oi.product_id = p_product_id
        AND o.status NOT IN ('delivered', 'cancelled', 'stock_review')
    LOOP
      v_has_unavailable := false;
      v_has_insufficient := false;

      IF EXISTS (
        SELECT 1 FROM public.order_items oi2
        JOIN public.products p2 ON p2.id = oi2.product_id
        WHERE oi2.order_id = v_order.id
          AND (p2.is_out_of_stock = true OR p2.is_active = false)
      ) THEN
        v_has_unavailable := true;
      END IF;

      IF v_order.inventory_deducted_at IS NULL THEN
        SELECT EXISTS (
          SELECT 1 FROM public.order_items oi3
          JOIN public.inventory inv ON inv.product_id = oi3.product_id
          WHERE oi3.order_id = v_order.id
            AND inv.quantity < oi3.piece_quantity
        ) INTO v_has_insufficient;
      END IF;

      IF v_has_unavailable OR v_has_insufficient THEN
        PERFORM public.governed_inventory_restore(v_order.id);

        UPDATE public.orders
        SET status = 'stock_review',
            order_negative_selling_allowed = false,
            updated_at = now()
        WHERE id = v_order.id;

        INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason, changed_at)
        VALUES (v_order.id, v_order.status, 'stock_review', v_session.identity_id,
                'تم نقل الطلب لمراجعة المخزونdue to Negative Selling policy change', now());

        v_moved_count := v_moved_count + 1;
      ELSE
        UPDATE public.orders
        SET order_negative_selling_allowed = false, updated_at = now()
        WHERE id = v_order.id;
      END IF;
    END LOOP;
  ELSIF p_scope = 'previous_and_new' THEN
    UPDATE public.orders
    SET order_negative_selling_allowed = p_negative_selling, updated_at = now()
    WHERE id IN (
      SELECT o.id FROM public.orders o
      JOIN public.order_items oi ON oi.order_id = o.id
      WHERE oi.product_id = p_product_id
        AND o.status NOT IN ('delivered', 'cancelled', 'stock_review')
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'product_id', p_product_id,
    'negative_selling_allowed', p_negative_selling,
    'scope', p_scope, 'moved_to_stock_review', v_moved_count
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_order_status(p_token text, p_order_id uuid, p_new_status text, p_reason text DEFAULT NULL::text, p_reference_number text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_current_status text;
  v_customer_id uuid;
  v_total_amount decimal(12,2);
  v_payment_method varchar(20);
  v_from_idx int;
  v_to_idx int;
  v_required_capability text;
  v_has_capability boolean;
  v_is_exceptional boolean;
  v_order record;
  v_deduct_result jsonb;
  statuses text[] := ARRAY[
    'draft','submitted','reviewing','returned_for_revision',
    'approved','preparing','prepared','ready_for_dispatch',
    'sent_to_delivery','dispatched','deferred','cancelled',
    'delivered','stock_review'
  ];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'INVALID_SESSION');
  END IF;

  IF NOT (p_new_status = ANY(statuses)) THEN
    RETURN json_build_object('success', false, 'error', 'حالة غير صالحة');
  END IF;

  SELECT status::text, customer_id, total_amount, payment_method
  INTO v_current_status, v_customer_id, v_total_amount, v_payment_method
  FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'الطلب غير موجود');
  END IF;

  IF v_current_status = p_new_status THEN
    RETURN json_build_object('success', false, 'error', 'الطلب بنفس الحالة');
  END IF;

  v_from_idx := array_position(statuses, v_current_status);
  v_to_idx := array_position(statuses, p_new_status);

  SELECT check_capability(p_token, 'orders.manage') INTO v_has_capability;
  IF v_has_capability THEN
    v_required_capability := 'orders.manage';
  ELSE
    IF v_current_status = 'submitted' AND p_new_status = 'reviewing' THEN
      v_required_capability := 'orders.review';
    ELSIF v_current_status = 'approved' AND p_new_status = 'preparing' THEN
      v_required_capability := 'warehouse.complete_preparation';
    ELSIF v_current_status = 'preparing' AND p_new_status = 'prepared' THEN
      v_required_capability := 'warehouse.complete_preparation';
    ELSIF (v_current_status = 'prepared' OR v_current_status = 'ready_for_dispatch') AND p_new_status = 'sent_to_delivery' THEN
      v_required_capability := 'transportation.send_to_delivery';
    ELSE
      v_required_capability := 'orders.manage';
    END IF;
  END IF;

  SELECT check_capability(p_token, v_required_capability) INTO v_has_capability;
  IF NOT v_has_capability THEN
    RETURN json_build_object('success', false, 'error', 'ليس لديك الصلاحية لهذا الإجراء');
  END IF;

  v_is_exceptional := false;
  IF v_current_status = 'cancelled' OR p_new_status = 'cancelled' THEN
    v_is_exceptional := true;
  ELSIF v_current_status = 'deferred' OR p_new_status = 'deferred' THEN
    v_is_exceptional := true;
  ELSIF v_to_idx < v_from_idx THEN
    v_is_exceptional := true;
  ELSIF v_to_idx > v_from_idx + 1 THEN
    v_is_exceptional := true;
  END IF;

  IF v_is_exceptional AND (p_reason IS NULL OR trim(p_reason) = '') THEN
    RETURN json_build_object('success', false, 'error', 'الرجاء إدخال سبب للتغيير الاستثنائي');
  END IF;

  IF v_current_status = 'submitted' AND p_new_status = 'reviewing' THEN
    IF p_reference_number IS NULL OR trim(p_reference_number) = '' THEN
      RETURN json_build_object('success', false, 'error', 'الرقم المرجعى إجباري عند التحويل إلى جارى المراجعة');
    END IF;
  END IF;

  -- Inventory deduction at configured status
  IF p_new_status != v_current_status THEN
    SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
    IF v_order.order_inventory_deduction_status = p_new_status
       AND v_order.inventory_deducted_at IS NULL THEN
      v_deduct_result := public.governed_inventory_deduct(p_order_id);
      IF (v_deduct_result->>'error') IS NOT NULL THEN
        RETURN json_build_object('success', false, 'error', (v_deduct_result->>'error')::text);
      END IF;
    END IF;
  END IF;

  UPDATE orders SET
    status = p_new_status,
    reference_number = CASE
      WHEN v_current_status = 'submitted' AND p_new_status = 'reviewing' THEN trim(p_reference_number)
      ELSE reference_number
    END,
    delivered_at = CASE WHEN p_new_status = 'delivered' THEN now() ELSE delivered_at END,
    updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO order_status_history (order_id, from_status, to_status, changed_by, reason, changed_at)
  VALUES (p_order_id, v_current_status, p_new_status, v_session.identity_id, p_reason, now());

  IF p_new_status = 'cancelled' AND v_payment_method = 'credit' THEN
    UPDATE customer_credit_accounts SET
      reserved_credit = GREATEST(0, reserved_credit - v_total_amount),
      updated_at = now()
    WHERE customer_id = v_customer_id;
  END IF;

  RETURN json_build_object('success', true, 'from_status', v_current_status, 'to_status', p_new_status);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_change_product_company(p_token uuid, p_product_id uuid, p_new_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  UPDATE public.products SET company_id = p_new_company_id, updated_at = now() WHERE id = p_product_id;
  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_checkin_visit(p_token uuid, p_customer_id uuid, p_start_location_id uuid DEFAULT NULL::uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_visit_id uuid; v_code varchar(30);
  v_year integer := EXTRACT(YEAR FROM now()); v_seq integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  SELECT id INTO v_visit_id FROM visits
  WHERE employee_id = v_session.employee_id AND customer_id = p_customer_id AND status = 'active' LIMIT 1;
  IF v_visit_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'id', v_visit_id, 'existing', true);
  END IF;
  INSERT INTO public.code_sequences (code_type, year, last_sequence)
  VALUES ('visit', v_year, 1)
  ON CONFLICT (code_type, year) DO UPDATE SET last_sequence = code_sequences.last_sequence + 1
  RETURNING last_sequence INTO v_seq;
  v_code := 'VIS-' || v_year::text || '-' || LPAD(v_seq::text, 6, '0');
  INSERT INTO public.visits (code, employee_id, customer_id, status, check_in_at,
    start_location_id, check_in_latitude, check_in_longitude)
  VALUES (v_code, v_session.employee_id, p_customer_id, 'active', now(),
    p_start_location_id, p_latitude, p_longitude)
  RETURNING id INTO v_visit_id;
  RETURN jsonb_build_object('success', true, 'id', v_visit_id, 'code', v_code);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_checkout_visit(p_token uuid, p_visit_id uuid, p_visit_result character varying DEFAULT NULL::character varying, p_notes text DEFAULT NULL::text, p_end_location_id uuid DEFAULT NULL::uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_visit_status varchar(20);
  v_customer_id uuid;
  v_formatted_address text;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT status, customer_id INTO v_visit_status, v_customer_id FROM visits WHERE id = p_visit_id;
  IF v_visit_status IS NULL THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;
  IF v_visit_status != 'active' THEN RETURN jsonb_build_object('error', 'INVALID_STATE'); END IF;

  UPDATE public.visits
  SET
    status = 'completed',
    check_out_at = now(),
    end_location_id = COALESCE(p_end_location_id, end_location_id),
    check_out_latitude = COALESCE(p_latitude, check_out_latitude),
    check_out_longitude = COALESCE(p_longitude, check_out_longitude),
    visit_result = COALESCE(p_visit_result, visit_result),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_visit_id;

  -- Enrich customer using shared service (best-effort, must never fail visit)
  BEGIN
    SELECT formatted_address INTO v_formatted_address
    FROM unified_locations WHERE id = p_end_location_id;

    PERFORM fn_enrich_customer_location(
      p_customer_id        := v_customer_id,
      p_latitude           := p_latitude,
      p_longitude          := p_longitude,
      p_formatted_address  := v_formatted_address,
      p_accuracy_level     := 'GPS'
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'governed_checkout_visit: enrichment failed for visit % (customer %): %', p_visit_id, v_customer_id, SQLERRM;
  END;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_complete_delivery(p_token text, p_delivery_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE
  v_session app.sessions;
  v_dt public.delivery_tracking;
  v_order public.orders;
  v_invoice_id uuid;
  v_invoice_num varchar(50);
  v_due_date date;
  v_account public.customer_credit_accounts;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'delivery.deliver') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;

  SELECT * INTO v_dt FROM public.delivery_tracking WHERE id = p_delivery_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_dt.status NOT IN ('out_for_delivery','assigned') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;

  UPDATE public.delivery_tracking SET status = 'delivered', completed_at = now(), notes = COALESCE(p_notes, notes), updated_at = now() WHERE id = p_delivery_id RETURNING * INTO v_dt;
  UPDATE public.orders SET status = 'delivered', delivered_at = now(), updated_at = now() WHERE id = v_dt.order_id RETURNING * INTO v_order;

  IF v_order.payment_method = 'credit' THEN
    SELECT * INTO v_account FROM public.customer_credit_accounts
    WHERE customer_id = v_order.customer_id AND credit_status = 'active';
    IF FOUND THEN
      UPDATE public.customer_credit_accounts SET
        reserved_credit = GREATEST(0, reserved_credit - v_order.total_amount),
        outstanding_credit = outstanding_credit + v_order.total_amount,
        updated_at = now()
      WHERE id = v_account.id;

      v_invoice_num := 'CI-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-' || COALESCE((SELECT MAX(SUBSTRING(invoice_number FROM '\d+$'))::int + 1 FROM public.credit_invoices WHERE invoice_number LIKE 'CI-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-%'), 1);
      v_due_date := CURRENT_DATE + v_account.payment_term_days;

      INSERT INTO public.credit_invoices (invoice_number, customer_id, order_id, invoice_amount, issue_date, due_date, status)
      VALUES (v_invoice_num, v_order.customer_id, v_dt.order_id, v_order.total_amount, CURRENT_DATE, v_due_date, 'open')
      RETURNING id INTO v_invoice_id;

      INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, reference_type, reference_id, notes, created_by)
      SELECT v_order.customer_id, 'debit', v_order.total_amount,
        (SELECT outstanding_credit FROM public.customer_credit_accounts WHERE customer_id = v_order.customer_id),
        'credit_invoice', v_invoice_id, 'تحويل طلب رقم ' || v_order.order_number || ' إلى فاتورة ائتمان', v_session.employee_id;
    END IF;
  END IF;

  RETURN jsonb_build_object('delivery_status', 'delivered', 'order_status', v_order.status, 'delivered_at', v_order.delivered_at);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_complete_preparation(p_token uuid, p_preparation_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_rec public.preparation_records;
  v_order_id uuid;
  v_cap_ok boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  -- Accept either warehouse.prepare OR orders.prepare
  v_cap_ok := public.check_capability(p_token, 'warehouse.prepare')
           OR public.check_capability(p_token, 'orders.prepare');
  IF NOT v_cap_ok THEN RETURN json_build_object('error', 'FORBIDDEN'); END IF;

  SELECT INTO v_rec FROM public.preparation_records WHERE id = p_preparation_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_rec.status != 'in_progress' THEN RETURN json_build_object('error', 'INVALID_STATUS'); END IF;

  SELECT order_id INTO v_order_id FROM public.preparation_records WHERE id = p_preparation_id;

  UPDATE public.preparation_records
  SET status = 'completed', completed_by = v_session.employee_id, completed_at = now(),
      notes = COALESCE(p_notes, notes), updated_at = now()
  WHERE id = p_preparation_id;

  UPDATE public.orders SET status = 'prepared', updated_at = now() WHERE id = v_order_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (v_order_id, 'preparing', 'prepared', v_session.identity_id, COALESCE(p_notes, 'Preparation completed'));

  RETURN json_build_object('id', p_preparation_id, 'status', 'completed', 'completed_by', v_session.employee_id, 'completed_at', now(), 'order_status', 'prepared');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_confirm_documents(p_token uuid, p_id uuid, p_doc_commercial_reg boolean, p_doc_tax_card boolean, p_doc_national_id boolean, p_doc_cheques boolean, p_doc_contract_signed boolean)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.confirm_documents') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status NOT IN ('submitted','under_review') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  IF p_doc_commercial_reg AND p_doc_tax_card AND p_doc_national_id AND p_doc_cheques AND p_doc_contract_signed THEN
    UPDATE public.credit_applications SET doc_commercial_reg = p_doc_commercial_reg, doc_tax_card = p_doc_tax_card, doc_national_id = p_doc_national_id, doc_cheques = p_doc_cheques, doc_contract_signed = p_doc_contract_signed, doc_confirmed_by = v_session.employee_id, doc_confirmed_at = now(), status = 'documents_received', updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  ELSE
    UPDATE public.credit_applications SET doc_commercial_reg = p_doc_commercial_reg, doc_tax_card = p_doc_tax_card, doc_national_id = p_doc_national_id, doc_cheques = p_doc_cheques, doc_contract_signed = p_doc_contract_signed, doc_confirmed_by = v_session.employee_id, doc_confirmed_at = now(), updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  END IF;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_convert_credit_reservation_to_outstanding(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_account public.customer_credit_accounts;
  v_invoice_id uuid;
  v_invoice_num varchar(50);
  v_due_date date;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  SELECT * INTO v_account FROM public.customer_credit_accounts
  WHERE customer_id = v_order.customer_id AND credit_status = 'active';
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NO_ACTIVE_CREDIT'); END IF;

  -- Move reserved to outstanding
  UPDATE public.customer_credit_accounts SET
    reserved_credit = GREATEST(0, reserved_credit - v_order.total_amount),
    outstanding_credit = outstanding_credit + v_order.total_amount,
    updated_at = now()
  WHERE id = v_account.id;

  -- Generate invoice number
  v_invoice_num := 'CI-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-' || COALESCE((SELECT MAX(SUBSTRING(invoice_number FROM '\d+$'))::int + 1 FROM public.credit_invoices WHERE invoice_number LIKE 'CI-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-%'), 1);

  -- Calculate due date based on payment term
  v_due_date := CURRENT_DATE + v_account.payment_term_days;

  -- Create invoice
  INSERT INTO public.credit_invoices (invoice_number, customer_id, order_id, invoice_amount, issue_date, due_date, status)
  VALUES (v_invoice_num, v_order.customer_id, p_order_id, v_order.total_amount, CURRENT_DATE, v_due_date, 'open')
  RETURNING id INTO v_invoice_id;

  -- Log to ledger
    INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, reference_type, reference_id, notes, created_by)
    SELECT v_order.customer_id, 'debit', v_order.total_amount,
      (SELECT outstanding_credit FROM public.customer_credit_accounts WHERE customer_id = v_order.customer_id),
      'credit_invoice', v_invoice_id, 'تحويل طلب رقم ' || v_order.order_number || ' إلى فاتورة ائتمان', v_session.employee_id;

  RETURN jsonb_build_object('success', true, 'invoice_id', v_invoice_id, 'invoice_number', v_invoice_num, 'due_date', v_due_date::text);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_auction(p_token uuid, p_code character varying, p_title character varying, p_description text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_starting_price numeric DEFAULT 0, p_bid_increment numeric DEFAULT 1, p_deposit_amount numeric DEFAULT NULL::numeric, p_start_time timestamp with time zone DEFAULT now(), p_end_time timestamp with time zone DEFAULT (now() + '7 days'::interval))
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auction_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'auctions.manage');

  INSERT INTO public.auctions (code, title, description, image_url, starting_price, current_price, bid_increment, deposit_amount, start_time, end_time, created_by)
  VALUES (p_code, p_title, p_description, p_image_url, p_starting_price, p_starting_price, p_bid_increment, p_deposit_amount, p_start_time, p_end_time, v_session.employee_id)
  RETURNING id INTO v_auction_id;

  RETURN jsonb_build_object('success', true, 'id', v_auction_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_collection(p_token uuid, p_customer_id uuid, p_method text, p_amount numeric, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_collection public.collections;
  v_code text;
  v_seq int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF v_session.identity_type = 'customer' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF NOT public.check_capability(p_token, 'collections.create') THEN RAISE EXCEPTION 'MISSING_CAPABILITY: collections.create'; END IF;

  SELECT last_sequence + 1 INTO v_seq FROM public.code_sequences WHERE code_type = 'collection' AND year = EXTRACT(year FROM now())::int FOR UPDATE;
  IF NOT FOUND THEN v_seq := 1; END IF;
  v_code := 'COL-' || EXTRACT(year FROM now())::int || '-' || LPAD(v_seq::text, 6, '0');

  INSERT INTO public.collections (code, customer_id, owner_type, owner_id, method, amount, reference_number, notes, created_by, order_id)
  VALUES (v_code, p_customer_id, 'employee', v_session.employee_id, p_method, p_amount, p_reference_number, p_notes, v_session.employee_id, p_order_id)
  RETURNING * INTO v_collection;

  INSERT INTO public.code_sequences (code_type, year, last_sequence)
  VALUES ('collection', EXTRACT(year FROM now())::int, v_seq)
  ON CONFLICT (code_type, year) DO UPDATE SET last_sequence = v_seq;

  RETURN row_to_json(v_collection);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_company(p_token uuid, p_company_name character varying, p_legacy_code character varying, p_display_order integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_company_id uuid;
  v_position int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'companies.manage');

  IF p_display_order IS NOT NULL AND p_display_order > 0 THEN
    v_position := p_display_order;
  ELSE
    SELECT COALESCE(MAX(display_order), 0) + 1 INTO v_position FROM companies;
  END IF;

  -- Clamp: cannot exceed count+1 (append to end)
  v_position := LEAST(v_position, (SELECT COUNT(*) + 1 FROM companies));

  -- Shift companies at or after the target position DOWN
  UPDATE companies SET display_order = display_order + 1
  WHERE display_order >= v_position;

  INSERT INTO public.companies (company_name, legacy_code, is_active, display_order)
  VALUES (p_company_name, p_legacy_code, true, v_position)
  RETURNING id INTO v_company_id;

  RETURN jsonb_build_object('success', true, 'id', v_company_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_credit_application(p_token uuid, p_customer_id uuid, p_program_id uuid)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications; v_prog public.credit_programs;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.create') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_prog FROM public.credit_programs WHERE id = p_program_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_PROGRAM'; END IF;
  IF v_session.identity_type = 'customer' THEN
    IF v_session.customer_id IS DISTINCT FROM p_customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    INSERT INTO public.credit_applications (customer_id, program_id, created_by) VALUES (p_customer_id, p_program_id, v_session.customer_id) RETURNING * INTO v_app;
  ELSE
    INSERT INTO public.credit_applications (customer_id, program_id, created_by) VALUES (p_customer_id, p_program_id, v_session.employee_id) RETURNING * INTO v_app;
  END IF;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_credit_program(p_token uuid, p_name character varying, p_credit_limit numeric, p_credit_days integer, p_terms text DEFAULT NULL::text)
 RETURNS credit_programs
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_prog public.credit_programs;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.manage_programs') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  INSERT INTO public.credit_programs (name, credit_limit, credit_days, terms) VALUES (p_name, p_credit_limit, p_credit_days, p_terms) RETURNING * INTO v_prog;
  RETURN v_prog;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_customer(p_token uuid, p_company_name character varying, p_phone character varying DEFAULT NULL::character varying, p_contact_name character varying DEFAULT NULL::character varying, p_contact_phone character varying DEFAULT NULL::character varying, p_address_line1 character varying DEFAULT NULL::character varying, p_city character varying DEFAULT 'القاهرة'::character varying, p_region character varying DEFAULT NULL::character varying, p_business_type business_type DEFAULT NULL::business_type, p_responsible_name character varying DEFAULT NULL::character varying, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_accuracy_meters numeric DEFAULT NULL::numeric, p_formatted_address text DEFAULT NULL::text, p_password character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_credit_limit numeric DEFAULT NULL::numeric, p_credit_days integer DEFAULT NULL::integer, p_governorate_id uuid DEFAULT NULL::uuid, p_city_id uuid DEFAULT NULL::uuid, p_street_address character varying DEFAULT NULL::character varying, p_landmark text DEFAULT NULL::text, p_address_source address_source_type DEFAULT NULL::address_source_type)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
  v_identity_id uuid;
  v_customer_id uuid;
  v_contact_id uuid;
  v_address_id uuid;
  v_location_id uuid;
  v_code varchar(20);
  v_year integer := EXTRACT(YEAR FROM now());
  v_seq integer;
  v_has_new_address boolean;
  v_gov_name varchar(200);
  v_city_name varchar(200);
  v_address_line1 varchar(255);
  v_auto_source address_source_type;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_employee_id := v_session.employee_id;
  PERFORM check_capability(p_token, 'customers.create');

  INSERT INTO public.code_sequences (code_type, year, last_sequence)
  VALUES ('customer', v_year, 1)
  ON CONFLICT (code_type, year)
  DO UPDATE SET last_sequence = code_sequences.last_sequence + 1
  RETURNING last_sequence INTO v_seq;

  v_code := 'CUS-' || v_year::text || '-' || LPAD(v_seq::text, 6, '0');
  v_identity_id := gen_random_uuid();
  v_customer_id := gen_random_uuid();

  -- Auto-detect address source based on GPS presence
  v_auto_source := CASE
    WHEN p_address_source IS NOT NULL THEN p_address_source
    WHEN p_latitude IS NOT NULL AND p_longitude IS NOT NULL THEN 'mixed'::address_source_type
    ELSE 'manual'::address_source_type
  END;

  -- Create unified_locations record
  IF p_latitude IS NOT NULL AND p_longitude IS NOT NULL THEN
    v_location_id := gen_random_uuid();
    INSERT INTO unified_locations (id, latitude, longitude, accuracy_meters, formatted_address, captured_at)
    VALUES (v_location_id, p_latitude, p_longitude, p_accuracy_meters, COALESCE(p_formatted_address, p_address_line1), now());
  ELSIF p_formatted_address IS NOT NULL THEN
    v_location_id := gen_random_uuid();
    INSERT INTO unified_locations (id, formatted_address, captured_at)
    VALUES (v_location_id, p_formatted_address, now());
  END IF;

  INSERT INTO public.identities (id, phone, password_hash, identity_type, is_active)
  VALUES (
    v_identity_id,
    COALESCE(p_phone, 'ext-' || v_customer_id::text || '-' || substr(md5(random()::text || clock_timestamp()::text), 1, 8)),
    CASE WHEN p_password IS NOT NULL THEN extensions.crypt(p_password::text, extensions.gen_salt('bf'))
         ELSE extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf'))
    END,
    'customer',
    true
  );

  INSERT INTO public.customers (id, identity_id, code, company_name, responsible_name, business_type, location_id, owner_type, owner_id, is_active, email, credit_limit, credit_days)
  VALUES (v_customer_id, v_identity_id, v_code, p_company_name, COALESCE(p_responsible_name, p_contact_name), p_business_type, v_location_id, 'employee', v_employee_id, true, p_email, COALESCE(p_credit_limit, 0), COALESCE(p_credit_days, 0));

  IF p_contact_phone IS NOT NULL OR p_contact_name IS NOT NULL THEN
    INSERT INTO public.customer_contacts (customer_id, full_name, phone, is_primary)
    VALUES (v_customer_id, COALESCE(p_contact_name, p_company_name), COALESCE(p_contact_phone, '0000000000'), true)
    RETURNING id INTO v_contact_id;
  END IF;

  v_has_new_address := p_governorate_id IS NOT NULL OR p_city_id IS NOT NULL
    OR p_street_address IS NOT NULL OR p_landmark IS NOT NULL;

  IF v_has_new_address THEN
    v_gov_name := (SELECT name_ar FROM reference_governorates WHERE id = p_governorate_id);
    v_city_name := (SELECT name_ar FROM reference_cities WHERE id = p_city_id);
    v_address_line1 := TRIM(COALESCE(v_gov_name, '') || ' - ' || COALESCE(v_city_name, ''));
    IF p_street_address IS NOT NULL AND p_street_address != '' THEN
      v_address_line1 := v_address_line1 || ' - ' || p_street_address;
    END IF;
    IF p_landmark IS NOT NULL AND p_landmark != '' THEN
      v_address_line1 := v_address_line1 || ' - ' || p_landmark;
    END IF;

    INSERT INTO public.customer_addresses (
      customer_id, address_line1, city, governorate,
      governorate_id, city_id, street_address, landmark,
      address_source, address_updated_at, is_default
    ) VALUES (
      v_customer_id, v_address_line1, COALESCE(v_city_name, p_city), COALESCE(v_gov_name, ''),
      p_governorate_id, p_city_id, p_street_address, p_landmark,
      v_auto_source, now(), true
    )
    RETURNING id INTO v_address_id;
  ELSIF p_address_line1 IS NOT NULL THEN
    INSERT INTO public.customer_addresses (customer_id, address_line1, city, is_default)
    VALUES (v_customer_id, p_address_line1, p_city, true)
    RETURNING id INTO v_address_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'id', v_customer_id, 'code', v_code, 'company_name', p_company_name);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_daily_deal(p_token uuid, p_title character varying, p_fixed_price numeric, p_quantity integer, p_image_url text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_deal_id uuid;
  v_item jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'deals.manage');

  IF p_fixed_price < 0 THEN RETURN jsonb_build_object('error', 'INVALID_PRICE'); END IF;
  IF p_quantity <= 0 THEN RETURN jsonb_build_object('error', 'INVALID_QUANTITY'); END IF;

  INSERT INTO public.daily_deals (
    title, image_url, description, fixed_price,
    available_quantity, original_quantity,
    starts_at, ends_at, status, created_by
  ) VALUES (
    p_title, p_image_url, p_description, p_fixed_price,
    p_quantity, p_quantity,
    p_starts_at, p_ends_at,
    CASE
      WHEN p_starts_at IS NOT NULL AND p_starts_at > now() THEN 'scheduled'::daily_deal_status
      ELSE 'active'::daily_deal_status
    END,
    v_session.employee_id
  )
  RETURNING id INTO v_deal_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.daily_deal_items (deal_id, product_id, quantity)
    VALUES (
      v_deal_id,
      (v_item->>'product_id')::uuid,
      (v_item->>'quantity')::int
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', v_deal_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_employee(p_token uuid, p_full_name character varying, p_phone character varying, p_password character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_role_id uuid DEFAULT NULL::uuid, p_manager_id uuid DEFAULT NULL::uuid, p_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auth jsonb;
  v_employee_id uuid;
  v_identity_id uuid;
  v_code varchar(20);
  v_year integer := EXTRACT(YEAR FROM now());
  v_seq integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  -- Rule 2: Hierarchy Authorization (check proposed manager is in scope)
  v_auth := public.require_hierarchy_scope(v_session.employee_id, p_manager_id);
  IF v_auth ? 'error' THEN RETURN v_auth; END IF;

  PERFORM check_capability(p_token, 'employees.manage');

  IF EXISTS (SELECT 1 FROM identities WHERE phone = p_phone) THEN
    RETURN jsonb_build_object('error', 'PHONE_EXISTS');
  END IF;

  INSERT INTO public.code_sequences (code_type, year, last_sequence)
  VALUES ('employee', v_year, 1)
  ON CONFLICT (code_type, year)
  DO UPDATE SET last_sequence = code_sequences.last_sequence + 1
  RETURNING last_sequence INTO v_seq;

  v_code := 'EMP-' || v_year::text || '-' || LPAD(v_seq::text, 6, '0');
  v_identity_id := gen_random_uuid();
  v_employee_id := gen_random_uuid();

  INSERT INTO public.identities (id, phone, password_hash, identity_type, is_active)
  VALUES (
    v_identity_id,
    p_phone,
    extensions.crypt(COALESCE(p_password, p_phone), extensions.gen_salt('bf')),
    'employee',
    true
  );

  INSERT INTO public.employees (id, identity_id, code, full_name, email, manager_id, address, is_active)
  VALUES (v_employee_id, v_identity_id, v_code, p_full_name, p_email, p_manager_id, p_address, true);

  IF p_role_id IS NOT NULL THEN
    INSERT INTO public.employee_roles (employee_id, role_id, assigned_by)
    VALUES (v_employee_id, p_role_id, v_session.employee_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'id', v_employee_id,
    'code', v_code,
    'full_name', p_full_name
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_flash_offer(p_token uuid, p_title character varying, p_fixed_price numeric, p_quantity integer, p_image_url text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_offer_id uuid;
  v_item jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'flash_offers.manage');

  IF p_fixed_price < 0 THEN RETURN jsonb_build_object('error', 'INVALID_PRICE'); END IF;
  IF p_quantity <= 0 THEN RETURN jsonb_build_object('error', 'INVALID_QUANTITY'); END IF;

  INSERT INTO public.flash_offers (
    title, image_url, description, fixed_price,
    available_quantity, original_quantity,
    starts_at, ends_at, status, created_by
  ) VALUES (
    p_title, p_image_url, p_description, p_fixed_price,
    p_quantity, p_quantity,
    p_starts_at, p_ends_at,
    CASE
      WHEN p_starts_at IS NOT NULL AND p_starts_at > now() THEN 'scheduled'::flash_offer_status
      ELSE 'active'::flash_offer_status
    END,
    v_session.employee_id
  )
  RETURNING id INTO v_offer_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.flash_offer_items (offer_id, product_id, quantity)
    VALUES (
      v_offer_id,
      (v_item->>'product_id')::uuid,
      (v_item->>'quantity')::int
    );
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', v_offer_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_location(p_token uuid, p_latitude numeric, p_longitude numeric, p_accuracy_meters numeric DEFAULT NULL::numeric, p_formatted_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_location_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_location_id := gen_random_uuid();

  -- GPS → location_verified = true
  INSERT INTO unified_locations (id, latitude, longitude, accuracy_meters, formatted_address, captured_at, location_verified)
  VALUES (v_location_id, p_latitude, p_longitude, p_accuracy_meters, p_formatted_address, now(), true);

  RETURN jsonb_build_object(
    'success', true,
    'id', v_location_id,
    'latitude', p_latitude,
    'longitude', p_longitude,
    'accuracy_meters', p_accuracy_meters
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_order(p_token uuid, p_customer_id uuid, p_tier_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_execution_location_id uuid DEFAULT NULL::uuid, p_execution_latitude numeric DEFAULT NULL::numeric, p_execution_longitude numeric DEFAULT NULL::numeric, p_execution_accuracy_meters numeric DEFAULT NULL::numeric, p_execution_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_order_type character varying DEFAULT 'cash'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_employee_id uuid;
  v_order_number text;
  v_seq int;
  v_order_item jsonb;
  v_product record;
  v_calculated_unit_price numeric;
  v_calculated_total_price numeric;
  v_exec_location_id uuid;
  v_cust_name text;
  v_cust_phone text;
  v_cust_address text;
  v_owner_name text;
  v_owner_phone text;
  v_owner_address text;
  v_sender_name text;
  v_sender_phone text;
  v_sender_address text;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;

  IF v_session.identity_type = 'employee' THEN
    IF NOT public.check_capability(p_token, 'orders.create') THEN RAISE EXCEPTION 'MISSING_CAPABILITY: orders.create'; END IF;
    SELECT id INTO v_employee_id FROM employees WHERE identity_id = v_session.identity_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'EMPLOYEE_NOT_FOUND'; END IF;
  ELSE
    IF v_session.customer_id IS NULL OR p_customer_id IS DISTINCT FROM v_session.customer_id THEN
      RAISE EXCEPTION 'FORBIDDEN: customers can only create orders for themselves';
    END IF;
  END IF;

  IF p_tier_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.tiers WHERE id = p_tier_id AND is_active = true) THEN
      RAISE EXCEPTION 'TIER_NOT_FOUND_OR_INACTIVE';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_items) AS vi
    JOIN public.products p ON p.id = (vi->>'product_id')::uuid
    WHERE p.is_out_of_stock = true AND p.is_active = true
  ) THEN
    RAISE EXCEPTION 'ORDER_CONTAINS_OUT_OF_STOCK_PRODUCTS';
  END IF;

  v_exec_location_id := p_execution_location_id;
  IF v_exec_location_id IS NULL AND p_execution_latitude IS NOT NULL AND p_execution_longitude IS NOT NULL THEN
    v_exec_location_id := gen_random_uuid();
    INSERT INTO unified_locations (id, latitude, longitude, accuracy_meters, captured_at)
    VALUES (v_exec_location_id, p_execution_latitude, p_execution_longitude, p_execution_accuracy_meters, COALESCE(p_execution_captured_at, now()));
  END IF;

  SELECT
    c.company_name,
    COALESCE((SELECT phone FROM customer_contacts WHERE customer_id = c.id AND is_primary = true LIMIT 1), ''),
    COALESCE(
      (SELECT formatted_address FROM unified_locations ul WHERE ul.id = c.location_id),
      (SELECT address_line1 FROM customer_addresses ca WHERE ca.customer_id = c.id AND ca.is_default = true LIMIT 1),
      ''
    )
  INTO v_cust_name, v_cust_phone, v_cust_address
  FROM customers c WHERE c.id = p_customer_id;

  SELECT
    COALESCE(e.full_name, ''), COALESCE(i.phone, ''), COALESCE(e.address, '')
  INTO v_owner_name, v_owner_phone, v_owner_address
  FROM customers c
  LEFT JOIN employees e ON e.id = c.owner_id
  LEFT JOIN identities i ON i.id = e.identity_id
  WHERE c.id = p_customer_id;

  IF v_session.identity_type = 'employee' THEN
    SELECT COALESCE(e.full_name, ''), COALESCE(i.phone, ''), COALESCE(e.address, '')
    INTO v_sender_name, v_sender_phone, v_sender_address
    FROM employees e
    LEFT JOIN identities i ON i.id = e.identity_id
    WHERE e.identity_id = v_session.identity_id;
  ELSE
    SELECT COALESCE(c.company_name, ''),
      COALESCE((SELECT phone FROM customer_contacts WHERE customer_id = c.id AND is_primary = true LIMIT 1), ''),
      COALESCE((SELECT formatted_address FROM unified_locations ul WHERE ul.id = c.location_id),
        (SELECT address_line1 FROM customer_addresses ca WHERE ca.customer_id = c.id AND ca.is_default = true LIMIT 1), '')
    INTO v_sender_name, v_sender_phone, v_sender_address
    FROM customers c WHERE c.identity_id = v_session.identity_id;
  END IF;

  SELECT last_sequence + 1 INTO v_seq FROM public.code_sequences WHERE code_type = 'order' AND year = EXTRACT(year FROM now())::int FOR UPDATE;
  IF NOT FOUND THEN v_seq := 1; END IF;
  v_order_number := 'ORD-' || EXTRACT(year FROM now())::int || '-' || LPAD(v_seq::text, 6, '0');

  IF v_session.identity_type = 'employee' THEN
    INSERT INTO public.orders (
      order_number, customer_id, owner_type, owner_id, created_by,
      notes, tier_id, order_type,
      execution_location_id, execution_latitude, execution_longitude,
      execution_accuracy_meters, execution_captured_at,
      snapshot_customer_name, snapshot_customer_phone, snapshot_customer_address,
      snapshot_owner_name, snapshot_owner_phone, snapshot_owner_address,
      snapshot_sender_name, snapshot_sender_phone, snapshot_sender_address
    ) VALUES (
      v_order_number, p_customer_id, 'employee', v_employee_id, v_session.identity_id,
      p_notes, p_tier_id, p_order_type,
      v_exec_location_id, p_execution_latitude, p_execution_longitude,
      p_execution_accuracy_meters, p_execution_captured_at,
      v_cust_name, v_cust_phone, v_cust_address,
      v_owner_name, v_owner_phone, v_owner_address,
      v_sender_name, v_sender_phone, v_sender_address
    ) RETURNING * INTO v_order;
  ELSE
    INSERT INTO public.orders (
      order_number, customer_id, owner_type, owner_id, created_by,
      notes, tier_id, order_type,
      execution_location_id, execution_latitude, execution_longitude,
      execution_accuracy_meters, execution_captured_at,
      snapshot_customer_name, snapshot_customer_phone, snapshot_customer_address,
      snapshot_owner_name, snapshot_owner_phone, snapshot_owner_address,
      snapshot_sender_name, snapshot_sender_phone, snapshot_sender_address
    ) VALUES (
      v_order_number, p_customer_id, 'customer', v_session.identity_id, v_session.identity_id,
      p_notes, p_tier_id, p_order_type,
      v_exec_location_id, p_execution_latitude, p_execution_longitude,
      p_execution_accuracy_meters, p_execution_captured_at,
      v_cust_name, v_cust_phone, v_cust_address,
      v_owner_name, v_owner_phone, v_owner_address,
      v_sender_name, v_sender_phone, v_sender_address
    ) RETURNING * INTO v_order;
  END IF;

  FOR v_order_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    SELECT id, product_name, legacy_code AS product_code, carton_price, carton_quantity
    INTO v_product FROM public.products WHERE id = (v_order_item->>'product_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND: %', (v_order_item->>'product_id')::uuid; END IF;
    v_calculated_unit_price := (v_order_item->>'unit_price')::numeric;
    v_calculated_total_price := ROUND((v_calculated_unit_price * (v_order_item->>'unit_quantity')::numeric)::numeric, 2);
    INSERT INTO public.order_items (order_id, product_id, unit_type, unit_quantity, piece_quantity, unit_price, total_price)
    VALUES (v_order.id, v_product.id, COALESCE(v_order_item->>'unit_type', 'piece'),
      GREATEST(COALESCE((v_order_item->>'unit_quantity')::integer, 1), 1),
      GREATEST(COALESCE((v_order_item->>'piece_quantity')::integer, 0), 1),
      v_calculated_unit_price, v_calculated_total_price);
  END LOOP;

  UPDATE public.orders SET
    subtotal = (SELECT COALESCE(SUM(total_price), 0) FROM public.order_items WHERE order_id = v_order.id),
    total_amount = (SELECT COALESCE(SUM(total_price), 0) FROM public.order_items WHERE order_id = v_order.id)
  WHERE id = v_order.id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (v_order.id, NULL, 'draft', v_session.identity_id, 'Order created');

  UPDATE public.code_sequences SET last_sequence = v_seq
  WHERE code_type = 'order' AND year = EXTRACT(year FROM now())::int;

  BEGIN
    PERFORM fn_enrich_customer_location(
      p_customer_id := p_customer_id, p_latitude := p_execution_latitude,
      p_longitude := p_execution_longitude, p_accuracy_meters := p_execution_accuracy_meters,
      p_accuracy_level := 'GEOCODED');
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'governed_create_order: enrichment failed for order % (customer %): %', v_order.id, p_customer_id, SQLERRM;
  END;

  PERFORM pg_notify('order_created', jsonb_build_object('order_id', v_order.id, 'number', v_order.order_number)::text);

  RETURN jsonb_build_object('success', true, 'id', v_order.id, 'order_number', v_order.order_number);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_product(p_token uuid, p_company_id uuid, p_product_name character varying, p_legacy_code character varying, p_description text DEFAULT NULL::text, p_carton_quantity integer DEFAULT NULL::integer, p_carton_price numeric DEFAULT NULL::numeric, p_units jsonb DEFAULT '["piece", "dozen", "carton"]'::jsonb, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_product_id uuid;
  v_unit text;
  v_piece_price numeric;
  v_dozen_price numeric;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  IF p_carton_price IS NOT NULL AND p_carton_price > 0
     AND p_carton_quantity IS NOT NULL AND p_carton_quantity > 0
  THEN
    v_piece_price := ROUND((p_carton_price / p_carton_quantity)::numeric, 2);
    v_dozen_price := ROUND((p_carton_price / p_carton_quantity * 12)::numeric, 2);
  ELSE
    v_piece_price := 0;
    v_dozen_price := 0;
  END IF;

  INSERT INTO public.products (
    company_id, product_name, legacy_code, description, image_url,
    carton_quantity, carton_price, piece_price, dozen_price,
    is_active, recently_available_at
  ) VALUES (
    p_company_id, p_product_name, p_legacy_code, p_description, p_image_url,
    p_carton_quantity, p_carton_price, v_piece_price, v_dozen_price,
    true, now()
  )
  RETURNING id INTO v_product_id;

  FOR v_unit IN SELECT * FROM jsonb_array_elements_text(p_units)
  LOOP
    INSERT INTO public.product_units (product_id, unit_type, is_active)
    VALUES (v_product_id, v_unit, true);
  END LOOP;

  INSERT INTO public.inventory (product_id, quantity)
  VALUES (v_product_id, 0);

  RETURN jsonb_build_object('success', true, 'id', v_product_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_return(p_token uuid, p_order_id uuid, p_customer_id uuid, p_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb)
 RETURNS returns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE
    v_session app.sessions;
    v_order public.orders;
    v_return public.returns;
    v_code text;
    v_seq int;
    v_item jsonb;
    v_employee_id uuid;
    v_already_returned_pieces int;
    v_requested_pieces int;
    v_product_carton_qty int;
    v_oi record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;

    IF v_session.identity_type = 'employee' THEN
        IF NOT public.check_capability(p_token, 'returns.create') THEN
            RAISE EXCEPTION 'MISSING_CAPABILITY: returns.create';
        END IF;
    END IF;

    IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'RETURN_ITEMS_REQUIRED';
    END IF;

    SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
    IF v_order.status != 'delivered' THEN RAISE EXCEPTION 'INVALID_ORDER_STATUS'; END IF;
    IF v_order.customer_id != p_customer_id THEN RAISE EXCEPTION 'CUSTOMER_MISMATCH'; END IF;

    IF v_session.identity_type = 'employee' THEN
        v_employee_id := v_session.employee_id;
    ELSE
        SELECT owner_id INTO v_employee_id FROM public.customers
        WHERE id = p_customer_id AND owner_type = 'employee';
        IF v_employee_id IS NULL THEN
            SELECT e.id INTO v_employee_id FROM public.employees e
            WHERE e.identity_id = v_order.created_by LIMIT 1;
        END IF;
        IF v_employee_id IS NULL THEN
            RAISE EXCEPTION 'NO_RESPONSIBLE_EMPLOYEE';
        END IF;
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        SELECT oi.id, oi.piece_quantity
        INTO v_oi
        FROM public.order_items oi
        WHERE oi.order_id = p_order_id AND oi.product_id = (v_item->>'product_id')::uuid;
        IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_IN_ORDER'; END IF;

        SELECT COALESCE(carton_quantity, 1) INTO v_product_carton_qty
        FROM public.products WHERE id = (v_item->>'product_id')::uuid;

        SELECT COALESCE(SUM(
            CASE WHEN ri.unit_type = 'piece' THEN ri.quantity
                 WHEN ri.unit_type = 'dozen' THEN ri.quantity * 12
                 WHEN ri.unit_type = 'carton' THEN ri.quantity * v_product_carton_qty
            END
        ), 0) INTO v_already_returned_pieces
        FROM public.return_items ri
        JOIN public.returns r ON r.id = ri.return_id
        WHERE r.order_id = p_order_id
          AND ri.product_id = (v_item->>'product_id')::uuid
          AND r.status != 'rejected';

        v_requested_pieces := public._return_qty_to_pieces(
            (v_item->>'quantity')::int,
            v_item->>'unit_type',
            v_product_carton_qty
        );

        IF v_already_returned_pieces + v_requested_pieces > v_oi.piece_quantity THEN
            RAISE EXCEPTION 'RETURN_QUANTITY_EXCEEDS_ORDERED';
        END IF;
    END LOOP;

    SELECT last_sequence + 1 INTO v_seq FROM public.code_sequences
    WHERE code_type = 'return' AND year = EXTRACT(year FROM now())::int FOR UPDATE;
    IF NOT FOUND THEN v_seq := 1; END IF;
    v_code := 'RET-' || EXTRACT(year FROM now())::int || '-' || LPAD(v_seq::text, 6, '0');

    INSERT INTO public.returns (code, order_id, customer_id, owner_type, owner_id, created_by, notes)
    VALUES (v_code, p_order_id, p_customer_id, 'employee', v_employee_id, v_employee_id, p_notes)
    RETURNING * INTO v_return;

    INSERT INTO public.code_sequences (code_type, year, last_sequence)
    VALUES ('return', EXTRACT(year FROM now())::int, v_seq)
    ON CONFLICT (code_type, year) DO UPDATE SET last_sequence = v_seq;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        INSERT INTO public.return_items (return_id, product_id, unit_type, quantity, reason)
        VALUES (
            v_return.id,
            (v_item->>'product_id')::uuid,
            v_item->>'unit_type',
            (v_item->>'quantity')::int,
            v_item->>'reason'
        );
    END LOOP;

    INSERT INTO public.return_status_history (return_id, from_status, to_status, changed_by, reason)
    VALUES (v_return.id, NULL, 'pending', v_session.identity_id, 'Return created');

    RETURN v_return;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_role(p_token uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
