CREATE OR REPLACE FUNCTION public.governed_create_tier(p_token uuid, p_name character varying, p_description text DEFAULT NULL::text, p_discount_percent numeric DEFAULT 0, p_minimum_order_amount numeric DEFAULT 0, p_color character varying DEFAULT NULL::character varying, p_icon_url text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer, p_is_visible boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_tier_id uuid;
  v_max_order integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'tiers.manage');

  IF p_sort_order IS NULL THEN
    SELECT COALESCE(MAX(sort_order), 0) + 1 INTO v_max_order FROM public.tiers;
    p_sort_order := v_max_order;
  END IF;

  INSERT INTO public.tiers (name, description, discount_percent, minimum_order_amount, color, icon_url, sort_order, is_visible, is_active)
  VALUES (p_name, p_description, p_discount_percent, p_minimum_order_amount, p_color, p_icon_url, p_sort_order, p_is_visible, true)
  RETURNING id INTO v_tier_id;

  RETURN jsonb_build_object('success', true, 'id', v_tier_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_create_visit(p_token uuid, p_customer_id uuid, p_check_in_latitude numeric DEFAULT NULL::numeric, p_check_in_longitude numeric DEFAULT NULL::numeric, p_google_maps_link text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS visits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

    DECLARE
      v_session app.sessions;
      v_visit public.visits;
      v_code text;
      v_seq int;
    BEGIN
      SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
      IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
      IF v_session.identity_type = 'customer' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
      IF NOT public.check_capability(p_token, 'visits.create') THEN RAISE EXCEPTION 'MISSING_CAPABILITY: visits.create'; END IF;

      SELECT last_sequence + 1 INTO v_seq FROM public.code_sequences WHERE code_type = 'visit' AND year = EXTRACT(year FROM now())::int FOR UPDATE;
      IF NOT FOUND THEN v_seq := 1; END IF;
      v_code := 'VIS-' || EXTRACT(year FROM now())::int || '-' || LPAD(v_seq::text, 6, '0');

      INSERT INTO public.visits (code, employee_id, customer_id, check_in_latitude, check_in_longitude, google_maps_link, notes)
      VALUES (v_code, v_session.employee_id, p_customer_id, p_check_in_latitude, p_check_in_longitude, p_google_maps_link, p_notes)
      RETURNING * INTO v_visit;

      INSERT INTO public.code_sequences (code_type, year, last_sequence)
      VALUES ('visit', EXTRACT(year FROM now())::int, v_seq)
      ON CONFLICT (code_type, year) DO UPDATE SET last_sequence = v_seq;

      RETURN v_visit;
    END;
    
$function$;

