CREATE OR REPLACE FUNCTION public.governed_deletion_search_collections(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', cl.id,
        'name', cl.code,
        'code', cl.code,
        'status', cl.status,
        'created_at', cl.created_at,
        'customer_name', (SELECT cu.company_name FROM public.customers cu WHERE cu.id = cl.customer_id),
        'amount', cl.amount,
        'related_counts', jsonb_build_object(
            'treasury_transactions', (SELECT COUNT(*)::int FROM public.treasury_transactions tt WHERE tt.reference_type = 'collection' AND tt.reference_id = cl.id)
        )
    ) ORDER BY cl.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.collections cl
    WHERE (p_search IS NULL OR cl.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR cl.status = p_status)
      AND (p_date_from IS NULL OR cl.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR cl.created_at < (p_date_to + 1)::timestamptz)
      AND (p_customer_id IS NULL OR cl.customer_id = p_customer_id);

    SELECT COUNT(*)::int INTO v_total
    FROM public.collections cl
    WHERE (p_search IS NULL OR cl.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR cl.status = p_status)
      AND (p_date_from IS NULL OR cl.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR cl.created_at < (p_date_to + 1)::timestamptz)
      AND (p_customer_id IS NULL OR cl.customer_id = p_customer_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_companies(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', c.id,
        'name', c.company_name,
        'code', c.legacy_code,
        'status', CASE WHEN c.is_active THEN 'active' ELSE 'inactive' END,
        'created_at', c.created_at,
        'related_counts', jsonb_build_object(
            'products', (SELECT COUNT(*)::int FROM public.products p WHERE p.company_id = c.id),
            'customers', (SELECT COUNT(*)::int FROM public.customers cu WHERE cu.owner_id = c.id OR cu.location_id IN (SELECT id FROM public.locations l WHERE l.company_id = c.id))
        )
    ) ORDER BY c.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.companies c
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.legacy_code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN c.is_active = true ELSE c.is_active = false END))
      AND (p_date_from IS NULL OR c.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR c.created_at < (p_date_to + 1)::timestamptz);

    SELECT COUNT(*)::int INTO v_total
    FROM public.companies c
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.legacy_code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN c.is_active = true ELSE c.is_active = false END))
      AND (p_date_from IS NULL OR c.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR c.created_at < (p_date_to + 1)::timestamptz);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_customers(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_gov text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_rep_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', c.id,
        'name', c.company_name,
        'code', c.code,
        'status', CASE WHEN c.is_active THEN 'active' ELSE 'inactive' END,
        'created_at', c.created_at,
        'owner_name', (SELECT e.full_name FROM public.employees e WHERE e.id = c.owner_id),
        'governorate', (SELECT ca.governorate FROM public.customer_addresses ca WHERE ca.customer_id = c.id LIMIT 1),
        'related_counts', jsonb_build_object(
            'orders', (SELECT COUNT(*)::int FROM public.orders o WHERE o.customer_id = c.id),
            'visits', (SELECT COUNT(*)::int FROM public.visits v WHERE v.customer_id = c.id),
            'collections', (SELECT COUNT(*)::int FROM public.collections cl WHERE cl.customer_id = c.id),
            'returns', (SELECT COUNT(*)::int FROM public.returns r WHERE r.customer_id = c.id),
            'addresses', (SELECT COUNT(*)::int FROM public.customer_addresses ca WHERE ca.customer_id = c.id),
            'contacts', (SELECT COUNT(*)::int FROM public.customer_contacts cc WHERE cc.customer_id = c.id),
            'credit_accounts', (SELECT COUNT(*)::int FROM public.customer_credit_accounts cca WHERE cca.customer_id = c.id)
        )
    ) ORDER BY c.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.customers c
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN c.is_active = true ELSE c.is_active = false END))
      AND (p_date_from IS NULL OR c.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR c.created_at < (p_date_to + 1)::timestamptz)
      AND (p_gov IS NULL OR EXISTS (SELECT 1 FROM public.customer_addresses ca WHERE ca.customer_id = c.id AND ca.governorate = p_gov))
      AND (p_rep_id IS NULL OR c.owner_id = p_rep_id);

    SELECT COUNT(*)::int INTO v_total
    FROM public.customers c
    WHERE (p_search IS NULL OR c.company_name ILIKE '%' || p_search || '%' OR c.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN c.is_active = true ELSE c.is_active = false END))
      AND (p_date_from IS NULL OR c.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR c.created_at < (p_date_to + 1)::timestamptz)
      AND (p_gov IS NULL OR EXISTS (SELECT 1 FROM public.customer_addresses ca WHERE ca.customer_id = c.id AND ca.governorate = p_gov))
      AND (p_rep_id IS NULL OR c.owner_id = p_rep_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_employees(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
    v_oid uuid[];
    v_cid uuid[];
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', e.id,
        'name', e.full_name,
        'code', e.code,
        'status', CASE WHEN e.is_active THEN 'active' ELSE 'inactive' END,
        'created_at', e.created_at,
        'related_counts', jsonb_build_object(
            -- Employee-specific tables
            'employee_roles', (SELECT COUNT(*)::int FROM public.employee_roles x WHERE x.employee_id = e.id),
            'employee_capabilities', (SELECT COUNT(*)::int FROM public.employee_capabilities x WHERE x.employee_id = e.id),
            'employee_monthly_targets', (SELECT COUNT(*)::int FROM public.employee_monthly_targets x WHERE x.employee_id = e.id),
            'employee_weight_overrides', (SELECT COUNT(*)::int FROM public.employee_weight_overrides x WHERE x.employee_id = e.id),
            'employee_work_policies', (SELECT COUNT(*)::int FROM public.employee_work_policies x WHERE x.employee_id = e.id),
            'employee_advances', (SELECT COUNT(*)::int FROM public.employee_advances x WHERE x.employee_id = e.id OR x.created_by = e.id OR x.approved_by = e.id),
            -- Attendance & tracking
            'workday_sessions', (SELECT COUNT(*)::int FROM public.workday_sessions x WHERE x.employee_id = e.id),
            'workday_breaks', (SELECT COUNT(*)::int FROM public.workday_breaks x WHERE x.employee_id = e.id),
            'tracking_points', (SELECT COUNT(*)::int FROM public.tracking_points x WHERE x.employee_id = e.id),
            'attendance_audit_log', (SELECT COUNT(*)::int FROM public.attendance_audit_log x WHERE x.employee_id = e.id),
            'session_recovery_log', (SELECT COUNT(*)::int FROM public.session_recovery_log x WHERE x.employee_id = e.id),
            'tracking_cleanup_log', (SELECT COUNT(*)::int FROM public.tracking_cleanup_log x WHERE x.executed_by = e.id),
            -- Field work
            'visits', (SELECT COUNT(*)::int FROM public.visits x WHERE x.employee_id = e.id),
            'delivery_tracking_assigned_to', (SELECT COUNT(*)::int FROM public.delivery_tracking x WHERE x.assigned_to = e.id),
            'delivery_tracking_assigned_by', (SELECT COUNT(*)::int FROM public.delivery_tracking x WHERE x.assigned_by = e.id),
            'preparation_records', (SELECT COUNT(*)::int FROM public.preparation_records x WHERE x.started_by = e.id OR x.completed_by = e.id OR x.cancelled_by = e.id OR x.reviewed_by = e.id),
            'return_inspection', (SELECT COUNT(*)::int FROM public.return_inspection x WHERE x.inspected_by = e.id),
            -- Financial
            'collections_created_by', (SELECT COUNT(*)::int FROM public.collections x WHERE x.created_by = e.id),
            'collections_approved_by', (SELECT COUNT(*)::int FROM public.collections x WHERE x.approved_by = e.id),
            'treasury_transactions', (SELECT COUNT(*)::int FROM public.treasury_transactions x WHERE x.created_by = e.id),
            'expenses', (SELECT COUNT(*)::int FROM public.expenses x WHERE x.created_by = e.id OR x.approved_by = e.id),
            'returns', (SELECT COUNT(*)::int FROM public.returns x WHERE x.created_by = e.id),
            -- Credit
            'credit_applications', (SELECT COUNT(*)::int FROM public.credit_applications x WHERE x.created_by = e.id OR x.doc_confirmed_by = e.id OR x.reviewed_by = e.id OR x.approved_by = e.id OR x.suspended_by = e.id),
            'credit_contracts', (SELECT COUNT(*)::int FROM public.credit_contracts x WHERE x.verified_by = e.id),
            'customer_credit_ledger', (SELECT COUNT(*)::int FROM public.customer_credit_ledger x WHERE x.created_by = e.id),
            'customer_credit_accounts', (SELECT COUNT(*)::int FROM public.customer_credit_accounts x WHERE x.activated_by = e.id),
            'credit_invoice_cheques', (SELECT COUNT(*)::int FROM public.credit_invoice_cheques x WHERE x.recorded_by = e.id),
            'tier_exceptions', (SELECT COUNT(*)::int FROM public.tier_exceptions x WHERE x.assigned_by = e.id),
            -- Products & deals
            'daily_deals', (SELECT COUNT(*)::int FROM public.daily_deals x WHERE x.created_by = e.id),
            'flash_offers', (SELECT COUNT(*)::int FROM public.flash_offers x WHERE x.created_by = e.id),
            'packages', (SELECT COUNT(*)::int FROM public.packages x WHERE x.created_by = e.id),
            -- Auctions
            'auctions', (SELECT COUNT(*)::int FROM public.auctions x WHERE x.created_by = e.id),
            'auction_participants', (SELECT COUNT(*)::int FROM public.auction_participants x WHERE x.approved_by = e.id),
            'auction_awards', (SELECT COUNT(*)::int FROM public.auction_awards x WHERE x.awarded_by = e.id),
            -- Ownership & customers
            'customer_ownership_history', (SELECT COUNT(*)::int FROM public.customer_ownership_history x WHERE x.previous_owner_id = e.id OR x.new_owner_id = e.id OR x.changed_by = e.id),
            'customers_owner', (SELECT COUNT(*)::int FROM public.customers x WHERE x.owner_id = e.id),
            -- Orders
            'orders', (SELECT COUNT(*)::int FROM public.orders x WHERE x.created_by = e.id),
            -- App sessions
            'app_sessions', (SELECT COUNT(*)::int FROM app.sessions x WHERE x.employee_id = e.id),
            -- Self
            'managed_employees', (SELECT COUNT(*)::int FROM public.employees x WHERE x.manager_id = e.id)
        )
    ) ORDER BY e.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.employees e
    WHERE (p_search IS NULL OR e.full_name ILIKE '%' || p_search || '%' OR e.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN e.is_active = true ELSE e.is_active = false END))
      AND (p_date_from IS NULL OR e.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR e.created_at < (p_date_to + 1)::timestamptz);

    SELECT COUNT(*)::int INTO v_total
    FROM public.employees e
    WHERE (p_search IS NULL OR e.full_name ILIKE '%' || p_search || '%' OR e.code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN e.is_active = true ELSE e.is_active = false END))
      AND (p_date_from IS NULL OR e.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR e.created_at < (p_date_to + 1)::timestamptz);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_orders(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_customer_id uuid DEFAULT NULL::uuid, p_rep_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', o.id,
        'name', o.order_number,
        'code', o.order_number,
        'status', o.status,
        'created_at', o.created_at,
        'customer_name', COALESCE(o.snapshot_customer_name, (SELECT cu.company_name FROM public.customers cu WHERE cu.id = o.customer_id)),
        'owner_name', COALESCE(o.snapshot_owner_name, (SELECT e.full_name FROM public.employees e WHERE e.id = o.owner_id)),
        'total_amount', o.total_amount,
        'related_counts', jsonb_build_object(
            'order_items', (SELECT COUNT(*)::int FROM public.order_items oi WHERE oi.order_id = o.id),
            'delivery_tracking', (SELECT COUNT(*)::int FROM public.delivery_tracking dt WHERE dt.order_id = o.id),
            'returns', (SELECT COUNT(*)::int FROM public.returns r WHERE r.order_id = o.id),
            'collections', (SELECT COUNT(*)::int FROM public.collections cl WHERE cl.order_id = o.id),
            'preparation_records', (SELECT COUNT(*)::int FROM public.preparation_records pr WHERE pr.order_id = o.id),
            'credit_invoices', (SELECT COUNT(*)::int FROM public.credit_invoices ci WHERE ci.order_id = o.id)
        )
    ) ORDER BY o.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.orders o
    WHERE (p_search IS NULL OR o.order_number ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR o.created_at < (p_date_to + 1)::timestamptz)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_rep_id IS NULL OR o.owner_id = p_rep_id);

    SELECT COUNT(*)::int INTO v_total
    FROM public.orders o
    WHERE (p_search IS NULL OR o.order_number ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR o.status = p_status)
      AND (p_date_from IS NULL OR o.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR o.created_at < (p_date_to + 1)::timestamptz)
      AND (p_customer_id IS NULL OR o.customer_id = p_customer_id)
      AND (p_rep_id IS NULL OR o.owner_id = p_rep_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_products(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_company_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', p.id,
        'name', p.product_name,
        'code', p.legacy_code,
        'status', CASE WHEN p.is_active THEN 'active' ELSE 'inactive' END,
        'created_at', p.created_at,
        'company_name', (SELECT cp.company_name FROM public.companies cp WHERE cp.id = p.company_id),
        'related_counts', jsonb_build_object(
            'order_items', (SELECT COUNT(*)::int FROM public.order_items oi WHERE oi.product_id = p.id),
            'inventory', (SELECT COUNT(*)::int FROM public.inventory i WHERE i.product_id = p.id),
            'product_units', (SELECT COUNT(*)::int FROM public.product_units pu WHERE pu.product_id = p.id),
            'return_items', (SELECT COUNT(*)::int FROM public.return_items ri WHERE ri.product_id = p.id),
            'daily_deal_items', (SELECT COUNT(*)::int FROM public.daily_deal_items ddi WHERE ddi.product_id = p.id),
            'flash_offer_items', (SELECT COUNT(*)::int FROM public.flash_offer_items foi WHERE foi.product_id = p.id),
            'auction_items', (SELECT COUNT(*)::int FROM public.auction_items ai WHERE ai.product_id = p.id)
        )
    ) ORDER BY p.created_at DESC), '[]'::jsonb)
    INTO v_data
    FROM public.products p
    WHERE (p_search IS NULL OR p.product_name ILIKE '%' || p_search || '%' OR p.legacy_code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN p.is_active = true ELSE p.is_active = false END))
      AND (p_date_from IS NULL OR p.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR p.created_at < (p_date_to + 1)::timestamptz)
      AND (p_company_id IS NULL OR p.company_id = p_company_id);

    SELECT COUNT(*)::int INTO v_total
    FROM public.products p
    WHERE (p_search IS NULL OR p.product_name ILIKE '%' || p_search || '%' OR p.legacy_code ILIKE '%' || p_search || '%')
      AND (p_status IS NULL OR (CASE WHEN p_status = 'active' THEN p.is_active = true ELSE p.is_active = false END))
      AND (p_date_from IS NULL OR p.created_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR p.created_at < (p_date_to + 1)::timestamptz)
      AND (p_company_id IS NULL OR p.company_id = p_company_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_deletion_search_tracking(p_token uuid, p_search text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_rep_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(subq ORDER BY subq.recorded_at DESC), '[]'::jsonb)
    INTO v_data
    FROM (
        SELECT jsonb_build_object(
            'id', tp.id,
            'name', tp.recorded_at::text,
            'code', tp.id::text,
            'status', tp.point_type,
            'created_at', tp.recorded_at,
            'employee_name', (SELECT e.full_name FROM public.employees e WHERE e.id = tp.employee_id),
            'recorded_at', tp.recorded_at,
            'session_date', (SELECT ws.date::text FROM public.workday_sessions ws WHERE ws.id = tp.session_id),
            'related_counts', '{}'::jsonb
        ) AS row_data,
        tp.recorded_at
        FROM public.tracking_points tp
        WHERE (p_search IS NULL OR tp.id::text ILIKE '%' || p_search || '%')
          AND (p_date_from IS NULL OR tp.recorded_at >= p_date_from::timestamptz)
          AND (p_date_to IS NULL OR tp.recorded_at < (p_date_to + 1)::timestamptz)
          AND (p_rep_id IS NULL OR tp.employee_id = p_rep_id)
        ORDER BY tp.recorded_at DESC
        LIMIT 1000
    ) subq;

    SELECT COUNT(*)::int INTO v_total
    FROM public.tracking_points tp
    WHERE (p_search IS NULL OR tp.id::text ILIKE '%' || p_search || '%')
      AND (p_date_from IS NULL OR tp.recorded_at >= p_date_from::timestamptz)
      AND (p_date_to IS NULL OR tp.recorded_at < (p_date_to + 1)::timestamptz)
      AND (p_rep_id IS NULL OR tp.employee_id = p_rep_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

