CREATE OR REPLACE FUNCTION public.governed_deletion_search_workdays(p_token uuid, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_rep_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_data jsonb;
    v_total int;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF NOT public.check_capability(p_token, 'data.deletion_center') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', ws.id,
        'name', ws.date::text || ' - ' || COALESCE((SELECT e.full_name FROM public.employees e WHERE e.id = ws.employee_id), ''),
        'code', ws.date::text,
        'status', ws.status,
        'created_at', ws.created_at,
        'employee_name', (SELECT e.full_name FROM public.employees e WHERE e.id = ws.employee_id),
        'date', ws.date,
        'related_counts', jsonb_build_object(
            'tracking_points', (SELECT COUNT(*)::int FROM public.tracking_points tp WHERE tp.session_id = ws.id),
            'workday_breaks', (SELECT COUNT(*)::int FROM public.workday_breaks wb WHERE wb.session_id = ws.id),
            'visit_links', (SELECT COUNT(*)::int FROM public.visit_links vl WHERE vl.session_id = ws.id)
        )
    ) ORDER BY ws.date DESC), '[]'::jsonb)
    INTO v_data
    FROM public.workday_sessions ws
    WHERE (p_search IS NULL OR EXISTS (SELECT 1 FROM public.employees e WHERE e.id = ws.employee_id AND e.full_name ILIKE '%' || p_search || '%'))
      AND (p_status IS NULL OR ws.status = p_status)
      AND (p_date_from IS NULL OR ws.date >= p_date_from::date)
      AND (p_date_to IS NULL OR ws.date <= p_date_to::date)
      AND (p_rep_id IS NULL OR ws.employee_id = p_rep_id);

    SELECT COUNT(*)::int INTO v_total
    FROM public.workday_sessions ws
    WHERE (p_search IS NULL OR EXISTS (SELECT 1 FROM public.employees e WHERE e.id = ws.employee_id AND e.full_name ILIKE '%' || p_search || '%'))
      AND (p_status IS NULL OR ws.status = p_status)
      AND (p_date_from IS NULL OR ws.date >= p_date_from::date)
      AND (p_date_to IS NULL OR ws.date <= p_date_to::date)
      AND (p_rep_id IS NULL OR ws.employee_id = p_rep_id);

    RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_dispatch_decision(p_token uuid, p_id uuid, p_action text, p_assigned_to uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_follow_up_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_order public.orders; v_authorized boolean; v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_authorized := public.is_upper_management(v_session.employee_id);
  IF NOT v_authorized THEN RETURN json_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only'); END IF;
  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'NOT_FOUND'); END IF;
  IF v_order.status != 'ready_for_dispatch' THEN RETURN json_build_object('error', 'INVALID_STATE', 'detail', 'Order must be in ready_for_dispatch status'); END IF;
  IF p_action = 'send' THEN
    IF p_assigned_to IS NULL THEN RETURN json_build_object('error', 'MISSING_ASSIGNEE', 'detail', 'A delivery employee must be assigned'); END IF;
    UPDATE public.orders SET status = 'sent_to_delivery', updated_at = now() WHERE id = p_id;
    INSERT INTO public.delivery_tracking (order_id, status, assigned_to, assigned_by, assigned_at) VALUES (p_id, 'assigned', p_assigned_to, v_session.employee_id, now()) RETURNING * INTO v_dt;
    INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason) VALUES (p_id, 'ready_for_dispatch', 'sent_to_delivery', v_session.identity_id, COALESCE(p_reason, 'Sent to delivery'));
    RETURN json_build_object('action', 'sent_to_delivery', 'order_status', 'sent_to_delivery', 'delivery_id', v_dt.id);
  ELSIF p_action = 'defer' THEN
    IF p_follow_up_date IS NULL THEN RETURN json_build_object('error', 'MISSING_FOLLOW_UP', 'detail', 'Follow-up date is required for deferral'); END IF;
    UPDATE public.orders SET status = 'deferred', deferred_until = p_follow_up_date, defer_reason = p_reason, updated_at = now() WHERE id = p_id;
    INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason) VALUES (p_id, 'ready_for_dispatch', 'deferred', v_session.identity_id, COALESCE(p_reason, 'Order deferred'));
    RETURN json_build_object('action', 'deferred', 'order_status', 'deferred', 'deferred_until', p_follow_up_date);
  ELSIF p_action = 'cancel' THEN
    IF p_reason IS NULL THEN RETURN json_build_object('error', 'MISSING_REASON', 'detail', 'Cancellation reason is required'); END IF;
    UPDATE public.orders SET status = 'cancelled', cancelled_at = now(), cancel_reason = p_reason, updated_at = now() WHERE id = p_id;
    INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason) VALUES (p_id, 'ready_for_dispatch', 'cancelled', v_session.identity_id, p_reason);
    RETURN json_build_object('action', 'cancelled', 'order_status', 'cancelled', 'cancelled_at', now());
  ELSE
    RETURN json_build_object('error', 'INVALID_ACTION', 'detail', 'Action must be send, defer, or cancel');
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_dispatch_order(p_token text, p_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_external_carrier_id uuid DEFAULT NULL::uuid, p_waybill_number character varying DEFAULT NULL::character varying, p_tracking_url text DEFAULT NULL::text, p_vehicle_number character varying DEFAULT NULL::character varying, p_departure_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_carrier_name text DEFAULT NULL::text, p_carrier_delivery_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_employee_id uuid;
  v_old_status varchar(30);
  v_prev_attempt integer;
  v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  v_employee_id := v_session.employee_id;
  PERFORM check_capability(p_token, 'orders.dispatch');

  SELECT status INTO v_old_status FROM public.orders WHERE id = p_id;
  IF v_old_status IS NULL THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;
  IF v_old_status NOT IN ('approved', 'preparing', 'prepared', 'ready_for_dispatch', 'sent_to_delivery') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE: cannot dispatch order in status ' || v_old_status);
  END IF;

  IF p_carrier_name IS NOT NULL OR p_external_carrier_id IS NOT NULL THEN
    UPDATE public.orders SET delivery_mode = 'external', updated_at = now() WHERE id = p_id;
  ELSIF p_assigned_to IS NOT NULL THEN
    UPDATE public.orders SET delivery_mode = 'internal', updated_at = now() WHERE id = p_id;
  END IF;

  UPDATE public.orders SET status = 'dispatched', updated_at = now() WHERE id = p_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, changed_at)
  VALUES (p_id, v_old_status, 'dispatched', v_session.identity_id, now());

  UPDATE public.delivery_tracking SET is_active = false
  WHERE order_id = p_id AND is_active = true;

  SELECT COALESCE(MAX(attempt_number), 0) + 1 INTO v_prev_attempt
  FROM public.delivery_tracking WHERE order_id = p_id;

  IF p_carrier_name IS NOT NULL THEN
    INSERT INTO public.delivery_tracking (
      order_id, status, carrier_name, waybill_number, tracking_url,
      carrier_delivery_date, assigned_by, assigned_at, attempt_number, is_active, notes
    ) VALUES (
      p_id, 'assigned', p_carrier_name, p_waybill_number, p_tracking_url,
      p_carrier_delivery_date, v_employee_id, now(), v_prev_attempt, true,
      COALESCE(p_notes, 'External delivery')
    ) RETURNING * INTO v_dt;
  ELSIF p_external_carrier_id IS NOT NULL THEN
    INSERT INTO public.delivery_tracking (
      order_id, status, external_carrier_id, waybill_number, tracking_url,
      assigned_by, assigned_at, attempt_number, is_active, notes
    ) VALUES (
      p_id, 'assigned', p_external_carrier_id, p_waybill_number, p_tracking_url,
      v_employee_id, now(), v_prev_attempt, true,
      COALESCE(p_notes, 'External delivery')
    ) RETURNING * INTO v_dt;
  ELSE
    INSERT INTO public.delivery_tracking (
      order_id, status, assigned_to, assigned_by, assigned_at, attempt_number, is_active,
      vehicle_number, departure_date, notes
    ) VALUES (
      p_id, 'assigned', p_assigned_to, v_employee_id, now(), v_prev_attempt, true,
      p_vehicle_number, p_departure_date, p_notes
    ) RETURNING * INTO v_dt;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'delivery_id', v_dt.id,
    'attempt_number', v_dt.attempt_number,
    'delivery_mode', CASE WHEN p_carrier_name IS NOT NULL OR p_external_carrier_id IS NOT NULL THEN 'external' ELSE 'internal' END
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_end_auction(p_token uuid, p_auction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auction public.auctions;
  v_winning_bid public.auction_bids;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'auctions.manage');

  SELECT * INTO v_auction FROM public.auctions WHERE id = p_auction_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'AUCTION_NOT_FOUND'); END IF;
  IF v_auction.status != 'live' THEN RETURN jsonb_build_object('error', 'AUCTION_NOT_LIVE'); END IF;

  -- Find winning bid
  SELECT * INTO v_winning_bid FROM public.auction_bids
  WHERE auction_id = p_auction_id AND is_winning = true LIMIT 1;

  UPDATE public.auctions SET
    status = 'ended',
    winner_id = v_winning_bid.participant_id,
    winner_amount = v_winning_bid.amount,
    updated_at = now()
  WHERE id = p_auction_id;

  -- Create award
  IF v_winning_bid.id IS NOT NULL THEN
    INSERT INTO public.auction_awards (auction_id, participant_id, amount, status, awarded_by, confirmation_deadline)
    VALUES (p_auction_id, v_winning_bid.participant_id, v_winning_bid.amount, 'pending', v_session.employee_id, now() + interval '1 hour');

    INSERT INTO public.auction_activity (auction_id, activity_type, actor_name, message)
    VALUES (p_auction_id, 'auction_ended', NULL, 'انتهى المزاد. جاري تأكيد الفائز.');
  END IF;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_fail_delivery(p_token text, p_delivery_id uuid, p_reason character varying, p_notes text DEFAULT NULL::text)
 RETURNS delivery_tracking
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'delivery.deliver') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_dt FROM public.delivery_tracking WHERE id = p_delivery_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_dt.status NOT IN ('out_for_delivery','assigned') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.delivery_tracking SET status = 'failed', failure_reason = p_reason, failure_notes = p_notes, completed_at = now(), updated_at = now() WHERE id = p_delivery_id RETURNING * INTO v_dt;
  RETURN v_dt;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_fail_preparation(p_token uuid, p_preparation_id uuid, p_failure_reason text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE
  v_session app.sessions;
  v_prep_status text;
  v_order_id uuid;
  v_order_status text;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'warehouse.prepare') THEN
    RETURN json_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT status::text, order_id INTO v_prep_status, v_order_id
  FROM public.preparation_records WHERE id = p_preparation_id;
  IF v_order_id IS NULL THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_prep_status NOT IN ('in_progress', 'completed') THEN
    RETURN json_build_object('error', 'INVALID_STATUS', 'detail', 'Can only fail in_progress or completed preparations');
  END IF;

  SELECT status::text INTO v_order_status FROM public.orders WHERE id = v_order_id;

  UPDATE public.preparation_records
  SET status = 'failed'::preparation_status,
      cancelled_by = v_session.employee_id,
      cancelled_at = now(),
      notes = COALESCE(p_notes, notes) || E'\nFailure reason: ' || p_failure_reason,
      updated_at = now()
  WHERE id = p_preparation_id;

  UPDATE public.orders SET status = 'approved', updated_at = now() WHERE id = v_order_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason, changed_at)
  VALUES (v_order_id, v_order_status, 'approved', v_session.identity_id, 'Preparation failed: ' || p_failure_reason, now());

  RETURN json_build_object(
    'id', p_preparation_id,
    'order_id', v_order_id,
    'status', 'failed',
    'failure_reason', p_failure_reason,
    'cancelled_by', v_session.employee_id,
    'cancelled_at', now()
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_get_contract_by_application(p_token uuid, p_application_id uuid)
 RETURNS SETOF credit_contracts
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_application_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' AND v_app.customer_id IS DISTINCT FROM v_session.customer_id THEN RETURN; END IF;
  RETURN QUERY SELECT cc.* FROM public.credit_contracts cc WHERE cc.application_id = p_application_id LIMIT 1;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_get_contract_template(p_token uuid)
 RETURNS SETOF credit_contract_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  RETURN QUERY SELECT * FROM public.credit_contract_templates WHERE is_active = true ORDER BY updated_at DESC LIMIT 1;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_get_credit_programs(p_token uuid, p_include_inactive boolean DEFAULT false)
 RETURNS SETOF credit_programs
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_is_admin boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN; END IF;
  IF v_session.identity_type = 'customer' OR NOT p_include_inactive THEN
    RETURN QUERY SELECT * FROM public.credit_programs WHERE is_active = true ORDER BY credit_limit;
  ELSE
    SELECT EXISTS(SELECT 1 FROM public.check_capability(p_token, 'credit.manage_programs')) INTO v_is_admin;
    IF v_is_admin THEN
      RETURN QUERY SELECT * FROM public.credit_programs ORDER BY is_active DESC, credit_limit;
    ELSE
      RETURN QUERY SELECT * FROM public.credit_programs WHERE is_active = true ORDER BY credit_limit;
    END IF;
  END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_get_delivery(p_token text, p_delivery_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT jsonb_build_object('delivery', row_to_json(dt)::jsonb, 'order', row_to_json(o)::jsonb, 'customer', row_to_json(c)::jsonb, 'assigned_employee', (SELECT row_to_json(e)::jsonb FROM employees e WHERE e.id = dt.assigned_to)) INTO v_result FROM public.delivery_tracking dt JOIN public.orders o ON o.id = dt.order_id JOIN public.customers c ON c.id = o.customer_id WHERE dt.id = p_delivery_id AND (v_session.identity_type != 'customer' OR o.customer_id = v_session.customer_id);
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_global_search(p_token uuid, p_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb; v_ql text; v_emp_id uuid; v_is_super boolean; v_sub_ids uuid[];
  v_orders jsonb; v_companies jsonb; v_collections jsonb; v_visits jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;
  v_ql := '%' || p_query || '%';
  v_emp_id := v_session.employee_id;
  v_is_super := public.is_upper_management(v_emp_id);
  WITH RECURSIVE sub AS (
    SELECT e.id FROM employees e WHERE e.manager_id = v_emp_id
    UNION ALL SELECT e.id FROM employees e JOIN sub s ON e.manager_id = s.id
  )
  SELECT COALESCE(ARRAY_AGG(id), '{}'::uuid[]) INTO v_sub_ids FROM sub;
  SELECT jsonb_agg(jsonb_build_object('type','order','id',o.id,'label',o.order_number,'sublabel',COALESCE(cust.company_name,'')||' | '||COALESCE(o.total_amount::text,'0'),'path','/orders/'||o.id)) INTO v_orders
  FROM orders o LEFT JOIN customers cust ON cust.id = o.customer_id
  WHERE o.order_number ILIKE v_ql OR cust.company_name ILIKE v_ql LIMIT 5;
  SELECT jsonb_agg(jsonb_build_object('type','company','id',comp.id,'label',comp.company_name,'sublabel',COALESCE(comp.legacy_code,''),'path','/storefront/products?company='||comp.id)) INTO v_companies
  FROM companies comp WHERE comp.company_name ILIKE v_ql OR comp.legacy_code ILIKE v_ql LIMIT 5;
  SELECT jsonb_agg(jsonb_build_object('type','collection','id',col.id,'label',col.code,'sublabel',COALESCE(cust2.company_name,'')||' | '||COALESCE(col.amount::text,'0'),'path','/collections')) INTO v_collections
  FROM collections col LEFT JOIN customers cust2 ON cust2.id = col.customer_id
  WHERE (col.code ILIKE v_ql OR cust2.company_name ILIKE v_ql) AND (v_is_super OR col.created_by = v_emp_id) LIMIT 5;
  SELECT jsonb_agg(jsonb_build_object('type','visit','id',v.id,'label',COALESCE(cust3.company_name,''),'sublabel',COALESCE(v.status,''),'path','/visits/'||v.id)) INTO v_visits
  FROM visits v LEFT JOIN customers cust3 ON cust3.id = v.customer_id
  WHERE cust3.company_name ILIKE v_ql AND (v_is_super OR v.employee_id = v_emp_id OR v.employee_id = ANY(v_sub_ids)) LIMIT 5;
  v_result := COALESCE(v_orders, '[]'::jsonb) || COALESCE(v_companies, '[]'::jsonb) || COALESCE(v_collections, '[]'::jsonb) || COALESCE(v_visits, '[]'::jsonb);
  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_inventory_deduct(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_order record;
  v_item record;
  v_inv record;
  v_product record;
  v_deducted_items jsonb := '[]'::jsonb;
  v_new_qty integer;
  v_negative_selling boolean;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  -- Exactly-once guard
  IF v_order.inventory_deducted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_deducted', true);
  END IF;

  -- Check per-order negative selling policy
  v_negative_selling := v_order.order_negative_selling_allowed;

  -- Deduct normal order items
  FOR v_item IN
    SELECT oi.product_id, oi.piece_quantity, oi.unit_type, oi.unit_quantity
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
  LOOP
    SELECT * INTO v_inv FROM public.inventory
    WHERE product_id = v_item.product_id FOR UPDATE;

    IF FOUND THEN
      IF v_negative_selling THEN
        v_new_qty := v_inv.quantity - v_item.piece_quantity;
      ELSE
        IF v_inv.quantity < v_item.piece_quantity THEN
          RETURN jsonb_build_object(
            'error', 'INSUFFICIENT_STOCK',
            'product_id', v_item.product_id,
            'available', v_inv.quantity,
            'required', v_item.piece_quantity
          );
        END IF;
        v_new_qty := v_inv.quantity - v_item.piece_quantity;
      END IF;

      UPDATE public.inventory
      SET quantity = v_new_qty, updated_at = now()
      WHERE product_id = v_item.product_id;

      v_deducted_items := v_deducted_items || jsonb_build_object(
        'product_id', v_item.product_id,
        'piece_quantity', v_item.piece_quantity
      );
    END IF;
  END LOOP;

  -- Deduct daily deal component inventory
  FOR v_item IN
    SELECT di.product_id, (di.quantity * odd.quantity) AS total_pieces
    FROM public.order_daily_deals odd
    JOIN public.daily_deal_items di ON di.deal_id = odd.deal_id
    WHERE odd.order_id = p_order_id
  LOOP
    SELECT * INTO v_inv FROM public.inventory
    WHERE product_id = v_item.product_id FOR UPDATE;

    IF FOUND THEN
      IF NOT v_negative_selling AND v_inv.quantity < v_item.total_pieces THEN
        RETURN jsonb_build_object(
          'error', 'INSUFFICIENT_STOCK',
          'product_id', v_item.product_id,
          'available', v_inv.quantity,
          'required', v_item.total_pieces
        );
      END IF;

      UPDATE public.inventory
      SET quantity = v_inv.quantity - v_item.total_pieces, updated_at = now()
      WHERE product_id = v_item.product_id;

      v_deducted_items := v_deducted_items || jsonb_build_object(
        'product_id', v_item.product_id,
        'piece_quantity', v_item.total_pieces
      );
    END IF;
  END LOOP;

  -- Deduct flash offer component inventory
  FOR v_item IN
    SELECT foi.product_id, (foi.quantity * ofo.quantity) AS total_pieces
    FROM public.order_flash_offers ofo
    JOIN public.flash_offer_items foi ON foi.offer_id = ofo.offer_id
    WHERE ofo.order_id = p_order_id
  LOOP
    SELECT * INTO v_inv FROM public.inventory
    WHERE product_id = v_item.product_id FOR UPDATE;

    IF FOUND THEN
      IF NOT v_negative_selling AND v_inv.quantity < v_item.total_pieces THEN
        RETURN jsonb_build_object(
          'error', 'INSUFFICIENT_STOCK',
          'product_id', v_item.product_id,
          'available', v_inv.quantity,
          'required', v_item.total_pieces
        );
      END IF;

      UPDATE public.inventory
      SET quantity = v_inv.quantity - v_item.total_pieces, updated_at = now()
      WHERE product_id = v_item.product_id;

      v_deducted_items := v_deducted_items || jsonb_build_object(
        'product_id', v_item.product_id,
        'piece_quantity', v_item.total_pieces
      );
    END IF;
  END LOOP;

  -- Mark as deducted (exactly-once)
  UPDATE public.orders
  SET inventory_deducted_at = now(),
      inventory_deducted_items = v_deducted_items,
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'deducted', true,
    'item_count', jsonb_array_length(v_deducted_items)
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_inventory_restore(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_order record;
  v_item jsonb;
  v_restored_count integer := 0;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  IF v_order.inventory_deducted_at IS NULL OR v_order.inventory_deducted_items IS NULL THEN
    RETURN jsonb_build_object('success', true, 'nothing_to_restore', true);
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_order.inventory_deducted_items)
  LOOP
    UPDATE public.inventory
    SET quantity = quantity + (v_item->>'piece_quantity')::integer,
        updated_at = now()
    WHERE product_id = (v_item->>'product_id')::uuid;

    v_restored_count := v_restored_count + 1;
  END LOOP;

  UPDATE public.orders
  SET inventory_deducted_at = NULL,
      inventory_deducted_items = NULL,
      updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'restored', true,
    'item_count', v_restored_count
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_place_bid(p_token uuid, p_auction_id uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auction public.auctions;
  v_participant public.auction_participants;
  v_current_top public.auction_bids;
  v_min_acceptable numeric;
  v_bid_id uuid;
  v_company_name varchar(255);
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_auction FROM public.auctions WHERE id = p_auction_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'AUCTION_NOT_FOUND'); END IF;
  IF v_auction.status != 'live' THEN RETURN jsonb_build_object('error', 'AUCTION_NOT_LIVE'); END IF;
  IF now() > v_auction.end_time THEN RETURN jsonb_build_object('error', 'AUCTION_ENDED'); END IF;

  -- Find participant
  IF v_session.customer_id IS NOT NULL THEN
    SELECT * INTO v_participant FROM public.auction_participants
    WHERE auction_id = p_auction_id AND participant_type = 'customer' AND participant_id = v_session.customer_id;
    SELECT company_name INTO v_company_name FROM public.customers WHERE id = v_session.customer_id;
  ELSIF v_session.employee_id IS NOT NULL THEN
    SELECT * INTO v_participant FROM public.auction_participants
    WHERE auction_id = p_auction_id AND participant_type = 'employee' AND participant_id = v_session.employee_id;
    SELECT full_name INTO v_company_name FROM public.employees WHERE id = v_session.employee_id;
  END IF;

  IF v_participant.id IS NULL THEN RETURN jsonb_build_object('error', 'NOT_PARTICIPANT'); END IF;
  IF v_participant.status != 'approved' THEN RETURN jsonb_build_object('error', 'NOT_APPROVED'); END IF;

  -- Validate bid amount
  SELECT * INTO v_current_top FROM public.auction_bids
  WHERE auction_id = p_auction_id AND is_winning = true LIMIT 1;

  IF v_current_top.id IS NULL THEN
    v_min_acceptable := v_auction.starting_price;
  ELSE
    v_min_acceptable := v_current_top.amount + v_auction.bid_increment;
  END IF;

  IF p_amount < v_min_acceptable THEN
    RETURN jsonb_build_object('error', 'BID_TOO_LOW', 'minimum_acceptable', v_min_acceptable);
  END IF;

  -- Reset previous winning bids
  UPDATE public.auction_bids SET is_winning = false
  WHERE auction_id = p_auction_id AND is_winning = true;

  -- Insert new bid
  INSERT INTO public.auction_bids (auction_id, participant_id, amount, is_winning)
  VALUES (p_auction_id, v_participant.id, p_amount, true)
  RETURNING id INTO v_bid_id;

  -- Update auction current price
  UPDATE public.auctions SET current_price = p_amount, updated_at = now() WHERE id = p_auction_id;

  -- Add activity
  INSERT INTO public.auction_activity (auction_id, activity_type, actor_name, message, metadata)
  VALUES (
    p_auction_id, 'bid_placed', v_company_name,
    v_company_name || ' رفعت السعر إلى ' || p_amount || ' جنيه',
    jsonb_build_object('amount', p_amount, 'participant_id', v_participant.id)
  );

  RETURN jsonb_build_object('success', true, 'bid_id', v_bid_id, 'new_current_price', p_amount);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reactivate_credit(p_token uuid, p_id uuid)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.suspend') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status != 'suspended' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.credit_applications SET status = 'approved', updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reactivate_credit_account(p_token uuid, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'credit.account.reactivate');

  UPDATE public.customer_credit_accounts SET
    credit_status = 'active', updated_at = now()
  WHERE customer_id = p_customer_id AND credit_status = 'suspended';

  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND_OR_NOT_SUSPENDED'); END IF;

    INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, notes, created_by)
    SELECT p_customer_id, 'credit', 0, outstanding_credit, 'إعادة تفعيل الحساب الائتماني', v_session.employee_id
  FROM public.customer_credit_accounts WHERE customer_id = p_customer_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_record_cheque(p_token uuid, p_invoice_id uuid, p_cheque_number character varying, p_bank_name character varying, p_amount numeric, p_due_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'credit.cheque.manage');

  IF EXISTS (SELECT 1 FROM public.credit_invoice_cheques WHERE invoice_id = p_invoice_id) THEN
    RETURN jsonb_build_object('error', 'CHEQUE_ALREADY_EXISTS');
  END IF;

  INSERT INTO public.credit_invoice_cheques (invoice_id, cheque_number, bank_name, amount, due_date, recorded_by)
  VALUES (p_invoice_id, p_cheque_number, p_bank_name, p_amount, p_due_date, v_session.employee_id);

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_record_credit_payment(p_token uuid, p_invoice_id uuid, p_payment_method character varying DEFAULT 'collected'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_invoice public.credit_invoices;
  v_customer_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'credit.payment.record');

  SELECT * INTO v_invoice FROM public.credit_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVOICE_NOT_FOUND'); END IF;
  IF v_invoice.status = 'paid' THEN RETURN jsonb_build_object('error', 'ALREADY_PAID'); END IF;

  v_customer_id := v_invoice.customer_id;

  -- Update invoice
  UPDATE public.credit_invoices SET status = 'paid', paid_at = now(), updated_at = now() WHERE id = p_invoice_id;

  -- Update cheque status if exists
  IF p_payment_method IN ('collected', 'paid_directly') THEN
    UPDATE public.credit_invoice_cheques SET status = p_payment_method::public.cheque_status
    WHERE invoice_id = p_invoice_id;
  END IF;

  -- Reduce outstanding credit
  UPDATE public.customer_credit_accounts SET
    outstanding_credit = GREATEST(0, outstanding_credit - v_invoice.invoice_amount),
    updated_at = now()
  WHERE customer_id = v_customer_id;

  -- Log to ledger
    INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, reference_type, reference_id, notes, created_by)
    SELECT v_customer_id, 'credit', v_invoice.invoice_amount,
      (SELECT outstanding_credit FROM public.customer_credit_accounts WHERE customer_id = v_customer_id),
      'credit_invoice', p_invoice_id, 'تسجيل دفع فاتورة ائتمان', v_session.employee_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_record_exception(p_token uuid, p_preparation_id uuid, p_exception_type text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE
  v_employee_id uuid;
  v_prep_status text;
  v_exc_id uuid;
BEGIN
  SELECT employee_id INTO v_employee_id FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'warehouse.prepare') THEN
    RETURN json_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT status::text INTO v_prep_status FROM public.preparation_records WHERE id = p_preparation_id;
  IF v_prep_status IS NULL THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_prep_status NOT IN ('in_progress', 'completed') THEN
    RETURN json_build_object('error', 'INVALID_STATUS', 'detail', 'Can only record exceptions on active or completed preparations');
  END IF;

  INSERT INTO public.preparation_exceptions (preparation_id, exception_type, notes, created_by)
  VALUES (p_preparation_id, p_exception_type::public.preparation_exception_type, p_notes, v_employee_id)
  RETURNING id INTO v_exc_id;

  RETURN json_build_object('id', v_exc_id, 'preparation_id', p_preparation_id, 'exception_type', p_exception_type, 'created_by', v_employee_id, 'created_at', now());
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reject_credit(p_token uuid, p_id uuid, p_reason text)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.approve') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status NOT IN ('documents_received','under_review','submitted') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.credit_applications SET status = 'rejected', approved_by = v_session.employee_id, approved_at = now(), rejection_reason = p_reason, updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reject_order(p_token text, p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'orders.approve') THEN RAISE EXCEPTION 'MISSING_CAPABILITY: orders.approve'; END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_order.status IN ('delivered', 'cancelled') THEN RAISE EXCEPTION 'INVALID_STATE: order cannot be rejected'; END IF;

  UPDATE public.orders SET status = 'cancelled', cancelled_at = now(), updated_at = now() WHERE id = p_id RETURNING * INTO v_order;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (p_id, v_order.status, 'cancelled', v_session.identity_id, COALESCE(p_reason, 'Order rejected'));

  RETURN v_order;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reject_return(p_token uuid, p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS returns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE
    v_session app.sessions;
    v_return public.returns;
    v_old_status varchar(20);
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
    IF v_session.identity_type = 'customer' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
    IF NOT public.check_capability(p_token, 'returns.approve') THEN RAISE EXCEPTION 'MISSING_CAPABILITY: returns.approve'; END IF;

    SELECT * INTO v_return FROM public.returns WHERE id = p_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
    IF v_return.status IN ('approved', 'rejected') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;

    v_old_status := v_return.status;

    UPDATE public.returns SET
        status = 'rejected',
        notes = COALESCE(p_reason, notes),
        updated_at = now()
    WHERE id = p_id
    RETURNING * INTO v_return;

    INSERT INTO public.return_status_history (return_id, from_status, to_status, changed_by, reason)
    VALUES (p_id, v_old_status, 'rejected', v_session.identity_id, p_reason);

    RETURN v_return;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_release_credit_reservation(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  UPDATE public.customer_credit_accounts SET
    reserved_credit = GREATEST(0, reserved_credit - v_order.total_amount),
    updated_at = now()
  WHERE customer_id = v_order.customer_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

