CREATE OR REPLACE FUNCTION public.governed_reopen_cancelled(p_token uuid, p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_authorized boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_authorized := public.is_upper_management(v_session.employee_id);
  IF NOT v_authorized THEN RETURN json_build_object('error', 'FORBIDDEN', 'detail', 'Upper management only'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.orders WHERE id = p_order_id AND status = 'cancelled') THEN
    RETURN json_build_object('error', 'INVALID_STATE', 'detail', 'Only cancelled orders can be reopened');
  END IF;
  UPDATE public.orders SET status = 'ready_for_dispatch', cancelled_at = NULL, cancel_reason = NULL, updated_at = now() WHERE id = p_order_id;
  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (p_order_id, 'cancelled', 'ready_for_dispatch', v_session.identity_id, COALESCE(p_reason, 'Order reopened for dispatch'));
  RETURN json_build_object('action', 'reopened', 'order_status', 'ready_for_dispatch');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reopen_order(p_token uuid, p_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_employee_id uuid; v_old_status varchar(30);
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  v_employee_id := v_session.employee_id;
  PERFORM check_capability(p_token, 'orders.approve');
  SELECT status INTO v_old_status FROM public.orders WHERE id = p_id;
  IF v_old_status IS NULL THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;
  IF v_old_status != 'cancelled' THEN RETURN jsonb_build_object('error', 'INVALID_STATE'); END IF;
  UPDATE public.orders SET status = 'submitted', updated_at = now() WHERE id = p_id;
  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason, changed_at) VALUES (p_id, v_old_status, 'submitted', v_employee_id, p_reason, now());
  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_replace_order_contents(p_token uuid, p_id uuid, p_items jsonb DEFAULT '[]'::jsonb, p_tier_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_daily_deals jsonb DEFAULT '[]'::jsonb, p_flash_offers jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_item jsonb;
  v_product record;
  v_calculated_unit_price numeric(12,2);
  v_calculated_total_price numeric(12,2);
  v_deal jsonb;
  v_deal_record record;
  v_offer jsonb;
  v_offer_record record;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  IF v_order.status NOT IN ('draft', 'returned_for_revision', 'stock_review') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE: only draft, returned_for_revision, or stock_review orders can be edited');
  END IF;

  IF v_session.identity_type = 'employee' THEN
    IF v_order.status = 'stock_review' THEN
      IF NOT public.check_capability(p_token, 'orders.create') AND NOT public.check_capability(p_token, 'orders.manage') THEN
        RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: orders.create or orders.manage');
      END IF;
    ELSE
      IF NOT public.check_capability(p_token, 'orders.create') THEN
        RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: orders.create');
      END IF;
    END IF;
  ELSE
    IF v_session.customer_id IS NULL OR v_order.customer_id IS DISTINCT FROM v_session.customer_id THEN
      RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
  END IF;

  IF p_tier_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.tiers WHERE id = p_tier_id AND is_active = true) THEN
      RETURN jsonb_build_object('error', 'TIER_NOT_FOUND_OR_INACTIVE');
    END IF;
  END IF;

  DELETE FROM public.order_items WHERE order_id = p_id;
  DELETE FROM public.order_daily_deals WHERE order_id = p_id;
  DELETE FROM public.order_flash_offers WHERE order_id = p_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT id, carton_price, carton_quantity INTO v_product
    FROM public.products WHERE id = (v_item->>'product_id')::uuid;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND: ' || (v_item->>'product_id')::uuid);
    END IF;
    v_calculated_unit_price := public._calc_base_unit_price(v_product.carton_price, v_product.carton_quantity, v_item->>'unit_type');
    IF v_calculated_unit_price IS NULL THEN
      RETURN jsonb_build_object('error', 'PRICE_NOT_CONFIGURED: product ' || (v_item->>'product_id')::uuid);
    END IF;
    v_calculated_total_price := ROUND((v_calculated_unit_price * (v_item->>'unit_quantity')::numeric)::numeric, 2);
    INSERT INTO public.order_items (order_id, product_id, unit_type, unit_quantity, piece_quantity, unit_price, total_price)
    VALUES (p_id, (v_item->>'product_id')::uuid, v_item->>'unit_type', (v_item->>'unit_quantity')::int,
      COALESCE((v_item->>'piece_quantity')::int, 0), v_calculated_unit_price, v_calculated_total_price);
  END LOOP;

  FOR v_deal IN SELECT * FROM jsonb_array_elements(p_daily_deals)
  LOOP
    SELECT id, fixed_price INTO v_deal_record FROM public.daily_deals WHERE id = (v_deal->>'deal_id')::uuid;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'DAILY_DEAL_NOT_FOUND: ' || (v_deal->>'deal_id')::uuid);
    END IF;
    INSERT INTO public.order_daily_deals (order_id, deal_id, quantity, unit_price, total_price)
    VALUES (p_id, v_deal_record.id, 1, v_deal_record.fixed_price, v_deal_record.fixed_price);
  END LOOP;

  FOR v_offer IN SELECT * FROM jsonb_array_elements(p_flash_offers)
  LOOP
    SELECT id, fixed_price INTO v_offer_record FROM public.flash_offers WHERE id = (v_offer->>'offer_id')::uuid;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'FLASH_OFFER_NOT_FOUND: ' || (v_offer->>'offer_id')::uuid);
    END IF;
    INSERT INTO public.order_flash_offers (order_id, offer_id, quantity, unit_price, total_price)
    VALUES (p_id, v_offer_record.id, 1, v_offer_record.fixed_price, v_offer_record.fixed_price);
  END LOOP;

  UPDATE public.orders SET tier_id = p_tier_id, notes = p_notes, updated_at = now() WHERE id = p_id;

  RETURN jsonb_build_object('success', true, 'item_count', (SELECT COUNT(*) FROM public.order_items WHERE order_id = p_id));
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_request_auction_participation(p_token uuid, p_auction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_auction public.auctions;
  v_participant_id uuid;
  v_participant_type varchar(20);
  v_participant_owner_id uuid;
  v_company_name varchar(255);
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_auction FROM public.auctions WHERE id = p_auction_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'AUCTION_NOT_FOUND'); END IF;
  IF v_auction.status = 'ended' OR v_auction.status = 'cancelled' THEN
    RETURN jsonb_build_object('error', 'AUCTION_CLOSED');
  END IF;

  IF v_session.customer_id IS NOT NULL THEN
    v_participant_type := 'customer';
    v_participant_owner_id := v_session.customer_id;
    SELECT company_name INTO v_company_name FROM public.customers WHERE id = v_session.customer_id;
  ELSIF v_session.employee_id IS NOT NULL THEN
    v_participant_type := 'employee';
    v_participant_owner_id := v_session.employee_id;
    SELECT full_name INTO v_company_name FROM public.employees WHERE id = v_session.employee_id;
  ELSE
    RETURN jsonb_build_object('error', 'UNKNOWN_IDENTITY');
  END IF;

  -- Check if already requested
  IF EXISTS (SELECT 1 FROM public.auction_participants
    WHERE auction_id = p_auction_id AND participant_type = v_participant_type AND participant_id = v_participant_owner_id)
  THEN
    RETURN jsonb_build_object('error', 'ALREADY_REGISTERED');
  END IF;

  INSERT INTO public.auction_participants (auction_id, participant_type, participant_id, status, deposit_paid)
  VALUES (p_auction_id, v_participant_type, v_participant_owner_id, 'pending', false)
  RETURNING id INTO v_participant_id;

  -- Add activity
  INSERT INTO public.auction_activity (auction_id, activity_type, actor_name, message)
  VALUES (p_auction_id, 'participation_requested', v_company_name, v_company_name || ' طلبت المشاركة في المزاد');

  RETURN jsonb_build_object('success', true, 'participant_id', v_participant_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reserve_credit_for_order(p_token uuid, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_account public.customer_credit_accounts;
  v_available decimal;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;
  IF v_order.status NOT IN ('draft', 'submitted', 'returned_for_revision') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATUS');
  END IF;

  SELECT * INTO v_account FROM public.customer_credit_accounts
  WHERE customer_id = v_order.customer_id AND credit_status = 'active';
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NO_ACTIVE_CREDIT'); END IF;

  v_available := v_account.credit_limit - v_account.outstanding_credit - v_account.reserved_credit;

  -- Soft-check: if over limit, still set payment_method and flag for UM review
  IF v_order.total_amount > v_available THEN
    UPDATE public.orders SET payment_method = 'credit' WHERE id = p_order_id;
    RETURN jsonb_build_object('success', true, 'over_limit', true, 'available', v_available, 'required', v_order.total_amount);
  END IF;

  UPDATE public.customer_credit_accounts SET
    reserved_credit = reserved_credit + v_order.total_amount,
    updated_at = now()
  WHERE id = v_account.id;

  UPDATE public.orders SET payment_method = 'credit' WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true, 'reserved', v_order.total_amount);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_reset_employee_password(p_token uuid, p_id uuid, p_new_password character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_identity_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'employees.manage');

  SELECT identity_id INTO v_identity_id FROM public.employees WHERE id = p_id;
  IF v_identity_id IS NULL THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  UPDATE public.identities
  SET password_hash = extensions.crypt(COALESCE(p_new_password, '123456'), extensions.gen_salt('bf'))
  WHERE id = v_identity_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_return_deferred(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_order public.orders;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'NOT_FOUND'); END IF;
  IF v_order.status != 'deferred' THEN RETURN json_build_object('error', 'INVALID_STATE', 'detail', 'Order must be deferred'); END IF;
  IF v_order.deferred_until IS NULL OR v_order.deferred_until > now() THEN
    RETURN json_build_object('error', 'TOO_EARLY', 'detail', 'Follow-up date has not been reached yet');
  END IF;
  UPDATE public.orders SET status = 'ready_for_dispatch', deferred_until = NULL, updated_at = now() WHERE id = p_order_id;
  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (p_order_id, 'deferred', 'ready_for_dispatch', v_order.created_by, 'Automatic return: follow-up date reached');
  RETURN json_build_object('action', 'returned_from_deferred', 'order_status', 'ready_for_dispatch');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_return_delivery(p_token text, p_delivery_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'delivery.deliver') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_dt FROM public.delivery_tracking WHERE id = p_delivery_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_dt.status NOT IN ('out_for_delivery','assigned') THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.delivery_tracking SET status = 'returned', failure_reason = 'returned_to_warehouse', failure_notes = p_notes, returned_at = now(), updated_at = now() WHERE id = p_delivery_id RETURNING * INTO v_dt;
  UPDATE public.orders SET status = 'approved', updated_at = now() WHERE id = v_dt.order_id;
  RETURN jsonb_build_object('delivery_status', 'returned', 'order_status', 'approved');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_return_order_for_revision(p_token uuid, p_id uuid, p_reason text DEFAULT NULL::text, p_items jsonb DEFAULT NULL::jsonb, p_daily_deals jsonb DEFAULT NULL::jsonb, p_flash_offers jsonb DEFAULT NULL::jsonb, p_tier_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_execution_location_id uuid DEFAULT NULL::uuid, p_execution_latitude numeric DEFAULT NULL::numeric, p_execution_longitude numeric DEFAULT NULL::numeric, p_execution_accuracy_meters numeric DEFAULT NULL::numeric, p_execution_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_old_status text;
  v_new_revision_number int;
  v_old_items_data jsonb;
  v_old_daily_deals_data jsonb;
  v_old_flash_offers_data jsonb;
  v_item jsonb;
  v_product record;
  v_calculated_unit_price numeric(12,2);
  v_calculated_total_price numeric(12,2);
  v_deal jsonb;
  v_deal_record record;
  v_offer jsonb;
  v_offer_record record;
  v_exec_location_id uuid;
  v_cust_code text;
  v_cust_name text;
  v_cust_phone text;
  v_cust_address text;
  v_owner_name text;
  v_owner_phone text;
  v_owner_address text;
  v_sender_name text;
  v_sender_phone text;
  v_sender_address text;
  v_restore_result jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF v_session.identity_type = 'employee' THEN
    IF NOT public.check_capability(p_token, 'orders.manage') AND NOT public.check_capability(p_token, 'orders.approve') THEN
      RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: orders.manage or orders.approve');
    END IF;
  ELSE
    RETURN jsonb_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  IF v_order.status NOT IN ('submitted', 'approved', 'delivered', 'partially_delivered', 'stock_review') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE: only submitted, approved, delivered, or stock_review orders can be returned for revision');
  END IF;

  v_old_status := v_order.status;

  -- Restore inventory if previously deducted
  v_restore_result := public.governed_inventory_restore(p_id);

  -- Snapshot old data
  SELECT jsonb_agg(row_to_json(sub)) INTO v_old_items_data
  FROM (SELECT product_id, unit_type, unit_quantity, piece_quantity, unit_price, total_price
        FROM public.order_items WHERE order_id = p_id) sub;

  SELECT jsonb_agg(row_to_json(sub)) INTO v_old_daily_deals_data
  FROM (SELECT deal_id, quantity, fixed_price AS unit_price, total_price
        FROM public.order_daily_deals WHERE order_id = p_id) sub;

  SELECT jsonb_agg(row_to_json(sub)) INTO v_old_flash_offers_data
  FROM (SELECT offer_id, quantity, fixed_price AS unit_price, total_price
        FROM public.order_flash_offers WHERE order_id = p_id) sub;

  -- Retire current prices
  UPDATE public.daily_deals dd SET status = 'active'
  FROM public.order_daily_deals odd WHERE odd.order_id = p_id AND odd.deal_id = dd.id;
  DELETE FROM public.order_daily_deals WHERE order_id = p_id;

  UPDATE public.flash_offers fo SET status = 'active'
  FROM public.order_flash_offers ofo WHERE ofo.order_id = p_id AND ofo.offer_id = fo.id;
  DELETE FROM public.order_flash_offers WHERE order_id = p_id;

  -- Location
  v_exec_location_id := p_execution_location_id;
  IF v_exec_location_id IS NULL AND p_execution_latitude IS NOT NULL AND p_execution_longitude IS NOT NULL THEN
    v_exec_location_id := gen_random_uuid();
    INSERT INTO unified_locations (id, latitude, longitude, accuracy_meters, captured_at)
    VALUES (v_exec_location_id, p_execution_latitude, p_execution_longitude, p_execution_accuracy_meters, COALESCE(p_execution_captured_at, now()));
  END IF;

  -- Snapshots
  SELECT c.code, c.company_name,
    COALESCE((SELECT phone FROM customer_contacts WHERE customer_id = c.id AND is_primary = true LIMIT 1), ''),
    COALESCE((SELECT formatted_address FROM unified_locations ul WHERE ul.id = c.location_id),
             (SELECT address_line1 FROM customer_addresses ca WHERE ca.customer_id = c.id AND ca.is_default = true LIMIT 1), '')
  INTO v_cust_code, v_cust_name, v_cust_phone, v_cust_address
  FROM customers c WHERE c.id = v_order.customer_id;

  SELECT COALESCE(e.full_name, ''), COALESCE(i.phone, ''), COALESCE(e.address, '')
  INTO v_owner_name, v_owner_phone, v_owner_address
  FROM customers c LEFT JOIN employees e ON e.id = c.owner_id LEFT JOIN identities i ON i.id = e.identity_id
  WHERE c.id = v_order.customer_id;

  SELECT COALESCE(e.full_name, ''), COALESCE(i.phone, ''), COALESCE(e.address, '')
  INTO v_sender_name, v_sender_phone, v_sender_address
  FROM employees e LEFT JOIN identities i ON i.id = e.identity_id
  WHERE e.identity_id = v_session.identity_id;

  SELECT COALESCE(MAX(revision_number), 0) + 1 INTO v_new_revision_number
  FROM public.order_modification_history WHERE order_id = p_id;

  INSERT INTO public.order_modification_history (
    order_id, revision_number, field_name, old_value, new_value,
    old_order_items, new_order_items,
    old_daily_deals, new_daily_deals,
    old_flash_offers, new_flash_offers,
    modified_by, reason, modified_at
  ) VALUES (
    p_id, v_new_revision_number, 'REVISION_SNAPSHOT',
    row_to_json(v_order)::text, NULL,
    v_old_items_data,
    (SELECT jsonb_agg(row_to_json(sub_oi))
     FROM (SELECT oi.product_id, pr.product_name, oi.unit_type, oi.unit_quantity,
                  oi.piece_quantity, oi.unit_price, oi.total_price
           FROM public.order_items oi LEFT JOIN public.products pr ON pr.id = oi.product_id
           WHERE oi.order_id = p_id) sub_oi),
    v_old_daily_deals_data,
    (SELECT jsonb_agg(row_to_json(sub_odd))
     FROM (SELECT odd.deal_id, odd.quantity, odd.fixed_price AS unit_price, odd.total_price
           FROM public.order_daily_deals odd WHERE odd.order_id = p_id) sub_odd),
    v_old_flash_offers_data,
    (SELECT jsonb_agg(row_to_json(sub_fo))
     FROM (SELECT ofo.offer_id, ofo.quantity, ofo.fixed_price AS unit_price, ofo.total_price
           FROM public.order_flash_offers ofo WHERE ofo.order_id = p_id) sub_fo),
    v_session.identity_id, p_reason, now()
  );

  -- Replace items if provided
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    DELETE FROM public.order_items WHERE order_id = p_id;
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
      SELECT id, carton_price, carton_quantity INTO v_product
      FROM public.products WHERE id = (v_item->>'product_id')::uuid;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND: ' || (v_item->>'product_id')::uuid);
      END IF;
      v_calculated_unit_price := public._calc_base_unit_price(v_product.carton_price, v_product.carton_quantity, v_item->>'unit_type');
      IF v_calculated_unit_price IS NULL THEN
        RETURN jsonb_build_object('error', 'PRICE_NOT_CONFIGURED: product ' || (v_item->>'product_id')::uuid);
      END IF;
      v_calculated_total_price := ROUND((v_calculated_unit_price * (v_item->>'unit_quantity')::numeric)::numeric, 2);
      INSERT INTO public.order_items (order_id, product_id, unit_type, unit_quantity, piece_quantity, unit_price, total_price)
      VALUES (p_id, (v_item->>'product_id')::uuid, v_item->>'unit_type', (v_item->>'unit_quantity')::int,
        COALESCE((v_item->>'piece_quantity')::int, 0), v_calculated_unit_price, v_calculated_total_price);
    END LOOP;
  END IF;

  IF p_daily_deals IS NOT NULL AND jsonb_array_length(p_daily_deals) > 0 THEN
    FOR v_deal IN SELECT * FROM jsonb_array_elements(p_daily_deals) LOOP
      SELECT id, fixed_price INTO v_deal_record FROM public.daily_deals WHERE id = (v_deal->>'deal_id')::uuid;
      IF NOT FOUND THEN RETURN jsonb_build_object('error', 'DAILY_DEAL_NOT_FOUND'); END IF;
      INSERT INTO public.order_daily_deals (order_id, deal_id, quantity, unit_price, total_price)
      VALUES (p_id, v_deal_record.id, 1, v_deal_record.fixed_price, v_deal_record.fixed_price);
    END LOOP;
  END IF;

  IF p_flash_offers IS NOT NULL AND jsonb_array_length(p_flash_offers) > 0 THEN
    FOR v_offer IN SELECT * FROM jsonb_array_elements(p_flash_offers) LOOP
      SELECT id, fixed_price INTO v_offer_record FROM public.flash_offers WHERE id = (v_offer->>'offer_id')::uuid;
      IF NOT FOUND THEN RETURN jsonb_build_object('error', 'FLASH_OFFER_NOT_FOUND'); END IF;
      INSERT INTO public.order_flash_offers (order_id, offer_id, quantity, unit_price, total_price)
      VALUES (p_id, v_offer_record.id, 1, v_offer_record.fixed_price, v_offer_record.fixed_price);
    END LOOP;
  END IF;

  UPDATE public.orders SET
    status = 'draft', revision_number = v_new_revision_number, last_revised_at = now(),
    tier_id = COALESCE(p_tier_id, tier_id), notes = COALESCE(p_notes, notes),
    execution_location_id = COALESCE(v_exec_location_id, execution_location_id),
    execution_latitude = COALESCE(p_execution_latitude, execution_latitude),
    execution_longitude = COALESCE(p_execution_longitude, execution_longitude),
    execution_accuracy_meters = COALESCE(p_execution_accuracy_meters, execution_accuracy_meters),
    execution_captured_at = COALESCE(p_execution_captured_at, execution_captured_at),
    snapshot_customer_code = v_cust_code, snapshot_customer_name = v_cust_name,
    snapshot_customer_phone = v_cust_phone, snapshot_customer_address = v_cust_address,
    snapshot_owner_name = v_owner_name, snapshot_owner_phone = v_owner_phone,
    snapshot_owner_address = v_owner_address, snapshot_sender_name = v_sender_name,
    snapshot_sender_phone = v_sender_phone, snapshot_sender_address = v_sender_address,
    updated_at = now()
  WHERE id = p_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
  VALUES (p_id, v_old_status, 'draft', v_session.identity_id, p_reason);

  RETURN jsonb_build_object('success', true, 'revision_number', v_new_revision_number);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_return_to_preparation(p_token uuid, p_preparation_id uuid, p_notes text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app', 'extensions', 'pg_catalog'
AS $function$

DECLARE v_session app.sessions; v_prep_status text; v_authorized boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_session.employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_authorized := public.is_upper_management(v_session.employee_id);
  IF NOT v_authorized THEN RETURN json_build_object('error', 'FORBIDDEN'); END IF;
  SELECT status::text INTO v_prep_status FROM public.preparation_records WHERE id = p_preparation_id;
  IF v_prep_status IS NULL THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_prep_status != 'completed' THEN RETURN json_build_object('error', 'INVALID_STATUS', 'current_status', v_prep_status); END IF;
  IF p_notes IS NULL OR trim(p_notes) = '' THEN
    RETURN json_build_object('error', 'REASON_REQUIRED', 'detail', 'A reason for returning to preparation is required');
  END IF;
  UPDATE public.preparation_records
  SET status = 'in_progress'::preparation_status,
      completed_by = NULL, completed_at = NULL,
      notes = COALESCE(notes, '') || E'\nReturned to preparation: ' || p_notes,
      updated_at = now()
  WHERE id = p_preparation_id;
  RETURN json_build_object('id', p_preparation_id, 'status', 'in_progress', 'returned_by', v_session.employee_id, 'returned_at', now(), 'reason', p_notes);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_review_credit(p_token uuid, p_id uuid)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.review') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status != 'submitted' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.credit_applications SET status = 'under_review', reviewed_by = v_session.employee_id, reviewed_at = now(), updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_review_preparation(p_token uuid, p_preparation_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_employee_id uuid; v_rec public.preparation_records; v_authorized boolean; v_order_id uuid;
BEGIN
  SELECT employee_id INTO v_employee_id FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF v_employee_id IS NULL THEN RETURN json_build_object('error', 'INVALID_SESSION'); END IF;
  v_authorized := public.is_upper_management(v_employee_id)
    OR EXISTS (SELECT 1 FROM public.employee_roles er JOIN public.roles r ON r.id = er.role_id
      WHERE er.employee_id = v_employee_id AND r.name = 'WAREHOUSE_MANAGER');
  IF NOT v_authorized THEN RETURN json_build_object('error', 'FORBIDDEN'); END IF;
  SELECT * INTO v_rec FROM public.preparation_records WHERE id = p_preparation_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'PREPARATION_NOT_FOUND'); END IF;
  IF v_rec.status != 'completed' THEN RETURN json_build_object('error', 'INVALID_STATUS'); END IF;
  SELECT order_id INTO v_order_id FROM public.preparation_records WHERE id = p_preparation_id;
  UPDATE public.preparation_records
    SET status = 'reviewed', reviewed_by = v_employee_id, reviewed_at = now(),
        notes = COALESCE(p_notes, notes), updated_at = now()
    WHERE id = p_preparation_id;
  UPDATE public.orders SET status = 'ready_for_dispatch', updated_at = now() WHERE id = v_order_id;
  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason)
    VALUES (v_order_id, 'prepared', 'ready_for_dispatch', v_employee_id, COALESCE(p_notes, 'Preparation reviewed'));
  RETURN json_build_object('id', p_preparation_id, 'status', 'reviewed', 'reviewed_by', v_employee_id,
    'reviewed_at', now(), 'order_status', 'ready_for_dispatch');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_location_override(p_token uuid, p_location_id uuid, p_latitude numeric, p_longitude numeric, p_source text, p_source_address text DEFAULT NULL::text, p_confidence_score numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_verified boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF p_source NOT IN ('geocoding', 'manual') THEN
    RETURN jsonb_build_object('error', 'INVALID_SOURCE');
  END IF;

  -- تحديد حالة الموقع حسب المصدر والثقة
  v_verified := CASE
    WHEN p_source = 'manual' THEN true
    WHEN p_source = 'geocoding' AND p_confidence_score >= 0.70 THEN true
    ELSE false
  END;

  -- تحديث unified_locations بالإحداثيات والحالة
  UPDATE public.unified_locations
  SET
    latitude = p_latitude,
    longitude = p_longitude,
    location_verified = v_verified,
    captured_at = now()
  WHERE id = p_location_id;

  -- إدراج أو تحديث location_overrides
  INSERT INTO public.location_overrides (location_id, latitude, longitude, source, source_address, confidence_score, geocoded_at)
  VALUES (p_location_id, p_latitude, p_longitude, p_source, p_source_address, p_confidence_score, now())
  ON CONFLICT (location_id)
  DO UPDATE SET
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    source = EXCLUDED.source,
    source_address = COALESCE(EXCLUDED.source_address, location_overrides.source_address),
    confidence_score = EXCLUDED.confidence_score,
    geocoded_at = now(),
    updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'location_id', p_location_id,
    'latitude', p_latitude,
    'longitude', p_longitude,
    'source', p_source,
    'confidence_score', p_confidence_score,
    'location_verified', v_verified
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_product_deduction_status(p_token uuid, p_product_id uuid, p_deduction_status character varying, p_scope character varying DEFAULT 'new_orders'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_product record;
  v_old_value varchar(30);
  v_valid_statuses text[] := ARRAY[
    'submitted', 'reviewing', 'approved', 'preparing', 'prepared',
    'ready_for_dispatch', 'sent_to_delivery', 'dispatched', 'delivered'
  ];
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'products.manage') THEN
    RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: products.manage');
  END IF;

  IF p_scope NOT IN ('new_orders', 'previous_and_new') THEN
    RETURN jsonb_build_object('error', 'INVALID_SCOPE');
  END IF;

  IF NOT (p_deduction_status = ANY(v_valid_statuses)) THEN
    RETURN jsonb_build_object('error', 'INVALID_DEDUCTION_STATUS');
  END IF;

  SELECT id, inventory_deduction_status INTO v_product
  FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND'); END IF;

  v_old_value := v_product.inventory_deduction_status;

  -- Update product setting
  UPDATE public.products
  SET inventory_deduction_status = p_deduction_status, updated_at = now()
  WHERE id = p_product_id;

  -- If scope is previous_and_new, update snapshot on existing non-delivered orders
  IF p_scope = 'previous_and_new' AND v_old_value != p_deduction_status THEN
    UPDATE public.orders
    SET order_inventory_deduction_status = p_deduction_status, updated_at = now()
    WHERE id IN (
      SELECT o.id FROM public.orders o
      WHERE o.customer_id IS NOT NULL
        AND o.status NOT IN ('delivered', 'cancelled', 'stock_review')
    )
    AND EXISTS (
      SELECT 1 FROM public.order_items oi
      WHERE oi.order_id = orders.id AND oi.product_id = p_product_id
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'inventory_deduction_status', p_deduction_status,
    'scope', p_scope
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_product_negative_selling(p_token uuid, p_product_id uuid, p_negative_selling boolean, p_scope character varying DEFAULT 'new_orders'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_product record;
  v_old_value boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'products.manage') THEN
    RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: products.manage');
  END IF;

  IF p_scope NOT IN ('new_orders', 'previous_and_new') THEN
    RETURN jsonb_build_object('error', 'INVALID_SCOPE');
  END IF;

  SELECT id, negative_selling_allowed INTO v_product
  FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND'); END IF;

  v_old_value := v_product.negative_selling_allowed;

  -- Update product setting
  UPDATE public.products
  SET negative_selling_allowed = p_negative_selling, updated_at = now()
  WHERE id = p_product_id;

  -- If scope is previous_and_new, update snapshot on existing non-delivered orders
  IF p_scope = 'previous_and_new' AND v_old_value != p_negative_selling THEN
    UPDATE public.orders
    SET order_negative_selling_allowed = p_negative_selling, updated_at = now()
    WHERE id IN (
      SELECT o.id FROM public.orders o
      WHERE o.customer_id IS NOT NULL
        AND o.status NOT IN ('delivered', 'cancelled', 'stock_review')
    )
    AND EXISTS (
      SELECT 1 FROM public.order_items oi
      WHERE oi.order_id = orders.id AND oi.product_id = p_product_id
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'negative_selling_allowed', p_negative_selling,
    'scope', p_scope
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_product_out_of_stock(p_token uuid, p_id uuid, p_is_out_of_stock boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  UPDATE public.products
  SET is_out_of_stock = p_is_out_of_stock,
      recently_available_at = CASE WHEN p_is_out_of_stock = false THEN now() ELSE recently_available_at END,
      updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_product_stock(p_token uuid, p_product_id uuid, p_quantity integer, p_unit character varying DEFAULT 'piece'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_product record;
  v_pieces integer;
  v_carton_qty integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  IF NOT public.check_capability(p_token, 'products.manage') THEN
    RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: products.manage');
  END IF;

  SELECT id, carton_quantity INTO v_product
  FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND'); END IF;

  -- Convert input to pieces
  IF p_unit = 'carton' THEN
    IF v_product.carton_quantity IS NULL OR v_product.carton_quantity <= 0 THEN
      RETURN jsonb_build_object('error', 'CARTON_QUANTITY_NOT_CONFIGURED');
    END IF;
    v_pieces := p_quantity * v_product.carton_quantity;
  ELSIF p_unit = 'piece' THEN
    v_pieces := p_quantity;
  ELSE
    RETURN jsonb_build_object('error', 'INVALID_UNIT: use piece or carton');
  END IF;

  -- SET/REPLACE semantics (not additive)
  INSERT INTO public.inventory (product_id, quantity, updated_at)
  VALUES (p_product_id, v_pieces, now())
  ON CONFLICT (product_id) DO UPDATE
  SET quantity = v_pieces, updated_at = now();

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'quantity_pieces', v_pieces,
    'unit', p_unit
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_set_tier_company_exception(p_token uuid, p_tier_id uuid, p_company_id uuid, p_discount_percent numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
