CREATE OR REPLACE FUNCTION public.governed_sign_contract(p_token uuid, p_application_id uuid)
 RETURNS credit_contracts
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_contract public.credit_contracts; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_application_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_session.identity_type = 'customer' AND v_app.customer_id IS DISTINCT FROM v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  UPDATE public.credit_contracts SET signed_at = now(), signed_by = v_session.identity_id WHERE application_id = p_application_id AND signed_at IS NULL RETURNING * INTO v_contract;
  IF NOT FOUND THEN RAISE EXCEPTION 'ALREADY_SIGNED_OR_NOT_FOUND'; END IF;
  RETURN v_contract;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_start_delivery(p_token text, p_delivery_id uuid)
 RETURNS delivery_tracking
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_dt public.delivery_tracking;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'delivery.deliver') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_dt FROM public.delivery_tracking WHERE id = p_delivery_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_dt.status != 'assigned' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.delivery_tracking SET status = 'out_for_delivery', started_at = now(), updated_at = now() WHERE id = p_delivery_id RETURNING * INTO v_dt;
  RETURN v_dt;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_start_preparation(p_token uuid, p_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_order public.orders; v_prep public.preparation_records;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  PERFORM check_capability(p_token, 'orders.prepare');
  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;
  IF v_order.status NOT IN ('approved', 'ready_for_dispatch') THEN RETURN jsonb_build_object('error', 'INVALID_STATE'); END IF;
  IF EXISTS (SELECT 1 FROM public.preparation_records WHERE order_id = p_id AND status = 'in_progress') THEN RETURN jsonb_build_object('error', 'ALREADY_IN_PREPARATION'); END IF;
  INSERT INTO public.preparation_records (order_id, started_by, status, notes) VALUES (p_id, v_session.employee_id, 'in_progress', p_notes) RETURNING * INTO v_prep;
  UPDATE public.orders SET status = 'preparing', updated_at = now() WHERE id = p_id;
  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, reason) VALUES (p_id, v_order.status, 'preparing', v_session.identity_id, 'Preparation started');
  RETURN jsonb_build_object('success', true, 'preparation_id', v_prep.id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_submit_credit_application(p_token uuid, p_id uuid)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.submit') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status != 'draft' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  IF v_session.identity_type = 'customer' AND v_app.customer_id IS DISTINCT FROM v_session.customer_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  UPDATE public.credit_applications SET status = 'submitted', submitted_at = now(), updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_submit_order(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_old_status text;
  v_is_revision boolean;
  v_creator_identity_type text;
  v_product_subtotal numeric := 0;
  v_deal_total numeric := 0;
  v_flash_offer_total numeric := 0;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  v_old_status := v_order.status;

  IF v_old_status NOT IN ('draft', 'returned_for_revision', 'stock_review') THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE: only draft, returned_for_revision, or stock_review orders can be submitted');
  END IF;

  v_is_revision := EXISTS(
    SELECT 1 FROM public.order_modification_history
    WHERE order_id = p_id AND field_name = 'REVISION_SNAPSHOT'
  );

  IF v_session.identity_type = 'employee' THEN
    IF NOT v_is_revision THEN
      IF NOT public.check_capability(p_token, 'orders.create') THEN
        RETURN jsonb_build_object('error', 'MISSING_CAPABILITY: orders.create');
      END IF;
      IF v_order.created_by IS DISTINCT FROM v_session.identity_id THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN: only the order creator can submit');
      END IF;
    ELSE
      SELECT identity_type INTO v_creator_identity_type
      FROM public.identities WHERE id = v_order.created_by;
    END IF;
  END IF;

  SELECT COALESCE(SUM(total_price), 0) INTO v_product_subtotal
  FROM public.order_items WHERE order_id = p_id;

  SELECT COALESCE(SUM(total_price), 0) INTO v_deal_total
  FROM public.order_daily_deals WHERE order_id = p_id;

  SELECT COALESCE(SUM(total_price), 0) INTO v_flash_offer_total
  FROM public.order_flash_offers WHERE order_id = p_id;

  UPDATE public.orders SET
    status = 'submitted',
    submitted_at = now(),
    subtotal = v_product_subtotal + v_deal_total + v_flash_offer_total,
    total_amount = v_product_subtotal + v_deal_total + v_flash_offer_total - COALESCE(discount_amount, 0),
    updated_at = now()
  WHERE id = p_id;

  INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by, changed_at)
  VALUES (p_id, v_old_status, 'submitted', v_session.identity_id, now());

  RETURN jsonb_build_object('success', true, 'status', 'submitted');
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_supreme_delete_cancelled_order(p_token text, p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_is_super boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_is_super := public.is_supreme_management(v_session.employee_id);
  IF NOT v_is_super THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Only Supreme Management can delete cancelled orders');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  IF v_order.status != 'cancelled' THEN
    RETURN jsonb_build_object('error', 'INVALID_STATE', 'detail', 'Only cancelled orders can be deleted');
  END IF;

  INSERT INTO public.order_modification_history (
    order_id, revision_number, field_name, old_value, new_value,
    old_order_items, modified_by, reason, modified_at
  )
  VALUES (
    p_order_id,
    v_order.revision_number,
    'supreme_delete',
    jsonb_build_object(
      'status', v_order.status,
      'total_amount', v_order.total_amount,
      'order_number', v_order.order_number
    )::text,
    jsonb_build_object('deleted', true)::text,
    (SELECT jsonb_agg(row_to_json(oi.*)) FROM public.order_items oi WHERE oi.order_id = p_order_id),
    v_session.identity_id,
    COALESCE(p_reason, 'Deleted by Supreme Management'),
    now()
  );

  INSERT INTO public.inventory (product_id, quantity)
  SELECT oi.product_id, SUM(oi.piece_quantity)
  FROM public.order_items oi WHERE oi.order_id = p_order_id
  GROUP BY oi.product_id
  ON CONFLICT (product_id) DO UPDATE
  SET quantity = public.inventory.quantity + EXCLUDED.quantity,
      updated_at = now();

  IF v_order.payment_method = 'credit' THEN
    UPDATE public.customer_credit_accounts
    SET reserved_credit = GREATEST(reserved_credit - v_order.total_amount, 0),
        updated_at = now()
    WHERE customer_id = v_order.customer_id;
  END IF;

  DELETE FROM public.treasury_transactions
  WHERE reference_type = 'collection'
    AND reference_id IN (SELECT id FROM public.collections WHERE order_id = p_order_id);

  DELETE FROM public.collections WHERE order_id = p_order_id;

  DELETE FROM public.preparation_exceptions
  WHERE preparation_id IN (SELECT id FROM public.preparation_records WHERE order_id = p_order_id);

  DELETE FROM public.preparation_records WHERE order_id = p_order_id;

  DELETE FROM public.delivery_tracking WHERE order_id = p_order_id;

  DELETE FROM public.return_items
  WHERE return_id IN (SELECT id FROM public.returns WHERE order_id = p_order_id);

  DELETE FROM public.returns WHERE order_id = p_order_id;

  DELETE FROM public.credit_invoice_cheques
  WHERE invoice_id IN (SELECT id FROM public.credit_invoices WHERE order_id = p_order_id);

  DELETE FROM public.credit_invoices WHERE order_id = p_order_id;

  DELETE FROM public.auction_awards WHERE order_id = p_order_id;

  DELETE FROM public.order_daily_deals WHERE order_id = p_order_id;
  DELETE FROM public.order_flash_offers WHERE order_id = p_order_id;

  DELETE FROM public.order_items WHERE order_id = p_order_id;
  DELETE FROM public.order_status_history WHERE order_id = p_order_id;
  DELETE FROM public.order_modification_history WHERE order_id = p_order_id;

  DELETE FROM public.orders WHERE id = p_order_id;

  INSERT INTO public.deletion_audit_log (employee_id, entity_type, entity_ids, record_count)
  VALUES (v_session.employee_id, 'order', ARRAY[p_order_id], 1);

  RETURN jsonb_build_object('success', true, 'action', 'deleted', 'order_id', p_order_id);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_supreme_edit_order(p_token text, p_order_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text, p_discount_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text, p_order_type character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_old_items jsonb;
  v_new_items jsonb;
  v_item jsonb;
  v_product record;
  v_subtotal decimal(12,2);
  v_discount_amount decimal(12,2);
  v_total decimal(12,2);
  v_is_super boolean;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token::uuid AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  v_is_super := public.is_supreme_management(v_session.employee_id);
  IF NOT v_is_super THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'Only Supreme Management can edit orders');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'product_id', oi.product_id, 'unit_type', oi.unit_type,
      'unit_quantity', oi.unit_quantity, 'piece_quantity', oi.piece_quantity,
      'unit_price', oi.unit_price, 'total_price', oi.total_price
    )
  ) INTO v_old_items
  FROM public.order_items oi WHERE oi.order_id = p_order_id;

  DELETE FROM public.order_items WHERE order_id = p_order_id;

  v_subtotal := 0;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT id, carton_price, carton_quantity INTO v_product
    FROM public.products WHERE id = (v_item->>'product_id')::uuid;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'PRODUCT_NOT_FOUND', 'detail', 'Product ' || (v_item->>'product_id'));
    END IF;

    INSERT INTO public.order_items (order_id, product_id, unit_type, unit_quantity, piece_quantity, unit_price, total_price)
    VALUES (
      p_order_id, (v_item->>'product_id')::uuid, v_item->>'unit_type',
      (v_item->>'unit_quantity')::int, COALESCE((v_item->>'piece_quantity')::int, 0),
      COALESCE((v_item->>'unit_price')::numeric, 0), COALESCE((v_item->>'total_price')::numeric, 0)
    );

    v_subtotal := v_subtotal + COALESCE((v_item->>'total_price')::numeric, 0);
  END LOOP;

  SELECT jsonb_agg(
    jsonb_build_object(
      'product_id', oi.product_id, 'unit_type', oi.unit_type,
      'unit_quantity', oi.unit_quantity, 'piece_quantity', oi.piece_quantity,
      'unit_price', oi.unit_price, 'total_price', oi.total_price
    )
  ) INTO v_new_items
  FROM public.order_items oi WHERE oi.order_id = p_order_id;

  v_subtotal := COALESCE(v_subtotal, 0);
  v_discount_amount := COALESCE(p_discount_amount, 0);
  v_total := GREATEST(v_subtotal - v_discount_amount, 0);

  UPDATE public.orders SET
    subtotal = v_subtotal, discount_amount = v_discount_amount, tax_amount = 0,
    total_amount = v_total, notes = COALESCE(p_notes, notes),
    order_type = COALESCE(p_order_type, order_type),
    updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_modification_history (
    order_id, revision_number, field_name, old_value, new_value,
    old_order_items, new_order_items, modified_by, reason, modified_at
  ) VALUES (
    p_order_id, v_order.revision_number, 'supreme_edit',
    jsonb_build_object('subtotal', v_order.subtotal, 'discount_amount', v_order.discount_amount, 'total_amount', v_order.total_amount, 'notes', v_order.notes)::text,
    jsonb_build_object('subtotal', v_subtotal, 'discount_amount', v_discount_amount, 'total_amount', v_total, 'notes', COALESCE(p_notes, v_order.notes))::text,
    v_old_items, v_new_items, v_session.identity_id, COALESCE(p_reason, 'Supreme Management edit'), now()
  );

  RETURN jsonb_build_object(
    'success', true, 'order_id', p_order_id,
    'item_count', (SELECT COUNT(*) FROM public.order_items WHERE order_id = p_order_id),
    'subtotal', v_subtotal, 'discount_amount', v_discount_amount, 'total_amount', v_total
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_suspend_credit(p_token uuid, p_id uuid, p_reason text)
 RETURNS credit_applications
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_app public.credit_applications;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.suspend') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  SELECT * INTO v_app FROM public.credit_applications WHERE id = p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_app.status != 'approved' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  UPDATE public.credit_applications SET status = 'suspended', suspended_by = v_session.employee_id, suspended_at = now(), suspension_reason = p_reason, updated_at = now() WHERE id = p_id RETURNING * INTO v_app;
  RETURN v_app;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_suspend_credit_account(p_token uuid, p_customer_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  PERFORM check_capability(p_token, 'credit.account.suspend');

  UPDATE public.customer_credit_accounts SET
    credit_status = 'suspended', updated_at = now()
  WHERE customer_id = p_customer_id AND credit_status = 'active';

  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND_OR_ALREADY_SUSPENDED'); END IF;

    -- Log to ledger
    INSERT INTO public.customer_credit_ledger (customer_id, transaction_type, amount, running_balance, notes, created_by)
    SELECT p_customer_id, 'debit', 0, outstanding_credit, COALESCE(p_reason, 'إيقاف الحساب الائتماني'), v_session.employee_id
  FROM public.customer_credit_accounts WHERE customer_id = p_customer_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_toggle_credit_program(p_token uuid, p_id uuid, p_is_active boolean)
 RETURNS credit_programs
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$

DECLARE v_session app.sessions; v_prog public.credit_programs;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SESSION'; END IF;
  IF NOT public.check_capability(p_token, 'credit.manage_programs') THEN RAISE EXCEPTION 'MISSING_CAPABILITY'; END IF;
  UPDATE public.credit_programs SET is_active = p_is_active, updated_at = now() WHERE id = p_id RETURNING * INTO v_prog;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  RETURN v_prog;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_transfer_order_owner(p_token text, p_order_id uuid, p_new_owner_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_token uuid := p_token::uuid;
  v_session app.sessions;
  v_order RECORD;
  v_old_owner_id uuid;
  v_old_owner_name text;
  v_new_owner_name text;
  v_is_super boolean;
  v_new_owner_exists boolean;
  v_visible uuid[];
BEGIN
  -- 1. Validate session
  SELECT * INTO v_session FROM app.sessions WHERE token = v_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
  IF v_session.identity_type != 'employee' THEN RETURN jsonb_build_object('error', 'NOT_EMPLOYEE'); END IF;

  -- 2. Load order
  SELECT o.id, o.owner_id, o.revision_number, o.order_number, o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND'); END IF;

  v_old_owner_id := v_order.owner_id;

  -- 3. Permission check
  v_is_super := public.is_upper_management(v_session.employee_id);
  IF NOT v_is_super THEN
    IF NOT (
      v_old_owner_id = v_session.employee_id
      OR EXISTS (
        SELECT 1 FROM public.employees
        WHERE id = v_old_owner_id AND manager_id = v_session.employee_id
      )
    ) THEN
      RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
  END IF;

  -- 4. Validate new owner is in caller's governed tree
  IF v_is_super THEN
    SELECT EXISTS(SELECT 1 FROM public.employees WHERE id = p_new_owner_id AND is_active = true)
    INTO v_new_owner_exists;
  ELSE
    v_visible := COALESCE(public.get_visible_employee_ids(p_token), '{}'::uuid[]);
    v_new_owner_exists := (p_new_owner_id = ANY(v_visible));
  END IF;
  IF NOT v_new_owner_exists THEN
    RETURN jsonb_build_object('error', 'NEW_OWNER_NOT_IN_SCOPE');
  END IF;

  -- 5. Prevent same owner
  IF v_old_owner_id = p_new_owner_id THEN
    RETURN jsonb_build_object('error', 'SAME_OWNER');
  END IF;

  -- 6. Get names for audit
  v_old_owner_name := COALESCE(
    (SELECT full_name FROM public.employees WHERE id = v_old_owner_id),
    'غير محدد'
  );
  v_new_owner_name := COALESCE(
    (SELECT full_name FROM public.employees WHERE id = p_new_owner_id),
    'غير محدد'
  );

  -- 7. Atomic transfer + audit
  UPDATE public.orders
  SET owner_id = p_new_owner_id,
      updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_modification_history (
    order_id, revision_number, field_name, old_value, new_value,
    modified_by, reason, modified_at
  ) VALUES (
    p_order_id,
    GREATEST(COALESCE(v_order.revision_number, 1), 1),
    'OWNER_TRANSFER',
    v_old_owner_name,
    v_new_owner_name,
    v_session.identity_id,
    COALESCE(p_reason, 'نقل ملكية الطلب'),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'order_number', v_order.order_number,
    'old_owner_id', v_old_owner_id,
    'new_owner_id', p_new_owner_id,
    'old_owner_name', v_old_owner_name,
    'new_owner_name', v_new_owner_name
  );
END;

$function$;

