CREATE OR REPLACE FUNCTION public.governed_update_company(p_token uuid, p_id uuid, p_company_name character varying DEFAULT NULL::character varying, p_legacy_code character varying DEFAULT NULL::character varying, p_logo_url text DEFAULT NULL::text, p_is_visible boolean DEFAULT NULL::boolean, p_display_order integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_old_position int;
  v_new_position int;
  v_total int;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'companies.manage');

  -- Update non-position fields first
  UPDATE public.companies
  SET
    company_name = COALESCE(p_company_name, company_name),
    legacy_code = COALESCE(p_legacy_code, legacy_code),
    logo_url = COALESCE(p_logo_url, logo_url),
    is_visible = COALESCE(p_is_visible, is_visible),
    updated_at = now()
  WHERE id = p_id;

  -- Reorder if position changed
  IF p_display_order IS NOT NULL THEN
    SELECT display_order INTO v_old_position FROM companies WHERE id = p_id;
    SELECT COUNT(*) INTO v_total FROM companies;

    -- Clamp new position: must be between 1 and total
    v_new_position := GREATEST(1, LEAST(p_display_order, v_total));

    IF v_old_position IS NOT NULL AND v_old_position <> v_new_position THEN
      IF v_old_position < v_new_position THEN
        -- Moving DOWN: shift companies between old+1..new UP (decrement)
        UPDATE companies SET display_order = display_order - 1
        WHERE display_order > v_old_position AND display_order <= v_new_position;
      ELSE
        -- Moving UP: shift companies between new..old-1 DOWN (increment)
        UPDATE companies SET display_order = display_order + 1
        WHERE display_order >= v_new_position AND display_order < v_old_position;
      END IF;

      UPDATE companies SET display_order = v_new_position WHERE id = p_id;
    END IF;
  END IF;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_update_company_profile(p_token uuid, p_company_name text DEFAULT NULL::text, p_company_banner_url text DEFAULT NULL::text, p_facebook_url text DEFAULT NULL::text, p_sales_phone_1 text DEFAULT NULL::text, p_sales_phone_2 text DEFAULT NULL::text, p_sales_whatsapp_1 text DEFAULT NULL::text, p_sales_whatsapp_2 text DEFAULT NULL::text, p_technical_support_phone text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
