CREATE OR REPLACE FUNCTION public.governed_update_product(p_token uuid, p_id uuid, p_product_name character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_legacy_code character varying DEFAULT NULL::character varying, p_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  UPDATE public.products
  SET
    product_name = COALESCE(p_product_name, product_name),
    description = COALESCE(p_description, description),
    legacy_code = COALESCE(p_legacy_code, legacy_code),
    image_url = COALESCE(p_image_url, image_url),
    updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_update_product_inventory(p_token uuid, p_id uuid, p_quantity integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_inv_id uuid;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  SELECT id INTO v_inv_id FROM public.inventory WHERE product_id = p_id;
  IF v_inv_id IS NULL THEN
    INSERT INTO public.inventory (product_id, quantity) VALUES (p_id, COALESCE(p_quantity, 0))
    ON CONFLICT (product_id) DO UPDATE SET quantity = COALESCE(p_quantity, EXCLUDED.quantity), updated_at = now();
  ELSE
    UPDATE public.inventory SET quantity = COALESCE(p_quantity, quantity), updated_at = now() WHERE product_id = p_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_update_product_pricing(p_token uuid, p_id uuid, p_carton_price numeric DEFAULT NULL::numeric, p_carton_quantity integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_new_carton_price numeric;
  v_new_carton_quantity integer;
  v_piece_price numeric;
  v_dozen_price numeric;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  -- Resolve final values (COALESCE with existing row)
  SELECT
    COALESCE(p_carton_price, carton_price),
    COALESCE(p_carton_quantity, carton_quantity)
  INTO v_new_carton_price, v_new_carton_quantity
  FROM public.products WHERE id = p_id;

  -- Generate derived prices
  IF v_new_carton_price IS NOT NULL AND v_new_carton_price > 0
     AND v_new_carton_quantity IS NOT NULL AND v_new_carton_quantity > 0
  THEN
    v_piece_price := ROUND((v_new_carton_price / v_new_carton_quantity)::numeric, 2);
    v_dozen_price := ROUND((v_new_carton_price / v_new_carton_quantity * 12)::numeric, 2);
  ELSE
    v_piece_price := 0;
    v_dozen_price := 0;
  END IF;

  -- Single atomic update: all pricing columns
  UPDATE public.products
  SET
    carton_price = COALESCE(p_carton_price, carton_price),
    carton_quantity = COALESCE(p_carton_quantity, carton_quantity),
    piece_price = v_piece_price,
    dozen_price = v_dozen_price,
    updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_update_product_units(p_token uuid, p_id uuid, p_units jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
  v_unit jsonb;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  PERFORM check_capability(p_token, 'products.manage');

  -- Deactivate all existing units
  UPDATE public.product_units SET is_active = false WHERE product_id = p_id;

  -- Activate specified units
  FOR v_unit IN SELECT * FROM jsonb_array_elements(p_units)
  LOOP
    INSERT INTO public.product_units (product_id, unit_type, is_active)
    VALUES (p_id, v_unit->>'unit_type', true)
    ON CONFLICT (product_id, unit_type)
    DO UPDATE SET is_active = true;
  END LOOP;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_update_product_visibility(p_token uuid, p_id uuid, p_is_visible boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
