CREATE OR REPLACE FUNCTION public.governed_update_role_capabilities(p_token uuid, p_role_id uuid, p_capability_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
