        (employee_id, target_month, target_year, sales_target, visits_target, orders_target, new_customers_target, collections_target)
    VALUES
        (p_employee_id, p_target_month, p_target_year, p_sales_target, p_visits_target, p_orders_target, p_new_customers_target, p_collections_target)
    ON CONFLICT (employee_id, target_month, target_year)
    DO UPDATE SET
        sales_target = EXCLUDED.sales_target,
        visits_target = EXCLUDED.visits_target,
        orders_target = EXCLUDED.orders_target,
        new_customers_target = EXCLUDED.new_customers_target,
        collections_target = EXCLUDED.collections_target,
        updated_at = now()
    RETURNING jsonb_build_object(
        'id', id,
        'employee_id', employee_id,
        'target_month', target_month,
        'target_year', target_year,
        'sales_target', sales_target,
        'visits_target', visits_target,
        'orders_target', orders_target,
        'new_customers_target', new_customers_target,
        'collections_target', collections_target,
        'is_locked', is_locked
    ) INTO v_result;
    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_upsert_employee_weight_override(p_token uuid, p_employee_id uuid, p_target_month integer, p_target_year integer, p_sales_weight_percent numeric DEFAULT NULL::numeric, p_collections_weight_percent numeric DEFAULT NULL::numeric, p_visits_weight_percent numeric DEFAULT NULL::numeric, p_new_customers_weight_percent numeric DEFAULT NULL::numeric, p_attendance_weight_percent numeric DEFAULT NULL::numeric, p_override_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_has_view_all boolean;
    v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    IF NOT public.check_capability(p_token, 'targets.manage') THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;

    
    v_has_view_all := public.check_capability(p_token, 'targets.view_all');
    IF NOT v_has_view_all THEN
        IF p_employee_id != ALL(app.get_subtree_ids(v_session.employee_id)) THEN
            RETURN jsonb_build_object('error', 'FORBIDDEN', 'detail', 'لا يمكن تعديل أوزان موظف خارج نطاقك');
        END IF;
    END IF;

    INSERT INTO public.employee_weight_overrides
        (employee_id, target_month, target_year, sales_weight_percent,
         collections_weight_percent, visits_weight_percent,
         new_customers_weight_percent, attendance_weight_percent,
         override_reason)
    VALUES
        (p_employee_id, p_target_month, p_target_year, p_sales_weight_percent,
         p_collections_weight_percent, p_visits_weight_percent,
         p_new_customers_weight_percent, p_attendance_weight_percent,
         p_override_reason)
    ON CONFLICT (employee_id, target_month, target_year)
    DO UPDATE SET
        sales_weight_percent = COALESCE(EXCLUDED.sales_weight_percent, employee_weight_overrides.sales_weight_percent),
        collections_weight_percent = COALESCE(EXCLUDED.collections_weight_percent, employee_weight_overrides.collections_weight_percent),
        visits_weight_percent = COALESCE(EXCLUDED.visits_weight_percent, employee_weight_overrides.visits_weight_percent),
        new_customers_weight_percent = COALESCE(EXCLUDED.new_customers_weight_percent, employee_weight_overrides.new_customers_weight_percent),
        attendance_weight_percent = COALESCE(EXCLUDED.attendance_weight_percent, employee_weight_overrides.attendance_weight_percent),
        override_reason = COALESCE(EXCLUDED.override_reason, employee_weight_overrides.override_reason),
        is_active = true,
        updated_at = now()
    RETURNING jsonb_build_object(
        'id', id,
        'employee_id', employee_id,
        'target_month', target_month,
        'target_year', target_year,
        'sales_weight_percent', sales_weight_percent,
        'collections_weight_percent', collections_weight_percent,
        'visits_weight_percent', visits_weight_percent,
        'new_customers_weight_percent', new_customers_weight_percent,
        'attendance_weight_percent', attendance_weight_percent,
        'override_reason', override_reason,
        'is_active', is_active
    ) INTO v_result;

    RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.governed_check_order_over_limit(
  p_token uuid,
  p_order_id uuid
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_session app.sessions;
  v_order public.orders;
  v_account public.customer_credit_accounts;
  v_available decimal;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'NOT_FOUND'); END IF;
  IF v_order.payment_method != 'credit' THEN RETURN jsonb_build_object('over_limit', false); END IF;

  SELECT * INTO v_account FROM public.customer_credit_accounts
  WHERE customer_id = v_order.customer_id AND credit_status = 'active';
  IF NOT FOUND THEN RETURN jsonb_build_object('over_limit', false); END IF;

  v_available := v_account.credit_limit - v_account.outstanding_credit - v_account.reserved_credit;

  RETURN jsonb_build_object(
    'over_limit', v_order.total_amount > v_available,
    'available', v_available,
    'required', v_order.total_amount
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.health_check_runtime()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_result jsonb;
  v_delivered_no_date bigint;
  v_delivered_no_date_amount numeric;
  v_visits_broken bigint;
  v_customers_broken bigint;
  v_excluded_employees jsonb;
BEGIN
  -- 1. Delivered orders with NULL delivered_at
  -- If > 0: there are orders delivered via change_order_status bypassing delivered_at
  SELECT COUNT(*), COALESCE(SUM(total_amount), 0)
  INTO v_delivered_no_date, v_delivered_no_date_amount
  FROM orders
  WHERE status = 'delivered' AND delivered_at IS NULL;

  -- 2. Completed visits without proper check-in/out
  SELECT COUNT(*) INTO v_visits_broken
  FROM visits
  WHERE status = 'completed'
    AND (check_in_at IS NULL OR check_out_at IS NULL OR check_out_at <= check_in_at);

  -- 3. Customers without required timestamps
  SELECT COUNT(*) INTO v_customers_broken
  FROM customers
  WHERE owner_id IS NULL OR (registered_at IS NULL AND created_at IS NULL);

  -- 4. Employees with excluded deliveries (for alert targeting)
  SELECT jsonb_agg(jsonb_build_object(
    'employee_id', e.id,
    'code', e.code,
    'full_name', e.full_name,
    'broken_orders', sub.cnt,
    'broken_amount', sub.amt
  ) ORDER BY sub.amt DESC)
  INTO v_excluded_employees
  FROM (
    SELECT o.owner_id, COUNT(*) AS cnt, COALESCE(SUM(o.total_amount), 0) AS amt
    FROM orders o
    WHERE o.status = 'delivered' AND o.delivered_at IS NULL
    GROUP BY o.owner_id
  ) sub
  JOIN employees e ON e.identity_id = sub.owner_id OR e.id = sub.owner_id
  WHERE sub.cnt > 0;

  v_result := jsonb_build_object(
    'timestamp', now(),
    'status', CASE WHEN v_delivered_no_date = 0 AND v_visits_broken = 0 AND v_customers_broken = 0 THEN 'CLEAN' ELSE 'ALERT' END,
    'checks', jsonb_build_object(
      'delivered_without_date', jsonb_build_object(
        'count', v_delivered_no_date,
        'total_amount', v_delivered_no_date_amount,
        'severity', CASE WHEN v_delivered_no_date > 0 THEN 'CRITICAL' ELSE 'OK' END
      ),
      'broken_visits', jsonb_build_object(
        'count', v_visits_broken,
        'severity', CASE WHEN v_visits_broken > 0 THEN 'WARNING' ELSE 'OK' END
      ),
      'broken_customers', jsonb_build_object(
        'count', v_customers_broken,
        'severity', CASE WHEN v_customers_broken > 0 THEN 'WARNING' ELSE 'OK' END
      )
    ),
    'affected_employees', COALESCE(v_excluded_employees, '[]'::jsonb),
    'recommendation', CASE
      WHEN v_delivered_no_date > 0 THEN 'CRITICAL: ' || v_delivered_no_date || ' orders delivered without delivered_at. Total amount: ' || ROUND(v_delivered_no_date_amount, 2) || ' EGP. Run: UPDATE orders SET delivered_at = updated_at WHERE status = ''delivered'' AND delivered_at IS NULL;'
      WHEN v_visits_broken > 0 OR v_customers_broken > 0 THEN 'WARNING: Non-critical integrity issues found. Review affected records.'
      ELSE 'All systems clean. No data integrity issues.'
    END
  );

  RETURN v_result;
END;

$function$;

CREATE OR REPLACE FUNCTION public.insert_gps_test_point(p_latitude numeric, p_longitude numeric, p_accuracy numeric DEFAULT NULL::numeric, p_altitude numeric DEFAULT NULL::numeric, p_speed numeric DEFAULT NULL::numeric, p_heading numeric DEFAULT NULL::numeric, p_device_info jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_id uuid;
BEGIN
    INSERT INTO public.gps_test_points (
        latitude, longitude, accuracy_meters, altitude_meters,
        speed_mps, heading_degrees, device_info
    ) VALUES (
        p_latitude, p_longitude, p_accuracy, p_altitude,
        p_speed, p_heading, p_device_info
    )
