$function$;

CREATE OR REPLACE FUNCTION public.is_upper_management(p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_employee_id UUID;
BEGIN
  IF p_employee_id IS NOT NULL THEN
    v_employee_id := p_employee_id;
  ELSE
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM employee_roles er
    JOIN roles r ON r.id = er.role_id
    WHERE er.employee_id = v_employee_id
    AND r.name = 'الإدارة العليا'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.list_employees_without_policies(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    SELECT jsonb_agg(
        jsonb_build_object(
            'employee_id', e.id,
            'employee_code', e.code,
            'employee_name', e.full_name,
            'is_active', e.is_active,
            'job_title', COALESCE((SELECT STRING_AGG(r.name, '، ' ORDER BY r.name) FROM employee_roles er2 JOIN roles r ON r.id = er2.role_id WHERE er2.employee_id = e.id), '')
        ) ORDER BY e.full_name
    ) INTO v_result
    FROM public.employees e
    WHERE NOT EXISTS (SELECT 1 FROM public.employee_work_policies ewp WHERE ewp.employee_id = e.id);
    RETURN jsonb_build_object('employees', COALESCE(v_result, '[]'::jsonb));
END;

$function$;

CREATE OR REPLACE FUNCTION public.list_work_policies(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE v_session app.sessions; v_result jsonb;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    SELECT jsonb_agg(
        jsonb_build_object(
            'policy_id', ewp.id,
            'employee_id', ewp.employee_id,
            'employee_code', e.code,
            'employee_name', e.full_name,
            'is_active', e.is_active,
            'work_location', ewp.work_location,
            'schedule_type', ewp.schedule_type,
            'tracking_required', ewp.tracking_required,
            'attendance_enabled', ewp.attendance_enabled,
            'required_daily_hours', ewp.required_daily_hours,
            'shift_start_time', ewp.shift_start_time,
            'shift_end_time', ewp.shift_end_time,
            'late_threshold_minutes', ewp.late_threshold_minutes,
            'early_departure_threshold_minutes', ewp.early_departure_threshold_minutes,
            'updated_at', ewp.updated_at,
            'job_title', COALESCE((SELECT STRING_AGG(r.name, '، ' ORDER BY r.name) FROM employee_roles er2 JOIN roles r ON r.id = er2.role_id WHERE er2.employee_id = e.id), '')
        ) ORDER BY e.full_name
    ) INTO v_result
    FROM public.employee_work_policies ewp
    JOIN public.employees e ON e.id = ewp.employee_id;
    RETURN jsonb_build_object('policies', COALESCE(v_result, '[]'::jsonb));
END;

$function$;

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_session app.sessions;
  v_updated integer;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  UPDATE public.notifications
  SET is_read = true
  WHERE recipient_employee_id = v_session.employee_id AND is_read = false;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'updated', v_updated);
END;

$function$;

