CREATE OR REPLACE FUNCTION public.require_hierarchy_scope(p_actor_id uuid, p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
  v_visible_ids uuid[];
  v_in_scope boolean;
BEGIN
  -- Upper Management: unrestricted
  IF public.is_upper_management(p_actor_id) THEN
    RETURN jsonb_build_object('success', true);
  END IF;

  -- Check role: only Sales Manager (مدير البيع) may operate on hierarchy
  IF NOT EXISTS (
    SELECT 1 FROM public.employee_roles er
    JOIN public.roles r ON r.id = er.role_id
    WHERE er.employee_id = p_actor_id AND r.name = 'مدير البيع'
  ) THEN
    RETURN jsonb_build_object('error', 'HIERARCHY_ACCESS_DENIED');
  END IF;

  -- Sales Manager: target must not be NULL (e.g. creating top-level employee, which requires UM)
  IF p_target_id IS NULL THEN
    RETURN jsonb_build_object('error', 'HIERARCHY_SCOPE_VIOLATION');
  END IF;

  -- Sales Manager: verify target is inside own subtree
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.employees WHERE id = p_actor_id
    UNION ALL
    SELECT e.id FROM public.employees e JOIN subtree s ON e.manager_id = s.id
  )
  SELECT p_target_id = ANY(array_agg(id)) INTO v_in_scope FROM subtree;

  IF NOT COALESCE(v_in_scope, false) THEN
    RETURN jsonb_build_object('error', 'HIERARCHY_SCOPE_VIOLATION');
  END IF;

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.resolve_stale_session(p_token uuid, p_stale_session_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_ws record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    SELECT * INTO v_ws FROM public.workday_sessions
    WHERE id = p_stale_session_id AND employee_id = v_employee_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'SESSION_NOT_FOUND'); END IF;

    IF p_action = 'close_and_continue' THEN
        PERFORM public.end_workday(p_token, p_stale_session_id,
            p_latitude => v_ws.end_latitude,
            p_longitude => v_ws.end_longitude,
            p_close_reason => 'day_rollover'
        );
        RETURN jsonb_build_object('ok', true, 'action', 'closed');
    ELSIF p_action = 'request_review' THEN
        RETURN jsonb_build_object('ok', true, 'action', 'pending_review');
    ELSE
        RETURN jsonb_build_object('error', 'INVALID_ACTION');
    END IF;
END;

$function$;

CREATE OR REPLACE FUNCTION public.runtime_reconciliation(p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_month integer;
  v_year integer;
  v_start date;
  v_end date;
  v_orders_total bigint; v_orders_achieved bigint; v_orders_excluded bigint;
  v_sales_total numeric; v_sales_achieved numeric; v_sales_excluded numeric;
  v_visits_total bigint; v_visits_achieved bigint; v_visits_excluded bigint;
  v_customers_total bigint; v_customers_achieved bigint; v_customers_excluded bigint;
  v_employees_with_issues jsonb;
BEGIN
  v_month := COALESCE(p_month, EXTRACT(MONTH FROM now())::integer);
  v_year := COALESCE(p_year, EXTRACT(YEAR FROM now())::integer);
  v_start := make_date(v_year, v_month, 1);
  v_end := v_start + interval '1 month';

  -- Orders/Sales
  SELECT
    COUNT(*), COALESCE(SUM(o.total_amount), 0),
    COUNT(*) FILTER (WHERE o.delivered_at IS NOT NULL AND o.owner_id IS NOT NULL AND o.customer_id IS NOT NULL),
    COALESCE(SUM(o.total_amount) FILTER (WHERE o.delivered_at IS NOT NULL AND o.owner_id IS NOT NULL AND o.customer_id IS NOT NULL), 0),
    COUNT(*) FILTER (WHERE o.delivered_at IS NULL OR o.owner_id IS NULL OR o.customer_id IS NULL),
    COALESCE(SUM(o.total_amount) FILTER (WHERE o.delivered_at IS NULL OR o.owner_id IS NULL OR o.customer_id IS NULL), 0)
  INTO v_orders_total, v_sales_total, v_orders_achieved, v_sales_achieved, v_orders_excluded, v_sales_excluded
  FROM orders o
  WHERE o.status = 'delivered'
    AND o.delivered_at >= v_start AND o.delivered_at < v_end;

  -- Visits
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE check_in_at IS NOT NULL AND check_out_at IS NOT NULL AND check_out_at > check_in_at),
    COUNT(*) FILTER (WHERE check_in_at IS NULL OR check_out_at IS NULL OR check_out_at <= check_in_at)
  INTO v_visits_total, v_visits_achieved, v_visits_excluded
  FROM visits
  WHERE status = 'completed'
    AND check_out_at >= v_start AND check_out_at < v_end;

  -- Customers
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE owner_id IS NOT NULL AND (registered_at IS NOT NULL OR created_at IS NOT NULL)),
    COUNT(*) FILTER (WHERE owner_id IS NULL OR (registered_at IS NULL AND created_at IS NULL))
  INTO v_customers_total, v_customers_achieved, v_customers_excluded
  FROM customers
  WHERE created_at >= v_start AND created_at < v_end;

  -- Employees with nonzero diff
  SELECT jsonb_agg(sub.emp)
  INTO v_employees_with_issues
  FROM (
    SELECT jsonb_build_object(
      'code', e.code,
      'full_name', e.full_name,
      'orders_total', eo.cnt,
      'orders_achieved', eo.achieved,
      'orders_excluded', eo.excluded,
      'orders_diff', eo.cnt - eo.achieved - eo.excluded
    ) AS emp
    FROM employees e
    CROSS JOIN LATERAL (
      SELECT
        COUNT(*) AS cnt,
        COUNT(*) FILTER (WHERE o.delivered_at IS NOT NULL AND o.owner_id IS NOT NULL AND o.customer_id IS NOT NULL) AS achieved,
        COUNT(*) FILTER (WHERE o.delivered_at IS NULL OR o.owner_id IS NULL OR o.customer_id IS NULL) AS excluded
      FROM orders o
      WHERE o.status = 'delivered'
        AND o.delivered_at >= v_start AND o.delivered_at < v_end
        AND o.owner_id IN (e.id, e.identity_id)
    ) eo
    WHERE e.is_active = true
      AND eo.cnt > 0
      AND eo.cnt - eo.achieved - eo.excluded != 0
  ) sub;

  RETURN jsonb_build_object(
    'period', jsonb_build_object('month', v_month, 'year', v_year, 'from', v_start, 'to', v_end),
    'status', CASE WHEN v_employees_with_issues IS NULL THEN 'CLEAN' ELSE 'ISSUES_FOUND' END,
    'orders', jsonb_build_object('total', v_orders_total, 'achieved', v_orders_achieved, 'excluded', v_orders_excluded, 'diff', v_orders_total - v_orders_achieved - v_orders_excluded),
    'sales', jsonb_build_object('total', v_sales_total, 'achieved', v_sales_achieved, 'excluded', v_sales_excluded, 'diff', v_sales_total - v_sales_achieved - v_sales_excluded),
    'visits', jsonb_build_object('total', v_visits_total, 'achieved', v_visits_achieved, 'excluded', v_visits_excluded, 'diff', v_visits_total - v_visits_achieved - v_visits_excluded),
    'customers', jsonb_build_object('total', v_customers_total, 'achieved', v_customers_achieved, 'excluded', v_customers_excluded, 'diff', v_customers_total - v_customers_achieved - v_customers_excluded),
    'employees_with_issues', COALESCE(v_employees_with_issues, '[]'::jsonb)
  );
END;

$function$;

CREATE OR REPLACE FUNCTION public.save_push_subscription(p_token uuid, p_endpoint text, p_p256dh text, p_auth text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
  v_session app.sessions;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

  INSERT INTO public.push_subscriptions (employee_id, endpoint, p256dh, auth_key, user_agent, last_used_at)
  VALUES (v_session.employee_id, p_endpoint, p_p256dh, p_auth, p_user_agent, now())
  ON CONFLICT (endpoint) DO UPDATE SET
    employee_id = v_session.employee_id,
    p256dh = EXCLUDED.p256dh,
    auth_key = EXCLUDED.auth_key,
    user_agent = EXCLUDED.user_agent,
    last_used_at = now();

  RETURN jsonb_build_object('success', true);
END;

$function$;

CREATE OR REPLACE FUNCTION public.seed_sales_rep_monthly_targets(p_token uuid, p_month integer DEFAULT NULL::integer, p_year integer DEFAULT NULL::integer, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_target_month int;
    v_target_year int;
    v_rep record;
    v_created int := 0;
    v_skipped int := 0;
    v_already_had int := 0;
    v_created_names text[] := '{}'::text[];
    v_skipped_names text[] := '{}'::text[];
    v_already_names text[] := '{}'::text[];
    v_total_reps int := 0;
    v_reps_with_targets int := 0;
    v_reps_without_targets int := 0;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;

    v_target_month := COALESCE(p_month, EXTRACT(MONTH FROM CURRENT_DATE)::int);
    v_target_year := COALESCE(p_year, EXTRACT(YEAR FROM CURRENT_DATE)::int);

    FOR v_rep IN
        WITH rep_candidates AS (
            SELECT e.id, e.code, e.full_name
            FROM public.employees e
            WHERE e.is_active = true
              AND EXISTS (
                  SELECT 1 FROM public.employee_roles er
                  JOIN public.roles r ON r.id = er.role_id
                  WHERE er.employee_id = e.id AND r.name = 'مندوب مبيعات'
              )
              AND NOT EXISTS (
                  SELECT 1 FROM public.employee_roles er
                  JOIN public.roles r ON r.id = er.role_id
                  WHERE er.employee_id = e.id
                    AND r.name IN (
                        'الإدارة العليا',
                        'مدير البيع',
                        'مشرف تنفيذي', 'مشرف عام',
                        'مدير عمليات تنفيذية'
                    )
              )
        )
        SELECT rc.*,
               CASE WHEN et.id IS NOT NULL THEN true ELSE false END AS has_target
        FROM rep_candidates rc
        LEFT JOIN public.employee_monthly_targets et
            ON et.employee_id = rc.id
            AND et.target_month = v_target_month
            AND et.target_year = v_target_year
        ORDER BY rc.full_name
    LOOP
        v_total_reps := v_total_reps + 1;

        IF v_rep.has_target THEN
            v_reps_with_targets := v_reps_with_targets + 1;
            v_already_had := v_already_had + 1;
            v_already_names := array_append(v_already_names, v_rep.full_name || ' (' || v_rep.code || ')');
        ELSE
            v_reps_without_targets := v_reps_without_targets + 1;

            IF NOT p_dry_run THEN
                INSERT INTO public.employee_monthly_targets
                    (employee_id, target_month, target_year,
                     sales_target, visits_target, orders_target, new_customers_target)
                VALUES
                    (v_rep.id, v_target_month, v_target_year,
                     5000000, 250, 250, 30)
                ON CONFLICT (employee_id, target_month, target_year)
                DO NOTHING;

                IF FOUND THEN
                    v_created := v_created + 1;
                    v_created_names := array_append(v_created_names, v_rep.full_name || ' (' || v_rep.code || ')');
                ELSE
                    v_skipped := v_skipped + 1;
                    v_skipped_names := array_append(v_skipped_names, v_rep.full_name || ' (' || v_rep.code || ')');
                END IF;
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'dry_run', p_dry_run,
        'month', v_target_month,
        'year', v_target_year,
        'total_sales_reps', v_total_reps,
        'reps_with_targets', v_reps_with_targets,
        'reps_without_targets', v_reps_without_targets,
        'created', CASE WHEN p_dry_run THEN 0 ELSE v_created END,
        'skipped', CASE WHEN p_dry_run THEN 0 ELSE v_skipped END,
        'missing_list', COALESCE(CASE WHEN p_dry_run THEN
            (SELECT array_agg(full_name || ' (' || code || ')') FROM (
                SELECT e2.full_name, e2.code
                FROM public.employees e2
                WHERE e2.is_active = true
                  AND EXISTS (
                      SELECT 1 FROM public.employee_roles er2
                      JOIN public.roles r2 ON r2.id = er2.role_id
                      WHERE er2.employee_id = e2.id AND r2.name = 'مندوب مبيعات'
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM public.employee_roles er2
                      JOIN public.roles r2 ON r2.id = er2.role_id
                      WHERE er2.employee_id = e2.id
                        AND r2.name IN (
                            'الإدارة العليا',
                            'مدير البيع',
                            'مشرف تنفيذي', 'مشرف عام',
                            'مدير عمليات تنفيذية'
                        )
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM public.employee_monthly_targets et2
                      WHERE et2.employee_id = e2.id
                        AND et2.target_month = v_target_month
                        AND et2.target_year = v_target_year
                  )
            ) missing
        ) ELSE v_created_names END, '{}'::text[]),
        'already_list', COALESCE(v_already_names, '{}'::text[]),
        'message', CASE
            WHEN p_dry_run THEN 'وضع المعاينة: ' || v_reps_without_targets || ' مندوب بدون هدف — جاهز للإنشاء'
            WHEN v_created > 0 THEN 'تم إنشاء ' || v_created || ' هدف للمناديب'
            ELSE 'جميع المناديب لديهم أهداف بالفعل'
        END
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.start_break(p_token uuid, p_session_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_reason character varying DEFAULT NULL::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_break_id uuid;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    IF public.is_employee_executive(v_employee_id) THEN
        RETURN jsonb_build_object('error', 'EXECUTIVE_NOT_AUTHORIZED');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.workday_sessions
        WHERE id = p_session_id AND employee_id = v_employee_id AND status = 'active') THEN
        RETURN jsonb_build_object('error', 'SESSION_NOT_FOUND');
    END IF;

    INSERT INTO public.workday_breaks (session_id, employee_id, break_reason, latitude, longitude)
    VALUES (p_session_id, v_employee_id, p_reason, p_latitude, p_longitude)
    RETURNING id INTO v_break_id;

    RETURN jsonb_build_object('break_id', v_break_id, 'break_start', now());
END;

$function$;

CREATE OR REPLACE FUNCTION public.start_workday(p_token uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_device_status jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_existing_id uuid;
    v_stale record;
    v_stale_count int := 0;
    v_settings record;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    IF v_session.identity_type != 'employee' THEN
        RETURN jsonb_build_object('error', 'FORBIDDEN');
    END IF;
    v_employee_id := v_session.employee_id;

    -- Auto-recover stale sessions from previous days
    FOR v_stale IN
        SELECT id, date, start_time
        FROM public.workday_sessions
        WHERE employee_id = v_employee_id
          AND status = 'active'
          AND date < CURRENT_DATE
        ORDER BY date ASC
    LOOP
        UPDATE public.workday_sessions
        SET end_time = now(),
            status = 'completed',
            attendance_status = 'auto_closed',
            updated_at = now()
        WHERE id = v_stale.id;
        v_stale_count := v_stale_count + 1;
    END LOOP;

    -- Check no active session today
    SELECT id INTO v_existing_id FROM public.workday_sessions
    WHERE employee_id = v_employee_id AND date = CURRENT_DATE AND status = 'active';
    IF FOUND THEN
        RETURN jsonb_build_object(
            'error', 'ALREADY_ACTIVE',
            'session_id', v_existing_id,
            'recovered_stale_sessions', v_stale_count
        );
    END IF;

    INSERT INTO public.workday_sessions (employee_id, start_latitude, start_longitude, start_device_status)
    VALUES (v_employee_id, p_latitude, p_longitude, p_device_status)
    RETURNING id INTO v_existing_id;

    INSERT INTO public.tracking_points (session_id, employee_id, latitude, longitude, recorded_at, point_type)
    VALUES (v_existing_id, v_employee_id, p_latitude, p_longitude, now(), 'start');

    RETURN jsonb_build_object(
        'session_id', v_existing_id,
        'started_at', now(),
        'recovered_stale_sessions', v_stale_count
    );
END;

$function$;

CREATE OR REPLACE FUNCTION public.sync_tracking_points(p_token uuid, p_session_id uuid, p_points jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$

DECLARE
    v_session app.sessions;
    v_employee_id uuid;
    v_points_arr jsonb;
    v_point jsonb;
    v_synced int := 0;
    v_rejected int := 0;
BEGIN
    SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'INVALID_SESSION'); END IF;
    v_employee_id := v_session.employee_id;

    IF NOT EXISTS (SELECT 1 FROM public.workday_sessions
        WHERE id = p_session_id AND employee_id = v_employee_id) THEN
        RETURN jsonb_build_object('error', 'SESSION_NOT_FOUND');
    END IF;

    PERFORM public.touch_session_activity(p_session_id);

    IF jsonb_typeof(p_points) = 'string' THEN
        v_points_arr := p_points::jsonb;
    ELSE
        v_points_arr := p_points;
    END IF;

    FOR v_point IN SELECT * FROM jsonb_array_elements(v_points_arr)
    LOOP
        BEGIN
            IF v_point->>'latitude' IS NULL OR v_point->>'longitude' IS NULL
               OR (v_point->>'latitude')::decimal IS NULL
               OR (v_point->>'longitude')::decimal IS NULL THEN
                v_rejected := v_rejected + 1;
                CONTINUE;
            END IF;
            INSERT INTO public.tracking_points (
                session_id, employee_id, latitude, longitude,
                accuracy_meters, altitude_meters, speed_mps, heading_degrees,
                battery_pct, recorded_at, point_type
            ) VALUES (
                p_session_id, v_employee_id,
                (v_point->>'latitude')::decimal,
                (v_point->>'longitude')::decimal,
                (v_point->>'accuracy_meters')::decimal,
                (v_point->>'altitude_meters')::decimal,
                (v_point->>'speed_mps')::decimal,
                (v_point->>'heading_degrees')::decimal,
                (v_point->>'battery_pct')::decimal,
                (v_point->>'recorded_at')::timestamptz,
                COALESCE(v_point->>'point_type', 'periodic')
            );
            v_synced := v_synced + 1;
        EXCEPTION WHEN OTHERS THEN
            v_rejected := v_rejected + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object('synced', v_synced, 'rejected', v_rejected);
END;

$function$;

