CREATE OR REPLACE FUNCTION public.fn_customer_default_address(p_customer_id uuid)
 RETURNS TABLE(id uuid, customer_id uuid, label character varying, address_line1 character varying, address_line2 character varying, city character varying, governorate character varying, postal_code character varying, latitude numeric, longitude numeric, is_default boolean, governorate_id uuid, city_id uuid, street_address character varying, landmark text, address_source address_source_type, address_updated_at timestamp with time zone, location_accuracy location_accuracy_level)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$

        SELECT ca.id, ca.customer_id, ca.label,
               ca.address_line1, ca.address_line2,
               ca.city, ca.governorate, ca.postal_code,
               ca.latitude, ca.longitude, ca.is_default,
               ca.governorate_id, ca.city_id,
               ca.street_address, ca.landmark,
               ca.address_source, ca.address_updated_at,
               ca.location_accuracy
        FROM customer_addresses ca
        WHERE ca.customer_id = p_customer_id AND ca.is_default = true
        LIMIT 1;
      
$function$;

