CREATE OR REPLACE FUNCTION public.get_kpi_collections_collected_amount(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_employee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(collected_amount numeric, collected_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

  SELECT
    COALESCE(SUM(amount), 0) AS collected_amount,
    COUNT(*)::bigint AS collected_count
  FROM public.collections
  WHERE status = 'collected'
    AND collected_at >= p_start_date
    AND collected_at < p_end_date
    AND (p_employee_ids IS NULL OR created_by = ANY(p_employee_ids) OR owner_id = ANY(p_employee_ids));

$function$;

CREATE OR REPLACE FUNCTION public.get_kpi_collections_pending_value(p_employee_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(pending_amount numeric, pending_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

  SELECT
    COALESCE(SUM(amount), 0) AS pending_amount,
    COUNT(*)::bigint AS pending_count
  FROM public.collections
  WHERE status = 'pending'
    AND (p_employee_ids IS NULL OR created_by = ANY(p_employee_ids) OR owner_id = ANY(p_employee_ids));

$function$;

CREATE OR REPLACE FUNCTION public.get_kpi_orders_count(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_identity_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(order_count bigint, sales_value numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$

  SELECT
    COUNT(*)::bigint AS order_count,
    COALESCE(SUM(total_amount), 0) AS sales_value
  FROM public.orders
  WHERE submitted_at >= p_start_date
    AND submitted_at < p_end_date
    AND public.is_order_in_statistics(status)
    AND (p_identity_ids IS NULL OR created_by = ANY(p_identity_ids));

$function$;

CREATE OR REPLACE FUNCTION public.get_unseen_counts(p_token uuid)
 RETURNS json
 LANGUAGE sql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
 WITH sess AS (SELECT e.id AS emp_id FROM app.sessions s JOIN public.employees e ON e.identity_id = s.identity_id WHERE s.token = p_token AND s.expires_at > now() LIMIT 1), bl AS (SELECT COALESCE(b.baseline_at, now()) AS baseline_at FROM sess LEFT JOIN public.employee_baselines b ON b.employee_id = sess.emp_id), vis AS (SELECT public.get_visible_employee_ids(p_token) AS ids) SELECT json_build_object('unseen_orders', (SELECT COUNT(*)::int FROM public.orders o, bl, vis WHERE o.status IN ('reviewing', 'submitted', 'approved', 'preparing', 'prepared', 'dispatched') AND o.created_at >= bl.baseline_at AND (vis.ids IS NULL OR o.owner_id = ANY(vis.ids)) AND NOT EXISTS (SELECT 1 FROM public.employee_entity_views v, sess WHERE v.employee_id = sess.emp_id AND v.entity_type = 'order' AND v.entity_id = o.id)), 'unseen_customers', (SELECT COUNT(*)::int FROM public.customers c, bl, vis WHERE c.is_active = true AND c.created_at >= bl.baseline_at AND (vis.ids IS NULL OR c.owner_id = ANY(vis.ids)) AND NOT EXISTS (SELECT 1 FROM public.employee_entity_views v, sess WHERE v.employee_id = sess.emp_id AND v.entity_type = 'customer' AND v.entity_id = c.id))); 
$function$;

