 WITH sess AS (SELECT e.id AS emp_id FROM app.sessions s JOIN public.employees e ON e.identity_id = s.identity_id WHERE s.token = p_token AND s.expires_at > now() LIMIT 1), bl AS (SELECT COALESCE(b.baseline_at, now()) AS baseline_at FROM sess LEFT JOIN public.employee_baselines b ON b.employee_id = sess.emp_id), vis AS (SELECT public.get_visible_employee_ids(p_token) AS ids) SELECT c.id FROM public.customers c, sess, bl, vis WHERE c.is_active = true AND c.created_at >= bl.baseline_at AND (vis.ids IS NULL OR c.owner_id = ANY(vis.ids)) AND NOT EXISTS (SELECT 1 FROM public.employee_entity_views v WHERE v.employee_id = sess.emp_id AND v.entity_type = 'customer' AND v.entity_id = c.id); 
