CREATE OR REPLACE FUNCTION public.validate_session(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_session app.sessions;
  v_employee RECORD;
BEGIN
  SELECT * INTO v_session FROM app.sessions WHERE token = p_token AND expires_at > now();
  IF NOT FOUND THEN
    RETURN json_build_object('error', 'INVALID_SESSION');
  END IF;
  SELECT e.id, e.full_name INTO v_employee
  FROM public.employees e WHERE e.id = v_session.employee_id;
  RETURN json_build_object(
    'valid', true,
    'session', json_build_object('token', v_session.token, 'employee_id', v_session.employee_id,
      'identity_id', v_session.identity_id, 'identity_type', v_session.identity_type),
    'employee', json_build_object('id', v_employee.id, 'full_name', v_employee.full_name)
  );
END;
$function$;

