  CREATE TRIGGER trg_notify_order_status_history AFTER INSERT ON public.order_status_history FOR EACH ROW EXECUTE FUNCTION fn_notify_order_status_history();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
