EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  CREATE TRIGGER trg_session_status_change AFTER INSERT ON public.workday_sessions FOR EACH ROW EXECUTE FUNCTION log_session_status_change();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  CREATE TRIGGER trg_session_status_change AFTER UPDATE ON public.workday_sessions FOR EACH ROW EXECUTE FUNCTION log_session_status_change();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

