  'delivery_tracking','tracking_points','tracking_cleanup_log',
  'session_recovery_log',
  'deletion_audit_log','gps_test_points'
]
$$;

CREATE OR REPLACE FUNCTION public.sync_outbox_capture()
RETURNS trigger
SECURITY DEFINER
SET search_path = 'public'
LANGUAGE plpgsql
AS $$
DECLARE
  v_table_name text := TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  v_record_id uuid;
  v_payload jsonb;
  v_operation text := TG_OP;
  v_employee_id uuid;
BEGIN
  IF current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF NOT (TG_TABLE_NAME = ANY(public.sync_get_table_allowlist())) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  BEGIN
    v_employee_id := current_setting('app.current_employee_id', true)::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_employee_id := NULL;
  END;

  IF TG_OP = 'DELETE' THEN
    v_payload := row_to_json(OLD)::jsonb;
    v_record_id := OLD.id;
  ELSE
    v_payload := row_to_json(NEW)::jsonb;
    v_record_id := NEW.id;
  END IF;

  IF v_record_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  INSERT INTO sync_outbox (table_name, operation, record_id, payload, employee_id)
  VALUES (v_table_name, v_operation, v_record_id, v_payload, v_employee_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;

DO $$
DECLARE
  t text;
  allowlist text[];
BEGIN
  allowlist := public.sync_get_table_allowlist();
  FOREACH t IN ARRAY allowlist
  LOOP
    BEGIN
      EXECUTE format('DROP TRIGGER IF EXISTS sync_outbox_trigger ON %I', t);
    EXCEPTION WHEN OTHERS THEN END;
    EXECUTE format(
      'CREATE TRIGGER sync_outbox_trigger AFTER INSERT OR UPDATE OR DELETE ON %I
       FOR EACH ROW EXECUTE FUNCTION public.sync_outbox_capture()',
      t
    );
  END LOOP;
END;
$$;

-- =============================================================================
-- END OF SCHEMA
